--
-- Name: add_waiting_item(uuid, uuid, text, text, text, bigint, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.add_waiting_item(c uuid, person uuid, item_kind text, item_title text, item_body text DEFAULT ''::text, card bigint DEFAULT NULL::bigint, conversation uuid DEFAULT NULL::uuid, asker text DEFAULT ''::text) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare result bigint; card_archived timestamptz; begin
 if not exists(select 1 from public.members where company_id=c and person_id=person and removed_at is null) then raise exception 'not a member' using errcode='22023'; end if;
 if conversation is not null and not exists(select 1 from public.conversations where id=conversation and company_id=c and person_id=person) then raise exception 'conversation not found' using errcode='P0002'; end if;
 -- An archived Card waits on nobody (#671). The Card is locked first, so an archive committing meanwhile (archive_cards
 -- holds it for update) is waited for and seen, and no wait lands after it cleared the Card's waits.
 if card is not null then
  select w.archived_at into card_archived from public.work_cards w where w.company_id=c and w.id=card for key share;
  if card_archived is not null then return null; end if;
 end if;
 insert into public.waiting_items(company_id,person_id,kind,title,body,asked_by,card_id,conversation_id)
  values(c,person,item_kind,btrim(item_title),coalesce(item_body,''),coalesce(asker,''),card,conversation) returning id into result;
 return result;
end $$;

ALTER FUNCTION public.add_waiting_item(c uuid, person uuid, item_kind text, item_title text, item_body text, card bigint, conversation uuid, asker text) OWNER TO postgres;

--
-- Name: adopt_engine(text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.adopt_engine(address text, key_encrypted text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare missing integer; engine uuid;
begin
 if address is null or length(address) not between 1 and 2048 or key_encrypted is null or length(key_encrypted)=0 then
  raise exception 'invalidEngine' using errcode='22023';
 end if;
 select count(*) into missing from public.companies c where c.engine_id is null;
 if missing=0 then return null; end if;
 if missing>1 then raise exception 'companyEngineMissing' using errcode='55000'; end if;
 insert into public.company_engines(address,key_encrypted) values(address,key_encrypted) returning id into engine;
 update public.companies set engine_id=engine where engine_id is null;
 return engine;
end $$;

ALTER FUNCTION public.adopt_engine(address text, key_encrypted text) OWNER TO postgres;

--
-- Name: agent_access_named(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.agent_access_named(c uuid, asker uuid, agent uuid) RETURNS uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
 select m.person_id from public.members m left join public.people p on p.id=m.person_id
  where m.company_id=c and public.may_open_agent_for(c,m.person_id,agent,asker)
  order by (m.role='manager') desc,
   (select min(a.created_at) from public.member_audit a where a.company_id=c and a.person_id=m.person_id and a.action='INSERT') nulls last,
   p.name, m.person_id
  limit 1;
$$;

ALTER FUNCTION public.agent_access_named(c uuid, asker uuid, agent uuid) OWNER TO postgres;

