--
-- Name: agent_access_requests; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.agent_access_requests (
    id bigint NOT NULL,
    company_id uuid NOT NULL,
    conversation_id uuid NOT NULL,
    run_id text NOT NULL,
    call_id text NOT NULL,
    agent_id uuid NOT NULL,
    asked_by uuid NOT NULL,
    named_to uuid NOT NULL,
    state text DEFAULT 'offered'::text NOT NULL,
    pressed_at timestamp with time zone,
    answered_by uuid,
    answered_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT agent_access_requests_answered CHECK ((((state = ANY (ARRAY['opened'::text, 'declined'::text])) = (answered_by IS NOT NULL)) AND ((answered_by IS NULL) = (answered_at IS NULL)))),
    CONSTRAINT agent_access_requests_pressed CHECK (((state = 'offered'::text) = (pressed_at IS NULL))),
    CONSTRAINT agent_access_requests_state CHECK ((state = ANY (ARRAY['offered'::text, 'asked'::text, 'dismissed'::text, 'opened'::text, 'declined'::text])))
);

ALTER TABLE public.agent_access_requests OWNER TO postgres;

--
-- Name: agent_access_waits(public.agent_access_requests); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.agent_access_waits(r public.agent_access_requests) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
 select r.state='asked' and public.can_open_agent_for(r.company_id,r.agent_id,r.asked_by)
  and not public.agent_visible_to(r.company_id,r.asked_by,r.agent_id)
  and not exists(select 1 from public.agent_access_requests e where e.company_id=r.company_id and e.asked_by=r.asked_by and e.agent_id=r.agent_id
   and e.state='asked' and e.id<r.id);
$$;

ALTER FUNCTION public.agent_access_waits(r public.agent_access_requests) OWNER TO postgres;

--
-- Name: agent_ask_to_open(uuid, text, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.agent_ask_to_open(conversation uuid, run text, call text, job text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare talk public.conversations; target public.hermes_agents; kept public.agent_access_requests; named uuid;
begin
 select * into kept from public.agent_access_requests r where r.conversation_id=conversation and r.run_id=run and r.call_id=call;
 if found then return jsonb_build_object('state','shown','card',kept.id); end if;
 select * into talk from public.conversations where id=conversation;
 if not found or talk.agent_id is null
  or not exists(select 1 from public.conversation_messages m where m.conversation_id=conversation and m.author='person' and m.run_id=run)
  or not public.may_ask_to_open_agents(talk.company_id,talk.agent_id,talk.person_id) then return jsonb_build_object('state','refused'); end if;
 if nullif(btrim(coalesce(job,'')),'') is null or length(job)>200 then return jsonb_build_object('state','invalid'); end if;
 select * into target from public.agents_hidden_from(talk.company_id,talk.person_id) a
  where lower(btrim(a.speciality))=lower(btrim(job)) order by a.id limit 1;
 if not found then return jsonb_build_object('state','ignored'); end if;
 named:=public.agent_access_named(talk.company_id,talk.person_id,target.id);
 if named is null then return jsonb_build_object('state','ignored'); end if;
 insert into public.agent_access_requests(company_id,conversation_id,run_id,call_id,agent_id,asked_by,named_to)
  values(talk.company_id,conversation,run,call,target.id,talk.person_id,named)
  on conflict (conversation_id,run_id,call_id) do nothing returning * into kept;
 if kept.id is null then
  select * into kept from public.agent_access_requests r where r.conversation_id=conversation and r.run_id=run and r.call_id=call;
 end if;
 return jsonb_build_object('state','shown','card',kept.id);
end $$;

ALTER FUNCTION public.agent_ask_to_open(conversation uuid, run text, call text, job text) OWNER TO postgres;

--
-- Name: agent_change_listed(text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.agent_change_listed(change text, setting text) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
 select case change
  when 'model' then setting is null
  when 'instructions' then setting is null
  when 'toolset' then setting='delegation'
  when 'setting' then setting in ('delegation.model','delegation.provider','delegation.max_concurrent_children','delegation.reasoning_effort',
   'delegation.max_spawn_depth','memory.memory_enabled','memory.memory_char_limit','memory.write_approval','skills.write_approval',
   'display.personality','timezone','agent.reasoning_effort','tts.speed','stt.language')
  else false end;
$$;

ALTER FUNCTION public.agent_change_listed(change text, setting text) OWNER TO postgres;

--
-- Name: agent_change_value_valid(text, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.agent_change_value_valid(change text, value jsonb) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $_$
 select coalesce(case change
  when 'model' then jsonb_typeof(value)='string' and value#>>'{}' ~ '^[a-z0-9][a-z0-9._-]{0,63}/[^\s/][^\s]{0,199}$'
  when 'instructions' then jsonb_typeof(value)='string' and length(value#>>'{}') between 1 and 20000
  when 'toolset' then jsonb_typeof(value)='boolean'
  when 'setting' then jsonb_typeof(value) in ('string','number','boolean') and length(value#>>'{}')<=500 and not public.secret_like(value#>>'{}')
  else false end,false);
$_$;

ALTER FUNCTION public.agent_change_value_valid(change text, value jsonb) OWNER TO postgres;

