--
-- Name: agent_look_auto(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.agent_look_auto(c uuid, template text) RETURNS TABLE(colour text, temperament text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
 with used as (select l.colour,l.temperament from public.agent_looks l where l.company_id=c and public.agent_look_in_use(l))
 select
  (select o.k from unnest(public.agent_look_choices('colour')) with ordinality o(k,n)
    order by (select count(*) from used u where u.colour=o.k),o.k='indigo',o.n limit 1),
  coalesce(public.agent_role_temperament(template),
   (select o.k from unnest(public.agent_look_choices('temperament')) with ordinality o(k,n)
     order by (select count(*) from used u where u.temperament=o.k),o.n limit 1));
$$;

ALTER FUNCTION public.agent_look_auto(c uuid, template text) OWNER TO postgres;

--
-- Name: agent_look_choices(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.agent_look_choices(part text) RETURNS text[]
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
 select case part when 'shape' then array['circle','squircle','blob']
  when 'colour' then array['indigo','violet','sky','teal','jade','rose','dusk','slate']
  when 'temperament' then array['calm','energetic','warm','dreamy','neat','caring'] end;
$$;

ALTER FUNCTION public.agent_look_choices(part text) OWNER TO postgres;

--
-- Name: agent_looks; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.agent_looks (
    agent_id uuid NOT NULL,
    company_id uuid NOT NULL,
    request_id bigint,
    auto_shape text NOT NULL,
    auto_colour text NOT NULL,
    auto_temperament text NOT NULL,
    picked_shape text,
    picked_colour text,
    picked_temperament text,
    shape text GENERATED ALWAYS AS (COALESCE(picked_shape, auto_shape)) STORED,
    colour text GENERATED ALWAYS AS (COALESCE(picked_colour, auto_colour)) STORED,
    temperament text GENERATED ALWAYS AS (COALESCE(picked_temperament, auto_temperament)) STORED,
    given_at timestamp with time zone DEFAULT now() NOT NULL,
    changed_at timestamp with time zone,
    kept_name text,
    CONSTRAINT agent_looks_auto_colour_check CHECK ((auto_colour = ANY (public.agent_look_choices('colour'::text)))),
    CONSTRAINT agent_looks_auto_shape_check CHECK ((auto_shape = ANY (public.agent_look_choices('shape'::text)))),
    CONSTRAINT agent_looks_auto_temperament_check CHECK ((auto_temperament = ANY (public.agent_look_choices('temperament'::text)))),
    CONSTRAINT agent_looks_picked_colour_check CHECK ((picked_colour = ANY (public.agent_look_choices('colour'::text)))),
    CONSTRAINT agent_looks_picked_shape_check CHECK ((picked_shape = ANY (public.agent_look_choices('shape'::text)))),
    CONSTRAINT agent_looks_picked_temperament_check CHECK ((picked_temperament = ANY (public.agent_look_choices('temperament'::text))))
);

ALTER TABLE public.agent_looks OWNER TO postgres;

--
-- Name: agent_look_in_use(public.agent_looks); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.agent_look_in_use(look public.agent_looks) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
 select exists(select 1 from public.hermes_agents a where a.id=look.agent_id and a.company_id=look.company_id)
  or exists(select 1 from public.lead_agent_requests r where r.id=look.request_id and r.state='waiting');
$$;

ALTER FUNCTION public.agent_look_in_use(look public.agent_looks) OWNER TO postgres;

--
-- Name: agent_may_move(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.agent_may_move(agent uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
 select exists(select 1 from public.hermes_agents a
  where a.id=agent and a.profile=public.company_engine_profile(a.company_id)
   and a.id is distinct from public.company_profile_keeper(a.company_id)
   and exists(select 1 from public.members m where m.company_id=a.company_id and m.role='owner' and m.removed_at is null));
$$;

ALTER FUNCTION public.agent_may_move(agent uuid) OWNER TO postgres;

--
-- Name: agent_move_blocked(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.agent_move_blocked(agent uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
 select exists(select 1 from public.conversation_messages m join public.conversations cv on cv.id=m.conversation_id
   where cv.agent_id=agent and m.author='person'
    and not exists(select 1 from public.conversation_messages r where r.conversation_id=m.conversation_id and r.author='agent' and r.run_id=m.run_id)
    and not exists(select 1 from public.conversation_run_ends u where u.conversation_id=m.conversation_id and u.run_id=m.run_id)
    and not exists(select 1 from public.agent_handovers h where h.conversation_id=m.conversation_id and h.run_id=m.run_id and h.answers_person))
  or exists(select 1 from public.conversation_run_reservations r where r.agent_id=agent and r.abandoned_at is null)
  or exists(select 1 from public.channel_runs r where r.agent_id=agent and r.outcome is null)
  or exists(select 1 from public.note_runs r where r.agent_id=agent and r.outcome is null)
  or exists(select 1 from public.conversation_messages m join public.conversations cv on cv.id=m.conversation_id
   where cv.agent_id=agent and m.created_at>now()-interval '5 minutes')
  or exists(select 1 from public.agent_handovers h where h.state not in ('done','failed')
   and ((h.to_agent=agent and (h.state in ('target','answering') or h.state='waiting' and h.target_attempts>0 or h.state='handing' and h.answer_attempts>0))
    or (h.from_agent=agent and (h.state='follow_up' or h.state='returning' and h.return_attempts>0))));
$$;

ALTER FUNCTION public.agent_move_blocked(agent uuid) OWNER TO postgres;

--
-- Name: agent_move_work(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.agent_move_work() RETURNS TABLE(agent_id uuid, company_id uuid, profile text, instructions text, subagents boolean, recorded boolean)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
 select a.id,a.company_id,public.agent_engine_profile(a.id),a.instructions,
  coalesce((select p.subagents from public.agent_profiles p where p.agent_id=a.id),false),
  exists(select 1 from public.agent_profiles p where p.agent_id=a.id)
 from public.hermes_agents a
 where public.company_profile_ready(a.company_id) and public.agent_may_move(a.id) and not public.agent_move_blocked(a.id)
 order by md5(a.id::text||date_trunc('minute',now())::text)
 limit 100;
$$;

ALTER FUNCTION public.agent_move_work() OWNER TO postgres;

--
-- Name: agent_open_run(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.agent_open_run(c uuid, agent uuid) RETURNS TABLE(started_at timestamp with time zone, my_conversation uuid)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
 select m.created_at,case when cv.person_id=auth.uid() then cv.id end
 from public.conversations cv
 cross join lateral public.conversation_open_run(cv.id) o
 join public.conversation_messages m on m.id=o.message
 where cv.company_id=c and cv.agent_id=agent and public.can_see_agent(c,agent)
 order by m.created_at desc,m.id desc limit 1;
$$;

ALTER FUNCTION public.agent_open_run(c uuid, agent uuid) OWNER TO postgres;

--
-- Name: agent_permission_grants(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.agent_permission_grants(c uuid, agent uuid) RETURNS TABLE(entry text, allowed_by text, allowed_at timestamp with time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
 select distinct on (g.entry) g.entry,p.name,g.at from (
  select a entry,r.decided_by who,r.decided_at at from public.reply_cards r join public.conversations v on v.id=r.conversation_id and v.company_id=r.company_id
   cross join unnest(r.allows) a
   where r.company_id=c and v.agent_id=agent and r.kind='permission' and r.state='decided' and r.content->>'choice'='always'
  union all
  select a,q.decided_by,q.decided_at from public.channel_permissions q join public.channel_runs u on u.message_id=q.message_id and u.run_id=q.run_id
   cross join unnest(q.allows) a
   where q.company_id=c and u.agent_id=agent and q.state='decided' and q.content->>'choice'='always'
 ) g join public.people p on p.id=g.who
 where not exists(select 1 from public.agent_permission_revoked x where x.agent_id=agent and x.company_id=c and x.entry=g.entry and x.revoked_at>=g.at)
  and public.is_member(c) and public.can_see_agent(c,agent) and exists(select 1 from public.hermes_agents h where h.id=agent and h.company_id=c)
 order by g.entry,g.at desc;
$$;

ALTER FUNCTION public.agent_permission_grants(c uuid, agent uuid) OWNER TO postgres;

--
-- Name: agent_permission_inflight(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.agent_permission_inflight(c uuid, agent uuid) RETURNS SETOF text
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
 perform public.check_permission_revoke(c,agent);
 return query select distinct g.entry from (
  select a entry,r.decided_at at from public.reply_cards r join public.conversations v on v.id=r.conversation_id and v.company_id=r.company_id
   cross join unnest(r.allows) a
   where r.company_id=c and v.agent_id=agent and r.kind='permission' and r.content->>'choice'='always'
    and r.state='decided' and r.decided_at>now()-interval '5 minutes'
  union all
  select a,q.decided_at from public.channel_permissions q join public.channel_runs u on u.message_id=q.message_id and u.run_id=q.run_id
   cross join unnest(q.allows) a
   where q.company_id=c and u.agent_id=agent and q.content->>'choice'='always'
    and q.state='decided' and q.decided_at>now()-interval '5 minutes'
 ) g
 where not exists(select 1 from public.agent_permission_revoked x where x.agent_id=agent and x.company_id=c and x.entry=g.entry and x.revoked_at>=g.at);
end $$;

ALTER FUNCTION public.agent_permission_inflight(c uuid, agent uuid) OWNER TO postgres;

--
-- Name: agent_permission_sending(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.agent_permission_sending(c uuid, agent uuid) RETURNS TABLE(entry text, handed boolean)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
#variable_conflict use_column
begin
 perform public.check_permission_revoke(c,agent);
 -- A request kept before this migration has no `allows`: its entry is unknown (null), and a revoke waits for it as for
 -- one of its own entry (Codex on #499).
 return query select g.entry,bool_or(g.handed) from (
  select a entry,coalesce(r.delivering_at>now()-interval '15 seconds',false) handed from public.reply_cards r
   join public.conversations v on v.id=r.conversation_id and v.company_id=r.company_id
   cross join unnest(coalesce(r.allows,array[null::text])) a
   where r.company_id=c and v.agent_id=agent and r.kind='permission' and r.state='sending' and r.content->>'choice'='always'
  union all
  select a,coalesce(q.delivering_at>now()-interval '15 seconds',false) from public.channel_permissions q
   join public.channel_runs u on u.message_id=q.message_id and u.run_id=q.run_id
   cross join unnest(coalesce(q.allows,array[null::text])) a
   where q.company_id=c and u.agent_id=agent and q.state='sending' and q.content->>'choice'='always'
 ) g group by g.entry;
end $$;

ALTER FUNCTION public.agent_permission_sending(c uuid, agent uuid) OWNER TO postgres;

--
-- Name: agent_profile_refusal(text, uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.agent_profile_refusal(engine_profile text, c uuid, agent uuid) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $_$
 select case
  when coalesce(engine_profile,'') ~ '^cs-[0-9a-f]{32}$' then 'hermesProfileNotShared'
  when coalesce(engine_profile,'') !~ '^ag-[0-9a-f]{32}$' then null
  when not exists(select 1 from public.agent_profiles p where p.profile=engine_profile and p.agent_id=agent and p.company_id=c) then 'hermesProfileNotShared'
  when exists(select 1 from public.agent_key_waits w where w.agent_id=agent and w.company_id=c) and public.company_holds_provider_key(c) then 'agentToolsPending'
  when not exists(select 1 from public.agent_profiles p
   where p.agent_id=agent and p.company_id=c and p.tools_confirmed and not p.tools_pending and (p.skills_shared or not public.shared_skills_active(c))) then 'agentToolsPending'
 end;
$_$;

ALTER FUNCTION public.agent_profile_refusal(engine_profile text, c uuid, agent uuid) OWNER TO postgres;

--
-- Name: agent_profile_work(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.agent_profile_work() RETURNS TABLE(agent_id uuid, company_id uuid, profile text, tools_confirmed boolean, tools_pending boolean, instructions text, subagents boolean)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
 select p.agent_id,p.company_id,p.profile,p.tools_confirmed,p.tools_pending,a.instructions,p.subagents
 from public.agent_profiles p join public.hermes_agents a on a.id=p.agent_id and a.company_id=p.company_id
 where not p.tools_confirmed or p.tools_pending
 order by p.tools_confirmed,md5(p.agent_id::text||date_trunc('minute',now())::text)
 limit 100;
$$;

ALTER FUNCTION public.agent_profile_work() OWNER TO postgres;

--
-- Name: agent_propose_change(uuid, text, text, text, text, text, jsonb, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.agent_propose_change(conversation uuid, run text, call text, agent_name text, change text, setting text, value jsonb, reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare talk public.conversations; target public.hermes_agents; kept public.agent_change_proposals; said text:=btrim(coalesce(reason,''),E' \t\r\n');
 listed boolean;
begin
 select * into kept from public.agent_change_proposals p where p.conversation_id=conversation and p.run_id=run and p.call_id=call;
 if found then return jsonb_build_object('state',case when kept.state='refused' then 'refused' else 'proposed' end,'proposal',kept.id); end if;
 select * into talk from public.conversations where id=conversation;
 if not found or talk.agent_id is null
  or not exists(select 1 from public.conversation_messages m where m.conversation_id=conversation and m.author='person' and m.run_id=run)
  or not public.may_propose_agent_change(talk.company_id,talk.agent_id,talk.person_id) then return jsonb_build_object('state','refused'); end if;
 if length(said) not between 1 and 500 or change not in ('model','instructions','toolset','setting') or value is null
  or (setting is not null and setting !~ '^[a-zA-Z0-9][a-zA-Z0-9_.-]{0,119}$') then return jsonb_build_object('state','invalid'); end if;
 if nullif(btrim(coalesce(agent_name,'')),'') is null then
  select * into target from public.hermes_agents a where a.id=talk.agent_id;
 else
  select * into target from public.hermes_agents a
   where a.company_id=talk.company_id and lower(btrim(a.name))=lower(btrim(agent_name)) and public.agent_visible_to(talk.company_id,talk.person_id,a.id)
   order by (a.id=talk.agent_id) desc, a.id limit 1;
  if not found or (target.id<>talk.agent_id and not public.is_company_lead(talk.company_id,talk.agent_id)) then return jsonb_build_object('state','ignored'); end if;
 end if;
 listed:=public.agent_change_listed(change,setting);
 -- A listed change whose value does not read keeps nothing, so the Agent can propose it again correctly.
 if listed and not public.agent_change_value_valid(change,value) then return jsonb_build_object('state','invalid'); end if;
 insert into public.agent_change_proposals(company_id,conversation_id,run_id,call_id,agent_id,proposed_by,asked_by,change,setting,value,reason,state)
  values(talk.company_id,conversation,run,call,target.id,talk.agent_id,talk.person_id,change,setting,value,said,case when listed then 'waiting' else 'refused' end)
  on conflict (conversation_id,run_id,call_id) do nothing returning * into kept;
 if kept.id is null then
  select * into kept from public.agent_change_proposals p where p.conversation_id=conversation and p.run_id=run and p.call_id=call;
 elsif kept.state='waiting' then
  -- The Agent that proposed is the row's actor, as for a card it shows (log_agent_event names people only).
  insert into public.company_log(company_id,actor_id,actor_kind,actor_name,subject,agent_id,action,details,source,source_id,created_at)
   values(talk.company_id,talk.agent_id,'agent',(select a.name from public.hermes_agents a where a.id=talk.agent_id),'agent',target.id,'agent_change_proposed',
    jsonb_strip_nulls(jsonb_build_object('agent_name',target.name,'setting',coalesce(setting,change),'new',case when change='instructions' then null else value end,
     'reason',said,'private','owners','teller',talk.person_id)),
    'hermes_agent_audit',nextval('public.agent_log_ids'),now());
 end if;
 return jsonb_build_object('state',case when kept.state='refused' then 'refused' else 'proposed' end,'proposal',kept.id);
end $_$;

ALTER FUNCTION public.agent_propose_change(conversation uuid, run text, call text, agent_name text, change text, setting text, value jsonb, reason text) OWNER TO postgres;

--
-- Name: agent_role_temperament(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.agent_role_temperament(template text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
 select case template when 'meta' then 'energetic' when 'hook' then 'caring' when 'writer' then 'dreamy'
  when 'numbers' then 'neat' when 'coder' then 'calm' end;
$$;

ALTER FUNCTION public.agent_role_temperament(template text) OWNER TO postgres;

