 select '{}'::text[];
$$;

ALTER FUNCTION public.agent_rules_in_force(agent uuid) OWNER TO postgres;

--
-- Name: agent_run_facts(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.agent_run_facts(c uuid, agent uuid) RETURNS TABLE(working boolean, started_at timestamp with time zone, worked_at timestamp with time zone, ended_at timestamp with time zone, outcome text, at_conversation uuid, at_channel uuid, at_card bigint, followed boolean)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
 with chats as (select cv.id, cv.person_id from public.conversations cv where cv.company_id=c and cv.agent_id=agent),
 -- The reader's ended Runs they can see: their own Conversations', the channels they are in, the notes of the Cards
 -- they see (can_see_card), and the
 -- Handover legs of the Agent in those places. A Conversation's Run another Agent answered by a Handover is that
 -- Agent's leg, not this one's.
 seen as (
  select e.recorded_at at, e.outcome, cv.id conversation, null::uuid channel, null::bigint card
   from chats cv join public.conversation_run_ends e on e.conversation_id=cv.id
   where cv.person_id=auth.uid()
    and not exists(select 1 from public.agent_handovers h where h.conversation_id=cv.id and h.run_id=e.run_id and h.answers_person)
  union all
  select r.closed_at, r.outcome, null, r.channel_id, null from public.channel_runs r
   where r.company_id=c and r.agent_id=agent and r.outcome is not null and public.in_channel(r.channel_id)
  union all
  select n.closed_at, n.outcome, null, null, n.card_id from public.note_runs n
   where n.company_id=c and n.agent_id=agent and n.outcome is not null and public.can_see_card(c, n.card_id)
  union all
  select coalesce(h.target_closed_at, h.closed_at), h.target_outcome, v.id, m.channel_id, null from public.agent_handovers h
   left join public.conversations v on v.id=h.conversation_id and v.person_id=auth.uid()
   left join public.channel_messages m on m.id=h.channel_message_id and public.in_channel(m.channel_id)
   where h.company_id=c and h.to_agent=agent and h.target_outcome is not null and (v.id is not null or m.id is not null)
  union all
  select h.closed_at, h.follow_up_outcome, v.id, m.channel_id, null from public.agent_handovers h
   left join public.conversations v on v.id=h.conversation_id and v.person_id=auth.uid()
   left join public.channel_messages m on m.id=h.channel_message_id and public.in_channel(m.channel_id)
   where h.company_id=c and h.from_agent=agent and h.follow_up_outcome is not null and h.closed_at is not null
    and (v.id is not null or m.id is not null)
 ),
 last_seen as (select * from seen where at is not null order by at desc limit 1),
 starts as (
  select max(m.created_at) at from chats cv join public.conversation_messages m on m.conversation_id=cv.id
   where m.author='person' and m.run_id is not null
  union all select max(r.created_at) from public.channel_runs r where r.company_id=c and r.agent_id=agent
  union all select max(n.created_at) from public.note_runs n where n.company_id=c and n.agent_id=agent
  union all select max(greatest(h.created_at, h.return_started_at, h.answer_started_at)) from public.agent_handovers h
   where h.company_id=c and (h.to_agent=agent or h.from_agent=agent)
  union all select max(r.started_at) from public.routine_runs_open r where r.company_id=c and r.agent_id=agent
 ),
 ends as (
  select max(e.recorded_at) at from chats cv join public.conversation_run_ends e on e.conversation_id=cv.id
  union all select max(r.closed_at) from public.channel_runs r where r.company_id=c and r.agent_id=agent
  union all select max(n.closed_at) from public.note_runs n where n.company_id=c and n.agent_id=agent
  union all select max(greatest(h.closed_at, h.target_closed_at)) from public.agent_handovers h
   where h.company_id=c and (h.to_agent=agent or h.from_agent=agent)
  union all select max(r.ended_at) from public.routine_results r where r.company_id=c and r.agent_id=agent
 )
 select
  exists(select 1 from chats cv cross join lateral public.conversation_open_run(cv.id))
   -- A channel message's Agents go one after another (#152): an Agent whose turn waits behind an earlier open one is
   -- not working yet.
   or exists(select 1 from public.channel_runs r where r.company_id=c and r.agent_id=agent and r.outcome is null
    and not exists(select 1 from public.channel_runs q where q.message_id=r.message_id and q.outcome is null and q.ordinal<r.ordinal))
   or exists(select 1 from public.note_runs n where n.company_id=c and n.agent_id=agent and n.outcome is null)
   or exists(select 1 from public.agent_handovers h where h.company_id=c
    and (h.to_agent=agent and h.state in ('waiting','target') or h.from_agent=agent and h.state in ('returning','follow_up')))
   or exists(select 1 from public.routine_runs_open r where r.company_id=c and r.agent_id=agent and r.seen_at > now() - interval '2 minutes'),
  (select max(at) from starts),
  greatest((select max(at) from starts), (select max(at) from ends)),
  l.at, l.outcome, l.conversation, l.channel, l.card,
  case when l.at is null then false
   when l.conversation is not null then exists(select 1 from public.conversation_messages m
    where m.conversation_id=l.conversation and m.author='person' and m.created_at>l.at)
   when l.channel is not null then exists(select 1 from public.channel_messages m
    where m.channel_id=l.channel and m.author='person' and m.created_at>l.at)
   else exists(select 1 from public.work_comments w
    where w.company_id=c and w.card_id=l.card and w.author_id is not null and w.created_at>l.at) end
 from (select 1) one left join last_seen l on true
 where public.can_see_agent(c, agent);
$$;

ALTER FUNCTION public.agent_run_facts(c uuid, agent uuid) OWNER TO postgres;

--
-- Name: agent_save_rule(uuid, text, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.agent_save_rule(conversation uuid, run text, call text, rule text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare talk public.conversations; said text:=btrim(rule,E' \t\r\n'); kept public.agent_rules; asked text;
begin
 select * into kept from public.agent_rules r where r.conversation_id=conversation and r.run_id=run and r.call_id=call;
 if not found then
  select * into talk from public.conversations where id=conversation;
  if not found or not exists(select 1 from public.conversation_messages m where m.conversation_id=conversation and m.author='person' and m.run_id=run) then
   return jsonb_build_object('state','refused'); end if;
  if public.may_suggest_agent_rules(talk.company_id,talk.agent_id,talk.person_id) then asked:='pending';
  elsif not public.may_tell_agent_rules(talk.company_id,talk.agent_id,talk.person_id) then return jsonb_build_object('state','refused'); end if;
  if coalesce(length(said) between 1 and 500,false) is not true then return jsonb_build_object('state','invalid'); end if;
  -- A lasting rule is the person's whole message of that run (#18).
  if not exists(select 1 from public.conversation_messages m where m.conversation_id=conversation and m.author='person' and m.run_id=run
   and public.rule_words(m.body)=public.rule_words(said)) then
   return jsonb_build_object('state','refused');
  end if;
  insert into public.agent_rules(company_id,agent_id,body,said_by,conversation_id,run_id,call_id,suggestion)
   values(talk.company_id,talk.agent_id,said,talk.person_id,conversation,run,call,asked)
   on conflict (conversation_id,run_id,call_id) do nothing returning * into kept;
  if kept.id is null then
   select * into kept from public.agent_rules r where r.conversation_id=conversation and r.run_id=run and r.call_id=call;
  else
   insert into public.waiting_items(company_id,person_id,kind,title,body,asked_by,agent_rule_id)
    select talk.company_id,m.person_id,'rule_suggestion',left(said,300),coalesce((select a.name from public.hermes_agents a where a.id=talk.agent_id),''),
     left(coalesce((select p.name from public.people p where p.id=talk.person_id),''),120),kept.id
    from public.members m where asked is not null and m.company_id=talk.company_id and public.may_tell_agent_rules(talk.company_id,talk.agent_id,m.person_id);
   perform public.log_agent_event(talk.company_id,talk.person_id,(select name from public.people where id=talk.person_id),talk.agent_id,
     case when asked is null then 'AGENT_RULE_SAVED' else 'AGENT_RULE_SUGGESTED' end,
     jsonb_build_object('rule',said,'rule_id',kept.id,'conversation_id',conversation)||case when asked is null then '{}'::jsonb else jsonb_build_object('private',true,'teller',talk.person_id) end);
  end if;
 end if;
 return jsonb_build_object('state',case when kept.suggestion is null then 'saved' else 'suggested' end,'rule',kept.id);
end $$;

ALTER FUNCTION public.agent_save_rule(conversation uuid, run text, call text, rule text) OWNER TO postgres;

--
-- Name: agent_show_card(uuid, text, text, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.agent_show_card(conversation uuid, run text, call text, kind text, title text, content jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare talk public.conversations; kept public.reply_cards; opened text:=case when kind in ('hand','connect') then 'open' else 'shown' end;
begin
 select * into kept from public.reply_cards r where r.conversation_id=conversation and r.run_id=run and r.call_id=call;
 if found then return jsonb_build_object('state','shown','card',kept.id); end if;
 select * into talk from public.conversations where id=conversation;
 if not found or not exists(select 1 from public.conversation_messages m where m.conversation_id=conversation and m.author='person' and m.run_id=run)
  or not public.may_show_reply_cards(talk.company_id,talk.agent_id,talk.person_id)
  or opened='open' and exists(select 1 from public.stopped_runs s where s.conversation_id=conversation and s.run_id=run) then return jsonb_build_object('state','refused'); end if;
 if not (public.reply_card_text(to_jsonb(title),100) and public.reply_card_valid(kind,opened,content)) then return jsonb_build_object('state','invalid'); end if;
 insert into public.reply_cards(company_id,conversation_id,run_id,call_id,kind,title,content,state)
  values(talk.company_id,conversation,run,call,kind,title,content,opened)
  on conflict (conversation_id,run_id,call_id) do nothing returning * into kept;
 if kept.id is null then
  select * into kept from public.reply_cards r where r.conversation_id=conversation and r.run_id=run and r.call_id=call;
 elsif kept.kind not in ('hand','connect') then
  perform public.log_chat_event(conversation,talk.agent_id,'agent',(select name from public.hermes_agents where id=talk.agent_id),'agent_card_shown',
   jsonb_build_object('card',jsonb_build_object('kind',kept.kind,'title',kept.title)||case when kept.kind='review' then
     (select jsonb_build_object('fine',count(*) filter (where i->'fine'='true'::jsonb),'edits',count(*) filter (where i->'fine'='false'::jsonb))
      from jsonb_array_elements(kept.content->'items') i) else '{}'::jsonb end),
   talk.person_id,'reply_cards',kept.id,kept.created_at);
 end if;
 return jsonb_build_object('state','shown','card',kept.id);
end $$;

ALTER FUNCTION public.agent_show_card(conversation uuid, run text, call text, kind text, title text, content jsonb) OWNER TO postgres;

--
-- Name: agent_soul_rules_all(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.agent_soul_rules_all() RETURNS TABLE(company_id uuid, profile text, rules jsonb)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
 select x.company_id,x.profile,coalesce((select jsonb_agg(r.body order by r.said_at,r.id) from public.agent_rules r
   where r.agent_id=x.id and r.removed_at is null and (r.suggestion is null or r.suggestion='approved')),'[]')
 from (select a.id,a.company_id,coalesce((select p.profile from public.agent_profiles p where p.agent_id=a.id and (p.tools_confirmed or p.tools_pending)),
   case when a.is_default then (select c.profile from public.company_profiles c where c.company_id=a.company_id) end) as profile
  from public.hermes_agents a) x
 where x.profile is not null
 order by x.company_id,x.profile;
$$;

ALTER FUNCTION public.agent_soul_rules_all() OWNER TO postgres;

--
-- Name: agent_soul_rules_work(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.agent_soul_rules_work() RETURNS TABLE(company_id uuid, profile text, rules jsonb)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
 select x.company_id,x.profile,coalesce((select jsonb_agg(r.body order by r.said_at,r.id) from public.agent_rules r
   where r.agent_id=x.id and r.removed_at is null and (r.suggestion is null or r.suggestion='approved')),'[]')
 from (select a.id,a.company_id,coalesce((select p.profile from public.agent_profiles p where p.agent_id=a.id and (p.tools_confirmed or p.tools_pending)),
   case when a.is_default then (select c.profile from public.company_profiles c where c.company_id=a.company_id) end) as profile
  from public.hermes_agents a) x
 where x.profile is not null
 order by md5(x.id::text||date_trunc('minute',now())::text)
 limit 100;
$$;

ALTER FUNCTION public.agent_soul_rules_work() OWNER TO postgres;

--
-- Name: agent_states(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.agent_states(c uuid) RETURNS TABLE(agent uuid, running boolean, waiting_mine boolean)
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
 with mine as (select distinct w.card_id from public.waiting_list(c) w where w.card_id is not null)
 select h.id,exists(select 1 from public.agent_open_run(c,h.id)),
  exists(select 1 from public.work_cards k join mine on mine.card_id=k.id where k.company_id=c and k.agent_id=h.id)
 from public.hermes_agents h where h.company_id=c and public.can_see_agent(c,h.id);
$$;

ALTER FUNCTION public.agent_states(c uuid) OWNER TO postgres;

--
-- Name: agent_visible_to(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.agent_visible_to(c uuid, person uuid, agent uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
 select agent is null
  or not exists(select 1 from public.hermes_agents h where h.id=agent and h.company_id=c and not h.is_default)
  or exists(select 1 from public.members m where m.company_id=c and m.person_id=person and m.removed_at is null and m.role='owner')
  or exists(select 1 from public.member_agent_access a where a.company_id=c and a.person_id=person and a.agent_id=agent);
$$;

ALTER FUNCTION public.agent_visible_to(c uuid, person uuid, agent uuid) OWNER TO postgres;

--
-- Name: agent_work(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.agent_work(c uuid) RETURNS TABLE(agent uuid, working boolean, failed_at timestamp with time zone, failed_conversation uuid, failed_channel uuid, failed_card bigint, last_work_at timestamp with time zone, created_at timestamp with time zone, woken_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    SET plan_cache_mode TO 'force_generic_plan'
    AS $$
#variable_conflict use_column
declare reader uuid := auth.uid();
begin
 if reader is null or not public.is_member(c) then return; end if;
 return query
 with seen_agents as (
  select h.id, h.created_at from public.hermes_agents h where h.company_id=c and public.can_see_agent(c, h.id)
 ),
 chats as (
  select cv.id, cv.agent_id, cv.person_id, cv.open_runs, cv.last_message_at from public.conversations cv join seen_agents a on a.id=cv.agent_id where cv.company_id=c
 ),
 -- The channels the reader is in, asked once each.
 my_channels as (select k.id from public.channels k where k.company_id=c and public.in_channel(k.id)),
 -- A Conversation's person's messages, each with whether its Run is still open (conversation_open_run's rule).
 asked as (
  select cv.agent_id, m.created_at, m.run_id,
   not exists(select 1 from public.conversation_messages r where r.conversation_id=m.conversation_id and r.author='agent' and r.run_id=m.run_id)
   and not exists(select 1 from public.conversation_run_ends u where u.conversation_id=m.conversation_id and u.run_id=m.run_id)
   and not exists(select 1 from public.agent_handovers h where h.conversation_id=m.conversation_id and h.run_id=m.run_id and h.answers_person) open
  from chats cv join public.conversation_messages m on m.conversation_id=cv.id where m.author='person'
 ),
 channel_work as (
  select r.agent_id, r.message_id, r.ordinal, r.channel_id, r.created_at, r.closed_at, r.outcome from public.channel_runs r
  join seen_agents a on a.id=r.agent_id where r.company_id=c
 ),
 note_work as (
  select n.agent_id, n.card_id, n.created_at, n.closed_at, n.outcome from public.note_runs n
  join seen_agents a on a.id=n.agent_id where n.company_id=c
 ),
 -- A Handover's two Agents, each with the leg that is theirs: the target's, and the follow-up of the Agent that handed it
 -- (never the same Agent, agent_handovers_other_agent): whether it is under way, and how and when it ended.
 handed as (
  select a.id agent_id, h.conversation_id, h.channel_message_id, h.created_at, h.closed_at, h.target_closed_at,
   h.return_started_at, h.answer_started_at,
   case when a.id=h.to_agent then h.state in ('waiting','target') else h.state in ('returning','follow_up') end leg_open,
   case when a.id=h.to_agent then coalesce(h.target_closed_at, h.closed_at) else h.closed_at end leg_closed_at,
   case when a.id=h.to_agent then h.target_outcome
    when h.closed_at is not null then h.follow_up_outcome end leg_outcome
  from public.agent_handovers h join seen_agents a on a.id in (h.to_agent, h.from_agent) where h.company_id=c
 ),
 -- The Cards with an ended note Run the reader may see, asked once each.
 seen_cards as (
  select v.card_id from (select distinct card_id from note_work where outcome is not null) v where public.can_see_card(c, v.card_id)
 ),
 -- Every fact of work, one row each: whether it is open, when it began, when it ended.
 facts as (
  select agent_id, open, case when run_id is not null then created_at end began, null::timestamptz ended from asked
  union all select cv.agent_id, false, null, e.recorded_at from chats cv join public.conversation_run_ends e on e.conversation_id=cv.id
  -- A Conversation whose messages are the Engine's (#882): its row holds the Run it works on until that Run's end is seen,
  -- and its last message is when that work began.
  union all select cv.agent_id, true, cv.last_message_at, null from chats cv where cardinality(cv.open_runs)>0
  union all select w.agent_id, w.outcome is null
    and not exists(select 1 from public.channel_runs q where q.message_id=w.message_id and q.outcome is null and q.ordinal<w.ordinal),
   w.created_at, w.closed_at from channel_work w
  union all select agent_id, outcome is null, created_at, closed_at from note_work
  union all select agent_id, leg_open, greatest(created_at, return_started_at, answer_started_at), greatest(closed_at, target_closed_at)
   from handed
  union all select r.agent_id, r.seen_at > now() - interval '2 minutes', r.started_at, null from public.routine_runs_open r
   join seen_agents a on a.id=r.agent_id where r.company_id=c
  union all select r.agent_id, false, null, r.ended_at from public.routine_results r join seen_agents a on a.id=r.agent_id where r.company_id=c
 ),
 work as (
  select agent_id, bool_or(open) working, max(began) started_at, greatest(max(began), max(ended)) worked_at from facts group by agent_id
 ),
 -- The ended Runs the reader can see, each where it ran.
 seen as (
  select cv.agent_id, e.recorded_at at, e.outcome, cv.id conversation, null::uuid channel, null::bigint card
   from chats cv join public.conversation_run_ends e on e.conversation_id=cv.id
   where cv.person_id=reader
    and not exists(select 1 from public.agent_handovers h where h.conversation_id=cv.id and h.run_id=e.run_id and h.answers_person)
  union all
  select w.agent_id, w.closed_at, w.outcome, null, w.channel_id, null from channel_work w join my_channels k on k.id=w.channel_id
   where w.outcome is not null
  union all
  select n.agent_id, n.closed_at, n.outcome, null, null, n.card_id from note_work n join seen_cards v on v.card_id=n.card_id
   where n.outcome is not null
  union all
  select h.agent_id, h.leg_closed_at, h.leg_outcome, v.id, k.id, null from handed h
   left join public.conversations v on v.id=h.conversation_id and v.person_id=reader
   left join public.channel_messages m on m.id=h.channel_message_id
   left join my_channels k on k.id=m.channel_id
   where (v.id is not null or k.id is not null) and h.leg_outcome is not null
 ),
 last_seen as (select distinct on (s.agent_id) s.* from seen s where s.at is not null order by s.agent_id, s.at desc),
 facts_of as (
  select a.id, a.created_at, w.working, w.started_at, w.worked_at, l.at ended_at, l.outcome,
   l.conversation, l.channel, l.card,
   case when l.at is null then false
    when l.conversation is not null then exists(select 1 from public.conversation_messages m
     where m.conversation_id=l.conversation and m.author='person' and m.created_at>l.at)
    when l.channel is not null then exists(select 1 from public.channel_messages m
     where m.channel_id=l.channel and m.author='person' and m.created_at>l.at)
    else exists(select 1 from public.work_comments w
     where w.company_id=c and w.card_id=l.card and w.author_id is not null and w.created_at>l.at) end followed
  from seen_agents a left join work w on w.agent_id=a.id left join last_seen l on l.agent_id=a.id
 )
 select f.id, coalesce(f.working, false), s.at, s.conversation, s.channel, s.card, f.worked_at, f.created_at, k.woken_at
 from facts_of f
 left join public.agent_reader_marks k on k.person_id=reader and k.agent_id=f.id
 left join lateral (select f.ended_at at, f.conversation, f.channel, f.card
  where f.outcome not in ('completed','stopped') and not f.followed and f.ended_at > now() - interval '24 hours'
   and (f.started_at is null or f.started_at <= f.ended_at)
   and (k.failure_seen_at is null or k.failure_seen_at < f.ended_at)) s on true;
end $$;

ALTER FUNCTION public.agent_work(c uuid) OWNER TO postgres;

--
-- Name: agent_write(uuid, text, text, text, bigint, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.agent_write(c uuid, request_key text, fingerprint text, op text, card bigint, payload jsonb) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare existing public.agent_requests%rowtype; result jsonb; created bigint; ev text := payload->>'evidence'; begin
 if length(request_key)<1 or length(request_key)>200 then raise exception 'invalid idempotency key'; end if;
 -- A run key reaches its one card in the database as well as in the route.
 if auth.jwt()->>'run_card' is not null and card is distinct from (auth.jwt()->>'run_card')::bigint then raise exception 'not permitted'; end if;
 -- A row added to such a Card is refused by its read rule, where one added to a missing Card fails the foreign key. As
 -- id 0, which no Card has, it gets every answer a missing Card gets.
 if card is not null and not public.can_see_card(c,card) then card:=0; end if;
 perform pg_advisory_xact_lock(hashtextextended(c::text || auth.uid()::text || request_key,0));
 select * into existing from public.agent_requests r where r.company_id=c and r.person_id=auth.uid() and r.request_key=agent_write.request_key;
 if found then if existing.fingerprint<>fingerprint then raise exception 'idempotency key reused'; end if; return existing.result; end if;
 case op
 when 'create' then
  if payload ? 'message' then created=public.create_card_request(c,payload->>'message',(payload->>'agent')::uuid,payload->>'mode');
  else created=public.create_work_card(c,(payload->>'stage')::bigint,payload->>'title',coalesce(payload->>'template',''),ev); end if;
  result=jsonb_build_object('id',created);
 when 'idea' then created=public.create_work_card(c,(payload->>'stage')::bigint,payload->>'title',(payload->>'agent')::uuid); result=jsonb_build_object('id',created);
 when 'move' then perform public.move_work_card(c,card,(payload->>'stage')::bigint,ev); result='{}'::jsonb;
 when 'edit' then perform public.edit_work_card(c,card,payload->'fields',ev); result='{}'::jsonb;
 else
  if op in ('actor','assignee','label','check','comment','version','creative_with_version') then created=public.change_work_card(c,card,op,payload,ev); result=jsonb_build_object('id',created);
  else raise exception 'operation forbidden'; end if;
 end case;
 insert into public.agent_requests(company_id,person_id,request_key,fingerprint,result) values(c,auth.uid(),request_key,fingerprint,result);
 return result;
end $$;

ALTER FUNCTION public.agent_write(c uuid, request_key text, fingerprint text, op text, card bigint, payload jsonb) OWNER TO postgres;

--
-- Name: hermes_agents; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.hermes_agents (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    company_id uuid NOT NULL,
    connection_id uuid DEFAULT gen_random_uuid() NOT NULL,
    name text NOT NULL,
    speciality text NOT NULL,
    is_default boolean DEFAULT false NOT NULL,
    created_at timestamp with time zone DEFAULT now(),
    requested_by uuid,
    apps text[],
    requester_opened_at timestamp with time zone,
    template text,
    instructions text,
    profile text NOT NULL,
    requester_toasted_at timestamp with time zone,
    requester_born_at timestamp with time zone,
    CONSTRAINT hermes_agents_name_check CHECK (((length(TRIM(BOTH FROM name)) >= 1) AND (length(TRIM(BOTH FROM name)) <= 100))),
    CONSTRAINT hermes_agents_profile_name CHECK ((profile ~ '^[a-zA-Z0-9_-]{1,100}$'::text)),
    CONSTRAINT hermes_agents_speciality_check CHECK (((length(TRIM(BOTH FROM speciality)) >= 1) AND (length(TRIM(BOTH FROM speciality)) <= 200)))
);

ALTER TABLE public.hermes_agents OWNER TO postgres;

--
-- Name: agents_hidden_from(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.agents_hidden_from(c uuid, person uuid) RETURNS SETOF public.hermes_agents
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
 select a.* from public.hermes_agents a where a.company_id=c and not a.is_default and not public.agent_visible_to(c,person,a.id)
  and not exists(select 1 from public.hermes_agents v where v.company_id=c and v.id<>a.id and public.agent_visible_to(c,person,v.id)
   and lower(btrim(v.speciality))=lower(btrim(a.speciality)));
$$;

ALTER FUNCTION public.agents_hidden_from(c uuid, person uuid) OWNER TO postgres;

--
-- Name: answer_agent_access(uuid, bigint, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.answer_agent_access(c uuid, request bigint, open boolean) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare asked public.agent_access_requests; wanted text:=case when open then 'opened' when not open then 'declined' end; asker text;
begin
 if wanted is null then raise exception 'agentAccessAnswerMissing' using errcode='22023'; end if;
 -- Every request of that Member for that Agent is locked first, in one order, so two answers never wait on each other.
 select * into asked from public.agent_access_requests r where r.id=request and r.company_id=c;
 if not found then raise exception 'agentAccessNotFound' using errcode='P0002'; end if;
 perform 1 from public.agent_access_requests r where r.company_id=c and r.asked_by=asked.asked_by and r.agent_id=asked.agent_id order by r.id for update;
 select * into asked from public.agent_access_requests r where r.id=request;
 if not public.can_open_agent_for(c,asked.agent_id,asked.asked_by) then raise exception 'agentAccessNotAllowed' using errcode='42501'; end if;
 if not exists(select 1 from public.members m where m.company_id=c and m.person_id=asked.asked_by and m.removed_at is null) then
  raise exception 'agentAccessNotFound' using errcode='P0002'; end if;
 if asked.state=wanted then return wanted; end if;
 if asked.state<>'asked' then raise exception 'agentAccessAnswered' using errcode='22023'; end if;
 if open then perform public.set_agent_visible(c,asked.asked_by,asked.agent_id,true); end if;
 update public.agent_access_requests set state=wanted,answered_by=auth.uid(),answered_at=now()
  where company_id=c and asked_by=asked.asked_by and agent_id=asked.agent_id and state='asked';
 asker:=(select name from public.people where id=asked.asked_by);
 perform public.log_agent_event(c,auth.uid(),null,asked.agent_id,case when open then 'AGENT_OPENED_FOR' else 'AGENT_KEPT_HIDDEN' end,
  jsonb_strip_nulls(jsonb_build_object('asked_by',asker,'private',case when open then null else 'managers' end)));
 return wanted;
end $$;

ALTER FUNCTION public.answer_agent_access(c uuid, request bigint, open boolean) OWNER TO postgres;

--
-- Name: answer_agent_change(uuid, bigint, boolean, text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.answer_agent_change(c uuid, proposal bigint, approve boolean, reason text DEFAULT NULL::text, claim uuid DEFAULT NULL::uuid) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare asked public.agent_change_proposals; wanted text:=case when approve then 'approved' when not approve then 'declined' end;
 said text:=nullif(btrim(coalesce(reason,''),E' \t\r\n'),''); edited boolean;
begin
 if wanted is null then raise exception 'agentChangeAnswerMissing' using errcode='22023'; end if;
 if not public.is_company_owner(c) then raise exception 'agentChangeNotAllowed' using errcode='42501'; end if;
 select * into asked from public.agent_change_proposals p where p.id=proposal and p.company_id=c for update;
 if not found then raise exception 'agentChangeNotFound' using errcode='P0002'; end if;
 if asked.state=wanted then return wanted; end if;
 if approve and not (asked.state='applying' and asked.claimed_by=auth.uid() and asked.claim_token=claim) then
  raise exception '%',case asked.state when 'waiting' then 'agentChangeNotClaimed' when 'applying' then 'agentChangeBusy' else 'agentChangeAnswered' end using errcode='22023';
 end if;
 if not approve and asked.state='applying' and asked.claimed_at>now()-interval '5 minutes' then raise exception 'agentChangeApplying' using errcode='22023'; end if;
 if not approve and asked.state not in ('waiting','applying') then raise exception 'agentChangeAnswered' using errcode='22023'; end if;
 if said is not null and length(said)>1000 then raise exception 'agentChangeReasonLong' using errcode='22023'; end if;
 if not approve and said is null and not exists(select 1 from public.companies co where co.id=c and co.work_mode='alone') then
  raise exception 'agentChangeReasonMissing' using errcode='22023';
 end if;
 edited:=approve and asked.approved_value is not null;
 update public.agent_change_proposals set state=wanted,answered_by=auth.uid(),answered_at=now(),answer=case when approve then null else said end,
  maybe_applied=(not approve and asked.state='applying'),claim_token=null,claimed_at=null,claimed_by=null,
  approved_value=case when approve or asked.state='applying' then approved_value end where id=asked.id;
 perform public.log_agent_event(c,auth.uid(),null,asked.agent_id,case when approve then 'AGENT_CHANGE_APPROVED' else 'AGENT_CHANGE_DECLINED' end,
  jsonb_build_object('setting',coalesce(asked.setting,asked.change),
   'new',case when asked.change='instructions' then null when edited then asked.approved_value else asked.value end,
   'reason',case when approve then null else said end,'asked_by',(select a.name from public.hermes_agents a where a.id=asked.proposed_by),
   'private','owners','teller',asked.asked_by)
  ||case when edited then jsonb_build_object('edited',true,'proposed',case when asked.change='instructions' then null else asked.value end) else '{}'::jsonb end);
 return wanted;
end $$;

ALTER FUNCTION public.answer_agent_change(c uuid, proposal bigint, approve boolean, reason text, claim uuid) OWNER TO postgres;

--
-- Name: answer_agent_request(uuid, bigint, boolean, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.answer_agent_request(c uuid, request bigint, make boolean, reason text DEFAULT NULL::text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare asked public.lead_agent_requests; wanted text:=case when make then 'made' when not make then 'declined' end;
 said text:=nullif(btrim(reason,E' \t\r\n'),''); done jsonb; asker text;
begin
 if wanted is null then raise exception 'agentRequestAnswerMissing' using errcode='22023'; end if;
 if not public.is_company_owner(c) then raise exception 'agentRequestNotAllowed' using errcode='42501'; end if;
 select * into asked from public.lead_agent_requests r where r.id=request and r.company_id=c for update;
 if not found or not exists(select 1 from public.members m where m.company_id=c and m.person_id=asked.asked_by and m.removed_at is null) then
  raise exception 'agentRequestNotFound' using errcode='P0002';
 end if;
 if asked.state=wanted then return wanted; end if;
 if asked.state<>'waiting' then raise exception 'agentRequestAnswered' using errcode='22023'; end if;
 asker:=(select name from public.people where id=asked.asked_by);
 if make then
  update public.lead_agent_requests set state='made',answered_by=auth.uid(),answered_at=now() where id=asked.id;
  done:=public.lead_create_agent(asked.conversation_id,asked.run_id,asked.call_id,asked.agent_name,asked.job,asked.apps,asked.template,asked.instructions);
  if done->>'state' is distinct from 'created' then raise exception 'agentRequestNotMade' using errcode='55000'; end if;
  -- An Owner sees every Agent and never has a row (20261216150000).
  insert into public.member_agent_access(company_id,person_id,agent_id)
   select c,asked.asked_by,(done->>'agent')::uuid
   where not exists(select 1 from public.members m where m.company_id=c and m.person_id=asked.asked_by and m.role='owner' and m.removed_at is null)
   on conflict do nothing;
  perform public.log_agent_event(c,auth.uid(),(select name from public.people where id=auth.uid()),(done->>'agent')::uuid,'AGENT_REQUEST_MADE',jsonb_build_object('asked_by',asker,'request_id',asked.id));
 else
  if said is null or length(said)>1000 then raise exception 'agentRequestReasonMissing' using errcode='22023'; end if;
  update public.lead_agent_requests set state='declined',answered_by=auth.uid(),answered_at=now(),reason=said where id=asked.id;
  perform public.log_agent_event(c,auth.uid(),(select name from public.people where id=auth.uid()),(select v.agent_id from public.conversations v where v.id=asked.conversation_id),'AGENT_REQUEST_DECLINED',
    jsonb_build_object('asked_for',asked.agent_name,'asked_by',asker,'reason',said,'request_id',asked.id,'private','owners','teller',asked.asked_by));
 end if;
 return wanted;
end $$;

ALTER FUNCTION public.answer_agent_request(c uuid, request bigint, make boolean, reason text) OWNER TO postgres;

--
-- Name: answer_channel_question(uuid, uuid, bigint, integer, text, uuid, integer[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.answer_channel_question(c uuid, channel uuid, card bigint, choice integer, answer text, answer_key uuid, picks integer[] DEFAULT NULL::integer[]) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare asked public.reply_cards; m public.channel_messages; said jsonb;
begin
 if not public.conversation_can_write(c) then raise exception 'channelNotAllowed' using errcode='42501'; end if;
 if answer_key is null then raise exception 'questionAnswerInvalid' using errcode='22023'; end if;
 -- Picks are the whole answer.
 if picks is not null and (choice is not null or answer is not null) then raise exception 'questionAnswerInvalid' using errcode='22023'; end if;
 select * into asked from public.reply_cards r where r.id=card and r.kind='question' and r.channel_message_id is not null for update;
 if not found then raise exception 'channelNotFound' using errcode='P0002'; end if;
 select * into m from public.channel_messages where id=asked.channel_message_id;
 if m.id is null or m.company_id<>c or m.channel_id<>channel or not public.in_channel(channel) then
  raise exception 'channelNotFound' using errcode='P0002'; end if;
 if asked.addressed_to is not null and asked.addressed_to<>auth.uid() then
  raise exception 'channelNotAllowed' using errcode='42501'; end if;
 if asked.answer_key=answer_key then return 'claimed'; end if;
 if asked.state<>'open' then return case when asked.state='closed' then 'closed' else 'taken' end; end if;
 if not exists(select 1 from public.channel_runs r where r.message_id=asked.channel_message_id
  and r.ordinal=coalesce(asked.channel_ordinal,1) and r.outcome is null) then
  update public.reply_cards set state='closed' where id=asked.id and state='open'; return 'closed'; end if;
 if picks is not null then
  -- One or more of a several-pick question's choices, each once, kept in the order they were offered.
  if not coalesce((asked.content->>'multiple')::boolean,false) or cardinality(picks)<1 or array_position(picks,null) is not null
   or exists(select 1 from unnest(picks) p where p<0 or p>=jsonb_array_length(asked.content->'choices'))
   or (select count(distinct p) from unnest(picks) p)<>cardinality(picks) then raise exception 'questionAnswerInvalid' using errcode='22023'; end if;
  -- Two choices may read alike: each text is kept once, at its first pick, so the card stays one reply_card_valid keeps.
  said:=(select jsonb_agg(text order by first) from (select asked.content->'choices'->p as text,min(p) as first from unnest(picks) p group by 1) picked);
 elsif choice is not null then
  if coalesce((asked.content->>'multiple')::boolean,false) or choice<0 or choice>=jsonb_array_length(asked.content->'choices') then
   raise exception 'questionAnswerInvalid' using errcode='22023'; end if;
  said:=asked.content->'choices'->choice;
 else
  said:=to_jsonb(answer);
 end if;
 if said is null or jsonb_typeof(said)='string' and (btrim(said#>>'{}',E' \t\r\n')='' or length(said#>>'{}')>20000) then
  raise exception 'questionAnswerInvalid' using errcode='22023'; end if;
 update public.reply_cards set state='sending',content=asked.content||jsonb_build_object('answer',said),answered_by=auth.uid(),
  answered_at=now(),answer_key=answer_channel_question.answer_key where id=asked.id;
 return 'claimed';
end $$;

ALTER FUNCTION public.answer_channel_question(c uuid, channel uuid, card bigint, choice integer, answer text, answer_key uuid, picks integer[]) OWNER TO postgres;

--
-- Name: answer_channel_start(bigint, integer, text, smallint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.answer_channel_start(message bigint, attempt integer, run text, ordinal smallint DEFAULT NULL::smallint) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare r public.channel_runs;
begin
 if run is not null then
  select * into r from public.channel_runs where message_id=message and run_id=run for update;
  if found then return r.outcome is null; end if;
 end if;
 if ordinal is not null then
  select * into r from public.channel_runs where message_id=message and public.channel_runs.ordinal=answer_channel_start.ordinal for update;
  if r.message_id is null or r.outcome is not null or r.attempts is distinct from attempt then return false; end if;
  if run is not null then
   if r.run_id is not null then return r.run_id=run; end if;
   update public.channel_runs set run_id=run where message_id=message and public.channel_runs.ordinal=r.ordinal;
   perform public.stop_named_channel_run(r,run);
   return true;
  end if;
  if attempt = 1 and r.attempts = 1 then
   return public.close_channel_run(message, null, 'failed', null, null, null);
  end if;
  return false;
 end if;
 select * into r from public.channel_runs where message_id=message and outcome is null and run_id is null order by ordinal limit 1 for update;
 if r.message_id is null or r.outcome is not null then return false; end if;
 if exists(select 1 from public.channel_runs o where o.message_id=message and o.ordinal<>r.ordinal and o.attempts>=attempt
   and (run is null or o.run_id is null)) then
  return false;
 end if;
 if run is not null then
  update public.channel_runs set run_id=run where message_id=message and public.channel_runs.ordinal=r.ordinal;
  perform public.stop_named_channel_run(r,run);
  return true;
 end if;
 -- A refused first start ends the Run only while no later attempt was made: only a first start can prove nothing started.
 if attempt = 1 and r.attempts = 1 then
  return public.close_channel_run(message, null, 'failed', null, null, null);
 end if;
 return false;
end $$;

ALTER FUNCTION public.answer_channel_start(message bigint, attempt integer, run text, ordinal smallint) OWNER TO postgres;

--
-- Name: answer_handover(bigint, integer, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.answer_handover(h bigint, attempt integer, run text, leg text DEFAULT NULL::text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare r public.agent_handovers;
begin
 select * into r from public.agent_handovers where id=h for update;
 if r.id is null or r.state not in ('waiting','handing','returning') then return false; end if;
 if r.stop_requested_at is not null then
  perform public.end_handovers_stopped(array[h]);
  if run is not null then update public.agent_handovers x set stopping_run=coalesce(x.stopping_run,run),
   stopping_profile=coalesce(x.stopping_profile,(select a.profile from public.hermes_agents a
    where a.id=case when x.follow_up_outcome='stopped' then x.from_agent else x.to_agent end)) where x.id=h; end if;
  return false;
 end if;
 if leg is not null and (leg<>r.state or (r.state='waiting' and r.target_attempts is distinct from attempt)
  or (r.state='handing' and r.answer_attempts is distinct from attempt)
  or (r.state='returning' and r.return_attempts is distinct from attempt)) then return false; end if;
 if run is not null then
  if r.state='waiting' then
   if r.target_run is not null then return r.target_run=run; end if;
   update public.agent_handovers set target_run=run, state='target' where id=h; return true;
  end if;
  if r.state='handing' then
   if r.answer_run is not null then return r.answer_run=run; end if;
   update public.agent_handovers set answer_run=run, state='answering' where id=h; return true;
  end if;
  if r.follow_up_run is not null then return r.follow_up_run=run; end if;
  update public.agent_handovers set follow_up_run=run, state='follow_up' where id=h; return true;
 end if;
 if r.state='waiting' then
  if attempt=1 and r.target_attempts=1 and r.target_run is null then
   update public.agent_handovers set state='returning', target_outcome='failed', attempted_at=null, return_started_at=now() where id=h; return true; end if;
 elsif r.state='handing' then
  if attempt=1 and r.answer_attempts=1 and r.answer_run is null then
   update public.agent_handovers set state='returning', target_outcome='failed', target_closed_at=now(), attempted_at=null, return_started_at=now() where id=h; return true; end if;
 elsif attempt=1 and r.return_attempts=1 and r.follow_up_run is null then
  update public.agent_handovers set state='failed', closed_at=now() where id=h; return true;
 end if;
 return false;
end $$;

ALTER FUNCTION public.answer_handover(h bigint, attempt integer, run text, leg text) OWNER TO postgres;

--
-- Name: answer_note_start(bigint, integer, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.answer_note_start(message bigint, attempt integer, run text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare r public.note_runs;
begin
 select * into r from public.note_runs where note_id=message for update;
 if r.note_id is null or r.outcome is not null then return false; end if;
 if run is not null then
  if r.run_id is not null then return r.run_id = run; end if;
  update public.note_runs set run_id=run where note_id=message;
  if r.stop_at_start is not null or exists(select 1 from public.work_cards w where w.company_id=r.company_id and w.id=r.card_id and w.archived_at is not null) then
   insert into public.stopped_runs(company_id,note_id,run_id) values(r.company_id,message,run) on conflict do nothing; end if;
  return true;
 end if;
 if attempt = 1 and r.attempts = 1 and r.run_id is null then
  return public.close_note_run(message, null, 'failed', null, null, null);
 end if;
 return false;
end $$;

ALTER FUNCTION public.answer_note_start(message bigint, attempt integer, run text) OWNER TO postgres;

--
-- Name: answer_question(uuid, uuid, bigint, integer, text, uuid, integer[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.answer_question(c uuid, conversation uuid, card bigint, choice integer, answer text, answer_key uuid, picks integer[] DEFAULT NULL::integer[]) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare talk public.conversations; asked public.reply_cards; said jsonb;
begin
 if not public.conversation_can_write(c) then raise exception 'conversationNotAllowed' using errcode='42501'; end if;
 select * into talk from public.conversations v where v.id=conversation and v.company_id=c;
 if not found or talk.person_id<>auth.uid() or not public.can_see_agent(c,talk.agent_id) then raise exception 'conversationNotFound' using errcode='P0002'; end if;
 if answer_question.answer_key is null then raise exception 'questionAnswerInvalid' using errcode='22023'; end if;
 -- Picks name their card, and are the whole answer.
 if picks is not null and (card is null or choice is not null or answer is not null) then raise exception 'questionAnswerInvalid' using errcode='22023'; end if;
 if card is null then
  -- Typed words while a question is open are its answer, unless they are a message already queued under this key (a
  -- retried send whose first answer was lost): that turn starts after the Run, so claiming it too would send it twice.
  -- Under reserve_conversation_turn's lock, so the queue and the claim never both take one send.
  perform pg_advisory_xact_lock(hashtextextended('conversation_turn:'||conversation::text,0));
  if exists(select 1 from public.conversation_queued_turns q where q.conversation_id=conversation and q.send_key=answer_question.answer_key) then return 'none'; end if;
  -- Keys before addressees, as reserve_conversation_turn: a send already kept as a note stays that note, and one
  -- already claimed as the answer stays that answer.
  if exists(select 1 from public.conversation_notes n where n.conversation_id=conversation and n.send_key=answer_question.answer_key) then return 'none'; end if;
  if exists(select 1 from public.reply_cards r where r.conversation_id=conversation and r.kind='question' and r.answer_key=answer_question.answer_key) then return 'claimed'; end if;
  select * into asked from public.reply_cards r where r.conversation_id=conversation and r.kind='question' and r.state in ('open','sending')
   order by r.id limit 1 for update;
  if not found then return 'none'; end if;
  -- Only while a question waits: a note to a person ("@Sara …") stays a note, as reserve_conversation_turn makes it.
  if exists(select 1 from public.conversation_addressee(c,answer)) then return 'none'; end if;
 else
  select * into asked from public.reply_cards r where r.id=card and r.conversation_id=conversation and r.kind='question' for update;
  if not found then raise exception 'conversationNotFound' using errcode='P0002'; end if;
 end if;
 if asked.answer_key=answer_question.answer_key then return 'claimed'; end if;
 if asked.state<>'open' then return case when asked.state='closed' then 'closed' else 'taken' end; end if;
 -- A slower closer may have kept this question after another ended its Run: nothing waits for an answer any more, so it
 -- closes here rather than holding the Conversation's one open question for good.
 if exists(select 1 from public.conversation_run_ends u where u.conversation_id=conversation and u.run_id=asked.run_id) then
  update public.reply_cards set state='closed' where id=asked.id and state='open';
  return 'closed';
 end if;
 if picks is not null then
  -- One or more of a several-pick question's choices, each once, kept in the order they were offered.
  if not coalesce((asked.content->>'multiple')::boolean,false) or cardinality(picks)<1 or array_position(picks,null) is not null
   or exists(select 1 from unnest(picks) p where p<0 or p>=jsonb_array_length(asked.content->'choices'))
   or (select count(distinct p) from unnest(picks) p)<>cardinality(picks) then raise exception 'questionAnswerInvalid' using errcode='22023'; end if;
  -- Two choices may read alike: each text is kept once, at its first pick, so the card stays one reply_card_valid keeps.
  said:=(select jsonb_agg(text order by first) from (select asked.content->'choices'->p as text,min(p) as first from unnest(picks) p group by 1) picked);
 elsif choice is not null then
  if (asked.content->>'multiple')::boolean or choice<0 or choice>=jsonb_array_length(asked.content->'choices') then raise exception 'questionAnswerInvalid' using errcode='22023'; end if;
  said:=asked.content->'choices'->choice;
 else
  if answer is null or btrim(answer,E' \t\r\n')='' or length(answer)>20000 then raise exception 'questionAnswerInvalid' using errcode='22023'; end if;
  said:=to_jsonb(answer);
 end if;
 if said is null or jsonb_typeof(said)='string' and (btrim(said#>>'{}',E' \t\r\n')='' or length(said#>>'{}')>20000) then raise exception 'questionAnswerInvalid' using errcode='22023'; end if;
 update public.reply_cards set state='sending',content=asked.content||jsonb_build_object('answer',said),answered_by=auth.uid(),answered_at=now(),
  answer_key=answer_question.answer_key where id=asked.id;
 return 'claimed';
end $$;

ALTER FUNCTION public.answer_question(c uuid, conversation uuid, card bigint, choice integer, answer text, answer_key uuid, picks integer[]) OWNER TO postgres;

--
-- Name: approval_actor(uuid, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.approval_actor(c uuid, step bigint) RETURNS uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
 select m.person_id from public.approval_steps s join public.members m on m.company_id=s.company_id and m.removed_at is null and m.role in ('owner','manager') and (m.person_id=s.person_id or (s.person_id is null and m.role=s.role)) where s.company_id=c and s.id=step and s.removed_at is null order by m.person_id limit 1 $$;

ALTER FUNCTION public.approval_actor(c uuid, step bigint) OWNER TO postgres;

--
-- Name: approval_card_guard(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.approval_card_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare oldkind text; newkind text; firststep bigint; begin
 select kind into newkind from public.work_stages where company_id=new.company_id and id=new.stage_id;
 if tg_op='UPDATE' then select kind into oldkind from public.work_stages where company_id=old.company_id and id=old.stage_id; end if;
 if current_setting('approval.internal',true) is distinct from 'yes' then
  if tg_op='INSERT' and (new.approval_step_id is not null or new.review_submitter is not null or new.rejection_reason is not null or new.review_entered_at is not null) then raise exception 'approval fields are protected'; end if;
  if tg_op='UPDATE' and (new.approval_step_id is distinct from old.approval_step_id or new.review_submitter is distinct from old.review_submitter or new.rejection_reason is distinct from old.rejection_reason or new.review_entered_at is distinct from old.review_entered_at) then raise exception 'approval fields are protected'; end if;
  if tg_op='UPDATE' and oldkind='review' and new.next_actor is distinct from old.next_actor then raise exception 'current approver controls next actor'; end if;
  if newkind='after_review' and (tg_op='INSERT' or oldkind is distinct from newkind) then if not public.can_manage_company(new.company_id) then raise exception 'contributors cannot move beyond review'; end if; raise exception 'approval required'; end if;
  if newkind='review' and (tg_op='INSERT' or oldkind is distinct from 'review') then
   select id into firststep from public.approval_steps where company_id=new.company_id and removed_at is null order by position,id limit 1;
   if firststep is null then raise exception 'approval step required'; end if;
   new.approval_step_id=firststep; new.review_submitter=auth.uid(); new.review_entered_at=now(); new.rejection_reason=null; new.next_actor=public.approval_actor(new.company_id,firststep);
  elsif tg_op='UPDATE' and oldkind='review' and newkind<>'review' then raise exception 'decision required'; end if;
 end if;
 return new; end $$;

ALTER FUNCTION public.approval_card_guard() OWNER TO postgres;

--
-- Name: approval_defaults(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.approval_defaults() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$ begin
 insert into public.approval_steps(company_id,name,position,role) values(new.id,'مراجعة',1,'owner'); return new; end $$;

ALTER FUNCTION public.approval_defaults() OWNER TO postgres;

--
-- Name: approval_holds(uuid, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.approval_holds(c uuid, step bigint) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
 select exists(select 1 from public.approval_steps s join public.members m on m.company_id=s.company_id and m.person_id=auth.uid() and m.removed_at is null and m.role in ('owner','manager') and (m.person_id=s.person_id or (s.person_id is null and m.role=s.role)) where s.company_id=c and s.id=step and s.removed_at is null) $$;

ALTER FUNCTION public.approval_holds(c uuid, step bigint) OWNER TO postgres;

--
-- Name: archive_cards(uuid, bigint[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.archive_cards(c uuid, cards bigint[]) RETURNS TABLE(card bigint, archived_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare w public.work_cards; left_column text; stamp timestamptz;
begin
 if auth.uid() is null or not public.work_can_edit(c) then raise exception 'cardArchiveNotAllowed' using errcode='42501'; end if;
 -- One time for the whole call, the archive's version, taken from the clock and not the transaction, so two archives
 -- of one Card are never the same version.
 stamp:=clock_timestamp();
 for w in select * from public.work_cards x where x.company_id=c and x.id=any(cards) and x.archived_at is null order by x.id for update loop
  if not public.can_see_card(c,w.id) then continue; end if;
  select s.board_column into left_column from public.work_stages s where s.company_id=c and s.id=w.stage_id;
  perform public.stop_card_work(c,w.id);
  perform set_config('approval.internal','yes',true);
  update public.work_cards x set archived_at=stamp,archived_by=auth.uid(),approval_step_id=null where x.company_id=c and x.id=w.id;
  perform set_config('approval.internal','',true);
  insert into public.work_activity(company_id,card_id,actor_id,action,details)
   values(c,w.id,auth.uid(),'card_archived',jsonb_build_object('column',left_column)
    ||case when w.approval_step_id is not null then jsonb_build_object('approval','ended') else '{}'::jsonb end);
  card:=w.id; archived_at:=stamp;
  return next;
 end loop;
end $$;

ALTER FUNCTION public.archive_cards(c uuid, cards bigint[]) OWNER TO postgres;

--
-- Name: archive_channel(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.archive_channel(c uuid, ch uuid) RETURNS TABLE(run text, profile text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare k public.channels; logged bigint; writer text;
begin
 if auth.uid() is null then raise exception 'channelArchiveNotAllowed' using errcode='42501'; end if;
 select * into k from public.channels x where x.id=ch for update;
 if k.id is null or k.company_id is distinct from c or not public.in_channel(ch) then raise exception 'channelNotFound' using errcode='P0002'; end if;
 if k.kind<>'team' or not public.can_manage_company(k.company_id) then raise exception 'channelArchiveNotAllowed' using errcode='42501'; end if;
 if k.archived_at is not null then return; end if;
 update public.channels x set archived_at=now(), archived_by=auth.uid() where x.id=ch;
 -- Its work stops as archiving the channel's Card stops it (stop_channel_work, 20270415999992): every Run not started
 -- yet ends as stopped, every open Handover started there ends as stopped down its chain, and its questions, requests
 -- and handed steps close. The started Runs are kept for the worker to stop (stopped_runs) and are answered to stop now.
 -- A channel raises no wait on a Card (post_channel_message's mentions name their message), so the waits it clears
 -- below are its messages' own.
 perform public.stop_channel_work(k.company_id,ch);
 return query select r.run_id, r.profile from public.channel_runs r where r.channel_id=ch and r.outcome is null and r.run_id is not null
  order by r.message_id, r.ordinal;
 update public.waiting_items w set resolved_at=now() from public.channel_messages cm
  where cm.id=w.channel_message_id and cm.channel_id=ch and w.company_id=k.company_id and w.resolved_at is null;
 insert into public.channel_archives(company_id,channel_id,actor_id,action) values (k.company_id,ch,auth.uid(),'archived') returning id into logged;
 select p.name into writer from public.people p where p.id=auth.uid();
 insert into public.company_log(company_id,actor_id,actor_kind,actor_name,subject,action,details,source,source_id,created_at)
  values (k.company_id,auth.uid(),'person',writer,'company','channel_archived',jsonb_build_object('channel_id',ch,'channel',k.name),'channel_archives',logged,now());
end $$;

ALTER FUNCTION public.archive_channel(c uuid, ch uuid) OWNER TO postgres;

--
-- Name: archive_conversations(uuid, uuid[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.archive_conversations(c uuid, chats uuid[]) RETURNS SETOF uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v uuid;
begin
 if auth.uid() is null or not public.is_member(c) then raise exception 'conversationArchiveNotAllowed' using errcode='42501'; end if;
 for v in select o.id from public.own_conversations(c) o where o.id=any(chats) and o.archived_at is null order by o.id loop
  perform 1 from public.conversations x where x.id=v and x.archived_at is null for update;
  if not found then continue; end if;
  perform public.stop_conversation_work(v);
  update public.conversations x set archived_at=now(), archived_by=auth.uid() where x.id=v;
  perform public.log_conversation_archive(v,true,auth.uid());
  return next v;
 end loop;
end $$;

ALTER FUNCTION public.archive_conversations(c uuid, chats uuid[]) OWNER TO postgres;

--
-- Name: archived_card_count(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.archived_card_count(c uuid) RETURNS integer
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
 return (select count(*)::int from public.work_cards w
  where w.company_id=c and w.archived_at is not null and public.is_member(c) and public.can_see_card(c,w.id));
end $$;

