--
-- Name: work_cards; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.work_cards (
    id bigint NOT NULL,
    company_id uuid NOT NULL,
    stage_id bigint NOT NULL,
    title text NOT NULL,
    offering text DEFAULT ''::text NOT NULL,
    segment text DEFAULT ''::text NOT NULL,
    hook text DEFAULT ''::text NOT NULL,
    channel text DEFAULT ''::text NOT NULL,
    format text DEFAULT ''::text NOT NULL,
    go_live timestamp with time zone,
    goal text DEFAULT ''::text NOT NULL,
    caption text DEFAULT ''::text NOT NULL,
    next_actor uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    approval_step_id bigint,
    review_submitter uuid,
    rejection_reason text,
    review_entered_at timestamp with time zone,
    mode text,
    project_id bigint,
    agent_id uuid,
    conversation_id uuid,
    board_order numeric NOT NULL,
    channel_id uuid,
    archived_at timestamp with time zone,
    archived_by uuid,
    kept_agent_id uuid,
    CONSTRAINT work_cards_archived_by_archived CHECK (((archived_by IS NULL) OR (archived_at IS NOT NULL))),
    CONSTRAINT work_cards_mode_check CHECK ((mode = ANY (ARRAY['plan'::text, 'do'::text, 'answer'::text]))),
    CONSTRAINT work_cards_one_place CHECK (((conversation_id IS NULL) OR (channel_id IS NULL)))
);

ALTER TABLE public.work_cards OWNER TO postgres;

--
-- Name: archived_card_list(uuid, text, uuid, bigint, timestamp with time zone, bigint, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.archived_card_list(c uuid, q text DEFAULT NULL::text, agent uuid DEFAULT NULL::uuid, project bigint DEFAULT NULL::bigint, after_at timestamp with time zone DEFAULT NULL::timestamp with time zone, after_id bigint DEFAULT NULL::bigint, lim integer DEFAULT 50) RETURNS SETOF public.work_cards
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
 return query select w.* from public.work_cards w, (select nullif(public.search_fold(coalesce(q,'')),'') as fold) wanted
 where w.company_id=c and w.archived_at is not null and public.is_member(c) and public.can_see_card(c,w.id)
  and (agent is null or w.agent_id=agent) and (project is null or w.project_id=project)
  and (after_at is null or (w.archived_at,w.id)<(after_at,after_id))
  and (wanted.fold is null or position(wanted.fold in public.search_fold(w.title))>0)
 order by w.archived_at desc, w.id desc
 limit least(greatest(coalesce(lim,50),1),100);
end $$;

ALTER FUNCTION public.archived_card_list(c uuid, q text, agent uuid, project bigint, after_at timestamp with time zone, after_id bigint, lim integer) OWNER TO postgres;

