    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
 select w.* from public.work_cards w
 where w.company_id=c and w.archived_at is not null and public.is_member(c) and public.can_see_card(c,w.id)
 order by w.archived_at desc, w.id desc;
$$;

ALTER FUNCTION public.archived_cards(c uuid) OWNER TO postgres;

--
-- Name: archived_channels(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.archived_channels(c uuid) RETURNS TABLE(id uuid, name text, archived_at timestamp with time zone, archived_by uuid, archived_by_name text, last_body text, last_at timestamp with time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
 select k.id, k.name, k.archived_at, k.archived_by, coalesce(p.name,''), l.body, l.created_at
 from public.channels k
  left join public.people p on p.id=k.archived_by
  left join lateral (select x.body, x.created_at from public.channel_messages x where x.channel_id=k.id and x.hand_card is null
   order by x.id desc limit 1) l on true
 where k.company_id=c and k.archived_at is not null and auth.uid() is not null and public.in_channel(k.id)
 order by k.archived_at desc, k.id;
$$;

ALTER FUNCTION public.archived_channels(c uuid) OWNER TO postgres;

--
-- Name: attach_company_profile(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.attach_company_profile(c uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare first_owner uuid; agent uuid;
begin
 -- The same lock as agent assignments: a company is provided once, even with a second worker.
 perform pg_advisory_xact_lock(hashtextextended('hermes_agents',0));
 if not public.company_profile_ready(c) or exists(select 1 from public.hermes_agents a where a.company_id=c) then return false; end if;
 select m.person_id into first_owner from public.members m where m.company_id=c and m.role='owner' and m.removed_at is null order by m.person_id limit 1;
 if first_owner is null then return false; end if;
 insert into public.hermes_agents(company_id,profile,name,speciality,is_default) values(c,public.company_engine_profile(c),'Lead','General',true) returning id into agent;
 perform public.log_agent_event(c,first_owner,null,agent,'PROVIDE_BUNDLED_HERMES_AGENT','{}');
 return true;
end $$;

ALTER FUNCTION public.attach_company_profile(c uuid) OWNER TO postgres;

--
-- Name: attach_files(uuid, bigint, bigint, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.attach_files(c uuid, card bigint, message bigint, files jsonb) RETURNS integer
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare target bigint; added integer; begin
 if not public.work_can_edit(c) then raise exception 'not permitted'; end if;
 if jsonb_typeof(files) is distinct from 'array' then raise exception 'invalid files' using errcode='22023'; end if;
 if jsonb_array_length(files) not between 1 and 5 then raise exception 'invalid files' using errcode='22023'; end if;
 select m.id into target from public.work_comments m where m.company_id=c and m.card_id=card and (attach_files.message is null or m.id=attach_files.message) order by m.id limit 1;
 if target is null then raise exception 'card or message not found'; end if;
 insert into public.work_attachments(company_id,card_id,comment_id,name,content_type,size,path)
  select c, card, target, f.name, f.content_type, f.size, f.path
  from jsonb_to_recordset(files) as f(name text, content_type text, size bigint, path text)
  where exists(select 1 from storage.objects o where o.bucket_id='creatives' and o.name=f.path)
  on conflict (company_id, path) do nothing;
 get diagnostics added = row_count;
 return added;
end $$;

ALTER FUNCTION public.attach_files(c uuid, card bigint, message bigint, files jsonb) OWNER TO postgres;

--
-- Name: audit_member(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.audit_member() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
 insert into public.member_audit(company_id,actor_id,actor_name,person_id,person_name,action,before_data,after_data) values (coalesce(new.company_id,old.company_id),auth.uid(),(select name from public.people where id=auth.uid()),coalesce(new.person_id,old.person_id),(select name from public.people where id=coalesce(new.person_id,old.person_id)),case when tg_op = 'UPDATE' and old.removed_at is null and new.removed_at is not null then 'DELETE' else tg_op end,case when tg_op <> 'INSERT' then to_jsonb(old) end,case when tg_op <> 'DELETE' then to_jsonb(new) end);
 return coalesce(new,old);
end $$;

ALTER FUNCTION public.audit_member() OWNER TO postgres;

--
-- Name: backfill_review_approvals(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.backfill_review_approvals() RETURNS void
    LANGUAGE sql
    SET search_path TO ''
    AS $$
 update public.work_cards w set
  approval_step_id=(select s.id from public.approval_steps s where s.company_id=w.company_id and s.removed_at is null order by s.position,s.id limit 1),
  review_submitter=(select a.actor_id from public.work_activity a where a.company_id=w.company_id and a.card_id=w.id and ((a.action='card_changed' and a.details->>'field'='stage_id' and a.details->>'new'=w.stage_id::text) or (a.action='card_created' and a.details->>'stage_id'=w.stage_id::text)) order by a.id desc limit 1),
  review_entered_at=coalesce((select a.created_at from public.work_activity a where a.company_id=w.company_id and a.card_id=w.id and ((a.action='card_changed' and a.details->>'field'='stage_id' and a.details->>'new'=w.stage_id::text) or (a.action='card_created' and a.details->>'stage_id'=w.stage_id::text)) order by a.id desc limit 1),w.created_at),
  next_actor=public.approval_actor(w.company_id,(select s.id from public.approval_steps s where s.company_id=w.company_id and s.removed_at is null order by s.position,s.id limit 1))
 where w.approval_step_id is null and exists(select 1 from public.work_stages st where st.company_id=w.company_id and st.id=w.stage_id and st.kind='review');
$$;

ALTER FUNCTION public.backfill_review_approvals() OWNER TO postgres;

--
-- Name: begin_agent_profile_move(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.begin_agent_profile_move(agent uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare moving public.hermes_agents;
begin
 perform pg_advisory_xact_lock(hashtextextended('hermes_agents',0));
 select * into moving from public.hermes_agents where id=agent;
 if not found or moving.profile<>public.company_engine_profile(moving.company_id) then return false; end if;
 insert into public.company_profile_keepers(company_id,agent_id) values(moving.company_id,public.company_profile_keeper(moving.company_id))
  on conflict (company_id) do nothing;
 if not public.agent_may_move(agent) then return false; end if;
 insert into public.agent_profiles(agent_id,company_id) values(agent,moving.company_id) on conflict (agent_id) do nothing;
 return true;
end $$;

ALTER FUNCTION public.begin_agent_profile_move(agent uuid) OWNER TO postgres;

