--
-- Name: can_see_card(uuid, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.can_see_card(c uuid, card bigint) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
 select coalesce((select public.can_see_conversation_agent(c,w.conversation_id) and (w.agent_id is null or public.can_see_agent(c,w.agent_id))
  from public.work_cards w where w.company_id=c and w.id=card),true);
$$;

ALTER FUNCTION public.can_see_card(c uuid, card bigint) OWNER TO postgres;

--
-- Name: can_see_card_file(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.can_see_card_file(object text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $_$
 select case when coalesce((storage.foldername(object))[1],'') !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then true else
  coalesce((select bool_and(public.can_see_card(f.company,f.card)) from (
   select (storage.foldername(object))[1]::uuid as company,(storage.foldername(object))[2]::bigint as card where (storage.foldername(object))[2] ~ '^[0-9]{1,18}$'
   union all select a.company_id,a.card_id from public.work_attachments a where a.path=object
   union all select v.company_id,v.card_id from public.work_versions v where v.path=object) f),true) end;
$_$;

ALTER FUNCTION public.can_see_card_file(object text) OWNER TO postgres;

