    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
 select conversation is null or public.can_see_agent(c,(select v.agent_id from public.conversations v where v.id=conversation and v.company_id=c));
$$;

ALTER FUNCTION public.can_see_conversation_agent(c uuid, conversation uuid) OWNER TO postgres;

--
-- Name: cancel_invite_link(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.cancel_invite_link(c uuid, link uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare stopped public.company_links;
begin
 if c is null or not public.is_company_owner(c) then raise exception 'inviteLinkNotAllowed' using errcode='42501'; end if;
 update public.company_links set cancelled_at=now()
  where id=link and company_id=c and kind='invite' and used_at is null and cancelled_at is null
  returning * into stopped;
 if not found then return; end if;
 insert into public.company_log(company_id,actor_id,actor_kind,actor_name,subject,action,details,source,source_id,created_at)
  values(c,auth.uid(),public.log_actor_kind(c,auth.uid()),(select name from public.people where id=auth.uid()),'member','invite_link_cancelled',
   jsonb_build_object('label',stopped.label,'role',stopped.role,'private','managers'),'company_links',nextval('public.company_link_log_seq'),now());
end $$;

ALTER FUNCTION public.cancel_invite_link(c uuid, link uuid) OWNER TO postgres;

--
-- Name: card_archive_stops(uuid, bigint[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.card_archive_stops(c uuid, cards bigint[]) RETURNS TABLE(card bigint, title text, kind text, agent text, agent_id uuid)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
 with chosen as (
  select w.id, w.title, w.company_id, w.conversation_id, w.channel_id, w.stage_id, w.approval_step_id from public.work_cards w
  where w.company_id=c and w.id=any(cards) and w.archived_at is null and auth.uid() is not null and public.is_member(c) and public.can_see_card(c,w.id)),
 found(id,title,kind,agent_id,agent_name) as (
  select w.id, w.title, s.kind, s.agent_id, s.agent_name
  from chosen w join public.conversations v on v.id=w.conversation_id and v.company_id=w.company_id
   cross join lateral public.conversation_work_stops(v.id) s
  union all
  select w.id, w.title, s.kind, s.agent_id, s.agent_name
  from chosen w join public.channels k on k.id=w.channel_id and k.company_id=w.company_id and public.in_channel(k.id)
   cross join lateral public.channel_work_stops(k.id) s
  union all
  select w.id, w.title, 'run', n.agent_id, n.agent_name
  from chosen w join public.note_runs n on n.company_id=w.company_id and n.card_id=w.id and n.outcome is null
  union all
  select w.id, w.title, 'approval', null::uuid, null::text
  from chosen w join public.work_stages s on s.company_id=w.company_id and s.id=w.stage_id and s.kind='review'
  where w.approval_step_id is not null)
 -- Each Card's lines in its own order: who stops working, then what it asked, then the approval.
 select d.* from (
  select distinct f.id, f.title, f.kind, x.agent_name, x.agent_id
  from found f cross join lateral (select case when seen then f.agent_name end, case when seen then f.agent_id end
   from (select f.agent_id is not null and public.can_see_agent(c,f.agent_id) as seen) v) x(agent_name,agent_id)) d
 order by d.id, array_position(array['run','question','permission','hand','approval'],d.kind), d.agent_name;
$$;

ALTER FUNCTION public.card_archive_stops(c uuid, cards bigint[]) OWNER TO postgres;

--
-- Name: card_chat_person(uuid, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.card_chat_person(c uuid, card bigint) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
 select split_part(btrim(p.name),' ',1) from public.work_cards w
  join public.conversations v on v.id=w.conversation_id and v.company_id=w.company_id
  join public.people p on p.id=v.person_id
 where w.company_id=c and w.id=card and public.is_member(c) and public.can_see_card(c,card);
$$;

ALTER FUNCTION public.card_chat_person(c uuid, card bigint) OWNER TO postgres;

--
-- Name: card_wait(public.work_cards); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.card_wait(card public.work_cards) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
 select jsonb_build_object('person',v.person_id,'kind',r.kind,'title',case r.kind when 'question' then r.content->>'question' else r.title end)
 from public.work_cards w
 join public.conversations v on v.id=w.conversation_id and v.company_id=w.company_id
 join public.reply_cards r on r.conversation_id=v.id and r.company_id=v.company_id and r.kind in ('question','hand','permission') and r.state='open'
 where w.conversation_id is not null and w.id=card.id and w.company_id=card.company_id and public.is_member(w.company_id)
  and public.can_see_card(w.company_id,w.id) and public.reply_card_waits(r)
 order by r.created_at desc, r.id desc limit 1;
$$;

ALTER FUNCTION public.card_wait(card public.work_cards) OWNER TO postgres;

--
-- Name: change_agent_look(uuid, uuid, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.change_agent_look(c uuid, agent uuid, part text, choice text) RETURNS public.agent_looks
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare was public.agent_looks; now_is public.agent_looks;
begin
 if not public.is_company_owner(c) then raise exception 'agentLookNotAllowed' using errcode='42501'; end if;
 if part is null or part not in ('shape','colour','temperament') or (choice is not null and not (choice=any(public.agent_look_choices(part)))) then
  raise exception 'agentLookInvalid' using errcode='22023';
 end if;
 if not exists(select 1 from public.hermes_agents a where a.id=agent and a.company_id=c) then raise exception 'agentLookNotFound' using errcode='P0002'; end if;
 perform pg_advisory_xact_lock(hashtextextended('agent_looks:'||c::text,0));
 select * into was from public.agent_looks l where l.agent_id=agent and l.company_id=c;
 if not found then raise exception 'agentLookNotFound' using errcode='P0002'; end if;
 if (case part when 'shape' then was.picked_shape when 'colour' then was.picked_colour else was.picked_temperament end) is not distinct from choice then return was; end if;
 update public.agent_looks l set
  picked_shape=case when part='shape' then choice else l.picked_shape end,
  picked_colour=case when part='colour' then choice else l.picked_colour end,
  picked_temperament=case when part='temperament' then choice else l.picked_temperament end,
  changed_at=now()
  where l.agent_id=agent returning * into now_is;
 insert into public.company_log(company_id,actor_id,actor_kind,actor_name,subject,agent_id,action,details,source,source_id,created_at)
  values(c,auth.uid(),public.log_actor_kind(c,auth.uid()),(select name from public.people where id=auth.uid()),'agent',agent,'agent_look_changed',
   jsonb_build_object('agent_name',(select a.name from public.hermes_agents a where a.id=agent),'part',part,
    'from',case part when 'shape' then was.shape when 'colour' then was.colour else was.temperament end,
    'to',case part when 'shape' then now_is.shape when 'colour' then now_is.colour else now_is.temperament end,
    'automatic',choice is null),
   'hermes_agent_audit',nextval('public.agent_log_ids'),now());
 return now_is;
end $$;

ALTER FUNCTION public.change_agent_look(c uuid, agent uuid, part text, choice text) OWNER TO postgres;

--
-- Name: change_work_card(uuid, bigint, text, jsonb, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.change_work_card(c uuid, card bigint, operation text, payload jsonb, evidence text DEFAULT NULL::text) RETURNS bigint
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$ declare result bigint; begin
 if not public.work_can_edit(c) then raise exception 'not permitted'; end if;
 perform set_config('work.evidence',coalesce(evidence,''),true);
 case operation
 when 'actor' then update public.work_cards set next_actor=nullif(payload->>'person','')::uuid where company_id=c and id=card;
 when 'assignee' then insert into public.work_assignees(company_id,card_id,person_id) values(c,card,(payload->>'person')::uuid) returning id into result;
 when 'label' then insert into public.work_card_labels(company_id,card_id,label_id) values(c,card,(payload->>'label')::bigint) returning id into result;
 when 'check' then update public.work_checklist set done=(payload->>'done')::boolean where company_id=c and card_id=card and id=(payload->>'item')::bigint;
 when 'comment' then insert into public.work_comments(company_id,card_id,body) values(c,card,payload->>'body') returning id into result;
 when 'creative' then insert into public.work_creatives(company_id,card_id,name) values(c,card,payload->>'name') returning id into result;
 when 'creative_with_version' then
  insert into public.work_creatives(company_id,card_id,name) values(c,card,payload->>'name') returning id into result;
  insert into public.work_versions(company_id,card_id,creative_id,path) values(c,card,result,payload->>'path');
 when 'version' then insert into public.work_versions(company_id,card_id,creative_id,path) values(c,card,(payload->>'creative')::bigint,payload->>'path') returning id into result;
 else raise exception 'unknown operation'; end case;
 if not found then raise exception 'card or item not found'; end if; return result; end $$;

ALTER FUNCTION public.change_work_card(c uuid, card bigint, operation text, payload jsonb, evidence text) OWNER TO postgres;

--
-- Name: channel_agent(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.channel_agent(ch uuid, person uuid, agent uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
 select exists(select 1 from public.channels k join public.hermes_agents h on h.company_id=k.company_id and h.id=agent
  where k.id=ch and public.channel_member(ch, person)
   and case when k.kind='general' then public.agent_visible_to(k.company_id, person, agent)
    else exists(select 1 from public.channel_agents a where a.channel_id=ch and a.agent_id=agent) end);
$$;

ALTER FUNCTION public.channel_agent(ch uuid, person uuid, agent uuid) OWNER TO postgres;

