CREATE FUNCTION public.channel_handover_targets(message bigint) RETURNS TABLE(name text, job text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
 select a.name, a.speciality
 from (select r.* from public.channel_runs r where r.message_id=channel_handover_targets.message and r.outcome is null
   order by r.ordinal limit 1) r
  join public.channel_messages m on m.id=r.message_id and m.author='person'
  join public.hermes_agents a on a.company_id=r.company_id
 where r.agent_id is not null and a.id<>r.agent_id and a.profile is not null and btrim(a.name)<>''
  and public.channel_can_hand_over(m.channel_id,m.person_id,r.agent_id)
 order by a.name, a.id;
$$;

ALTER FUNCTION public.channel_handover_targets(message bigint) OWNER TO postgres;

--
-- Name: channel_handovers(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.channel_handovers(ch uuid) RETURNS TABLE(id bigint, message bigint, from_agent uuid, from_name text, from_connection uuid, to_agent uuid, to_name text, to_connection uuid, goal text, summary text, reply text, state text, target_outcome text, created_at timestamp with time zone, answered_at timestamp with time zone, closed_at timestamp with time zone, no_model boolean, stopped boolean, model_end text, model_agent text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
 select h.id,h.channel_message_id,h.from_agent,n.from_name,coalesce(f.connection_id,h.from_agent),h.to_agent,n.to_name,coalesce(t.connection_id,h.to_agent),h.goal,h.summary,h.reply,
  h.state,h.target_outcome,h.created_at,h.target_closed_at,h.closed_at,
  coalesce(e.ended='no_model',false),coalesce(h.target_outcome='stopped' or h.follow_up_outcome='stopped',false),e.ended,case when e.ended is not null then case when h.follow_up_outcome is not null then n.from_name else n.to_name end end
 from public.agent_handovers h
  join public.channel_messages m on m.id=h.channel_message_id
  left join public.hermes_agents f on f.id=h.from_agent and f.company_id=h.company_id
  left join public.agent_looks fl on fl.agent_id=h.from_agent and fl.company_id=h.company_id
  left join public.hermes_agents t on t.id=h.to_agent and t.company_id=h.company_id
  left join public.agent_looks tl on tl.agent_id=h.to_agent and tl.company_id=h.company_id
  cross join lateral (select coalesce(f.name,fl.kept_name) as from_name,coalesce(t.name,tl.kept_name) as to_name) n
  cross join lateral (select case when h.state in ('done','failed') and h.reply is null
   and coalesce(h.follow_up_outcome,h.target_outcome) in ('no_model','no_credit','key_refused','model_missing','no_access')
   then coalesce(h.follow_up_outcome,h.target_outcome) end as ended) e
 where m.channel_id=ch and h.company_id=m.company_id and auth.uid() is not null and public.in_channel(ch)
  and n.from_name is not null and n.to_name is not null
 order by h.id desc;
$$;

ALTER FUNCTION public.channel_handovers(ch uuid) OWNER TO postgres;

--
-- Name: channel_list(uuid, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.channel_list(c uuid, archived boolean DEFAULT false) RETURNS TABLE(id uuid, kind text, name text, last_at timestamp with time zone, last_body text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
 select k.id, k.kind, k.name,
  coalesce((select m.created_at from public.channel_messages m where m.channel_id=k.id order by m.id desc limit 1),k.created_at),
  (select m.body from public.channel_messages m where m.channel_id=k.id and m.body<>'' and m.hand_card is null order by m.id desc limit 1)
 from public.channels k
 where k.company_id=c and auth.uid() is not null and public.in_channel(k.id) and (k.archived_at is not null)=channel_list.archived
 order by 4 desc, k.id desc
 limit 500;
$$;

