--
-- Name: channel_mentions(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.channel_mentions(c uuid, person uuid, message text) RETURNS TABLE(agent uuid, ordinal smallint)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare a record; body text := coalesce(message,''); at int; from_at int := 1; taken uuid[] := '{}'; called int := 0;
begin
 while from_at <= length(body) loop
  at := position('@' in substr(body, from_at)); exit when at = 0; at := at + from_at - 1;
  if not (at = 1 or substr(body, at-1, 1) ~ '[[:space:][:punct:]،؛؟]') then from_at := at + 1; continue; end if;
  select x.id, x.handle into a from (
    select h.id, h.is_default, lower('@'||btrim(h.name)) handle from public.hermes_agents h
    where h.company_id=c and btrim(h.name)<>'' and public.agent_visible_to(c, person, h.id)) x
   where strpos(lower(substr(body, at)), x.handle) = 1
    and (at + length(x.handle) > length(body) or substr(body, at + length(x.handle), 1) ~ '[[:space:][:punct:]،؛؟]')
   order by length(x.handle) desc, x.is_default desc, x.id limit 1;
  if a.id is null then from_at := at + 1; continue; end if;
  from_at := at + length(a.handle);
  continue when a.id = any(taken);
  taken := taken || a.id; called := called + 1;
  agent := a.id; ordinal := called::smallint; return next;
  exit when called = 3;
 end loop;
end $$;

ALTER FUNCTION public.channel_mentions(c uuid, person uuid, message text) OWNER TO postgres;

--
-- Name: channel_mentions_in(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.channel_mentions_in(ch uuid, person uuid, message text) RETURNS TABLE(agent uuid, ordinal smallint)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare a record; body text := coalesce(message,''); at int; from_at int := 1; taken uuid[] := '{}'; called int := 0;
begin
 while from_at <= length(body) loop
  at := position('@' in substr(body, from_at)); exit when at = 0; at := at + from_at - 1;
  if not (at = 1 or substr(body, at-1, 1) ~ '[[:space:][:punct:]،؛؟]') then from_at := at + 1; continue; end if;
  select x.id, x.handle into a from (
    select h.id, h.is_default, lower('@'||btrim(h.name)) handle
    from public.channels k join public.hermes_agents h on h.company_id=k.company_id
    where k.id=ch and btrim(h.name)<>'' and public.channel_agent(ch, person, h.id)) x
   where strpos(lower(substr(body, at)), x.handle) = 1
    and (at + length(x.handle) > length(body) or substr(body, at + length(x.handle), 1) ~ '[[:space:][:punct:]،؛؟]')
   order by length(x.handle) desc, x.is_default desc, x.id limit 1;
  if a.id is null then from_at := at + 1; continue; end if;
  from_at := at + length(a.handle);
  continue when a.id = any(taken);
  taken := taken || a.id; called := called + 1;
  agent := a.id; ordinal := called::smallint; return next;
  exit when called = 3;
 end loop;
end $$;

ALTER FUNCTION public.channel_mentions_in(ch uuid, person uuid, message text) OWNER TO postgres;

--
-- Name: channel_message_mentions(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.channel_message_mentions(ch uuid, person uuid, message text) RETURNS TABLE(person uuid)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
 select m.person_id from public.channels k
  join public.members m on m.company_id=k.company_id
  join public.people p on p.id=m.person_id
 where k.id=ch and m.removed_at is null
  and public.channel_member(ch, m.person_id) and m.person_id <> person
  and btrim(p.name) <> ''
  and not exists(select 1 from public.hermes_agents h where h.company_id=k.company_id
   and lower(btrim(h.name)) in (lower(btrim(p.name)), lower(split_part(btrim(p.name),' ',1))))
  and (public.mention_at(message, p.name) > 0 or public.mention_at(message, split_part(btrim(p.name),' ',1)) > 0)
 order by m.person_id;
$$;

ALTER FUNCTION public.channel_message_mentions(ch uuid, person uuid, message text) OWNER TO postgres;

--
-- Name: permission_allows_valid(text[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.permission_allows_valid(allows text[]) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
 select allows is null or cardinality(allows) between 1 and 32 and array_ndims(allows)=1
  and not exists(select 1 from unnest(allows) a where a is null or length(a) not between 1 and 1000 or btrim(a)<>a);
$$;

ALTER FUNCTION public.permission_allows_valid(allows text[]) OWNER TO postgres;

--
-- Name: reply_card_valid(text, text, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.reply_card_valid(kind text, state text, content jsonb) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $_$
 select coalesce(case kind
  when 'draft' then state='shown' and case when jsonb_typeof(content)='object' then
   (select array_agg(k order by k) from jsonb_object_keys(content) k)=array['line','rows']
   and public.reply_card_text(content->'line',160)
   and case when jsonb_typeof(content->'rows')='array' then jsonb_array_length(content->'rows')<=8
    and not exists(select 1 from jsonb_array_elements(content->'rows') r where not case when jsonb_typeof(r)='object' then
     (select array_agg(k order by k) from jsonb_object_keys(r) k)=array['label','value']
     and public.reply_card_text(r->'label',40) and public.reply_card_text(r->'value',240) else false end) else false end
  else false end
  when 'review' then state='shown' and case when jsonb_typeof(content)='object' then
   (select array_agg(k order by k) from jsonb_object_keys(content) k)=array['decision','items','line']
   and public.reply_card_text(content->'line',160)
   and public.reply_card_text(content->'decision',160)
   and case when jsonb_typeof(content->'items')='array' then jsonb_array_length(content->'items') between 1 and 8
    and not exists(select 1 from jsonb_array_elements(content->'items') i where not case when jsonb_typeof(i)='object' then
     (select array_agg(k order by k) from jsonb_object_keys(i) k)=array['fine','note','text']
     and jsonb_typeof(i->'fine')='boolean'
     and public.reply_card_text(i->'text',240) and public.reply_card_text(i->'note',240) else false end) else false end
  else false end
  when 'question' then case when jsonb_typeof(content)='object' then
   case (select array_agg(k order by k) from jsonb_object_keys(content) k)
    when array['choices','multiple','question'] then state in ('open','closed')
    when array['answer','choices','multiple','question'] then state in ('sending','answered','closed')
     and case jsonb_typeof(content->'answer')
      when 'string' then length(content->>'answer') between 1 and 20000 and btrim(content->>'answer',E' \t\r\n')<>''
      -- Several picks (#648): only on a question where several may be picked, each one of its choices, once.
      when 'array' then coalesce((content->>'multiple')::boolean,false) and jsonb_array_length(content->'answer')>=1
       and jsonb_typeof(content->'choices')='array' and (content->'choices') @> (content->'answer')
       and not exists(select 1 from jsonb_array_elements(content->'answer') a where jsonb_typeof(a)<>'string')
       and (select count(distinct a) from jsonb_array_elements(content->'answer') a)=jsonb_array_length(content->'answer')
      else false end
    else false end
   and public.reply_card_text(content->'question',4000)
   and jsonb_typeof(content->'multiple')='boolean'
   and case when jsonb_typeof(content->'choices')='array' then jsonb_array_length(content->'choices')<=4
    and not exists(select 1 from jsonb_array_elements(content->'choices') o where not coalesce(jsonb_typeof(o)='string'
     and length(o#>>'{}') between 1 and 1000 and btrim(o#>>'{}',E' \t\r\n')<>'',false)) else false end
  else false end
  when 'hand' then state in ('open','done','closed') and case when jsonb_typeof(content)='object' then
   (select array_agg(k order by k) from jsonb_object_keys(content) k where k not in ('screen','step')) in
    (array['app','line','rows'],array['app','line','rows','url'],array['app','line','note','rows'],array['app','line','note','rows','url'])
   and public.reply_card_text(content->'app',40)
   and public.reply_card_text(content->'line',160)
   and case when jsonb_typeof(content->'rows')='array' then jsonb_array_length(content->'rows')<=8
    and not exists(select 1 from jsonb_array_elements(content->'rows') r where not case when jsonb_typeof(r)='object' then
     (select array_agg(k order by k) from jsonb_object_keys(r) k)=array['label','value']
     and public.reply_card_text(r->'label',40) and public.reply_card_text(r->'value',240) else false end) else false end
   and (not content ? 'url' or coalesce(jsonb_typeof(content->'url')='string' and content->>'url' ~* '^https://[^[:space:]]+$' and length(content->>'url')<=2000,false))
   and (not content ? 'note' or public.reply_card_text(content->'note',240))
   -- #714: a step the Agent stopped at on its own Screen; the key is there only as true.
   and (not content ? 'screen' or content->'screen'='true'::jsonb)
   and (not content ? 'step' or (content->'screen'='true'::jsonb and public.reply_card_text(content->'step',40)))
  else false end
  when 'permission' then case when jsonb_typeof(content)='object' then
   case (select array_agg(k order by k) from jsonb_object_keys(content) k)
    when array['choices','command','description'] then state in ('open','closed')
    when array['choice','choices','command','description'] then state in ('sending','decided','closed')
     and jsonb_typeof(content->'choice')='string' and content->'choices' ? (content->>'choice')
    else false end
   and jsonb_typeof(content->'description')='string' and length(content->>'description')<=4000
   and jsonb_typeof(content->'command')='string' and length(content->>'command')<=4000
   and btrim((content->>'description')||(content->>'command'),E' \t\r\n')<>''
   and case when jsonb_typeof(content->'choices')='array' then jsonb_array_length(content->'choices')<=3
    and content->'choices' ?& array['once','deny']
    and not exists(select 1 from jsonb_array_elements(content->'choices') o where not coalesce(o#>>'{}' in ('once','always','deny'),false))
    and (select count(distinct o) from jsonb_array_elements(content->'choices') o)=jsonb_array_length(content->'choices') else false end
  else false end
  when 'connect' then state in ('open','postponed') and case when jsonb_typeof(content)='object' then
   (select array_agg(k order by k) from jsonb_object_keys(content) k)=array['app','reason']
   and coalesce(jsonb_typeof(content->'app')='string' and content->>'app' ~ '^[a-z][a-z0-9_-]{0,63}$',false)
   and public.reply_card_text(content->'reason',200)
  else false end
 end,false);
$_$;

ALTER FUNCTION public.reply_card_valid(kind text, state text, content jsonb) OWNER TO postgres;

--
-- Name: channel_permissions; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.channel_permissions (
    id bigint NOT NULL,
    company_id uuid NOT NULL,
    channel_id uuid NOT NULL,
    message_id bigint NOT NULL,
    run_id text NOT NULL,
    request_id text NOT NULL,
    title text NOT NULL,
    content jsonb NOT NULL,
    state text NOT NULL,
    decided_by uuid,
    decided_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    delivering_at timestamp with time zone,
    ordinal smallint DEFAULT 1,
    allows text[],
    said_before text,
    CONSTRAINT channel_permissions_allows CHECK ((((allows IS NULL) OR ((content -> 'choices'::text) ? 'always'::text)) AND public.permission_allows_valid(allows))),
    CONSTRAINT channel_permissions_decided CHECK ((((decided_by IS NULL) = (decided_at IS NULL)) AND ((decided_at IS NOT NULL) = (content ? 'choice'::text)))),
    CONSTRAINT channel_permissions_ordinal CHECK (((ordinal IS NULL) OR ((ordinal >= 1) AND (ordinal <= 3)))),
    CONSTRAINT channel_permissions_request_id_check CHECK (((length(request_id) >= 1) AND (length(request_id) <= 200))),
    CONSTRAINT channel_permissions_said_before_check CHECK (((said_before IS NULL) OR ((length(said_before) >= 1) AND (length(said_before) <= 200000)))),
    CONSTRAINT channel_permissions_title_check CHECK (((length(title) >= 1) AND (length(title) <= 100))),
    CONSTRAINT channel_permissions_valid CHECK (public.reply_card_valid('permission'::text, state, content))
);

ALTER TABLE public.channel_permissions OWNER TO postgres;

--
-- Name: channel_permission_waits(public.channel_permissions); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.channel_permission_waits(request public.channel_permissions) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
 select exists(select 1 from public.channel_permissions p
  join public.channel_runs r on r.run_id=p.run_id and r.outcome is null
  join public.channel_messages m on m.id=p.message_id
  where p.id=request.id and p.state='open' and m.person_id=auth.uid() and public.conversation_can_write(p.company_id)
   and r.agent_id is not null and public.channel_agent(p.channel_id,auth.uid(),r.agent_id));
$$;

ALTER FUNCTION public.channel_permission_waits(request public.channel_permissions) OWNER TO postgres;

--
-- Name: channel_person(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.channel_person(c uuid, person uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
 select exists(select 1 from public.members m where m.company_id=c and m.person_id=person and m.removed_at is null);
$$;

ALTER FUNCTION public.channel_person(c uuid, person uuid) OWNER TO postgres;

--
-- Name: channel_reply_card(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.channel_reply_card() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
 insert into public.company_log(company_id,actor_id,actor_kind,actor_name,subject,card_id,agent_id,action,details,source,source_id,created_at)
  select new.company_id,new.agent_id,'agent',new.author_name,'card',w.id,new.agent_id,'channel_reply','{}'::jsonb,
   'channel_replies',new.id,new.created_at
  from public.work_cards w where w.company_id=new.company_id and w.channel_id=new.channel_id
  on conflict (source,source_id) do nothing;
 return null;
end $$;

ALTER FUNCTION public.channel_reply_card() OWNER TO postgres;

--
-- Name: channel_run_card(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.channel_run_card() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare k public.channels; stage bigint; made public.work_cards; line bigint;
begin
 select * into k from public.channels where id=new.channel_id and company_id=new.company_id;
 if k.id is null or k.kind<>'team' then return null; end if;
 select s.id into stage from public.work_stages s
  where s.company_id=k.company_id and s.board_column='progress' and s.kind='before_review'
  order by s.position,s.id limit 1;
 if stage is null then return null; end if;
 insert into public.work_cards(company_id,stage_id,title,agent_id,channel_id)
  values (k.company_id,stage,coalesce(k.name,''),new.agent_id,k.id)
  on conflict (channel_id) where channel_id is not null do nothing returning * into made;
 if made.id is null then return null; end if;
 insert into public.channel_notes(company_id,channel_id,kind,card_id,actor_name)
  values (k.company_id,k.id,'card',made.id,'') on conflict (card_id) where card_id is not null do nothing returning id into line;
 insert into public.company_log(company_id,actor_id,actor_kind,subject,card_id,action,details,source,source_id,created_at)
  values (k.company_id,null,'system','card',made.id,'channel_card_added',
   jsonb_build_object('channel_id',k.id,'channel',k.name),'channel_cards',made.id,now())
  on conflict (source,source_id) do nothing;
 return null;
end $$;

ALTER FUNCTION public.channel_run_card() OWNER TO postgres;

--
-- Name: channel_run_said(bigint, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.channel_run_said(asked bigint, asking_run text, words text) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
 select words is not null and (exists(select 1 from public.reply_cards r where r.channel_message_id=asked and r.run_id=asking_run and r.said_before=words)
  or exists(select 1 from public.channel_permissions p where p.message_id=asked and p.run_id=asking_run and p.said_before=words));
$$;

ALTER FUNCTION public.channel_run_said(asked bigint, asking_run text, words text) OWNER TO postgres;

--
-- Name: channel_run_sessions(uuid, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.channel_run_sessions(ch uuid, after bigint DEFAULT 0) RETURNS TABLE(message_id bigint, agent_id uuid, profile text, session uuid, reply bigint)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
 select r.message_id,r.agent_id,r.profile,r.session,m.id from public.channel_runs r
  join public.channel_messages m on m.reply_to=r.message_id and coalesce(m.reply_ordinal,1)=r.ordinal and m.author='agent'
 where r.channel_id=ch and auth.uid() is not null and public.in_channel(ch) and r.message_id>coalesce(after,0)
  and r.outcome='completed' and r.agent_id is not null and r.profile is not null and r.session is not null;
$$;

ALTER FUNCTION public.channel_run_sessions(ch uuid, after bigint) OWNER TO postgres;

--
-- Name: channel_runs_due(uuid, bigint, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.channel_runs_due(just_channel uuid DEFAULT NULL::uuid, just_message bigint DEFAULT NULL::bigint, after bigint DEFAULT 0) RETURNS TABLE(message bigint, run text, profile text, ordinal smallint, company uuid)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
 select r.message_id, r.run_id, r.profile, r.ordinal, r.company_id from public.channel_runs r
 where r.outcome is null and r.message_id > coalesce(after, 0)
  and (just_channel is null or r.channel_id=just_channel) and (just_message is null or r.message_id=just_message)
  and (r.run_id is not null or r.message_id=just_message or (r.ordinal > 1 and r.attempts = 0)
   or (r.attempts = 0 and r.created_at < now()-interval '1 minute') or (r.attempts > 0 and r.attempted_at < now()-interval '30 seconds'))
  and not exists(select 1 from public.channel_runs e where e.message_id=r.message_id and e.ordinal<r.ordinal and e.outcome is null)
 order by r.message_id, r.ordinal limit 500;
$$;

ALTER FUNCTION public.channel_runs_due(just_channel uuid, just_message bigint, after bigint) OWNER TO postgres;

--
-- Name: channel_show_card(bigint, text, text, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.channel_show_card(message bigint, run text, call text, kind text, title text, content jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare r public.channel_runs; m public.channel_messages; kept public.reply_cards; opened text:=case when kind='hand' then 'open' else 'shown' end;
begin
 select * into kept from public.reply_cards c where c.channel_message_id=message and c.run_id=run and c.call_id=call;
 if found then return jsonb_build_object('state','shown','card',kept.id); end if;
 select * into r from public.channel_runs where message_id=message and run_id=run;
 select * into m from public.channel_messages where id=message;
 if r.message_id is null or m.id is null or m.author<>'person' or r.run_id is distinct from run
  or kind not in ('draft','review','hand')
  or not public.channel_can_show_cards(r.channel_id,m.person_id,r.agent_id)
  or opened='open' and exists(select 1 from public.stopped_runs s where s.channel_message_id=message and s.run_id=run) then return jsonb_build_object('state','refused'); end if;
 if not (public.reply_card_text(to_jsonb(title),100) and public.reply_card_valid(kind,opened,content)) then
  return jsonb_build_object('state','invalid'); end if;
 insert into public.reply_cards(company_id,channel_message_id,channel_ordinal,run_id,call_id,kind,title,content,state)
  values(r.company_id,message,r.ordinal,run,call,kind,title,content,opened)
  on conflict (channel_message_id,run_id,call_id) do nothing returning * into kept;
 if kept.id is null then
  select * into kept from public.reply_cards c where c.channel_message_id=message and c.run_id=run and c.call_id=call;
 elsif kept.kind<>'hand' then
  insert into public.company_log(company_id,actor_id,actor_kind,actor_name,subject,agent_id,action,details,source,source_id,created_at)
   values(r.company_id,r.agent_id,'agent',(select name from public.hermes_agents where id=r.agent_id),'agent',r.agent_id,'agent_card_shown',
    jsonb_build_object('card',jsonb_build_object('kind',kept.kind,'title',kept.title)||case when kept.kind='review' then
      (select jsonb_build_object('fine',count(*) filter (where i->'fine'='true'::jsonb),'edits',count(*) filter (where i->'fine'='false'::jsonb))
       from jsonb_array_elements(kept.content->'items') i) else '{}'::jsonb end,
     'private',true,'teller',m.person_id),
    'reply_cards',kept.id,kept.created_at)
   on conflict (source,source_id) do nothing;
 end if;
 return jsonb_build_object('state','shown','card',kept.id);
end $$;

ALTER FUNCTION public.channel_show_card(message bigint, run text, call text, kind text, title text, content jsonb) OWNER TO postgres;

--
-- Name: channel_sidebar(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.channel_sidebar(c uuid) RETURNS TABLE(id uuid, kind text, name text, unread integer)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
 select k.id, k.kind, k.name, (select count(*)::int from public.channel_messages m where m.channel_id=k.id
   and m.person_id is distinct from auth.uid() and m.hand_card is null
   and m.id > greatest(coalesce((select r.read_through from public.channel_reads r where r.channel_id=k.id and r.person_id=auth.uid()),0),
                       coalesce((select p.joined_through from public.channel_people p where p.channel_id=k.id and p.person_id=auth.uid()),0)))
 from public.channels k
 where k.company_id=c and k.archived_at is null and auth.uid() is not null and public.in_channel(k.id)
 order by k.kind='general' desc, k.created_at, k.id;
$$;

ALTER FUNCTION public.channel_sidebar(c uuid) OWNER TO postgres;

--
-- Name: channel_stoppable(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.channel_stoppable(ch uuid) RETURNS TABLE(message bigint, agent_name text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
 select m.id,
  coalesce((select r.agent_name from public.channel_runs r where r.message_id=m.id and r.outcome is null order by r.ordinal limit 1),
   (select a.name from public.agent_handovers h join public.hermes_agents a on a.id=h.from_agent
    where h.channel_message_id=m.id and h.parent_id is null order by h.id limit 1))
 from public.channel_messages m
  join public.channels k on k.id=m.channel_id and k.company_id=m.company_id
 where m.channel_id=ch and m.author='person' and auth.uid() is not null and public.in_channel(ch)
  and public.conversation_can_write(k.company_id) and (m.person_id=auth.uid() or public.can_manage_company(k.company_id))
  and (exists(select 1 from public.channel_runs r where r.message_id=m.id and r.outcome is null)
   or exists(select 1 from public.agent_handovers h where h.channel_message_id=m.id and h.state not in ('done','failed')))
 order by m.id desc limit 1;
$$;

ALTER FUNCTION public.channel_stoppable(ch uuid) OWNER TO postgres;

--
-- Name: channel_work_stops(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.channel_work_stops(ch uuid) RETURNS TABLE(kind text, agent_id uuid, agent_name text, title text)
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
 select distinct 'run'::text, r.agent_id, r.agent_name, ''::text from public.channel_runs r where r.channel_id=ch and r.outcome is null
 union
 select 'run', a.id, a.name, '' from public.agent_handovers h
  join public.channel_messages m on m.id=h.channel_message_id
  join public.hermes_agents a on a.id=h.to_agent and a.company_id=h.company_id
  where m.channel_id=ch and h.state not in ('done','failed')
 union all
 select 'question', cr.agent_id, cr.agent_name, x.content->>'question' from public.reply_cards x
  join public.channel_messages m on m.id=x.channel_message_id
  join public.channel_runs cr on cr.message_id=x.channel_message_id and cr.ordinal=coalesce(x.channel_ordinal,1)
  where m.channel_id=ch and x.kind='question' and x.state='open' and cr.outcome is null
 union all
 select 'permission', cr.agent_id, cr.agent_name, p.title from public.channel_permissions p
  join public.channel_runs cr on cr.message_id=p.message_id and cr.ordinal=coalesce(p.ordinal,1)
  where p.channel_id=ch and p.state='open'
 union all
 select 'hand', cr.agent_id, cr.agent_name, x.title from public.reply_cards x
  join public.channel_messages m on m.id=x.channel_message_id
  join public.channel_runs cr on cr.message_id=x.channel_message_id and cr.ordinal=coalesce(x.channel_ordinal,1)
  where m.channel_id=ch and x.kind='hand' and x.state='open';
$$;

ALTER FUNCTION public.channel_work_stops(ch uuid) OWNER TO postgres;

--
