-- Name: claim_agent_change(uuid, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.claim_agent_change(c uuid, proposal bigint) RETURNS jsonb
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO ''
    AS $$
 select public.claim_agent_change(c,proposal,null::jsonb)-'edited';
$$;

ALTER FUNCTION public.claim_agent_change(c uuid, proposal bigint) OWNER TO postgres;

--
-- Name: claim_agent_change(uuid, bigint, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.claim_agent_change(c uuid, proposal bigint, edited jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare asked public.agent_change_proposals; token uuid:=gen_random_uuid(); chosen jsonb;
begin
 if not public.is_company_owner(c) then raise exception 'agentChangeNotAllowed' using errcode='42501'; end if;
 select * into asked from public.agent_change_proposals p where p.id=proposal and p.company_id=c for update;
 if not found then raise exception 'agentChangeNotFound' using errcode='P0002'; end if;
 if asked.state in ('approved','declined','refused') then return jsonb_build_object('state',asked.state); end if;
 if asked.state='applying' and asked.claimed_at>now()-interval '5 minutes' then return jsonb_build_object('state','busy'); end if;
 if edited is not null and not public.agent_change_value_valid(asked.change,edited) then raise exception 'agentChangeEditInvalid' using errcode='22023'; end if;
 -- Approving again after an unconfirmed write finishes that write: it keeps the value the earlier claim may have written,
 -- whatever this claim sends, so a decline after it still names what may be in the Agent's settings.
 chosen:=case when asked.state='applying' then asked.approved_value when edited is null or edited=asked.value then null else edited end;
 update public.agent_change_proposals set state='applying',claimed_by=auth.uid(),claimed_at=now(),claim_token=token,approved_value=chosen where id=asked.id;
 return jsonb_build_object('state','claimed','token',token,'retry',asked.state='applying','agent',asked.agent_id,'change',asked.change,
  'setting',asked.setting,'value',coalesce(chosen,asked.value),'edited',chosen is not null);
end $$;

ALTER FUNCTION public.claim_agent_change(c uuid, proposal bigint, edited jsonb) OWNER TO postgres;

--
-- Name: claim_company_owner_link(text, uuid, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.claim_company_owner_link(link_hash text, person uuid, person_name text, language text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare link public.company_owner_links; slug text;
begin
 if link_hash is null or link_hash !~ '^[a-f0-9]{64}$' then raise exception 'ownerLinkInvalid' using errcode='55000'; end if;
 select l.* into link from public.company_owner_links l where l.secret_hash=link_hash for update;
 if not found or link.claimed_at is not null then raise exception 'ownerLinkUsed' using errcode='55000'; end if;
 slug:=public.create_company_with_owner(link.engine_id,link.company_name,person,person_name,language);
 update public.company_owner_links set claimed_at=now() where id=link.id;
 return slug;
end $_$;

