--
-- Name: claim_conversation_turn(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.claim_conversation_turn(conversation uuid) RETURNS TABLE(company uuid, agent uuid, person uuid, send_key uuid, message text, connection uuid, profile text, note text, retry boolean, has_files boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare turn public.conversation_queued_turns; held public.conversation_run_reservations; uncertain boolean; refusal text; target text; token uuid;
begin
 perform pg_advisory_xact_lock(hashtextextended('conversation_turn:'||conversation::text,0));
 perform pg_advisory_xact_lock(hashtextextended('hermes_agents',0));
 if exists(select 1 from public.conversation_open_run(conversation)) then return; end if;
 select q.* into turn from public.conversation_queued_turns q where q.conversation_id=conversation and q.started_at is null and q.failed_at is null
  order by exists(select 1 from public.conversation_run_reservations r where r.conversation_id=q.conversation_id and r.send_key=q.send_key and r.abandoned_at is null) desc,q.queued_at,q.send_key limit 1;
 if not found then return; end if;
 if exists(select 1 from public.conversation_messages m where m.conversation_id=conversation and m.send_key=turn.send_key and m.author='person') then
  perform pg_advisory_xact_lock(hashtextextended('hermes_agents',0));
  update public.conversation_queued_turns q set started_at=now() where q.conversation_id=conversation and q.send_key=turn.send_key;
  delete from public.conversation_run_reservations r where r.conversation_id=conversation and r.send_key=turn.send_key and r.abandoned_at is null;
  return;
 end if;
 if exists(select 1 from public.conversation_run_reservations r where r.conversation_id=conversation and r.abandoned_at is null and r.send_key<>turn.send_key) then return; end if;
 if not exists(select 1 from public.members m where m.company_id=turn.company_id and m.person_id=turn.person_id and m.removed_at is null and m.role<>'viewer')
  or not exists(select 1 from public.conversations cv where cv.id=conversation and cv.agent_id=turn.agent_id) then
  update public.conversation_queued_turns q set failed_at=now() where q.conversation_id=conversation and q.send_key=turn.send_key; return;
 end if;
 select * into held from public.conversation_run_reservations r where r.conversation_id=conversation and r.send_key=turn.send_key and r.abandoned_at is null;
 uncertain:=held.conversation_id is not null and (held.start_unknown_at is not null or held.start_attempts>0);
 if held.conversation_id is not null then target:=held.profile; token:=held.connection_id;
 else select a.profile,a.connection_id into target,token from public.hermes_agents a where a.id=turn.agent_id and a.company_id=turn.company_id;
 end if;
 refusal:=public.agent_profile_refusal(target,turn.company_id,turn.agent_id);
 if (target is null or (target ~ '^co-[0-9a-f]{32}$' and target<>public.company_engine_profile(turn.company_id)) or refusal='hermesProfileNotShared') and not uncertain then
  update public.conversation_queued_turns q set failed_at=now() where q.conversation_id=conversation and q.send_key=turn.send_key; return;
 end if;
 if target is null then return; end if;
 -- A retry whose first start's answer was lost still waits for the fixed set: the Run is never sent to a profile whose
 -- tools are being changed or were never confirmed.
 if (target ~ '^co-[0-9a-f]{32}$' and not public.company_profile_ready(turn.company_id)) or refusal='agentToolsPending' then return; end if;
 if held.conversation_id is null then
  insert into public.conversation_run_reservations(conversation_id,send_key,company_id,connection_id,person_id,agent_id,message,profile)
   values(conversation,turn.send_key,turn.company_id,token,turn.person_id,turn.agent_id,turn.message,target)
   on conflict on constraint conversation_run_reservations_pkey do update set connection_id=excluded.connection_id,profile=excluded.profile,message=excluded.message,created_at=now(),abandoned_at=null,
    start_attempts=0,start_unknown_at=null
    where public.conversation_run_reservations.abandoned_at is not null;
 end if;
 return query select turn.company_id,turn.agent_id,turn.person_id,turn.send_key,turn.message,token,target,
  public.pinned_run_note(conversation,turn.send_key,turn.company_id,turn.person_id),uncertain,
  exists(select 1 from public.conversation_attachments a where a.conversation_id=conversation and a.company_id=turn.company_id and a.send_key=turn.send_key);
end $_$;

ALTER FUNCTION public.claim_conversation_turn(conversation uuid) OWNER TO postgres;

--
-- Name: claim_invitations(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.claim_invitations() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare inv public.member_invitations; mail text; joined boolean;
begin
 select email into mail from auth.users where id=auth.uid();
 if mail is null then return; end if;
 insert into public.people(id,name) values(auth.uid(),split_part(mail,'@',1)) on conflict(id) do nothing;
 for inv in select * from public.member_invitations where lower(email)=lower(mail) and claimed_at is null and ended_at is null for update loop
  joined := false;
  insert into public.members(company_id,person_id,role,grant_publishing,grant_money_figures,grant_customer_data) values(inv.company_id,auth.uid(),inv.role,inv.grant_publishing,inv.grant_money_figures,inv.grant_customer_data) on conflict (company_id,person_id) do update set role=excluded.role, grant_publishing=excluded.grant_publishing, grant_money_figures=excluded.grant_money_figures, grant_customer_data=excluded.grant_customer_data, removed_at=null where public.members.removed_at is not null
   returning true into joined;
  if joined then
   delete from public.member_agent_access where company_id=inv.company_id and person_id=auth.uid();
   insert into public.member_agent_access(company_id,person_id,agent_id)
    select inv.company_id,auth.uid(),a.agent_id from public.invitation_agent_access a where a.invitation_id=inv.id
    on conflict do nothing;
  end if;
  insert into public.channel_people(channel_id, company_id, person_id, joined_through, added_by)
   select i.channel_id, i.company_id, auth.uid(), coalesce((select max(m.id) from public.channel_messages m where m.channel_id=i.channel_id),0), i.added_by
   from public.channel_invitees i where i.invitation_id=inv.id
   on conflict (channel_id, person_id) do nothing;
  delete from public.channel_invitees where invitation_id=inv.id;
  delete from public.invitation_agent_access where invitation_id=inv.id;
  update public.member_invitations set claimed_at=now() where id=inv.id;
 end loop;
end $$;

ALTER FUNCTION public.claim_invitations() OWNER TO postgres;

--
-- Name: claim_invite_link(text, uuid, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.claim_invite_link(link_hash text, person uuid, person_name text, language text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare link public.company_links; joined boolean; slug text;
begin
 if link_hash is null or link_hash !~ '^[a-f0-9]{64}$' then raise exception 'inviteLinkInvalid' using errcode='55000'; end if;
 select l.* into link from public.company_links l where l.secret_hash=link_hash and l.kind='invite' for update;
 if not found or link.used_at is not null then raise exception 'inviteLinkUsed' using errcode='55000'; end if;
 if link.cancelled_at is not null then raise exception 'inviteLinkCancelled' using errcode='55000'; end if;
 if link.ends_at<=now() then raise exception 'inviteLinkEnded' using errcode='55000'; end if;
 if person is null then raise exception 'invalidPerson' using errcode='22023'; end if;
 if not exists(select 1 from public.people p where p.id=person) then
  if person_name is null then
   select split_part(u.email,'@',1) into person_name from auth.users u where u.id=person;
   language:=coalesce(language,'en');
  end if;
  if person_name is null or length(btrim(person_name)) not between 1 and 120 or language is null or language not in ('en','ar') then
   raise exception 'invalidPerson' using errcode='22023';
  end if;
  insert into public.people(id,name,language) values(person,btrim(person_name),language);
 end if;
 insert into public.members(company_id,person_id,role) values(link.company_id,person,link.role::public.member_role)
  on conflict (company_id,person_id) do update set role=excluded.role,grant_publishing=false,grant_money_figures=false,grant_customer_data=false,removed_at=null
  where public.members.removed_at is not null
  returning true into joined;
 if joined is not true then raise exception 'alreadyMember' using errcode='23505'; end if;
 delete from public.member_agent_access where company_id=link.company_id and person_id=person;
 insert into public.member_agent_access(company_id,person_id,agent_id)
  select link.company_id,person,a.agent_id from public.company_link_agents a where a.link_id=link.id on conflict do nothing;
 update public.company_links set used_at=now(),used_by=person where id=link.id;
 insert into public.company_log(company_id,actor_id,actor_kind,actor_name,subject,person_id,action,details,source,source_id,created_at)
  values(link.company_id,person,'person',(select name from public.people where id=person),'member',person,'invite_link_used',
   jsonb_build_object('label',link.label,'role',link.role,'person_name',(select name from public.people where id=person)),'company_links',nextval('public.company_link_log_seq'),now());
 select c.slug into slug from public.companies c where c.id=link.company_id;
 return slug;
end $_$;

ALTER FUNCTION public.claim_invite_link(link_hash text, person uuid, person_name text, language text) OWNER TO postgres;

--
-- Name: claim_password_link(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.claim_password_link(link_hash text) RETURNS TABLE(person uuid, email text, slug text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare link public.company_links; named text;
begin
 if link_hash is null or link_hash !~ '^[a-f0-9]{64}$' then raise exception 'passwordLinkInvalid' using errcode='55000'; end if;
 select l.* into link from public.company_links l where l.secret_hash=link_hash and l.kind='password' for update;
 if not found or link.used_at is not null then raise exception 'passwordLinkUsed' using errcode='55000'; end if;
 if link.cancelled_at is not null then raise exception 'passwordLinkCancelled' using errcode='55000'; end if;
 if link.ends_at<=now() then raise exception 'passwordLinkEnded' using errcode='55000'; end if;
 if not exists(select 1 from public.members m where m.company_id=link.company_id and m.person_id=link.person_id and m.removed_at is null)
  or (link.made_on_server and not exists(select 1 from public.members m where m.company_id=link.company_id and m.person_id=link.person_id and m.role='owner' and m.removed_at is null))
  or (not link.made_on_server and (exists(select 1 from public.install_owner o where o.person_id=link.person_id)
   or not public.password_link_allowed(link.made_by,link.person_id))) then
  raise exception 'passwordLinkEnded' using errcode='55000';
 end if;
 update public.company_links set used_at=now(),used_by=link.person_id where id=link.id;
 delete from auth.sessions s where s.user_id=link.person_id;
 select p.name into named from public.people p where p.id=link.person_id;
 insert into public.company_log(company_id,actor_id,actor_kind,actor_name,subject,person_id,action,details,source,source_id,created_at)
  values(link.company_id,link.person_id,'person',named,'member',link.person_id,'password_link_used',
   jsonb_build_object('person_name',named,'private','managers'),'company_links',nextval('public.company_link_log_seq'),now());
 return query select link.person_id,u.email::text,c.slug from auth.users u, public.companies c where u.id=link.person_id and c.id=link.company_id;
end $_$;

ALTER FUNCTION public.claim_password_link(link_hash text) OWNER TO postgres;

--
-- Name: close_channel_run(bigint, text, text, text, bigint, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.close_channel_run(message bigint, run text, run_outcome text, reply text, used_input bigint, used_output bigint) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare r public.channel_runs;
begin
 if run_outcome is null or run_outcome not in ('completed','failed','no_model','no_credit','key_refused','model_missing','no_access','stopped','lost') or (run_outcome='completed') <> (coalesce(btrim(reply),'') <> '') then
  raise exception 'channelFailed' using errcode='22023'; end if;
 if run is null then
  select * into r from public.channel_runs where message_id=message and outcome is null order by ordinal limit 1 for no key update;
 else
  select * into r from public.channel_runs where message_id=message and outcome is null and run_id=run for no key update;
 end if;
 if r.message_id is null then return false; end if;
 update public.channel_runs set outcome=run_outcome, closed_at=now()
  where message_id=message and ordinal=r.ordinal;
 if run_outcome='completed' then
  insert into public.channel_messages(company_id, channel_id, author, agent_id, author_name, body, reply_to, reply_ordinal)
   values (r.company_id, r.channel_id, 'agent', r.agent_id, r.agent_name, left(reply, 200000), message, r.ordinal)
   on conflict (reply_to, reply_ordinal) do nothing;
 end if;
 return true;
end $$;

ALTER FUNCTION public.close_channel_run(message bigint, run text, run_outcome text, reply text, used_input bigint, used_output bigint) OWNER TO postgres;

--
-- Name: close_channel_run(bigint, text, text, text, bigint, bigint, jsonb, text[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.close_channel_run(message bigint, run text, run_outcome text, reply text, used_input bigint, used_output bigint, reply_files jsonb, missed_files text[]) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare r public.channel_runs; said bigint; handed boolean := public.reply_hands_files(reply_files,missed_files);
begin
 if run_outcome is null or run_outcome not in ('completed','failed','no_model','no_credit','key_refused','model_missing','no_access','stopped','lost')
  or (run_outcome='completed') <> (coalesce(btrim(reply),'') <> '' or handed) or not public.reply_files_valid(reply_files,missed_files)
  or handed and run is null then
  raise exception 'channelFailed' using errcode='22023'; end if;
 if run is null then
  select * into r from public.channel_runs where message_id=message and outcome is null order by ordinal limit 1 for no key update;
 else
  select * into r from public.channel_runs where message_id=message and outcome is null and run_id=run for no key update;
 end if;
 if r.message_id is null then return false; end if;
 update public.channel_runs set outcome=run_outcome, closed_at=now()
  where message_id=message and ordinal=r.ordinal;
 if run_outcome='completed' then
  insert into public.channel_messages(company_id, channel_id, author, agent_id, author_name, body, reply_to, reply_ordinal, missed_files)
   values (r.company_id, r.channel_id, 'agent', r.agent_id, r.agent_name, left(coalesce(reply,''), 200000), message, r.ordinal,
    (select array_agg(left(m,255)) from unnest(missed_files) m))
   on conflict (reply_to, reply_ordinal) do nothing returning id into said;
  if said is not null then
   insert into public.channel_attachments(company_id,channel_id,send_key,message_id,position,name,content_type,size,path)
    select r.company_id,r.channel_id,md5(run)::uuid,said,(f->>'position')::smallint,f->>'name',f->>'content_type',(f->>'size')::bigint,
     r.company_id::text||'/channels/'||r.channel_id::text||'/reply-'||md5(run)||'-'||(f->>'position')
    from jsonb_array_elements(coalesce(reply_files,'[]'::jsonb)) f
    on conflict do nothing;
  end if;
 end if;
 return true;
end $$;

ALTER FUNCTION public.close_channel_run(message bigint, run text, run_outcome text, reply text, used_input bigint, used_output bigint, reply_files jsonb, missed_files text[]) OWNER TO postgres;

