-- Name: close_conversation_run(uuid, text, text, text, text, bigint, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.close_conversation_run(conversation uuid, run text, run_outcome text, reply text, hermes_session text, used_input bigint, used_output bigint) RETURNS boolean
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO ''
    AS $$
 select public.close_conversation_run(conversation,run,run_outcome,reply,hermes_session,used_input,used_output,false);
$$;

ALTER FUNCTION public.close_conversation_run(conversation uuid, run text, run_outcome text, reply text, hermes_session text, used_input bigint, used_output bigint) OWNER TO postgres;

--
-- Name: close_conversation_run(uuid, text, text, text, text, bigint, bigint, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.close_conversation_run(conversation uuid, run text, run_outcome text, reply text, hermes_session text, used_input bigint, used_output bigint, read_completed boolean) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare existing public.conversations; closed text; carded boolean := false;
begin
 if run_outcome is null or run_outcome not in ('completed','stopped','lost','failed','no_model','no_credit','key_refused','model_missing','no_access') or run_outcome='completed' and coalesce(btrim(reply),'')='' then raise exception 'conversationFailed' using errcode='22023'; end if;
 select * into existing from public.conversations where id=conversation;
 if not found or not exists(select 1 from public.conversation_messages where conversation_id=conversation and author='person' and run_id=run) then raise exception 'conversationNotFound' using errcode='P0002'; end if;
 if run_outcome='failed' and read_completed then
  carded := exists(select 1 from public.reply_cards where conversation_id=conversation and run_id=run and kind in ('draft','review','hand'))
   or exists(select 1 from public.lead_made_agents where conversation_id=conversation and run_id=run)
   or exists(select 1 from public.lead_agent_requests where conversation_id=conversation and run_id=run)
   or exists(select 1 from public.agent_rules where conversation_id=conversation and run_id=run);
 end if;
 insert into public.conversation_run_ends(company_id,conversation_id,run_id,outcome)
  values(existing.company_id,conversation,run,case when carded then 'completed' else run_outcome end)
  on conflict do nothing returning run_id into closed;
 if closed is null then return false; end if;
 if run_outcome='completed' then
  insert into public.conversation_messages(company_id,conversation_id,author,agent_id,author_name,body,run_id)
   values(existing.company_id,conversation,'agent',existing.agent_id,existing.agent_name,left(reply,200000),run) on conflict do nothing;
 end if;
 if run_outcome in ('completed','stopped') or carded then
  update public.conversations set hermes_session_id=hermes_session where id=conversation and hermes_session_id is null and hermes_session is not null;
 end if;
 return true;
end;
$$;

ALTER FUNCTION public.close_conversation_run(conversation uuid, run text, run_outcome text, reply text, hermes_session text, used_input bigint, used_output bigint, read_completed boolean) OWNER TO postgres;

--
-- Name: close_conversation_run(uuid, text, text, text, text, bigint, bigint, boolean, jsonb, text[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.close_conversation_run(conversation uuid, run text, run_outcome text, reply text, hermes_session text, used_input bigint, used_output bigint, read_completed boolean, reply_files jsonb, missed_files text[]) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare existing public.conversations; closed text; carded boolean := false; said bigint; handed boolean := public.reply_hands_files(reply_files,missed_files);
begin
 if run_outcome is null or run_outcome not in ('completed','stopped','lost','failed','no_model','no_credit','key_refused','model_missing','no_access')
  or run_outcome='completed' and coalesce(btrim(reply),'')='' and not handed or not public.reply_files_valid(reply_files,missed_files)
  or run_outcome<>'completed' and handed then raise exception 'conversationFailed' using errcode='22023'; end if;
 select * into existing from public.conversations where id=conversation;
 if not found or not exists(select 1 from public.conversation_messages where conversation_id=conversation and author='person' and run_id=run) then raise exception 'conversationNotFound' using errcode='P0002'; end if;
 if run_outcome='failed' and read_completed then
  carded := exists(select 1 from public.reply_cards where conversation_id=conversation and run_id=run and kind in ('draft','review','hand'))
   or exists(select 1 from public.lead_made_agents where conversation_id=conversation and run_id=run)
   or exists(select 1 from public.lead_agent_requests where conversation_id=conversation and run_id=run)
   or exists(select 1 from public.agent_rules where conversation_id=conversation and run_id=run);
 end if;
 insert into public.conversation_run_ends(company_id,conversation_id,run_id,outcome)
  values(existing.company_id,conversation,run,case when carded then 'completed' else run_outcome end)
  on conflict do nothing returning run_id into closed;
 if closed is null then return false; end if;
 if run_outcome='completed' then
  insert into public.conversation_messages(company_id,conversation_id,author,agent_id,author_name,body,run_id,missed_files)
   values(existing.company_id,conversation,'agent',existing.agent_id,existing.agent_name,left(coalesce(reply,''),200000),run,
    (select array_agg(left(m,255)) from unnest(missed_files) m))
   on conflict do nothing returning id into said;
  if said is not null then
   insert into public.conversation_attachments(company_id,conversation_id,message_id,position,name,content_type,size,path)
    select existing.company_id,conversation,said,(f->>'position')::smallint,f->>'name',f->>'content_type',(f->>'size')::bigint,
     existing.company_id::text||'/conversations/'||conversation::text||'/reply-'||md5(run)||'-'||(f->>'position')
    from jsonb_array_elements(coalesce(reply_files,'[]'::jsonb)) f
    on conflict (company_id,path) do nothing;
  end if;
 end if;
 if run_outcome in ('completed','stopped') or carded then
  update public.conversations set hermes_session_id=hermes_session where id=conversation and hermes_session_id is null and hermes_session is not null;
 end if;
 return true;
end;
$$;

ALTER FUNCTION public.close_conversation_run(conversation uuid, run text, run_outcome text, reply text, hermes_session text, used_input bigint, used_output bigint, read_completed boolean, reply_files jsonb, missed_files text[]) OWNER TO postgres;

--
-- Name: close_conversation_run_out_of_usage(uuid, text, text, boolean, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.close_conversation_run_out_of_usage(conversation uuid, run text, hermes_session text, read_completed boolean, usage_resets_at timestamp with time zone) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare closed boolean;
begin
 closed := public.close_conversation_run(conversation,run,'no_access',null,hermes_session,null,null,read_completed);
 if closed and usage_resets_at is not null then
  insert into public.conversation_run_resets(company_id,conversation_id,run_id,resets_at)
   select e.company_id,e.conversation_id,e.run_id,usage_resets_at from public.conversation_run_ends e
   where e.conversation_id=conversation and e.run_id=run and e.outcome='no_access';
 end if;
 return closed;
end $$;

ALTER FUNCTION public.close_conversation_run_out_of_usage(conversation uuid, run text, hermes_session text, read_completed boolean, usage_resets_at timestamp with time zone) OWNER TO postgres;

--
-- Name: close_conversation_run_ran_out(uuid, text, text, boolean, timestamp with time zone, text, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.close_conversation_run_ran_out(conversation uuid, run text, hermes_session text, read_completed boolean, usage_resets_at timestamp with time zone, own_provider text, ran_out jsonb) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare closed boolean; chosen text;
begin
 closed := public.close_conversation_run_out_of_usage(conversation,run,hermes_session,read_completed,usage_resets_at);
 if not closed or jsonb_typeof(ran_out) is distinct from 'array' or jsonb_array_length(ran_out)>64 then return closed; end if;
 select n.model->>'provider' into chosen from public.conversation_messages m
  join public.conversation_run_notes n on n.conversation_id=m.conversation_id and n.send_key=m.send_key
  where m.conversation_id=conversation and m.run_id=run and m.author='person' and jsonb_typeof(n.model)='object' limit 1;
 insert into public.conversation_run_ran_out(company_id,conversation_id,run_id,provider,account,place)
  select distinct on (a.provider,a.account) e.company_id,e.conversation_id,e.run_id,a.provider,a.account,n.place
  from public.conversation_run_ends e,
   jsonb_to_recordset((select coalesce(jsonb_agg(item),'[]'::jsonb) from jsonb_array_elements(ran_out) item where jsonb_typeof(item)='object'))
    as a(provider text,account text,place text)
   -- The cast runs only on a place that is a number: the WHERE clause's checks run in no set order.
   cross join lateral (select case when a.place ~ '^[1-9][0-9]?$' then a.place::integer end as place) n
  where e.conversation_id=conversation and e.run_id=run and e.outcome='no_access'
   and a.provider=coalesce(chosen,own_provider) and a.provider ~ '^[a-z0-9][a-z0-9._-]{0,63}$'
   and a.account ~ '^[A-Za-z0-9_-]{1,64}$' and n.place<=64
   and not exists(select 1 from public.provider_order o where o.company_id=e.company_id and o.provider=a.provider and o.account=a.account and not o.enabled);
 return closed;
end $_$;

ALTER FUNCTION public.close_conversation_run_ran_out(conversation uuid, run text, hermes_session text, read_completed boolean, usage_resets_at timestamp with time zone, own_provider text, ran_out jsonb) OWNER TO postgres;

