--
-- Name: close_handover_answer(bigint, text, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.close_handover_answer(h bigint, run text, run_outcome text, answer text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare r public.agent_handovers;
begin
 if run_outcome is null or run_outcome not in ('completed','failed','no_model','no_credit','key_refused','model_missing','no_access','stopped','lost') or (run_outcome='completed') <> (coalesce(btrim(answer),'') <> '')
  then raise exception 'handoverFailed' using errcode='22023'; end if;
 update public.agent_handovers set state='returning', target_outcome=run_outcome,
  summary=case when run_outcome='completed' then left(btrim(answer),8000) end, target_closed_at=now(), attempted_at=null,
  return_started_at=now()
  where id=h and state='answering' and answer_run=run and target_outcome is null
  returning * into r;
 if r.id is not null and run_outcome='completed' and r.channel_message_id is not null then
  insert into public.company_log(company_id,actor_id,actor_kind,actor_name,subject,card_id,agent_id,action,details,source,source_id,created_at)
   select r.company_id,r.to_agent,'agent',t.name,'card',w.id,r.to_agent,'channel_reply','{}'::jsonb,
    'channel_handover_replies',r.id,now()
   from public.hermes_agents t
   join public.work_cards w on w.company_id=r.company_id
    and w.channel_id=(select m.channel_id from public.channel_messages m where m.id=r.channel_message_id)
   where t.id=r.to_agent
   on conflict (source,source_id) do nothing;
 end if;
 return r.id is not null;
end $$;

ALTER FUNCTION public.close_handover_answer(h bigint, run text, run_outcome text, answer text) OWNER TO postgres;

--
-- Name: close_handover_follow_up(bigint, text, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.close_handover_follow_up(h bigint, run text, run_outcome text, reply text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare r public.agent_handovers; existing public.conversations;
begin
 if run_outcome is null or run_outcome not in ('completed','failed','no_model','no_credit','key_refused','model_missing','no_access','stopped','lost') or (run_outcome='completed') <> (coalesce(btrim(reply),'') <> '')
  then raise exception 'handoverFailed' using errcode='22023'; end if;
 select * into r from public.agent_handovers where id=h for update;
 if r.id is null or r.state<>'follow_up' or r.follow_up_run is distinct from run then return false; end if;
 if r.conversation_id is not null then
  select * into existing from public.conversations where id=r.conversation_id;
  insert into public.conversation_run_ends(company_id,conversation_id,run_id,outcome)
   values(existing.company_id,r.conversation_id,run,run_outcome) on conflict do nothing;
  if run_outcome='completed' then
   insert into public.conversation_messages(company_id,conversation_id,author,agent_id,author_name,body,run_id)
    values(existing.company_id,r.conversation_id,'agent',existing.agent_id,existing.agent_name,left(reply,200000),run)
    on conflict do nothing;
  end if;
 end if;
 update public.agent_handovers set state='done', follow_up_outcome=run_outcome,
  reply=case when r.conversation_id is null and run_outcome='completed' then left(btrim(close_handover_follow_up.reply),200000) end,
  closed_at=now() where id=h;
 return true;
end $$;

ALTER FUNCTION public.close_handover_follow_up(h bigint, run text, run_outcome text, reply text) OWNER TO postgres;

--
-- Name: close_handover_target(bigint, text, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.close_handover_target(h bigint, run text, run_outcome text, words text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare r public.agent_handovers; target public.hermes_agents;
begin
 if run_outcome='completed' and exists(select 1 from public.agent_handovers c where c.parent_id=h and c.run_id=run) then
  update public.agent_handovers set state='handing', attempted_at=null, answer_started_at=null
   where id=h and state='target' and target_run=run and target_outcome is null and not answers_person
   returning * into r;
  return r.id is not null;
 end if;
 if run_outcome is null or run_outcome not in ('completed','failed','no_model','no_credit','key_refused','model_missing','no_access','stopped','lost') or (run_outcome='completed') <> (coalesce(btrim(words),'') <> '')
  then raise exception 'handoverFailed' using errcode='22023'; end if;
 update public.agent_handovers set state=case when answers_person then 'done' else 'returning' end, target_outcome=run_outcome,
  summary=case when run_outcome='completed' then left(btrim(words),8000) end, target_closed_at=now(), attempted_at=null,
  return_started_at=case when answers_person then null else now() end,
  closed_at=case when answers_person then now() end
  where id=h and state='target' and target_run=run and target_outcome is null
  returning * into r;
 if r.id is not null and r.answers_person and r.conversation_id is not null then
  insert into public.conversation_run_ends(company_id,conversation_id,run_id,outcome)
   values(r.company_id,r.conversation_id,r.run_id,run_outcome) on conflict do nothing;
  if run_outcome='completed' then
   select * into target from public.hermes_agents where id=r.to_agent;
   insert into public.conversation_messages(company_id,conversation_id,author,agent_id,author_name,body,run_id)
    values(r.company_id,r.conversation_id,'agent',target.id,coalesce(target.name,''),left(words,200000),run) on conflict do nothing;
  end if;
 end if;
 if r.id is not null and run_outcome='completed' and r.channel_message_id is not null then
  insert into public.company_log(company_id,actor_id,actor_kind,actor_name,subject,card_id,agent_id,action,details,source,source_id,created_at)
   select r.company_id,r.to_agent,'agent',t.name,'card',w.id,r.to_agent,'channel_reply','{}'::jsonb,
    'channel_handover_replies',r.id,now()
   from public.hermes_agents t
   join public.work_cards w on w.company_id=r.company_id
    and w.channel_id=(select m.channel_id from public.channel_messages m where m.id=r.channel_message_id)
   where t.id=r.to_agent
   on conflict (source,source_id) do nothing;
 end if;
 return r.id is not null;
end $$;

ALTER FUNCTION public.close_handover_target(h bigint, run text, run_outcome text, words text) OWNER TO postgres;

--
-- Name: close_note_run(bigint, text, text, text, bigint, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.close_note_run(message bigint, run text, run_outcome text, reply text, used_input bigint, used_output bigint) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare r public.note_runs;
begin
 if run_outcome is null or run_outcome not in ('completed','failed','no_model','no_credit','key_refused','model_missing','no_access','stopped','lost') or (run_outcome='completed') <> (coalesce(btrim(reply),'') <> '') then
  raise exception 'noteFailed' using errcode='22023'; end if;
 update public.note_runs set outcome=run_outcome, closed_at=now(),
  reply=case when run_outcome='completed' then left(close_note_run.reply, 200000) end
  where note_id=message and outcome is null and run_id is not distinct from run returning * into r;
 if r.note_id is null then return false; end if;
 if run_outcome='completed' then
  insert into public.company_log(company_id,actor_id,actor_kind,actor_name,subject,card_id,agent_id,action,details,body,source,source_id,created_at)
   values (r.company_id, r.agent_id, 'agent', r.agent_name, 'card', r.card_id, r.agent_id, 'note_reply',
           jsonb_build_object('reply_to', r.note_id), r.reply, 'note_runs', r.note_id, r.closed_at)
   on conflict (source,source_id) do nothing;
 end if;
 return true;
end $$;

ALTER FUNCTION public.close_note_run(message bigint, run text, run_outcome text, reply text, used_input bigint, used_output bigint) OWNER TO postgres;

--
-- Name: command_handover(uuid, uuid, uuid, uuid, text, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.command_handover(conversation uuid, c uuid, agent uuid, message_key uuid, message text, role text, goal text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare existing public.conversations; lead public.hermes_agents; target public.hermes_agents; writer text; kept text; job text; saved bigint;
begin
 if not public.conversation_can_write(c) then raise exception 'conversationNotAllowed' using errcode='42501'; end if;
 if message is null or length(message) not between 1 and 200000 or message_key is null then raise exception 'conversationNotFound' using errcode='22023'; end if;
 job:=left(btrim(coalesce(goal,'')),500);
 if job='' then return false; end if;
 perform pg_advisory_xact_lock(hashtextextended('conversation_turn:'||conversation::text,0));
 select * into existing from public.conversations where id=conversation;
 if found and (existing.person_id<>auth.uid() or existing.company_id<>c or existing.agent_id is distinct from agent)
  then raise exception 'conversationNotFound' using errcode='P0002'; end if;
 select * into lead from public.hermes_agents where id=agent and company_id=c;
 if not found or not public.may_hand_to_agent(c,lead.id,auth.uid()) or not public.is_company_lead(c,lead.id) then return false; end if;
 select * into target from public.hermes_agents a
  where a.company_id=c and a.id<>lead.id and a.profile is not null and a.template=role
   and public.agent_visible_to(c,auth.uid(),a.id)
  order by a.name,a.id limit 1;
 if not found then return false; end if;
 kept:='command:'||message_key::text;
 select name into writer from public.people where id=auth.uid();
 insert into public.conversations(id,company_id,person_id,agent_id,agent_name)
  values(conversation,c,auth.uid(),lead.id,lead.name) on conflict (id) do nothing;
 insert into public.conversation_messages(company_id,conversation_id,author,person_id,author_name,body,send_key,run_id)
  values(c,conversation,'person',auth.uid(),coalesce(writer,''),message,message_key,kept) on conflict do nothing
  returning id into saved;
 -- A send key already stored as another Run is no command: nothing is handed over, and the caller sends it as typed.
 if saved is null then
  return exists(select 1 from public.conversation_messages m
   where m.conversation_id=conversation and m.send_key=message_key and m.run_id=kept);
 end if;
 insert into public.agent_handovers(company_id,conversation_id,run_id,call_id,from_agent,to_agent,goal,answers_person)
  values(c,conversation,kept,message_key::text,lead.id,target.id,job,true) on conflict do nothing;
 return true;
end $$;

ALTER FUNCTION public.command_handover(conversation uuid, c uuid, agent uuid, message_key uuid, message text, role text, goal text) OWNER TO postgres;

--
-- Name: company_addable_people(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.company_addable_people(c uuid) RETURNS TABLE(person_id uuid, name text, company text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
 select p.id, p.name, x.company from (
  select distinct on (m.person_id) m.person_id, co.name as company
  from public.members m join public.companies co on co.id=m.company_id
  where public.is_company_owner(c) and m.removed_at is null and m.company_id<>c and public.is_company_owner(m.company_id)
   and not exists(select 1 from public.members here where here.company_id=c and here.person_id=m.person_id and here.removed_at is null)
  order by m.person_id, co.name
 ) x join public.people p on p.id=x.person_id
 order by p.name, p.id;
$$;

ALTER FUNCTION public.company_addable_people(c uuid) OWNER TO postgres;

--
-- Name: company_agent_models(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.company_agent_models(c uuid) RETURNS TABLE(agent uuid, name text, profile text, own boolean, choosable boolean, model_choice text, subagents boolean)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
 select a.id,a.name,a.profile,
  public.is_profile_keeper(c,a.id) or exists(select 1 from public.agent_profiles ap where ap.agent_id=a.id and ap.company_id=c and ap.profile=a.profile),
  case when g.agent_id is not null then g.profile=a.profile else public.keeps_profile_alone(c,a.id) end,
  case when g.agent_id is not null then g.model_choice when public.is_profile_keeper(c,a.id) then p.model_choice end,
  case when g.agent_id is not null then g.subagents when public.is_profile_keeper(c,a.id) then p.subagents else false end
 from public.hermes_agents a
  join public.company_profiles p on p.company_id=c
  left join public.agent_profiles g on g.agent_id=a.id and g.company_id=c
 where a.company_id=c and public.can_see_agent(c,a.id)
  and (a.profile=p.profile or a.profile=public.agent_engine_profile(a.id))
 order by a.is_default desc,a.name,a.id;
$$;

ALTER FUNCTION public.company_agent_models(c uuid) OWNER TO postgres;

--
-- Name: company_app_agents(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.company_app_agents(c uuid) RETURNS TABLE(agent uuid, name text, connection uuid, profile text, main boolean, own boolean)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
 select a.id,a.name,a.connection_id,a.profile,a.is_default,
  (a.profile=p.profile and a.id=public.company_profile_keeper(c))
   or exists(select 1 from public.agent_profiles g where g.agent_id=a.id and g.company_id=c and g.profile=a.profile)
 from public.hermes_agents a join public.company_profiles p on p.company_id=c
 where a.company_id=c and public.can_see_agent(c,a.id)
  and (a.profile=p.profile or a.profile=public.agent_engine_profile(a.id))
 order by a.is_default desc,a.name,a.id;
$$;

ALTER FUNCTION public.company_app_agents(c uuid) OWNER TO postgres;

--
-- Name: company_engine_profile(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.company_engine_profile(c uuid) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
 select 'co-'||replace(c::text,'-','');
$$;

ALTER FUNCTION public.company_engine_profile(c uuid) OWNER TO postgres;

--
-- Name: company_engine_target(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.company_engine_target(c uuid) RETURNS TABLE(profile text, profiles text[])
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
 -- `profile` is the Company's own profile, null before the worker makes it; the root profile is the Engine's and is
 -- never one of these. `profiles` is every profile of this Company and no other Company's, the Company's own first.
 select (select p.profile from public.company_profiles p where p.company_id=c),
  coalesce(array(select x.profile from (
    select p.profile, true as own from public.company_profiles p where p.company_id=c
    union all
    select a.profile, false from public.agent_profiles a where a.company_id=c) x order by x.own desc, x.profile),'{}'::text[])
 where public.is_member(c);
$$;

ALTER FUNCTION public.company_engine_target(c uuid) OWNER TO postgres;

--
-- Name: company_holds_provider_key(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.company_holds_provider_key(c uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
 select exists(select 1 from public.company_key_holds h where h.company_id=c
  and (h.held or h.changing or h.uncertain));
$$;

ALTER FUNCTION public.company_holds_provider_key(c uuid) OWNER TO postgres;

--
-- Name: company_key_profiles(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.company_key_profiles(c uuid) RETURNS TABLE(profile text, kind text, agent uuid, name text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
 select x.profile,x.kind,x.agent,x.name from (
  select s.profile,'space' as kind,null::uuid as agent,null::text as name,0 as rank from public.company_shared_spaces s where s.company_id=c
  union all
  select p.profile,'company',k.id,k.name,1 from public.company_profiles p
   left join public.hermes_agents k on k.company_id=c and k.id=public.company_profile_keeper(c) where p.company_id=c
  union all
  select a.profile,'agent',a.agent_id,g.name,2 from public.agent_profiles a
   left join public.hermes_agents g on g.company_id=c and g.id=a.agent_id where a.company_id=c
  union all
  select l.profile,'removed',l.agent_id,l.agent_name,3 from public.agent_profile_leftovers l
   where l.company_id=c and not exists(select 1 from public.agent_profiles a where a.profile=l.profile)
 ) x
 where public.is_member(c) and exists(select 1 from public.company_profiles p where p.company_id=c)
 order by x.rank,x.profile;
$$;

ALTER FUNCTION public.company_key_profiles(c uuid) OWNER TO postgres;

