-- Name: company_needs_engine(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.company_needs_engine() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
 if new.engine_id is null or not exists(select 1 from public.company_engines e where e.id=new.engine_id) then
  raise exception 'companyEngineMissing' using errcode='55000';
 end if;
 return new;
end $$;

