--
-- Name: company_profile_keeper(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.company_profile_keeper(c uuid) RETURNS uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
 select coalesce((select k.agent_id from public.company_profile_keepers k where k.company_id=c),
  (select a.id from public.hermes_agents a where a.company_id=c and a.profile=public.company_engine_profile(c)
   order by a.is_default desc,a.created_at nulls first,a.id limit 1));
$$;

ALTER FUNCTION public.company_profile_keeper(c uuid) OWNER TO postgres;

--
-- Name: company_profile_ready(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.company_profile_ready(c uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
 select exists(select 1 from public.company_profiles p
  where p.company_id=c and p.tools_confirmed and not p.tools_pending and (p.skills_shared or not public.shared_skills_active(c)));
$$;

ALTER FUNCTION public.company_profile_ready(c uuid) OWNER TO postgres;

--
-- Name: company_profile_work(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.company_profile_work() RETURNS TABLE(company_id uuid, profile text, tools_confirmed boolean, tools_pending boolean, attach boolean, move boolean, subagents boolean)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $_$
 select w.id,public.company_engine_profile(w.id),w.tools_confirmed,coalesce(w.tools_pending,false),w.attach,w.move,coalesce(w.subagents,false) from (
  select c.id,coalesce(p.tools_confirmed,false) as tools_confirmed,p.tools_pending,p.subagents,p.company_id is not null as recorded,
   p.company_id is null and exists(select 1 from public.hermes_agents a where a.company_id=c.id and a.profile=public.company_engine_profile(c.id)) as lost,
   not exists(select 1 from public.hermes_agents a where a.company_id=c.id) as attach,
   exists(select 1 from public.hermes_agents a where a.company_id=c.id and a.profile<>public.company_engine_profile(c.id) and a.profile !~ '^ag-[0-9a-f]{32}$') as move
  from public.companies c left join public.company_profiles p on p.company_id=c.id
  where exists(select 1 from public.members m where m.company_id=c.id and m.role='owner' and m.removed_at is null)) w
 where w.attach or w.move or w.lost
  or (w.recorded and (not w.tools_confirmed or w.tools_pending))
 order by (w.move and not w.attach and not w.lost and not (w.recorded and (not w.tools_confirmed or w.tools_pending))),
  case when w.move and not w.attach and not w.lost then md5(w.id::text||date_trunc('minute',now())::text) end,w.id
 limit 100;
$_$;

ALTER FUNCTION public.company_profile_work() OWNER TO postgres;

--
-- Name: complete_setup(uuid, text, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.complete_setup(person uuid, person_name text, company_name text, language text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare company uuid:=gen_random_uuid(); slug text; engine uuid;
begin
 perform pg_advisory_xact_lock(238, 1);
 if not public.setup_is_open() then raise exception 'Setup closed'; end if;
 if length(trim(person_name)) not between 1 and 120 or length(trim(company_name)) not between 1 and 120 or language not in ('en','ar') or person_name is null or company_name is null or language is null then raise exception 'Invalid setup'; end if;
 select e.id into engine from public.company_engines e
  where not exists(select 1 from public.companies c where c.engine_id=e.id)
  order by e.created_at,e.id limit 1 for update;
 if engine is null then raise exception 'companyEngineMissing' using errcode='55000'; end if;
 slug:=coalesce(nullif(trim(both '-' from regexp_replace(lower(company_name),'[^a-z0-9]+','-','g')),''),'company') || '-' || left(company::text,8);
 insert into public.people(id,name,language) values(person,person_name,language);
 insert into public.companies(id,slug,name,work_mode,engine_id) values(company,slug,company_name,null,engine);
 insert into public.members(company_id,person_id,role,grant_publishing,grant_money_figures,grant_customer_data) values(company,person,'owner',true,true,true);
 insert into public.install_owner(person_id) values(person) on conflict (singleton) do update set person_id=excluded.person_id;
 update public.setup_claim set closed=true where singleton;
 return slug;
end $$;

ALTER FUNCTION public.complete_setup(person uuid, person_name text, company_name text, language text) OWNER TO postgres;

--
-- Name: conversation_addressee(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.conversation_addressee(c uuid, message text) RETURNS TABLE(person uuid, name text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
 select p.id,p.name from public.members m join public.people p on p.id=m.person_id, lateral (select ltrim(message) as text) t
 where m.company_id=c and m.removed_at is null and length(btrim(p.name))>0
  and not exists(select 1 from public.hermes_agents h where h.company_id=c and lower(h.name)=lower(p.name))
  and lower(left(t.text,length(p.name)+1))='@'||lower(p.name)
  and (length(t.text)=length(p.name)+1 or substr(t.text,length(p.name)+2,1) ~ '[[:space:][:punct:]،؛؟]')
 order by length(p.name) desc,p.id limit 1;
$$;

ALTER FUNCTION public.conversation_addressee(c uuid, message text) OWNER TO postgres;

--
-- Name: conversation_agent(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.conversation_agent(conversation uuid, c uuid) RETURNS uuid
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare existing public.conversations;
begin
 if not public.conversation_can_write(c) then raise exception 'conversationNotAllowed' using errcode='42501'; end if;
 select * into existing from public.conversations where id=conversation;
 if not found then return null; end if;
 if existing.person_id<>auth.uid() or existing.company_id<>c or existing.agent_id is null then raise exception 'conversationNotFound' using errcode='P0002'; end if;
 return existing.agent_id;
end;
$$;

ALTER FUNCTION public.conversation_agent(conversation uuid, c uuid) OWNER TO postgres;

--
-- Name: conversation_agent_access(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.conversation_agent_access(conversation uuid) RETURNS TABLE(id bigint, run_id text, state text, named_first text, named_name text, named_role text, pressed_at timestamp with time zone, answered_at timestamp with time zone, answerer text, opened jsonb, available boolean, created_at timestamp with time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
 select r.id, r.run_id, r.state, split_part(coalesce(n.name,''),' ',1), coalesce(n.name,''), coalesce(nm.role::text,''), r.pressed_at, r.answered_at,
  coalesce(a.name,''),
  case when r.state='opened' and public.agent_visible_to(r.company_id,v.person_id,r.agent_id)
   then (select jsonb_build_object('id',g.id,'connection_id',g.connection_id,'name',g.name) from public.hermes_agents g where g.id=r.agent_id) end,
  public.agent_visible_to(r.company_id,v.person_id,r.agent_id),
  r.created_at
 from public.agent_access_requests r
 join public.conversations v on v.id=r.conversation_id and v.company_id=r.company_id
 cross join lateral (select case when r.state<>'offered' or public.may_open_agent_for(r.company_id,r.named_to,r.agent_id,r.asked_by) then r.named_to
   else coalesce(public.agent_access_named(r.company_id,r.asked_by,r.agent_id),r.named_to) end named) w
 left join public.people n on n.id=w.named
 left join public.members nm on nm.company_id=r.company_id and nm.person_id=w.named and nm.removed_at is null
 left join public.people a on a.id=r.answered_by
 where r.conversation_id=conversation and v.person_id=auth.uid() and r.asked_by=auth.uid() and public.is_member(v.company_id)
  and public.can_see_agent(v.company_id,v.agent_id)
 order by r.id;
$$;

ALTER FUNCTION public.conversation_agent_access(conversation uuid) OWNER TO postgres;

--
-- Name: conversation_archive_stops(uuid, uuid[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.conversation_archive_stops(c uuid, chats uuid[]) RETURNS TABLE(conversation uuid, kind text, agent text, agent_id uuid)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
 select v.id, s.kind, s.agent_name, s.agent_id
 from public.own_conversations(c) v cross join lateral public.conversation_work_stops(v.id) s
 where v.id=any(chats) and v.archived_at is null
 order by v.id, array_position(array['run','question','permission','hand'],s.kind);
$$;

ALTER FUNCTION public.conversation_archive_stops(c uuid, chats uuid[]) OWNER TO postgres;

--
-- Name: conversation_busy(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.conversation_busy(conversation uuid, except_key uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
 select exists(select 1 from public.conversation_open_run(conversation))
  or exists(select 1 from public.conversation_run_reservations r where r.conversation_id=conversation and r.abandoned_at is null and r.send_key<>except_key)
  or exists(select 1 from public.conversation_queued_turns q where q.conversation_id=conversation and q.started_at is null and q.failed_at is null and q.send_key<>except_key);
$$;

ALTER FUNCTION public.conversation_busy(conversation uuid, except_key uuid) OWNER TO postgres;

