-- Name: conversation_can_write(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.conversation_can_write(c uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
 select auth.uid() is not null and exists(select 1 from public.members where company_id=c and person_id=auth.uid() and removed_at is null and role<>'viewer');
$$;

ALTER FUNCTION public.conversation_can_write(c uuid) OWNER TO postgres;

--
-- Name: conversation_counts(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.conversation_counts(c uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
 select jsonb_build_object('current',
  (select count(*) from public.own_conversations(c) v where v.archived_at is null)
  +(select count(*) from public.channels k where k.company_id=c and k.archived_at is null and public.in_channel(k.id)),
  'archived',(select count(*) from public.own_conversations(c) v where v.archived_at is not null)
  +(select count(*) from public.channels k where k.company_id=c and k.archived_at is not null and public.in_channel(k.id)));
$$;

ALTER FUNCTION public.conversation_counts(c uuid) OWNER TO postgres;

--
-- Name: conversation_drift(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.conversation_drift() RETURNS TABLE(company_id uuid, profile text, sessions text[])
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
 select v.company_id, a.profile, array_agg(v.hermes_session_id order by v.hermes_session_id)
 from public.conversations v left join public.hermes_agents a on a.id=v.agent_id and a.company_id=v.company_id
 where v.hermes_session_id is not null and v.created_at<now()-interval '1 hour' and (a.id is null or a.profile is not null)
 group by v.company_id, a.profile
 order by v.company_id, a.profile nulls first;
$$;

ALTER FUNCTION public.conversation_drift() OWNER TO postgres;

--
-- Name: conversation_handover_agents(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.conversation_handover_agents(conversation uuid, message_key uuid) RETURNS TABLE(name text, job text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
 select a.name, a.speciality
 from public.conversation_run_reservations r
  join public.hermes_agents a on a.company_id=r.company_id
 where r.conversation_id=conversation_handover_agents.conversation and r.send_key=message_key and r.agent_id is not null
  and a.id<>r.agent_id and a.profile is not null and btrim(a.name)<>'' and public.may_hand_to_agent(r.company_id,r.agent_id,r.person_id)
 order by a.name, a.id;
$$;

ALTER FUNCTION public.conversation_handover_agents(conversation uuid, message_key uuid) OWNER TO postgres;

--
-- Name: conversation_handovers(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.conversation_handovers(conversation uuid) RETURNS TABLE(id bigint, run text, from_agent uuid, from_name text, from_connection uuid, to_agent uuid, to_name text, to_connection uuid, goal text, answer text, state text, target_outcome text, answers_person boolean, created_at timestamp with time zone, answered_at timestamp with time zone, parent bigint, stopped boolean)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
 select h.id,h.run_id,h.from_agent,coalesce(f.name,fl.kept_name),coalesce(f.connection_id,h.from_agent),h.to_agent,coalesce(t.name,tl.kept_name),coalesce(t.connection_id,h.to_agent),h.goal,
  case when h.target_outcome='completed' and not h.answers_person then h.summary end,
  h.state,h.target_outcome,h.answers_person,h.created_at,h.target_closed_at,h.parent_id,
  coalesce(h.target_outcome='stopped' or h.follow_up_outcome='stopped',false)
 from public.agent_handovers h
  join public.conversations c on c.id=h.conversation_id and c.company_id=h.company_id
  left join public.hermes_agents f on f.id=h.from_agent and f.company_id=h.company_id
  left join public.agent_looks fl on fl.agent_id=h.from_agent and fl.company_id=h.company_id
  left join public.hermes_agents t on t.id=h.to_agent and t.company_id=h.company_id
  left join public.agent_looks tl on tl.agent_id=h.to_agent and tl.company_id=h.company_id
 where h.conversation_id=conversation_handovers.conversation and auth.uid() is not null and c.person_id=auth.uid()
  and public.is_member(c.company_id) and public.can_see_agent(c.company_id,c.agent_id)
  and coalesce(f.name,fl.kept_name) is not null and coalesce(t.name,tl.kept_name) is not null
 order by h.created_at,h.id;
$$;

ALTER FUNCTION public.conversation_handovers(conversation uuid) OWNER TO postgres;

--
-- Name: conversation_list(uuid, text, boolean, timestamp with time zone, uuid, integer, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.conversation_list(c uuid, q text DEFAULT NULL::text, archived boolean DEFAULT false, after_at timestamp with time zone DEFAULT NULL::timestamp with time zone, after_id uuid DEFAULT NULL::uuid, lim integer DEFAULT 50, morning text DEFAULT NULL::text, general text DEFAULT NULL::text) RETURNS TABLE(kind text, id uuid, agent_id uuid, agent_name text, connection_id uuid, title text, good_morning_day date, channel_kind text, last_at timestamp with time zone, last_body text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
 with wanted as (select nullif(public.search_fold(coalesce(q,'')),'') as fold),
 listed as (
  select 'conversation'::text as kind, v.id, coalesce(v.agent_id,v.kept_agent_id) as agent_id, v.agent_name, v.good_morning_day, null::text as channel_kind, null::text as name, v.last_message_at as last_at
  from public.own_conversations(c) v
  where (v.archived_at is not null)=archived
  union all
  select 'channel', k.id, null, null, null, k.kind, k.name,
   coalesce((select m.created_at from public.channel_messages m where m.channel_id=k.id order by m.id desc limit 1),k.created_at)
  from public.channels k
  where k.company_id=c and public.in_channel(k.id) and (k.archived_at is not null)=archived
 ),
 page as (
  select t.* from listed t, wanted w
  where (after_at is null or (t.last_at,t.id)<(after_at,after_id))
   and case when w.fold is null then true
    else position(w.fold in public.search_fold(coalesce(case when t.kind='channel' then coalesce(t.name,general) when t.good_morning_day is not null then morning
     else public.conversation_title(t.id,t.agent_name) end,'')))>0 end
  order by t.last_at desc, t.id desc
  limit least(greatest(coalesce(lim,50),1),100)
 )
 select p.kind, p.id, p.agent_id, p.agent_name, h.connection_id,
  case when p.kind='channel' then p.name when p.good_morning_day is null then public.conversation_title(p.id,p.agent_name) end, p.good_morning_day, p.channel_kind, p.last_at,
  case when p.kind='conversation'
   then (select m.body from public.conversation_messages m where m.conversation_id=p.id and m.body<>'' and m.hand_card is null order by m.id desc limit 1)
   else (select m.body from public.channel_messages m where m.channel_id=p.id and m.body<>'' and m.hand_card is null order by m.id desc limit 1) end
 from page p left join public.hermes_agents h on h.id=p.agent_id and h.company_id=c
 order by p.last_at desc, p.id desc;
$$;

ALTER FUNCTION public.conversation_list(c uuid, q text, archived boolean, after_at timestamp with time zone, after_id uuid, lim integer, morning text, general text) OWNER TO postgres;

--
-- Name: conversation_live_run(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.conversation_live_run(conversation uuid) RETURNS TABLE(run text, profile text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
 select o.run,a.profile from public.conversations cv
  join public.hermes_agents a on a.id=cv.agent_id and a.company_id=cv.company_id
  cross join lateral public.conversation_open_run(cv.id) o
 where cv.id=conversation and auth.uid() is not null and cv.person_id=auth.uid()
  and public.is_member(cv.company_id) and public.can_see_agent(cv.company_id,cv.agent_id)
  and o.run is not null and a.profile is not null;
$$;

ALTER FUNCTION public.conversation_live_run(conversation uuid) OWNER TO postgres;

--
-- Name: conversation_message_hand_card(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.conversation_message_hand_card() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
 new.hand_card:=(select q.hand_card from public.conversation_queued_turns q where q.conversation_id=new.conversation_id and q.send_key=new.send_key);
 return new;
end $$;

ALTER FUNCTION public.conversation_message_hand_card() OWNER TO postgres;

--
-- Name: conversation_open_run(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.conversation_open_run(conversation uuid) RETURNS TABLE(message bigint, run text, person uuid, author_name text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
 select m.id,m.run_id,m.person_id,m.author_name from public.conversation_messages m
 where m.conversation_id=conversation and m.author='person'
  and not exists(select 1 from public.conversation_messages r where r.conversation_id=m.conversation_id and r.author='agent' and r.run_id=m.run_id)
  and not exists(select 1 from public.conversation_run_ends u where u.conversation_id=m.conversation_id and u.run_id=m.run_id)
  and not exists(select 1 from public.agent_handovers h where h.conversation_id=m.conversation_id and h.run_id=m.run_id and h.answers_person)
 order by m.id desc limit 1;
$$;

ALTER FUNCTION public.conversation_open_run(conversation uuid) OWNER TO postgres;

--
-- Name: conversation_reply_card(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.conversation_reply_card() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare chat public.conversations; agent public.hermes_agents; asked public.conversation_messages; stage bigint; card bigint;
begin
 select * into chat from public.conversations where id=new.conversation_id;
 select * into agent from public.hermes_agents where id=chat.agent_id and company_id=chat.company_id;
 if not found or agent.is_default then return null; end if;
 select * into asked from public.conversation_messages where conversation_id=chat.id and author='person' order by id limit 1;
 if asked.run_id is distinct from new.run_id
  or exists(select 1 from public.agent_rules where conversation_id=chat.id and run_id=new.run_id)
  or exists(select 1 from public.lead_made_agents where conversation_id=chat.id and run_id=new.run_id)
  or exists(select 1 from public.lead_agent_requests where conversation_id=chat.id and run_id=new.run_id) then return null; end if;
 -- A stage after review takes a Card only through an approval (approval_card_guard), which a new Card has not had.
 select id into stage from public.work_stages where company_id=chat.company_id and board_column='progress' and kind='before_review' order by position,id limit 1;
 if stage is null then return null; end if;
 insert into public.work_cards(company_id,stage_id,title,agent_id,conversation_id)
  values(chat.company_id,stage,public.chat_card_title(asked.body,agent.name),agent.id,chat.id)
  on conflict (conversation_id) where conversation_id is not null do nothing returning id into card;
 if card is not null then
  insert into public.company_log(company_id,actor_id,actor_kind,actor_name,subject,card_id,agent_id,action,details,source,source_id,created_at)
   select h.company_id,h.from_agent,'agent',f.name,'card',card,h.to_agent,'agent_handed_to',
    jsonb_build_object('agent_name',f.name,'to_name',t.name,'goal',h.goal),'agent_handovers',h.id,h.created_at
   from public.agent_handovers h
    join public.hermes_agents f on f.id=h.from_agent and f.company_id=h.company_id
    join public.hermes_agents t on t.id=h.to_agent and t.company_id=h.company_id
   where h.conversation_id=chat.id and h.company_id=chat.company_id
   order by h.id
   on conflict (source,source_id) do nothing;
 end if;
 return null;
end $$;

ALTER FUNCTION public.conversation_reply_card() OWNER TO postgres;

--
-- Name: conversation_run_said(uuid, text, text); Type: FUNCTION; Schema: public; Owner: postgres
