--
-- Name: conversation_session_marked(uuid, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.conversation_session_marked(conversation uuid, archived boolean) RETURNS boolean
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO ''
    AS $$
 with kept as (update public.conversations v set session_archived=archived, session_missing_since=null, session_mark_after=null
  where v.id=conversation and v.hermes_session_id is not null returning (v.archived_at is not null)=archived as settled)
 select coalesce((select settled from kept),false);
$$;

ALTER FUNCTION public.conversation_session_marked(conversation uuid, archived boolean) OWNER TO postgres;

--
-- Name: conversation_session_missing(uuid, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.conversation_session_missing(conversation uuid, archived boolean) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v public.conversations; gone boolean;
begin
 select * into v from public.conversations x where x.id=conversation and (x.archived_at is not null)=archived and x.hermes_session_id is not null for update;
 if v.id is null then return false; end if;
 gone:=v.agent_id is null or not exists(select 1 from public.hermes_agents a where a.id=v.agent_id and a.company_id=v.company_id and a.profile is not null)
  or coalesce(v.session_missing_since<now()-interval '1 day',false);
 if gone then
  update public.conversations x set session_archived=archived, session_missing_since=null, session_mark_after=null where x.id=v.id;
 else
  update public.conversations x set session_missing_since=coalesce(x.session_missing_since,now()), session_mark_after=now()+interval '1 minute' where x.id=v.id;
 end if;
 return gone;
end $$;

ALTER FUNCTION public.conversation_session_missing(conversation uuid, archived boolean) OWNER TO postgres;

--
-- Name: conversation_sessions_later(uuid[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.conversation_sessions_later(conversations uuid[]) RETURNS void
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO ''
    AS $$
 update public.conversations v set session_mark_after=now()+interval '15 seconds'
  where v.id=any(conversations) and v.hermes_session_id is not null;
$$;

ALTER FUNCTION public.conversation_sessions_later(conversations uuid[]) OWNER TO postgres;

--
-- Name: conversation_sessions_to_mark(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.conversation_sessions_to_mark() RETURNS TABLE(conversation uuid, company uuid, profile text, session text, archived boolean)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
 select v.id, v.company_id, a.profile, v.hermes_session_id, v.archived_at is not null
 from public.conversations v left join public.hermes_agents a on a.id=v.agent_id and a.company_id=v.company_id
 where v.hermes_session_id is not null and (v.archived_at is not null) is distinct from coalesce(v.session_archived,false)
  and (v.session_mark_after is null or v.session_mark_after<=now())
 order by v.id limit 100;
$$;

ALTER FUNCTION public.conversation_sessions_to_mark() OWNER TO postgres;

--
-- Name: conversation_stamp(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.conversation_stamp(conversation uuid) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
 select md5(concat_ws('|',
  (select xmin::text from public.conversations where id=conversation),
  (select count(*)::text||':'||coalesce(sum(xmin::text::bigint),0)::text from public.conversation_messages where conversation_id=conversation),
  (select count(*)::text||':'||coalesce(sum(xmin::text::bigint),0)::text from public.conversation_queued_turns where conversation_id=conversation),
  (select count(*)::text||':'||coalesce(sum(xmin::text::bigint),0)::text from public.conversation_run_ends where conversation_id=conversation),
  (select count(*)::text||':'||coalesce(sum(xmin::text::bigint),0)::text from public.conversation_run_resets where conversation_id=conversation),
  (select count(*)::text||':'||coalesce(sum(xmin::text::bigint),0)::text from public.conversation_run_reservations where conversation_id=conversation),
  (select count(*)::text||':'||coalesce(sum(xmin::text::bigint),0)::text from public.conversation_notes where conversation_id=conversation),
  (select count(*)::text||':'||coalesce(sum(xmin::text::bigint),0)::text from public.conversation_attachments where conversation_id=conversation),
  (select count(*)::text||':'||coalesce(sum(xmin::text::bigint),0)::text from public.reply_cards where conversation_id=conversation),
  (select count(*)::text||':'||coalesce(sum(xmin::text::bigint),0)::text from public.agent_rules where conversation_id=conversation),
  (select count(*)::text||':'||coalesce(sum(xmin::text::bigint),0)::text from public.agent_handovers where conversation_id=conversation),
  (select count(*)::text||':'||coalesce(sum(xmin::text::bigint),0)::text from public.agent_change_proposals where conversation_id=conversation),
  (select count(*)::text||':'||coalesce(sum(xmin::text::bigint),0)::text from public.lead_agent_requests where conversation_id=conversation),
  (select count(*)::text||':'||coalesce(sum(xmin::text::bigint),0)::text from public.lead_made_agents where conversation_id=conversation),
  (select count(*)::text||':'||coalesce(sum(xmin::text::bigint),0)::text from public.agent_access_requests where conversation_id=conversation),
  (select count(*)::text||':'||coalesce(sum(xmin::text::bigint),0)::text from public.work_cards where conversation_id=conversation)))
 where exists(select 1 from public.conversations v where v.id=conversation and v.person_id=auth.uid() and public.is_member(v.company_id));
$$;

ALTER FUNCTION public.conversation_stamp(conversation uuid) OWNER TO postgres;

--
-- Name: conversation_stop_target(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.conversation_stop_target(conversation uuid, c uuid) RETURNS TABLE(run text, profile text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare running record; named text;
begin
 if auth.uid() is null or not public.is_member(c) or not exists(select 1 from public.conversations cv where cv.id=conversation and cv.company_id=c)
  or not public.can_see_conversation_agent(c,conversation) then
  raise exception 'conversationNotFound' using errcode='P0002'; end if;
 select * into running from public.conversation_open_run(conversation);
 if running.run is null then raise exception 'conversationNothingToStop' using errcode='P0002'; end if;
 if running.person<>auth.uid() and not public.can_manage_company(c) then raise exception 'conversationStopNotAllowed' using errcode='42501'; end if;
 select a.profile into named from public.conversations cv join public.hermes_agents a on a.id=cv.agent_id and a.company_id=cv.company_id where cv.id=conversation;
 return query select running.run,named;
end $$;

ALTER FUNCTION public.conversation_stop_target(conversation uuid, c uuid) OWNER TO postgres;

--
-- Name: conversation_title(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.conversation_title(conversation uuid, agent_name text) RETURNS text
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
 select coalesce((select coalesce(nullif(split_part(m.body,E'\n',1),''),(select a.name from public.conversation_attachments a where a.message_id=m.id order by a.position,a.id limit 1))
  from public.conversation_messages m where m.conversation_id=conversation and m.author='person' order by m.id limit 1),agent_name);
$$;

ALTER FUNCTION public.conversation_title(conversation uuid, agent_name text) OWNER TO postgres;

--
-- Name: conversation_work_stops(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.conversation_work_stops(conversation uuid) RETURNS TABLE(kind text, agent_id uuid, agent_name text)
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
 select 'run'::text, v.agent_id, v.agent_name from public.conversations v
 where v.id=conversation and (exists(select 1 from public.conversation_open_run(v.id))
  or exists(select 1 from public.conversation_queued_turns q where q.conversation_id=v.id and q.started_at is null and q.failed_at is null)
  or exists(select 1 from public.agent_handovers h where h.conversation_id=v.id and h.state not in ('done','failed')))
 union all
 select distinct r.kind, v.agent_id, v.agent_name from public.conversations v
  join public.reply_cards r on r.conversation_id=v.id and r.company_id=v.company_id and r.kind in ('question','permission','hand') and r.state='open'
 where v.id=conversation
  and (r.kind='hand' or not exists(select 1 from public.conversation_run_ends u where u.conversation_id=r.conversation_id and u.run_id=r.run_id));
$$;

ALTER FUNCTION public.conversation_work_stops(conversation uuid) OWNER TO postgres;

--
-- Name: conversation_working_for(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.conversation_working_for(conversation uuid) RETURNS TABLE(person uuid, name text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
 with mine as (select cv.id, cv.person_id from public.conversations cv
  where cv.id=conversation_working_for.conversation and cv.person_id=auth.uid() and public.is_member(cv.company_id))
 select o.person,o.author_name from public.conversation_open_run(conversation) o where exists(select 1 from mine)
 union all
 select mine.person_id,p.name from mine join public.people p on p.id=mine.person_id
 where not exists(select 1 from public.conversation_open_run(conversation))
  and exists(select 1 from public.agent_handovers h where h.conversation_id=mine.id and h.state not in ('done','failed'))
 limit 1;
$$;

ALTER FUNCTION public.conversation_working_for(conversation uuid) OWNER TO postgres;

--
-- Name: create_card_request(uuid, text, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.create_card_request(c uuid, message text, agent uuid, card_mode text) RETURNS bigint
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare result bigint; first_stage bigint; text_body text := btrim(coalesce(message,'')); begin
 if not public.work_can_edit(c) then raise exception 'not permitted'; end if;
 if text_body='' or card_mode is null or card_mode not in ('plan','do','answer') then raise exception 'invalid request' using errcode='22023'; end if;
 if agent is null or not exists(select 1 from public.hermes_agents h where h.company_id=c and h.id=agent)
  or not public.can_see_agent(c,agent) then raise exception 'agent not found'; end if;
 select id into first_stage from public.work_stages where company_id=c and kind='ideas';
 if first_stage is null then raise exception 'no Ideas stage'; end if;
 insert into public.work_cards(company_id,stage_id,title,mode,agent_id) values (c,first_stage,left(btrim(split_part(text_body,E'\n',1)),80),card_mode,agent) returning id into result;
 insert into public.work_comments(company_id,card_id,body) values (c,result,text_body);
 return result;
end $$;

ALTER FUNCTION public.create_card_request(c uuid, message text, agent uuid, card_mode text) OWNER TO postgres;

--
-- Name: create_channel(uuid, uuid, text, uuid[], uuid[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.create_channel(c uuid, request_key uuid, channel_name text, people uuid[], agents uuid[]) RETURNS uuid
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO ''
    AS $$
 select public.create_channel_inviting(c, request_key, channel_name, people, agents, null);
$$;

ALTER FUNCTION public.create_channel(c uuid, request_key uuid, channel_name text, people uuid[], agents uuid[]) OWNER TO postgres;

--
-- Name: create_channel_inviting(uuid, uuid, text, uuid[], uuid[], uuid[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.create_channel_inviting(c uuid, request_key uuid, channel_name text, people uuid[], agents uuid[], invitees uuid[]) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare made public.channels; called text; chosen uuid; open_invite public.member_invitations;
begin
 if auth.uid() is null or not public.can_manage_company(c) or exists(select 1 from public.companies where id=c and work_mode='alone') then
  raise exception 'channelNotAllowed' using errcode='42501'; end if;
 if request_key is null then raise exception 'channelFailed' using errcode='22023'; end if;
 select * into made from public.channels where company_id=c and create_key=request_key;
 if made.id is not null then
  if made.created_by is distinct from auth.uid() then raise exception 'channelFailed' using errcode='22023'; end if;
  return made.id;
 end if;
 called := regexp_replace(regexp_replace(coalesce(channel_name,''), '[[:space:]]+$', ''), '^[#[:space:]]+', '');
 if called = '' then raise exception 'channelNameMissing' using errcode='22023'; end if;
 if length(called) > 32 then raise exception 'channelNameTooLong' using errcode='22023'; end if;
 if lower(called) in ('general','عام') or exists(select 1 from public.channels where company_id=c and kind='team' and lower(name)=lower(called)) then
  raise exception 'channelNameTaken' using errcode='23505'; end if;
 if exists(select 1 from unnest(coalesce(people,'{}')) p where not public.channel_person(c, p)) then
  raise exception 'memberNotFound' using errcode='P0002'; end if;
 for chosen in select distinct unnest(coalesce(invitees,'{}')) loop
  select * into open_invite from public.member_invitations v
   where v.id=chosen and v.company_id=c and v.claimed_at is null and v.ended_at is null for share;
  if open_invite.id is null then raise exception 'memberNotFound' using errcode='P0002'; end if;
 end loop;
 if exists(select 1 from unnest(coalesce(agents,'{}')) a where not exists(select 1 from public.hermes_agents h where h.company_id=c and h.id=a)
  or not public.agent_visible_to(c, auth.uid(), a)) then
  raise exception 'agentNotFound' using errcode='P0002'; end if;
 begin
  insert into public.channels(company_id, kind, name, created_by, create_key) values (c, 'team', called, auth.uid(), request_key) returning * into made;
 exception when unique_violation then
  select * into made from public.channels where company_id=c and create_key=request_key and created_by=auth.uid();
  if made.id is not null then return made.id; end if;
  raise exception 'channelNameTaken' using errcode='23505';
 end;
 insert into public.channel_people(channel_id, company_id, person_id, added_by)
  select made.id, c, p, auth.uid() from (select auth.uid() union select unnest(coalesce(people,'{}'))) x(p);
 insert into public.channel_agents(channel_id, company_id, agent_id, added_by)
  select made.id, c, a, auth.uid() from (select distinct unnest(coalesce(agents,'{}'))) x(a);
 insert into public.channel_invitees(channel_id, company_id, invitation_id, added_by)
  select made.id, c, i, auth.uid() from (select distinct unnest(coalesce(invitees,'{}'))) x(i);
 return made.id;
end $_$;

ALTER FUNCTION public.create_channel_inviting(c uuid, request_key uuid, channel_name text, people uuid[], agents uuid[], invitees uuid[]) OWNER TO postgres;

--
-- Name: create_company_with_owner(uuid, text, uuid, text, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.create_company_with_owner(engine uuid, company_name text, person uuid, person_name text, language text, slug text DEFAULT NULL::text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare company uuid:=gen_random_uuid(); made text;
begin
 if person is null or engine is null then raise exception 'invalidOwner' using errcode='22023'; end if;
 if company_name is null or length(trim(company_name)) not between 1 and 120 then raise exception 'invalidCompany' using errcode='22023'; end if;
 perform 1 from public.company_engines e where e.id=engine and not exists(select 1 from public.companies c where c.engine_id=e.id) for update;
 if not found then raise exception 'companyEngineUnknown' using errcode='55000'; end if;
 if not exists(select 1 from public.people p where p.id=person) then
  if person_name is null or length(trim(person_name)) not between 1 and 120 or language is null or language not in ('en','ar') then
   raise exception 'invalidOwner' using errcode='22023';
  end if;
  insert into public.people(id,name,language) values(person,trim(person_name),language);
 end if;
 if slug is null or slug='' then
  made:=coalesce(nullif(trim(both '-' from regexp_replace(lower(company_name),'[^a-z0-9]+','-','g')),''),'company') || '-' || left(company::text,8);
 else
  if slug !~ '^[a-z0-9-]{1,80}$' then raise exception 'invalidCompanySlug' using errcode='22023'; end if;
  made:=slug;
 end if;
 insert into public.companies(id,slug,name,work_mode,engine_id) values(company,made,trim(company_name),null,engine);
 insert into public.members(company_id,person_id,role,grant_publishing,grant_money_figures,grant_customer_data) values(company,person,'owner',true,true,true);
 return made;
end $_$;

ALTER FUNCTION public.create_company_with_owner(engine uuid, company_name text, person uuid, person_name text, language text, slug text) OWNER TO postgres;

--
-- Name: create_work_card(uuid, bigint, text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.create_work_card(c uuid, s bigint, card_title text, agent uuid) RETURNS bigint
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare result bigint; begin
 if not public.work_can_edit(c) then raise exception 'not permitted'; end if;
 if btrim(coalesce(card_title,''))='' then raise exception 'invalid idea' using errcode='22023'; end if;
 if not exists(select 1 from public.work_stages where company_id=c and id=s and kind='ideas') then raise exception 'no Ideas stage'; end if;
 if agent is null or not exists(select 1 from public.hermes_agents h where h.company_id=c and h.id=agent)
  or not public.can_see_agent(c,agent) then raise exception 'agent not found'; end if;
 perform set_config('work.idea','yes',true);
 insert into public.work_cards(company_id,stage_id,title,agent_id,board_order) values(c,s,card_title,agent,
  coalesce((select min(w.board_order) from public.work_cards w join public.work_stages t on t.company_id=w.company_id and t.id=w.stage_id
   where w.company_id=c and t.board_column='ideas'),1)-1) returning id into result;
 perform set_config('work.idea','',true);
 return result;
end $$;

ALTER FUNCTION public.create_work_card(c uuid, s bigint, card_title text, agent uuid) OWNER TO postgres;

--
-- Name: create_work_card(uuid, bigint, text, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.create_work_card(c uuid, s bigint, card_title text, template text DEFAULT ''::text, evidence text DEFAULT NULL::text) RETURNS bigint
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$ declare result bigint; label_name text; item text; begin
 if not public.work_can_edit(c) then raise exception 'not permitted'; end if;
 perform set_config('work.evidence',coalesce(evidence,''),true);
 insert into public.work_cards(company_id,stage_id,title,format) values(c,s,card_title,case template when 'reel' then 'ريل' when 'carosel' then 'كاروسيل' when 'static' then 'بوست' else '' end) returning id into result;
 if template in ('reel','carosel','static') then
 insert into public.work_card_labels(company_id,card_id,label_id) select c,result,id from public.work_labels where company_id=c and name=template;
 foreach item in array (case when template='reel' then array['Script Ready','Caption Written','videographer','Video Edited','Review','Approved','ScheduledPublished'] else array['TOV Ready','Caption Written','Design Finished','Review','Approved','ScheduledPublished'] end) loop insert into public.work_checklist(company_id,card_id,title) values(c,result,item); end loop; end if; return result; end $$;

ALTER FUNCTION public.create_work_card(c uuid, s bigint, card_title text, template text, evidence text) OWNER TO postgres;

--
-- Name: crew(public.work_cards); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.crew(card public.work_cards) RETURNS uuid[]
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
 select coalesce(array_agg(x.agent_id order by x.first_at,x.agent_id),'{}') from (
  select l.agent_id,min(l.created_at) first_at from public.company_log l
  where l.company_id=card.company_id and l.card_id=card.id
   and (exists(select 1 from public.hermes_agents h where h.id=l.agent_id and h.company_id=l.company_id)
    or exists(select 1 from public.agent_looks k where k.agent_id=l.agent_id and k.company_id=l.company_id and k.kept_name is not null))
  group by l.agent_id) x;
$$;

ALTER FUNCTION public.crew(card public.work_cards) OWNER TO postgres;

--
-- Name: decide_agent_rule(uuid, bigint, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.decide_agent_rule(c uuid, item bigint, approve boolean) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare kept public.agent_rules; wanted text:=case when approve then 'approved' when not approve then 'rejected' end;
begin
 if wanted is null then raise exception 'agentRuleDecisionMissing' using errcode='22023'; end if;
 select r.* into kept from public.waiting_items i join public.agent_rules r on r.id=i.agent_rule_id and r.company_id=i.company_id
  where i.id=item and i.company_id=c and i.person_id=auth.uid() and i.kind='rule_suggestion' and r.agent_id is not null and r.suggestion is not null and r.removed_at is null
  for update of r;
 if not found or not public.can_see_agent(c,kept.agent_id) then raise exception 'agentRuleNotFound' using errcode='P0002'; end if;
 if not public.may_tell_agent_rules(c,kept.agent_id,auth.uid()) then raise exception 'agentRuleNotAllowed' using errcode='42501'; end if;
 if kept.suggestion=wanted then return wanted; end if;
 if kept.suggestion<>'pending' then raise exception 'agentRuleDecided' using errcode='22023'; end if;
 update public.agent_rules set suggestion=wanted,decided_by=auth.uid(),decided_at=now() where id=kept.id;
 update public.waiting_items set resolved_at=now() where agent_rule_id=kept.id and resolved_at is null;
 perform public.log_agent_event(c,auth.uid(),(select name from public.people where id=auth.uid()),kept.agent_id,case when approve then 'AGENT_RULE_APPROVED' else 'AGENT_RULE_REJECTED' end,
   jsonb_build_object('rule',kept.body,'rule_id',kept.id,'taught_by',(select name from public.people where id=kept.said_by))
    ||case when approve then '{}'::jsonb else jsonb_build_object('private',true,'teller',kept.said_by) end);
 return wanted;
end $$;

ALTER FUNCTION public.decide_agent_rule(c uuid, item bigint, approve boolean) OWNER TO postgres;

--
-- Name: decide_approval(uuid, bigint, text, text, boolean, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.decide_approval(c uuid, card bigint, decision text, reason text DEFAULT NULL::text, caption_marked boolean DEFAULT false, design_marked boolean DEFAULT false) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare w public.work_cards%rowtype; s public.approval_steps%rowtype; nxt bigint; target bigint; begin
 select * into w from public.work_cards where company_id=c and id=card for update;
 if not found or not public.can_see_card(c,card) or not public.approval_holds(c,w.approval_step_id) or not exists(select 1 from public.work_stages where company_id=c and id=w.stage_id and kind='review') then raise exception 'not current approver'; end if;
 select * into s from public.approval_steps where company_id=c and id=w.approval_step_id;
 if decision not in ('approve','reject') then raise exception 'invalid decision'; end if;
 if decision='reject' and (nullif(trim(reason),'') is null or not (caption_marked or design_marked)) then raise exception 'reason and marked part required'; end if;
 insert into public.work_activity(company_id,card_id,actor_id,action,details) values(c,card,auth.uid(),case when decision='approve' then 'approval_approved' else 'approval_rejected' end,jsonb_build_object('step',s.name,'step_id',s.id,'reason',reason,'caption',caption_marked,'design',design_marked));
 perform set_config('approval.internal','yes',true);
 if decision='reject' then
  target=public.required_work_stage(c,case when caption_marked then 'writing' else 'design' end);
  update public.work_cards set stage_id=target,approval_step_id=null,next_actor=w.review_submitter,rejection_reason=trim(reason) where company_id=c and id=card;
 else
  select id into nxt from public.approval_steps where company_id=c and removed_at is null and (position,id)>(s.position,s.id) order by position,id limit 1;
  if nxt is not null then update public.work_cards set approval_step_id=nxt,next_actor=public.approval_actor(c,nxt) where company_id=c and id=card;
  else
   target=public.required_work_stage(c,'approved');
   update public.work_cards set stage_id=target,approval_step_id=null,next_actor=null where company_id=c and id=card;
   if w.go_live is not null then target=public.required_work_stage(c,'scheduled'); update public.work_cards set stage_id=target where company_id=c and id=card; end if;
  end if;
 end if;
 perform set_config('approval.internal','',true);
end $$;

ALTER FUNCTION public.decide_approval(c uuid, card bigint, decision text, reason text, caption_marked boolean, design_marked boolean) OWNER TO postgres;

--
-- Name: decide_channel_permission(uuid, bigint, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.decide_channel_permission(c uuid, request bigint, choice text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare asked public.channel_permissions; called public.channel_runs; caller uuid;
begin
 select * into asked from public.channel_permissions p where p.id=request and p.company_id=c and public.in_channel(p.channel_id) for update;
 if not found then raise exception 'channelNotFound' using errcode='P0002'; end if;
 select * into called from public.channel_runs where run_id=asked.run_id;
 select person_id into caller from public.channel_messages where id=asked.message_id;
 if caller is distinct from auth.uid() or not public.conversation_can_write(c) or called.agent_id is null
  or not public.channel_agent(asked.channel_id,auth.uid(),called.agent_id) then raise exception 'channelNotAllowed' using errcode='42501'; end if;
 if asked.state in ('sending','decided') then
  return jsonb_build_object('state','decided','choice',asked.content->'choice','at',asked.decided_at,'first',false); end if;
 if asked.state<>'open' then return jsonb_build_object('state','closed','choice',null,'at',null,'first',false); end if;
 if called.outcome is not null then
  update public.channel_permissions set state='closed' where id=asked.id;
  return jsonb_build_object('state','closed','choice',null,'at',null,'first',false);
 end if;
 if decide_channel_permission.choice is null or not asked.content->'choices' ? decide_channel_permission.choice then raise exception 'permissionChoiceInvalid' using errcode='22023'; end if;
 if not decide_channel_permission.choice=any(public.permission_choices(c)) then raise exception 'channelNotAllowed' using errcode='42501'; end if;
 update public.channel_permissions set state='sending',content=asked.content||jsonb_build_object('choice',decide_channel_permission.choice),decided_by=auth.uid(),decided_at=now()
  where id=asked.id returning * into asked;
 return jsonb_build_object('state','decided','choice',decide_channel_permission.choice,'at',asked.decided_at,'first',true);
end $$;

ALTER FUNCTION public.decide_channel_permission(c uuid, request bigint, choice text) OWNER TO postgres;

--
-- Name: decide_permission(uuid, uuid, bigint, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.decide_permission(c uuid, conversation uuid, card bigint, choice text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare talk public.conversations; asked public.reply_cards;
begin
 if not public.conversation_can_write(c) then raise exception 'conversationNotAllowed' using errcode='42501'; end if;
 select * into talk from public.conversations v where v.id=conversation and v.company_id=c;
 if not found or talk.person_id<>auth.uid() or not public.can_see_agent(c,talk.agent_id) then raise exception 'conversationNotFound' using errcode='P0002'; end if;
 select * into asked from public.reply_cards r where r.id=card and r.conversation_id=conversation and r.kind='permission' for update;
 if not found then raise exception 'conversationNotFound' using errcode='P0002'; end if;
 if asked.state in ('sending','decided') then
  return jsonb_build_object('state','decided','choice',asked.content->'choice','at',asked.decided_at,'first',false); end if;
 if asked.state<>'open' then return jsonb_build_object('state','closed','choice',null,'at',null,'first',false); end if;
 -- A slower closer may have kept this request after another ended its Run: nothing waits for it any more.
 if exists(select 1 from public.conversation_run_ends u where u.conversation_id=conversation and u.run_id=asked.run_id) then
  update public.reply_cards set state='closed' where id=asked.id;
  return jsonb_build_object('state','closed','choice',null,'at',null,'first',false);
 end if;
 if decide_permission.choice is null or not asked.content->'choices' ? decide_permission.choice then raise exception 'permissionChoiceInvalid' using errcode='22023'; end if;
 if not decide_permission.choice=any(public.permission_choices(c)) then raise exception 'conversationNotAllowed' using errcode='42501'; end if;
 update public.reply_cards set state='sending',content=asked.content||jsonb_build_object('choice',decide_permission.choice),decided_by=auth.uid(),decided_at=now()
  where id=asked.id returning * into asked;
 return jsonb_build_object('state','decided','choice',decide_permission.choice,'at',asked.decided_at,'first',true);
end $$;

ALTER FUNCTION public.decide_permission(c uuid, conversation uuid, card bigint, choice text) OWNER TO postgres;

--
-- Name: discard_channel_files(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.discard_channel_files(ch uuid, c uuid, message_key uuid) RETURNS SETOF text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
 if not exists(select 1 from public.channels k where k.id=ch and k.company_id=c) or not public.in_channel(ch) then
  raise exception 'channelNotFound' using errcode='P0002'; end if;
 if not public.conversation_can_write(c) then raise exception 'channelNotAllowed' using errcode='42501'; end if;
 perform pg_advisory_xact_lock(hashtextextended('channel_files:'||ch::text||':'||message_key::text,0));
 return query delete from public.channel_attachments a
  where a.channel_id=ch and a.company_id=c and a.send_key=message_key
   and a.message_id is null and a.person_id=auth.uid()
  returning a.path;
end;
$$;

ALTER FUNCTION public.discard_channel_files(ch uuid, c uuid, message_key uuid) OWNER TO postgres;

--
-- Name: discard_channel_files(uuid, uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.discard_channel_files(ch uuid, c uuid, message_key uuid, attempt uuid) RETURNS SETOF text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
 if not exists(select 1 from public.channels k where k.id=ch and k.company_id=c) or not public.in_channel(ch) then
  raise exception 'channelNotFound' using errcode='P0002'; end if;
 if not public.conversation_can_write(c) then raise exception 'channelNotAllowed' using errcode='42501'; end if;
 perform pg_advisory_xact_lock(hashtextextended('channel_files:'||ch::text||':'||message_key::text,0));
 if attempt is null then raise exception 'channelFilesInvalid' using errcode='22023'; end if;
 update public.channel_attachments a set holders=array_remove(a.holders,attempt)
  where a.channel_id=ch and a.company_id=c and a.send_key=message_key and a.message_id is null and a.person_id=auth.uid()
   and attempt=any(a.holders);
 return query delete from public.channel_attachments a
  where a.channel_id=ch and a.company_id=c and a.send_key=message_key
   and a.message_id is null and a.person_id=auth.uid()
   and (cardinality(a.holders)=0 or a.held_at<now()-interval '15 minutes')
  returning a.path;
end;
$$;

ALTER FUNCTION public.discard_channel_files(ch uuid, c uuid, message_key uuid, attempt uuid) OWNER TO postgres;

--
-- Name: discard_conversation_files(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.discard_conversation_files(conversation uuid, c uuid, message_key uuid) RETURNS SETOF text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
 if not public.conversation_can_write(c) then raise exception 'conversationNotAllowed' using errcode='42501'; end if;
 if not exists(select 1 from public.conversations v where v.id=conversation and v.company_id=c and v.person_id=auth.uid()) then
  raise exception 'conversationNotFound' using errcode='P0002'; end if;
 -- Under the Conversation's turn lock (a turn is queued and claimed under it) and then the agents lock (a turn is
 -- recorded or failed, and a reservation begun, released, kept unknown or abandoned, under it), in the order every
 -- other function takes them, so neither changes while this decides.
 perform pg_advisory_xact_lock(hashtextextended('conversation_files:'||conversation::text||':'||message_key::text,0));
 perform pg_advisory_xact_lock(hashtextextended('conversation_turn:'||conversation::text,0));
 perform pg_advisory_xact_lock(hashtextextended('hermes_agents',0));
 if exists(select 1 from public.conversation_queued_turns q where q.conversation_id=conversation and q.send_key=message_key
   and q.started_at is null and q.failed_at is null)
  or exists(select 1 from public.conversation_run_reservations r where r.conversation_id=conversation and r.send_key=message_key
   and r.abandoned_at is null) then
  return;
 end if;
 return query delete from public.conversation_attachments a
  where a.conversation_id=conversation and a.company_id=c and a.send_key=message_key and a.message_id is null
  returning a.path;
end;
$$;

ALTER FUNCTION public.discard_conversation_files(conversation uuid, c uuid, message_key uuid) OWNER TO postgres;

--
-- Name: discard_conversation_files(uuid, uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.discard_conversation_files(conversation uuid, c uuid, message_key uuid, attempt uuid) RETURNS SETOF text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
 if not public.conversation_can_write(c) then raise exception 'conversationNotAllowed' using errcode='42501'; end if;
 if not exists(select 1 from public.conversations v where v.id=conversation and v.company_id=c and v.person_id=auth.uid()) then
  raise exception 'conversationNotFound' using errcode='P0002'; end if;
 -- Under the Conversation's turn lock (a turn is queued and claimed under it) and then the agents lock (a turn is
 -- recorded or failed, and a reservation begun, released, kept unknown or abandoned, under it), in the order every
 -- other function takes them, so neither changes while this decides.
 perform pg_advisory_xact_lock(hashtextextended('conversation_files:'||conversation::text||':'||message_key::text,0));
 perform pg_advisory_xact_lock(hashtextextended('conversation_turn:'||conversation::text,0));
 perform pg_advisory_xact_lock(hashtextextended('hermes_agents',0));
 if attempt is null then raise exception 'conversationFilesInvalid' using errcode='22023'; end if;
 update public.conversation_attachments a set holders=array_remove(a.holders,attempt)
  where a.conversation_id=conversation and a.company_id=c and a.send_key=message_key and a.message_id is null
   and attempt=any(a.holders);
 if exists(select 1 from public.conversation_queued_turns q where q.conversation_id=conversation and q.send_key=message_key
   and q.started_at is null and q.failed_at is null)
  or exists(select 1 from public.conversation_run_reservations r where r.conversation_id=conversation and r.send_key=message_key
   and r.abandoned_at is null) then
  return;
 end if;
 return query delete from public.conversation_attachments a
  where a.conversation_id=conversation and a.company_id=c and a.send_key=message_key and a.message_id is null
   and (cardinality(a.holders)=0 or a.held_at<now()-interval '15 minutes')
  returning a.path;
end;
$$;

ALTER FUNCTION public.discard_conversation_files(conversation uuid, c uuid, message_key uuid, attempt uuid) OWNER TO postgres;

