--
-- Name: edit_card_note(uuid, bigint, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.edit_card_note(c uuid, note bigint, note_body text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare changed bigint;
begin
 if not public.work_can_edit(c) then raise exception 'noteNotAllowed' using errcode='42501'; end if;
 if not exists(select 1 from public.work_comments where id=note and company_id=c and public.can_see_card(c,card_id)) then raise exception 'noteNotFound' using errcode='P0002'; end if;
 update public.work_comments set body=btrim(coalesce(note_body,''), E' \t\r\n') where id=note and company_id=c returning id into changed;
 return changed is not null;
end $$;

ALTER FUNCTION public.edit_card_note(c uuid, note bigint, note_body text) OWNER TO postgres;

--
-- Name: edit_work_card(uuid, bigint, jsonb, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.edit_work_card(c uuid, card bigint, fields jsonb, evidence text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$ declare pid bigint; begin
 if fields ? 'project_id' then
  pid=nullif(fields->>'project_id','')::bigint;
  if pid is not null and not exists(select 1 from public.work_projects p where p.company_id=c and p.id=pid) then raise exception 'project not found'; end if;
 end if;
 perform set_config('work.evidence',coalesce(evidence,''),true); update public.work_cards set title=coalesce(fields->>'title',title), offering=coalesce(fields->>'offering',offering), segment=coalesce(fields->>'segment',segment), hook=coalesce(fields->>'hook',hook), channel=coalesce(fields->>'channel',channel), format=coalesce(fields->>'format',format), goal=coalesce(fields->>'goal',goal), caption=coalesce(fields->>'caption',caption), project_id=case when fields ? 'project_id' then pid else project_id end, go_live=case when fields ? 'go_live' and date_trunc('minute',go_live) is distinct from date_trunc('minute',nullif(fields->>'go_live','')::timestamptz) then nullif(fields->>'go_live','')::timestamptz else go_live end where company_id=c and id=card; if not found then raise exception 'card not found or not permitted'; end if; end $$;

ALTER FUNCTION public.edit_work_card(c uuid, card bigint, fields jsonb, evidence text) OWNER TO postgres;

--
-- Name: end_conversation_run(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.end_conversation_run(conversation uuid, run text) RETURNS boolean
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO ''
    AS $$
 with ended as (
  update public.conversations v set open_runs=array_remove(v.open_runs,run)
  where v.id=conversation and v.person_id=auth.uid() and run=any(v.open_runs) and public.is_member(v.company_id)
  returning 1)
 select exists(select 1 from ended);
$$;

ALTER FUNCTION public.end_conversation_run(conversation uuid, run text) OWNER TO postgres;

--
-- Name: end_handovers_stopped(bigint[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.end_handovers_stopped(ids bigint[]) RETURNS TABLE(handover bigint, run text, profile text)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO ''
    AS $$
 with open as (
  select h.id, h.state as was, h.parent_id, h.answers_person, h.company_id, h.conversation_id, h.run_id,
   case h.state when 'target' then h.target_run when 'answering' then h.answer_run when 'follow_up' then h.follow_up_run end as going,
   case h.state when 'target' then t.profile when 'answering' then t.profile when 'follow_up' then f.profile end as on_profile
  from public.agent_handovers h
   join public.hermes_agents t on t.id=h.to_agent
   join public.hermes_agents f on f.id=h.from_agent
  where h.id=any(ids) and h.state not in ('done','failed')
  order by h.id
  for update of h
 ), ended as (
  update public.agent_handovers h set state='done', closed_at=now(), attempted_at=null,
   target_outcome=case when o.was in ('waiting','target','handing','answering') then 'stopped' else h.target_outcome end,
   target_closed_at=case when o.was in ('waiting','target','handing','answering') then now() else h.target_closed_at end,
   follow_up_outcome=case when o.was in ('returning','follow_up') and o.parent_id is null and not o.answers_person then 'stopped' else h.follow_up_outcome end,
   stopping_run=o.going, stopping_profile=case when o.going is not null then o.on_profile end
  from open o where h.id=o.id
  returning h.id, o.going, o.on_profile, o.answers_person, o.company_id, o.conversation_id, o.run_id
 ), told as (
  insert into public.conversation_run_ends(company_id,conversation_id,run_id,outcome)
   select e.company_id,e.conversation_id,e.run_id,'stopped' from ended e where e.answers_person and e.conversation_id is not null
   on conflict do nothing
 )
 select e.id, e.going, case when e.going is not null then e.on_profile end from ended e order by e.id;
$$;

ALTER FUNCTION public.end_handovers_stopped(ids bigint[]) OWNER TO postgres;

