--
-- Name: finish_agent_change(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.finish_agent_change(change uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare held public.held_agent_changes;
begin
 delete from public.held_agent_changes h where h.id=change and h.actor_id=auth.uid() returning h.* into held;
 if held.id is null then return false; end if;
 perform public.log_held_change(held,true);
 return true;
end $$;

ALTER FUNCTION public.finish_agent_change(change uuid) OWNER TO postgres;

--
-- Name: finish_app_sign_in(text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.finish_app_sign_in(app_key text, flow text) RETURNS TABLE(company_id uuid, slug text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare pending public.company_app_sign_ins;
begin
 select * into pending from public.company_app_sign_ins s where s.app=app_key and s.flow_id=flow and s.started_by=auth.uid() and s.finished_at is null for update;
 if pending.id is null then return; end if;
 if not public.is_company_owner(pending.company_id) then raise exception 'appsNotAllowed' using errcode='42501'; end if;
 update public.company_app_sign_ins s set finished_at=now() where s.id=pending.id;
 insert into public.company_audit(company_id,actor_id,action,app,agent_id) values (pending.company_id,auth.uid(),'app_connected',pending.app,pending.agent_id);
 return query select pending.company_id,(select c.slug from public.companies c where c.id=pending.company_id);
end $$;

ALTER FUNCTION public.finish_app_sign_in(app_key text, flow text) OWNER TO postgres;

--
-- Name: finish_held_agent_changes(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.finish_held_agent_changes() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare change uuid; held public.held_agent_changes; logged integer:=0;
begin
 for change in select o.id from public.held_agent_changes o where o.held_at<=now()-interval '15 minutes' order by o.held_at limit 100 loop
  begin
   delete from public.held_agent_changes h where h.id=change returning h.* into held;
   if held.id is not null then
    perform public.log_held_change(held,false);
    logged:=logged+1;
   end if;
  exception when others then
   raise warning 'held agent change % not logged: %',change,sqlerrm;
  end;
 end loop;
 return logged;
end $$;

ALTER FUNCTION public.finish_held_agent_changes() OWNER TO postgres;

--
-- Name: finish_provider_key_change(uuid, text, boolean, text[], boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.finish_provider_key_change(c uuid, key_provider text, now_held boolean, reached text[], answered boolean DEFAULT true) RETURNS text[]
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare kept boolean;
begin
 if coalesce(key_provider,'') !~ '^[a-z0-9][a-z0-9._-]{0,63}$' then raise exception 'keyInvalid' using errcode='22023'; end if;
 perform pg_advisory_xact_lock(hashtextextended('hermes_agents',0));
 -- A change whose begin the database did not take has no row yet: its finish records the hold all the same.
 insert into public.company_key_holds as h(company_id,provider,held,changing,uncertain,changed_at,version)
  values(c,key_provider,case when not answered then false else coalesce(now_held,false) end,false,coalesce(not answered,false),case when not answered then now() end,(select coalesce(max(k.version),0)+1 from public.company_key_holds k where k.company_id=c))
  -- An unanswered set keeps the hold the Company had: its mark holds the Company's Agents until the space settles it.
  on conflict (company_id,provider) do update set held=case when not answered then h.held else coalesce(now_held,h.held) end,changing=false,
   uncertain=case when not answered then true when answered and now_held then false else h.uncertain end,
   changed_at=case when not answered then now() else h.changed_at end,version=(select coalesce(max(k.version),0)+1 from public.company_key_holds k where k.company_id=c)
  returning h.held into kept;
 if not public.company_holds_provider_key(c) then
  delete from public.agent_key_waits w where w.company_id=c;
  return '{}';
 end if;
 if not coalesce(kept,false) then return '{}'; end if;
 delete from public.agent_key_waits w using public.agent_profiles p
  where w.company_id=c and p.agent_id=w.agent_id and p.company_id=c and p.profile=any(coalesce(reached,'{}'));
 return array(select p.profile from public.agent_key_waits w join public.agent_profiles p on p.agent_id=w.agent_id and p.company_id=w.company_id
  where w.company_id=c order by w.id);
end $_$;

ALTER FUNCTION public.finish_provider_key_change(c uuid, key_provider text, now_held boolean, reached text[], answered boolean) OWNER TO postgres;

