--
-- Name: handover_not_finished(text, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.handover_not_finished(outcome text, agent text, unreached text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
 select case coalesce(outcome,'failed')
  when 'stopped' then 'was stopped before ' || unreached || '.'
  when 'lost' then 'could not be found before ' || unreached || '.'
  when 'no_model' then 'could not reply, because the company has no AI subscription or model key connected yet. The Owner can connect one in Providers.'
  when 'no_credit' then 'could not reply, because the company''s model key has no credit left. The Owner can check ' || agent || '''s model in Providers.'
  when 'key_refused' then 'could not reply, because the model provider refused the company''s key or sign-in. The Owner can check ' || agent || '''s model in Providers.'
  when 'model_missing' then 'could not reply, because its model is not available from the provider. The Owner can check ' || agent || '''s model in Providers.'
  when 'no_access' then 'could not reply, because every account it can use has run out of usage for now. The Owner can add an account or choose a fallback model in Providers.'
  else 'failed before ' || unreached || '.' end;
$$;

ALTER FUNCTION public.handover_not_finished(outcome text, agent text, unreached text) OWNER TO postgres;

--
-- Name: handover_root(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.handover_root(h bigint) RETURNS bigint
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
 with recursive up(id,parent_id) as (
  select x.id,x.parent_id from public.agent_handovers x where x.id=h
  union all
  select p.id,p.parent_id from public.agent_handovers p join up on p.id=up.parent_id)
 select id from up where parent_id is null limit 1;
$$;

ALTER FUNCTION public.handover_root(h bigint) OWNER TO postgres;

--
-- Name: handover_run_stopped(bigint, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.handover_run_stopped(h bigint, run text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare cleared bigint;
begin
 update public.agent_handovers x set stopping_run=null, stopping_profile=null where x.id=h and x.stopping_run=handover_run_stopped.run returning x.id into cleared;
 return cleared is not null;
end $$;

ALTER FUNCTION public.handover_run_stopped(h bigint, run text) OWNER TO postgres;

--
-- Name: handover_runs_stopping(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.handover_runs_stopping(after bigint DEFAULT 0) RETURNS TABLE(id bigint, run text, profile text, company uuid)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
 select x.id, x.stopping_run, coalesce(x.stopping_profile,a.profile), x.company_id from public.agent_handovers x
  left join public.hermes_agents a on a.id=case when x.follow_up_outcome='stopped' then x.from_agent else x.to_agent end
 where x.stopping_run is not null and x.id>coalesce(after,0)
 order by x.id limit 500;
$$;

ALTER FUNCTION public.handover_runs_stopping(after bigint) OWNER TO postgres;

--
-- Name: agent_handovers; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.agent_handovers (
    id bigint NOT NULL,
    company_id uuid NOT NULL,
    conversation_id uuid,
    run_id text NOT NULL,
    call_id text NOT NULL,
    from_agent uuid NOT NULL,
    to_agent uuid NOT NULL,
    goal text NOT NULL,
    context text,
    state text DEFAULT 'waiting'::text NOT NULL,
    target_attempts integer DEFAULT 0 NOT NULL,
    return_attempts integer DEFAULT 0 NOT NULL,
    attempted_at timestamp with time zone,
    target_run text,
    target_outcome text,
    summary text,
    follow_up_run text,
    follow_up_outcome text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    return_started_at timestamp with time zone,
    closed_at timestamp with time zone,
    channel_message_id bigint,
    target_closed_at timestamp with time zone,
    reply text,
    answers_person boolean DEFAULT false NOT NULL,
    start_waited_at timestamp with time zone,
    session_held_until timestamp with time zone,
    parent_id bigint,
    tools text,
    answer_run text,
    answer_attempts integer DEFAULT 0 NOT NULL,
    answer_started_at timestamp with time zone,
    stopping_run text,
    stopping_profile text,
    stop_requested_at timestamp with time zone,
    CONSTRAINT agent_handovers_answer_attempts CHECK ((answer_attempts >= 0)),
    CONSTRAINT agent_handovers_answer_run CHECK (((state <> 'answering'::text) OR (answer_run IS NOT NULL))),
    CONSTRAINT agent_handovers_child_of_a_job CHECK (((parent_id IS NULL) OR (NOT answers_person))),
    CONSTRAINT agent_handovers_closed CHECK (((state = ANY (ARRAY['done'::text, 'failed'::text])) = (closed_at IS NOT NULL))),
    CONSTRAINT agent_handovers_context CHECK (((context IS NULL) OR ((length(btrim(context)) >= 1) AND (length(btrim(context)) <= 2000)))),
    CONSTRAINT agent_handovers_follow_up_outcome CHECK ((follow_up_outcome = ANY (ARRAY['completed'::text, 'failed'::text, 'no_model'::text, 'no_credit'::text, 'key_refused'::text, 'model_missing'::text, 'no_access'::text, 'stopped'::text, 'lost'::text]))),
    CONSTRAINT agent_handovers_follow_up_run CHECK (((state <> 'follow_up'::text) OR (follow_up_run IS NOT NULL))),
    CONSTRAINT agent_handovers_goal CHECK (((length(btrim(goal)) >= 1) AND (length(btrim(goal)) <= 500))),
    CONSTRAINT agent_handovers_one_place CHECK (((conversation_id IS NULL) <> (channel_message_id IS NULL))),
    CONSTRAINT agent_handovers_other_agent CHECK ((from_agent <> to_agent)),
    CONSTRAINT agent_handovers_reply CHECK (((reply IS NULL) OR ((length(reply) >= 1) AND (length(reply) <= 200000)))),
    CONSTRAINT agent_handovers_reply_only_reported CHECK (((reply IS NULL) OR (follow_up_outcome = 'completed'::text))),
    CONSTRAINT agent_handovers_return_attempts CHECK ((return_attempts >= 0)),
    CONSTRAINT agent_handovers_state CHECK ((state = ANY (ARRAY['waiting'::text, 'target'::text, 'handing'::text, 'answering'::text, 'returning'::text, 'follow_up'::text, 'done'::text, 'failed'::text]))),
    CONSTRAINT agent_handovers_summary CHECK (((summary IS NULL) OR ((length(summary) >= 1) AND (length(summary) <= 8000)))),
    CONSTRAINT agent_handovers_summary_only_reported CHECK (((target_outcome = 'completed'::text) = (summary IS NOT NULL))),
    CONSTRAINT agent_handovers_target_attempts CHECK ((target_attempts >= 0)),
    CONSTRAINT agent_handovers_target_outcome CHECK ((target_outcome = ANY (ARRAY['completed'::text, 'failed'::text, 'no_model'::text, 'no_credit'::text, 'key_refused'::text, 'model_missing'::text, 'no_access'::text, 'stopped'::text, 'lost'::text]))),
    CONSTRAINT agent_handovers_target_run CHECK (((state <> 'target'::text) OR (target_run IS NOT NULL)))
);

ALTER TABLE public.agent_handovers OWNER TO postgres;

--
-- Name: handover_start_unsure(public.agent_handovers); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.handover_start_unsure(h public.agent_handovers) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
 select (h.state='waiting' and h.target_attempts>0) or (h.state='handing' and h.answer_attempts>0) or (h.state='returning' and h.return_attempts>0);
$$;

ALTER FUNCTION public.handover_start_unsure(h public.agent_handovers) OWNER TO postgres;

--
-- Name: handover_writer(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.handover_writer(h bigint) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare r public.agent_handovers; root public.agent_handovers; person uuid; chan uuid;
begin
 select * into r from public.agent_handovers where id=h;
 if r.id is null then return false; end if;
 if r.conversation_id is not null then
  select c.person_id into person from public.conversations c where c.id=r.conversation_id and c.company_id=r.company_id;
  return person is not null and public.may_hand_to_agent(r.company_id,r.from_agent,person);
 end if;
 select * into root from public.agent_handovers where id=public.handover_root(h);
 select m.channel_id,m.person_id into chan,person from public.channel_messages m where m.id=r.channel_message_id and m.company_id=r.company_id;
 return chan is not null and root.id is not null and public.channel_can_hand_over(chan,person,root.from_agent);
end $$;

ALTER FUNCTION public.handover_writer(h bigint) OWNER TO postgres;

--
-- Name: handovers_due(uuid, bigint, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.handovers_due(just_conversation uuid DEFAULT NULL::uuid, after bigint DEFAULT 0, just_channel uuid DEFAULT NULL::uuid) RETURNS TABLE(id bigint, state text, conversation uuid, run text, profile text, attempt integer, company uuid)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
 select h.id, h.state, h.conversation_id,
  case h.state when 'target' then h.target_run when 'answering' then h.answer_run when 'follow_up' then h.follow_up_run end,
  case h.state
   when 'target' then (select a.profile from public.hermes_agents a where a.id=h.to_agent)
   when 'answering' then (select a.profile from public.hermes_agents a where a.id=h.to_agent)
   when 'follow_up' then (select a.profile from public.hermes_agents a where a.id=h.from_agent)
   else null end,
  case when h.state='returning' then h.return_attempts when h.state in ('handing','answering') then h.answer_attempts else h.target_attempts end,
  h.company_id
 from public.agent_handovers h
 where h.state not in ('done','failed') and h.id > coalesce(after,0)
  and (just_conversation is null or h.conversation_id=just_conversation)
  and (just_channel is null or exists(select 1 from public.channel_messages m where m.id=h.channel_message_id and m.channel_id=just_channel))
  and (h.state in ('target','answering','follow_up') or h.attempted_at is null or h.attempted_at < now()-interval '30 seconds')
  -- A leg still waiting on a child is not due: nothing would move it, and begin_handover takes the Engine lock.
  and not (h.state='handing' and exists(select 1 from public.agent_handovers c where c.parent_id=h.id and c.state not in ('done','failed')))
 order by h.id limit 500;
$$;

ALTER FUNCTION public.handovers_due(just_conversation uuid, after bigint, just_channel uuid) OWNER TO postgres;

--
-- Name: hermes_profile_address(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.hermes_profile_address(address text) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $_$
declare parts text[]; hostname text; port integer; segment text; path text[]:='{}';
begin
 parts:=regexp_match(address,'^(https?)://(\[[0-9a-f:]+\]|[a-z0-9_.-]+)(:[0-9]{1,5})?(/[^?#]*)?$','i');
 if parts is null or address ~ '[[:space:]]' or position(chr(92) in address)>0 then return null; end if;
 hostname:=lower(parts[2]);
 if left(hostname,1)='[' then hostname:='['||host(trim(hostname,'[]')::inet)||']';
 elsif hostname ~ '(^|\.)([0-9]+|0x[0-9a-f]+)$' then
  if hostname !~ '^[0-9]+\.[0-9]+\.[0-9]+\.[0-9]+$' or hostname<>host(hostname::inet) then return null; end if;
 end if;
 port:=substring(parts[3] from 2)::integer;
 if port>65535 then return null; end if;
 foreach segment in array string_to_array(coalesce(parts[4],''),'/') loop
  if regexp_replace(segment,'%2e','.','gi')='..' then
   if cardinality(path)>1 then path:=path[1:cardinality(path)-1]; end if;
  elsif regexp_replace(segment,'%2e','.','gi')<>'.' then path:=array_append(path,segment);
  end if;
 end loop;
 return lower(parts[1])||'://'||hostname||case when port is null or (lower(parts[1])='http' and port=80) or (lower(parts[1])='https' and port=443) then '' else ':'||port::text end||rtrim(array_to_string(path,'/'),'/');
exception when invalid_text_representation then return null;
end;
$_$;

ALTER FUNCTION public.hermes_profile_address(address text) OWNER TO postgres;

--
-- Name: hold_agent_change(uuid, uuid, text, text, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.hold_agent_change(c uuid, agent uuid, act text, skill text, note text, body text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare held uuid;
begin
 if act='memory_reset' then perform public.check_memory_reset(c,agent);
 elsif act='memory_edit' then perform public.check_memory_edit(c,agent,note);
 elsif act='memory_forget' then perform public.check_memory_forget(c,agent,note);
 elsif act in ('skill_written','skill_enabled','skill_disabled') then
  perform public.check_skill_write(c,agent,body);
  if skill is null or skill !~ '^[a-z0-9][a-z0-9_-]{0,63}$' then raise exception 'skillInvalid' using errcode='22023'; end if;
 else raise exception 'changeInvalid' using errcode='22023'; end if;
 insert into public.held_agent_changes(company_id,agent_id,agent_name,actor_id,act,skill)
  values(c,agent,(select a.name from public.hermes_agents a where a.id=agent),auth.uid(),act,case when act like 'skill_%' then skill end)
  returning id into held;
 return held;
end $_$;

ALTER FUNCTION public.hold_agent_change(c uuid, agent uuid, act text, skill text, note text, body text) OWNER TO postgres;

--
-- Name: hold_conversation_run(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.hold_conversation_run(conversation uuid, person uuid, run text) RETURNS boolean
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
 with held as (
  update public.conversations v set open_runs=case when run=any(v.open_runs) then v.open_runs else v.open_runs||run end
  where v.id=conversation and v.person_id=person and run ~ '^[A-Za-z0-9_.:-]{1,200}$' and (run=any(v.open_runs) or cardinality(v.open_runs)<32)
   and exists(select 1 from public.members m where m.company_id=v.company_id and m.person_id=person and m.removed_at is null and m.role<>'viewer')
  returning 1)
 select exists(select 1 from held);
$_$;

ALTER FUNCTION public.hold_conversation_run(conversation uuid, person uuid, run text) OWNER TO postgres;

