--
-- Name: keep_routine_results(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.keep_routine_results(c uuid, results jsonb) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare added integer;
begin
 if results is null or jsonb_typeof(results)<>'array' or jsonb_array_length(results)>500 then raise exception 'routineResultsInvalid' using errcode='22023'; end if;
 insert into public.routine_results(company_id,agent_id,profile,routine_id,session_id,routine,line,ended_at)
  select c,(r->>'agent')::uuid,r->>'profile',r->>'routine_id',r->>'session',nullif(left(trim(coalesce(r->>'routine','')),200),''),
   nullif(left(trim(coalesce(r->>'line','')),300),''),(r->>'at')::timestamptz
  from jsonb_array_elements(results) r
  where exists(select 1 from public.hermes_agents a where a.id=(r->>'agent')::uuid and a.company_id=c and a.profile=r->>'profile')
  on conflict (company_id,profile,session_id) do nothing;
 get diagnostics added=row_count;
 delete from public.routine_results r where r.company_id=c and r.ended_at<now()-interval '30 days';
 return added;
end $$;

ALTER FUNCTION public.keep_routine_results(c uuid, results jsonb) OWNER TO postgres;

--
-- Name: keep_running_routines(uuid, text, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.keep_running_routines(c uuid, at_profile text, agent uuid, running jsonb) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare held integer;
begin
 if running is null or jsonb_typeof(running)<>'array' or jsonb_array_length(running)>500 then raise exception 'runningRoutinesInvalid' using errcode='22023'; end if;
 if not exists(select 1 from public.hermes_agents a where a.id=agent and a.company_id=c and a.profile=at_profile) then return 0; end if;
 delete from public.routine_runs_open r where r.company_id=c and r.profile=at_profile
  and not exists(select 1 from jsonb_array_elements(running) x where x->>'routine_id'=r.routine_id);
 insert into public.routine_runs_open(company_id,agent_id,profile,routine_id,started_at,seen_at)
  select distinct on (x->>'routine_id') c,agent,at_profile,x->>'routine_id',(x->>'started_at')::timestamptz,now()
  from jsonb_array_elements(running) x
  on conflict (company_id,profile,routine_id) do update set agent_id=excluded.agent_id,started_at=excluded.started_at,seen_at=excluded.seen_at;
 select count(*)::int into held from public.routine_runs_open r where r.company_id=c and r.profile=at_profile;
 return held;
end $$;

ALTER FUNCTION public.keep_running_routines(c uuid, at_profile text, agent uuid, running jsonb) OWNER TO postgres;

