--
-- Name: lead_agent_profile(uuid, text, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.lead_agent_profile(conversation uuid, run text, call text, instructions text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
 select coalesce(
  (select jsonb_build_object('state','created','agent',l.agent_id) from public.lead_made_agents l
   where l.conversation_id=conversation and l.run_id=run and l.call_id=call),
  (select jsonb_build_object('profile',public.agent_engine_profile(public.lead_agent_id(conversation,run,call)),
    'soul',replace(instructions,'{company}',co.name))
   from public.conversations v join public.companies co on co.id=v.company_id
   where v.id=conversation and public.may_use_lead_tools(v.company_id,v.agent_id,v.person_id)));
$$;

ALTER FUNCTION public.lead_agent_profile(conversation uuid, run text, call text, instructions text) OWNER TO postgres;

--
-- Name: lead_agent_temperament(uuid, text, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.lead_agent_temperament(conversation uuid, run text, call text, temperament text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare c uuid;
begin
 if temperament is null or not (temperament=any(public.agent_look_choices('temperament'))) then
  return jsonb_build_object('state','invalid','reason',
   'The temperament must be one of calm, energetic, warm, dreamy, neat or caring, or left out. Nothing was made; call again with one of them, or without it.');
 end if;
 select v.company_id into c from public.conversations v where v.id=conversation
  and exists(select 1 from public.conversation_messages m where m.conversation_id=v.id and m.author='person' and m.run_id=run);
 if c is null then return jsonb_build_object('state','refused'); end if;
 insert into public.lead_agent_temperaments(agent_id,company_id,temperament) values(public.lead_agent_id(conversation,run,call),c,temperament)
  on conflict (agent_id) do nothing;
 return jsonb_build_object('state','kept');
end $$;

ALTER FUNCTION public.lead_agent_temperament(conversation uuid, run text, call text, temperament text) OWNER TO postgres;

--
-- Name: lead_create_agent(uuid, text, text, text, text, text[], text, text, boolean, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.lead_create_agent(conversation uuid, run text, call text, agent_name text, job text, apps text[], template text DEFAULT NULL::text, instructions text DEFAULT NULL::text, own_profile boolean DEFAULT false, own_answers boolean DEFAULT true) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare talk public.conversations; source text; made uuid; held boolean;
 agent uuid:=public.lead_agent_id(conversation,run,call);
begin
 perform pg_advisory_xact_lock(hashtextextended('hermes_agents',0));
 select l.agent_id into made from public.lead_made_agents l where l.conversation_id=conversation and l.run_id=run and l.call_id=call;
 if found then
  -- A closer that raced the one that made the Agent wrote the same fixed set to the same profile and the Engine read it
  -- back (own_profile), so the record it left stays confirmed. One that did not provide it changes nothing: the worker
  -- makes the profile and records it.
  -- The closer wrote the set with sub-agents off (provideAgent), so it confirms only a record whose switch is still off:
  -- an Owner who turned it on meanwhile left the profile pending, and the worker writes their choice.
  if own_profile then update public.agent_profiles p set tools_confirmed=true,tools_pending=false where p.agent_id=made and not p.subagents; end if;
  return jsonb_build_object('state','created','agent',made);
 end if;
 select * into talk from public.conversations where id=conversation;
 if not found or not exists(select 1 from public.conversation_messages m where m.conversation_id=conversation and m.author='person' and m.run_id=run)
  or not (public.may_use_lead_tools(talk.company_id,talk.agent_id,talk.person_id)
   or exists(select 1 from public.lead_agent_requests r where r.conversation_id=conversation and r.run_id=run and r.call_id=call and r.state='made'
    and public.may_use_lead_tools(talk.company_id,talk.agent_id,r.answered_by))) then return jsonb_build_object('state','refused'); end if;
 if not public.agent_fields_valid(agent_name,job,apps,template,instructions) or own_profile is null or own_answers is null then
  return jsonb_build_object('state','invalid'); end if;
 held:=public.company_holds_provider_key(talk.company_id);
 if not held and not own_answers then own_profile:=false; end if;
 select a.profile into source from public.hermes_agents a where a.id=talk.agent_id;
 -- The owner record comes first: the Agent on its profile is checked against it. `own_profile` says the Engine provided
 -- the profile with the fixed set and the read-back matched, so its tools are confirmed; an Agent the Company's held key
 -- put on its own profile without that waits for the worker, which provides it. A Company holding a provider key gives
 -- every Agent its own profile, as before.
 if own_profile or held then
  insert into public.agent_profiles(agent_id,company_id,tools_confirmed,tools_pending) values(agent,talk.company_id,own_profile,not own_profile);
 end if;
 insert into public.hermes_agents(id,company_id,profile,name,speciality,requested_by,apps,template,instructions)
  values(agent,talk.company_id,
   case when own_profile or held then public.agent_engine_profile(agent) when source ~ '^ag-[0-9a-f]{32}$' then public.company_engine_profile(talk.company_id) else source end,
   trim(agent_name),trim(job),talk.person_id,array(select trim(app) from unnest(apps) app),template,
   replace(instructions,'{company}',(select c.name from public.companies c where c.id=talk.company_id))) returning id into made;
 insert into public.lead_made_agents(conversation_id,run_id,call_id,company_id,agent_id) values(conversation,run,call,talk.company_id,made);
 if held and (not own_profile or not own_answers) then insert into public.agent_key_waits(agent_id,company_id) values(made,talk.company_id); end if;
 perform public.log_agent_event(talk.company_id,talk.person_id,(select name from public.people where id=talk.person_id),made,'REQUEST_HERMES_AGENT',
  jsonb_strip_nulls(jsonb_build_object('agent_name',trim(agent_name),'job',trim(job),'conversation_id',conversation,'template',template)));
 return jsonb_build_object('state','created','agent',made);
end $_$;

ALTER FUNCTION public.lead_create_agent(conversation uuid, run text, call text, agent_name text, job text, apps text[], template text, instructions text, own_profile boolean, own_answers boolean) OWNER TO postgres;

--
-- Name: lead_hand_to_agent(uuid, text, text, text, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.lead_hand_to_agent(conversation uuid, run text, call text, agent_name text, goal text, context text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare talk public.conversations; target public.hermes_agents; handed public.agent_handovers; asker text; main boolean;
 card bigint; card_agent uuid; stage bigint; first_words text;
begin
 select * into talk from public.conversations where id=conversation for no key update;
 -- A call that cannot be carried out answers as a value, never an error: the run that made it still closes.
 if not found or not exists(select 1 from public.conversation_messages m where m.conversation_id=conversation and m.author='person' and m.run_id=run)
  then return jsonb_build_object('state','refused'); end if;
 if talk.agent_id is null or not public.may_hand_to_agent(talk.company_id,talk.agent_id,talk.person_id)
  then return jsonb_build_object('state','refused'); end if;
 if exists(select 1 from public.stopped_runs s where s.conversation_id=conversation and s.run_id=run)
  then return jsonb_build_object('state','refused'); end if;
 if coalesce(agent_name,'') = '' or coalesce(goal,'') = '' then return jsonb_build_object('state','ignored'); end if;
 select * into target from public.hermes_agents a
  where a.company_id=talk.company_id and a.id<>talk.agent_id and a.profile is not null
   and lower(btrim(a.name))=lower(btrim(agent_name))
  order by a.id limit 1;
 if not found then return jsonb_build_object('state','ignored'); end if;
 insert into public.agent_handovers(company_id,conversation_id,run_id,call_id,from_agent,to_agent,goal,context)
  values(talk.company_id,conversation,run,call,talk.agent_id,target.id,btrim(goal),nullif(btrim(coalesce(context,'')),''))
  on conflict (conversation_id,run_id,call_id) do nothing returning * into handed;
 -- The same call again keeps nothing twice: one handover, and so one Card and one log row.
 if handed.id is not null then
  main:=public.is_company_lead(talk.company_id,talk.agent_id);
  select w.id,w.agent_id into card,card_agent from public.work_cards w where w.company_id=talk.company_id and w.conversation_id=conversation;
  if card is null and main then
   -- As #144's Card: the Company's first stage In progress, titled from the person's first message in this chat.
   select s.id into stage from public.work_stages s where s.company_id=talk.company_id and s.board_column='progress' and s.kind='before_review' order by s.position,s.id limit 1;
   if stage is not null then
    select m.body into first_words from public.conversation_messages m where m.conversation_id=conversation and m.author='person' order by m.id limit 1;
    insert into public.work_cards(company_id,stage_id,title,agent_id,conversation_id)
     values(talk.company_id,stage,public.chat_card_title(first_words,target.name),target.id,conversation)
     on conflict (conversation_id) where conversation_id is not null do nothing returning id into card;
    -- #354: when two handovers race, the second insert finds the first's Card and takes it, giving it the Agent it
    -- handed the work to as a later handover does, and keeping that Card's stage and title.
    if card is null then
     select w.id into card from public.work_cards w where w.company_id=talk.company_id and w.conversation_id=conversation;
     if card is not null then
      update public.work_cards set agent_id=target.id
       where company_id=talk.company_id and id=card and agent_id is distinct from target.id and archived_at is null; end if;
    end if;
   end if;
  elsif card is not null and main and card_agent is distinct from target.id then
   update public.work_cards set agent_id=target.id where company_id=talk.company_id and id=card and archived_at is null;
  end if;
  if card is not null then
   select a.name into asker from public.hermes_agents a where a.company_id=talk.company_id and a.id=talk.agent_id;
   -- The one who handed the work is the row's actor and the Agent it went to is the Agent the row is about, so a Member
   -- who does not see either one reads no row (company_log_read) and no name in the Card's crew (crew).
   insert into public.company_log(company_id,actor_id,actor_kind,actor_name,subject,card_id,agent_id,action,details,source,source_id,created_at)
    values(talk.company_id,talk.agent_id,'agent',asker,'card',card,target.id,'agent_handed_to',
     jsonb_build_object('agent_name',asker,'to_name',target.name,'goal',handed.goal),'agent_handovers',handed.id,handed.created_at)
    on conflict (source,source_id) do nothing;
  end if;
 end if;
 return jsonb_build_object('state','created','agent',target.name);
end $$;

ALTER FUNCTION public.lead_hand_to_agent(conversation uuid, run text, call text, agent_name text, goal text, context text) OWNER TO postgres;

--
-- Name: lead_key_settle(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.lead_key_settle(conversation uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
 select jsonb_build_object('company',v.company_id,'space',s.profile,
   'seen',(select max(h.version) from public.company_key_holds h where h.company_id=v.company_id)) from public.conversations v
  join public.company_shared_spaces s on s.company_id=v.company_id
  where v.id=conversation and exists(select 1 from public.company_key_holds h where h.company_id=v.company_id and (h.uncertain or h.changing)
   and not coalesce(h.changed_at>now()-interval '10 minutes',false));
$$;

ALTER FUNCTION public.lead_key_settle(conversation uuid) OWNER TO postgres;

--
-- Name: lead_request_agent(uuid, text, text, text, text, text[], text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.lead_request_agent(conversation uuid, run text, call text, agent_name text, job text, apps text[], template text DEFAULT NULL::text, instructions text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare talk public.conversations; asked text; kept public.lead_agent_requests;
begin
 select * into kept from public.lead_agent_requests r where r.conversation_id=conversation and r.run_id=run and r.call_id=call;
 if found then return jsonb_build_object('state','requested','request',kept.id); end if;
 select * into talk from public.conversations where id=conversation;
 if not found then return jsonb_build_object('state','refused'); end if;
 select m.body into asked from public.conversation_messages m where m.conversation_id=conversation and m.author='person' and m.run_id=run order by m.id limit 1;
 if asked is null or not public.may_ask_lead_for_agents(talk.company_id,talk.agent_id,talk.person_id) then return jsonb_build_object('state','refused'); end if;
 if not public.agent_fields_valid(agent_name,job,apps,template,instructions) then return jsonb_build_object('state','invalid'); end if;
 insert into public.lead_agent_requests(company_id,conversation_id,run_id,call_id,asked_by,asked_with,agent_name,job,apps,template,instructions)
  values(talk.company_id,conversation,run,call,talk.person_id,asked,trim(agent_name),trim(job),array(select trim(app) from unnest(apps) app),template,instructions)
  on conflict (conversation_id,run_id,call_id) do nothing returning * into kept;
 if kept.id is null then
  select * into kept from public.lead_agent_requests r where r.conversation_id=conversation and r.run_id=run and r.call_id=call;
 else
  perform public.give_agent_look(talk.company_id,public.lead_agent_id(conversation,run,call),false,template,kept.id);
  perform public.log_agent_event(talk.company_id,talk.person_id,(select name from public.people where id=talk.person_id),talk.agent_id,'AGENT_REQUEST_SENT',
    jsonb_build_object('asked_for',kept.agent_name,'job',kept.job,'request_id',kept.id,'conversation_id',conversation,'private','owners','teller',talk.person_id));
 end if;
 return jsonb_build_object('state','requested','request',kept.id);
end $$;

ALTER FUNCTION public.lead_request_agent(conversation uuid, run text, call text, agent_name text, job text, apps text[], template text, instructions text) OWNER TO postgres;

