--
-- Name: log_chat_event(uuid, uuid, text, text, text, jsonb, uuid, text, bigint, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.log_chat_event(conversation uuid, actor uuid, actor_kind text, actor_name text, action text, details jsonb, teller uuid, origin text, origin_id bigint, at timestamp with time zone) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare talk public.conversations; tied bigint;
begin
 select * into talk from public.conversations where id=conversation;
 select w.id into tied from public.work_cards w where w.company_id=talk.company_id and w.conversation_id=conversation;
 insert into public.company_log(company_id,actor_id,actor_kind,actor_name,subject,card_id,agent_id,action,details,source,source_id,created_at)
  values(talk.company_id,actor,actor_kind,actor_name,case when tied is null then 'agent' else 'card' end,tied,talk.agent_id,action,
   case when tied is null then details||jsonb_build_object('private',true,'teller',teller) else details end,origin,origin_id,at)
  on conflict (source,source_id) do nothing;
end $$;

ALTER FUNCTION public.log_chat_event(conversation uuid, actor uuid, actor_kind text, actor_name text, action text, details jsonb, teller uuid, origin text, origin_id bigint, at timestamp with time zone) OWNER TO postgres;

--
-- Name: log_company_change(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.log_company_change() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
 insert into public.company_log(company_id,actor_id,actor_kind,actor_name,subject,action,details,source,source_id,created_at)
  values(new.company_id,new.actor_id,public.log_actor_kind(new.company_id,new.actor_id),(select name from public.people where id=new.actor_id),
   'company',new.action,case when new.action='agent_level_changed' then jsonb_build_object('old_level',new.old_level,'new_level',new.new_level)
    when new.action='company_knowledge_changed' then jsonb_build_object('part',new.knowledge_part,'cleared',new.knowledge_cleared)
    when new.action in ('app_connected','app_disconnected') then jsonb_build_object('app',new.app)
     ||case when new.agent_id is null then '{}'::jsonb else jsonb_strip_nulls(jsonb_build_object('agent_name',(select a.name from public.hermes_agents a where a.id=new.agent_id))) end
    when new.action in ('subscription_connected','subscription_disconnected','provider_key_set','provider_key_removed') then jsonb_build_object('provider',new.provider)
    when new.action='provider_switched' then jsonb_build_object('provider',new.provider,'from_name',new.from_name,'to_name',new.to_name)
    when new.action='fallback_model_used' then jsonb_build_object('from_provider',new.from_provider,'from_model',new.from_model,'to_provider',new.to_provider,'to_model',new.to_model)
    else jsonb_build_object('old_name',new.old_name,'new_name',new.new_name) end,'company_audit',new.id,new.created_at)
  on conflict (source,source_id) do nothing;
 return null;
end;
$$;

ALTER FUNCTION public.log_company_change() OWNER TO postgres;

