--
-- Name: log_conversation_archive(uuid, boolean, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.log_conversation_archive(v uuid, archived boolean, actor uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare talk public.conversations; logged bigint; writer text;
begin
 select * into talk from public.conversations x where x.id=v;
 insert into public.conversation_archives(company_id,conversation_id,actor_id,action)
  values(talk.company_id,v,actor,case when archived then 'archived' else 'restored' end) returning id into logged;
 select p.name into writer from public.people p where p.id=actor;
 perform public.log_chat_event(v,actor,'person',coalesce(writer,''),case when archived then 'conversation_archived' else 'conversation_restored' end,
  jsonb_build_object('title',public.conversation_title(v,talk.agent_name)),actor,'conversation_archives',logged,now());
end $$;

ALTER FUNCTION public.log_conversation_archive(v uuid, archived boolean, actor uuid) OWNER TO postgres;

--
-- Name: log_conversations_archived(uuid, uuid[], boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.log_conversations_archived(c uuid, chats uuid[], archived boolean) RETURNS SETOF uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v uuid;
begin
 if auth.uid() is null or not public.is_member(c) then raise exception 'conversationArchiveNotAllowed' using errcode='42501'; end if;
 for v in select o.id from public.own_conversations(c) o where o.id=any(chats) order by o.id loop
  perform 1 from public.conversations x where x.id=v for update;
  if archived then perform public.stop_conversation_work(v); end if;
  update public.conversations x set archived_at=null, archived_by=null, session_archived=null where x.id=v;
  perform public.log_conversation_archive(v,archived,auth.uid());
  return next v;
 end loop;
end $$;

ALTER FUNCTION public.log_conversations_archived(c uuid, chats uuid[], archived boolean) OWNER TO postgres;

--
-- Name: log_engine_dashboard(uuid, text, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.log_engine_dashboard(c uuid, act text, page text, kind text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare me uuid := auth.uid();
begin
 if me is null or not public.is_company_owner(c) then raise exception 'engineDashboardNotAllowed' using errcode='42501'; end if;
 if page is not null and page not in ('keys','config','plugins','mcp','channels','webhooks','pairing','cron','skills','models','profiles','files','system','sessions','kanban') then
  raise exception 'engineDashboardLineUnknown' using errcode='22023';
 end if;
 if act='opened' and page is null and kind is null then
  -- Two first pages loaded at once are still one visit.
  perform pg_advisory_xact_lock(hashtextextended('engine_dashboard_opened '||c::text||' '||me::text,0));
  if exists(select 1 from public.company_log l where l.company_id=c and l.source='engine_dashboard' and l.action='engine_dashboard_opened'
   and l.actor_id=me and l.created_at>now()-interval '30 minutes') then return; end if;
 elsif act in ('changed','rejected') and kind in ('keySaved','keyRemoved','pluginInstalled','platformSet','platformConnected','settingSaved','added','removed','changed') then
  null;
 elsif act='refused' and kind in ('engineKey','hermesUpdate','backupImport','agentProfile') then
  null;
 else raise exception 'engineDashboardLineUnknown' using errcode='22023';
 end if;
 insert into public.company_log(company_id,actor_id,actor_kind,actor_name,subject,action,details,source,source_id,created_at)
  values(c,me,public.log_actor_kind(c,me),(select name from public.people where id=me),'company','engine_dashboard_'||act,
   case act when 'refused' then jsonb_strip_nulls(jsonb_build_object('page',page,'refused',kind))
    when 'opened' then '{}'::jsonb else jsonb_strip_nulls(jsonb_build_object('page',page,'change',kind)) end
    ||jsonb_build_object('private','owners'),
   'engine_dashboard',nextval('public.engine_dashboard_log_ids'),now());
end $$;

ALTER FUNCTION public.log_engine_dashboard(c uuid, act text, page text, kind text) OWNER TO postgres;

--
-- Name: log_engine_setting(uuid, uuid, text, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.log_engine_setting(c uuid, agent uuid, setting text, old_value jsonb, new_value jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
begin
 if not public.is_company_owner(c) then raise exception 'settingNotAllowed' using errcode='42501'; end if;
 if setting is null or setting !~ '^[a-zA-Z0-9][a-zA-Z0-9_.-]{0,119}$' then raise exception 'settingInvalid' using errcode='22023'; end if;
 if not exists(select 1 from public.hermes_agents a where a.id=agent and a.company_id=c) then raise exception 'settingAgentUnknown' using errcode='P0002'; end if;
 if jsonb_typeof(coalesce(old_value,'null'::jsonb)) not in ('null','string','number','boolean')
  or jsonb_typeof(coalesce(new_value,'null'::jsonb)) not in ('null','string','number','boolean')
  then raise exception 'settingInvalid' using errcode='22023'; end if;
 if public.secret_like(coalesce(old_value#>>'{}','')) or public.secret_like(coalesce(new_value#>>'{}',''))
  then raise exception 'settingSecret' using errcode='22023'; end if;
 perform public.log_agent_event(c,auth.uid(),null,agent,'AGENT_SETTING_CHANGED',jsonb_build_object('setting',setting,'old',old_value,'new',new_value));
end $_$;

ALTER FUNCTION public.log_engine_setting(c uuid, agent uuid, setting text, old_value jsonb, new_value jsonb) OWNER TO postgres;

