    CONSTRAINT held_agent_changes_check CHECK (((act ~~ 'skill_%'::text) = (skill IS NOT NULL))),
    CONSTRAINT held_agent_changes_skill_check CHECK ((skill ~ '^[a-z0-9][a-z0-9_-]{0,63}$'::text))
);

