--
-- Name: make_administrator_password_link(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.make_administrator_password_link(c uuid, person uuid, link_hash text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare made uuid; named text;
begin
 if c is null or person is null then raise exception 'passwordLinkNotAllowed' using errcode='42501'; end if;
 if not exists(select 1 from public.companies co where co.id=c) then raise exception 'companyNotFound' using errcode='P0002'; end if;
 if not exists(select 1 from public.members m where m.company_id=c and m.person_id=person and m.role='owner' and m.removed_at is null) then
  raise exception 'passwordLinkNotAdministrator' using errcode='42501';
 end if;
 if link_hash is null or link_hash !~ '^[a-f0-9]{64}$' then raise exception 'passwordLinkInvalid' using errcode='22023'; end if;
 select p.name into named from public.people p where p.id=person for update;
 -- A Member has one live password link at a time, whichever Company or command made it: a new one ends the earlier ones.
 with ended as (update public.company_links set cancelled_at=now()
  where kind='password' and person_id=person and used_at is null and cancelled_at is null and ends_at>now() returning company_id)
 insert into public.company_log(company_id,actor_id,actor_kind,actor_name,subject,person_id,action,details,source,source_id,created_at)
  select ended.company_id,null,'system','gtmworks command','member',person,'password_link_cancelled',
   jsonb_build_object('person_name',named,'private','managers'),'company_links',nextval('public.company_link_log_seq'),now() from ended;
 insert into public.company_links(company_id,kind,secret_hash,made_by,person_id,ends_at,made_on_server)
  values(c,'password',link_hash,null,person,now()+interval '24 hours',true) returning id into made;
 insert into public.company_log(company_id,actor_id,actor_kind,actor_name,subject,person_id,action,details,source,source_id,created_at)
  values(c,null,'system','gtmworks command','member',person,'password_link_made',
   jsonb_build_object('person_name',named,'private','managers'),'company_links',nextval('public.company_link_log_seq'),now());
 return made;
end $_$;

ALTER FUNCTION public.make_administrator_password_link(c uuid, person uuid, link_hash text) OWNER TO postgres;

--
-- Name: make_invite_link(uuid, text, text, uuid[], text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.make_invite_link(c uuid, label text, link_role text, agents uuid[], link_hash text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare made uuid; named text:=btrim(coalesce(label,''),E' \t\r\n'); chosen uuid; agent public.hermes_agents;
begin
 if c is null or not public.is_company_owner(c) then raise exception 'inviteLinkNotAllowed' using errcode='42501'; end if;
 if link_role is null or link_role not in ('manager','contributor','viewer') then raise exception 'inviteRoleNotAllowed' using errcode='22023'; end if;
 if length(named) not between 1 and 120 then raise exception 'inviteLinkLabel' using errcode='22023'; end if;
 if link_hash is null or link_hash !~ '^[a-f0-9]{64}$' then raise exception 'inviteLinkInvalid' using errcode='22023'; end if;
 foreach chosen in array coalesce(agents,'{}'::uuid[]) loop
  select * into agent from public.hermes_agents a where a.id=chosen and a.company_id=c;
  if not found then raise exception 'agentNotFound' using errcode='P0002'; end if;
  if agent.is_default then raise exception 'mainAgentShownToAll' using errcode='42501'; end if;
 end loop;
 insert into public.company_links(company_id,kind,secret_hash,made_by,label,role,ends_at)
  values(c,'invite',link_hash,auth.uid(),named,link_role,now()+interval '7 days') returning id into made;
 insert into public.company_link_agents(company_id,link_id,agent_id) select c,made,x from unnest(coalesce(agents,'{}'::uuid[])) x on conflict do nothing;
 insert into public.company_log(company_id,actor_id,actor_kind,actor_name,subject,action,details,source,source_id,created_at)
  values(c,auth.uid(),public.log_actor_kind(c,auth.uid()),(select name from public.people where id=auth.uid()),'member','invite_link_made',
   jsonb_build_object('label',named,'role',link_role,'private','managers'),'company_links',nextval('public.company_link_log_seq'),now());
 return made;
end $_$;

ALTER FUNCTION public.make_invite_link(c uuid, label text, link_role text, agents uuid[], link_hash text) OWNER TO postgres;

--
-- Name: make_invite_links(uuid, text[], text[], text[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.make_invite_links(c uuid, labels text[], link_roles text[], hashes text[]) RETURNS uuid[]
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare i int; made uuid[]:='{}';
begin
 if labels is null or cardinality(labels)>50
  or cardinality(labels) is distinct from cardinality(link_roles)
  or cardinality(labels) is distinct from cardinality(hashes) then
  raise exception 'inviteLinkInvalid' using errcode='22023'; end if;
 for i in 1..cardinality(labels) loop
  made:=made||public.make_invite_link(c,labels[i],link_roles[i],'{}'::uuid[],hashes[i]);
 end loop;
 return made;
end $$;

ALTER FUNCTION public.make_invite_links(c uuid, labels text[], link_roles text[], hashes text[]) OWNER TO postgres;

--
-- Name: make_password_link(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.make_password_link(c uuid, person uuid, link_hash text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare made uuid; asker public.member_role; named text;
begin
 select m.role into asker from public.members m where m.company_id=c and m.person_id=auth.uid() and m.removed_at is null;
 if c is null or asker is null or asker not in ('owner','manager') then raise exception 'passwordLinkNotAllowed' using errcode='42501'; end if;
 if person is null or not exists(select 1 from public.members m where m.company_id=c and m.person_id=person and m.removed_at is null) then
  raise exception 'memberNotFound' using errcode='P0002';
 end if;
 -- The install owner's account opens the Engine's dashboard no other Administrator reaches (#915), so no one makes its
 -- password link from the Team page: the gtmworks command on the server does (#955).
 if exists(select 1 from public.install_owner o where o.person_id=person) then raise exception 'passwordLinkInstallOwner' using errcode='42501'; end if;
 if not public.password_link_allowed(auth.uid(),person) then raise exception 'passwordLinkNotAllowed' using errcode='42501'; end if;
 if link_hash is null or link_hash !~ '^[a-f0-9]{64}$' then raise exception 'passwordLinkInvalid' using errcode='22023'; end if;
 select p.name into named from public.people p where p.id=person for update;
 -- Each earlier live link it ends is written in its own Company's log as cancelled.
 with ended as (update public.company_links set cancelled_at=now()
  where kind='password' and person_id=person and used_at is null and cancelled_at is null and ends_at>now() returning company_id)
 insert into public.company_log(company_id,actor_id,actor_kind,actor_name,subject,person_id,action,details,source,source_id,created_at)
  select ended.company_id,auth.uid(),public.log_actor_kind(ended.company_id,auth.uid()),(select name from public.people where id=auth.uid()),'member',person,'password_link_cancelled',
   jsonb_build_object('person_name',named,'private','managers'),'company_links',nextval('public.company_link_log_seq'),now() from ended;
 insert into public.company_links(company_id,kind,secret_hash,made_by,person_id,ends_at)
  values(c,'password',link_hash,auth.uid(),person,now()+interval '24 hours') returning id into made;
 insert into public.company_log(company_id,actor_id,actor_kind,actor_name,subject,person_id,action,details,source,source_id,created_at)
  values(c,auth.uid(),public.log_actor_kind(c,auth.uid()),(select name from public.people where id=auth.uid()),'member',person,'password_link_made',
   jsonb_build_object('person_name',named,'private','managers'),'company_links',nextval('public.company_link_log_seq'),now());
 return made;
end $_$;

ALTER FUNCTION public.make_password_link(c uuid, person uuid, link_hash text) OWNER TO postgres;

--
-- Name: manage_hermes_agent(uuid, text, uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.manage_hermes_agent(c uuid, intent text, a uuid, replacement uuid DEFAULT NULL::uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare current_agent public.hermes_agents; actor text; applied_replacement uuid;
begin
 if auth.uid() is null or not public.is_company_owner(c) then raise exception 'hermesNotAllowed' using errcode='42501'; end if;
 -- This install has few assignment writes; one lock serializes profile sharing and company defaults together.
 perform pg_advisory_xact_lock(hashtextextended('hermes_agents',0));
 if not exists(select 1 from public.companies where id=c) then raise exception 'hermesAgentNotFound' using errcode='P0002'; end if;
 select * into current_agent from public.hermes_agents where id=a and company_id=c;
 if current_agent.id is null then raise exception 'hermesAgentNotFound' using errcode='P0002'; end if;
 if intent='default' then
  update public.hermes_agents set is_default=false where company_id=c and is_default;
  update public.hermes_agents set is_default=true where id=a;
 elsif intent='remove' then
  if current_agent.is_default and exists(select 1 from public.hermes_agents where company_id=c and id<>a) then
   if replacement is null or not exists(select 1 from public.hermes_agents where company_id=c and id=replacement and id<>a) then raise exception 'hermesNextDefault'; end if;
   update public.hermes_agents set is_default=false where id=a;
   update public.hermes_agents set is_default=true where id=replacement;
   applied_replacement:=replacement;
  end if;
  delete from public.hermes_agents where id=a;
 else raise exception 'hermesAgentFailed'; end if;
 select name into actor from public.people where id=auth.uid();
 perform public.log_agent_event(c,auth.uid(),actor,a,upper(intent)||'_HERMES_AGENT',jsonb_build_object('replacement_id',applied_replacement));
end;
$$;

ALTER FUNCTION public.manage_hermes_agent(c uuid, intent text, a uuid, replacement uuid) OWNER TO postgres;

--
-- Name: manage_hermes_agent_leased(uuid, uuid, text, uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.manage_hermes_agent_leased(c uuid, holder uuid, intent text, a uuid, replacement uuid DEFAULT NULL::uuid) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
 if not public.renew_morning_lease(c,holder) then raise exception 'morningLeaseLost' using errcode='55P03'; end if;
 perform public.manage_hermes_agent(c,intent,a,replacement);
end $$;

ALTER FUNCTION public.manage_hermes_agent_leased(c uuid, holder uuid, intent text, a uuid, replacement uuid) OWNER TO postgres;

