--
-- Name: member_turns_team(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.member_turns_team() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare mode text;
begin
 -- The Company row is locked first so a concurrent switch to alone waits for this Member and then counts them.
 select work_mode into mode from public.companies where id=new.company_id for update;
 if mode='alone' and (select count(*) from public.members where company_id=new.company_id and removed_at is null)>1 then
  update public.companies set work_mode='team' where id=new.company_id;
 end if;
 return null;
end $$;

ALTER FUNCTION public.member_turns_team() OWNER TO postgres;

--
-- Name: mention_at(text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.mention_at(message text, called text) RETURNS integer
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $$
declare t text := lower(coalesce(message,'')); handle text := '@'||lower(btrim(coalesce(called,''))); found_at int; from_at int := 1;
begin
 if handle = '@' then return 0; end if;
 loop
  found_at := strpos(substr(t, from_at), handle); exit when found_at = 0; found_at := found_at + from_at - 1;
  if (found_at = 1 or substr(t, found_at-1, 1) ~ '[[:space:][:punct:]،؛؟]')
     and (found_at + length(handle) > length(t) or substr(t, found_at+length(handle), 1) ~ '[[:space:][:punct:]،؛؟]') then
   return found_at;
  end if;
  from_at := found_at + 1;
 end loop;
 return 0;
end $$;

ALTER FUNCTION public.mention_at(message text, called text) OWNER TO postgres;

--
-- Name: model_choice_valid(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.model_choice_valid(choice jsonb) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
 select choice is null or jsonb_typeof(choice)='object' and (select array_agg(k order by k) from jsonb_object_keys(choice) k)=array['model','provider']
  and jsonb_typeof(choice->'provider')='string' and jsonb_typeof(choice->'model')='string'
  and length(btrim(choice->>'provider')) between 1 and 200 and length(btrim(choice->>'model')) between 1 and 200;
$$;

ALTER FUNCTION public.model_choice_valid(choice jsonb) OWNER TO postgres;

--
-- Name: morning_lease_profiles(uuid, uuid, text[], text[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.morning_lease_profiles(c uuid, holder uuid, adding text[], settled text[]) RETURNS text[]
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare kept text[];
begin
 if not public.can_manage_company(c) then raise exception 'agentSettingNotAllowed' using errcode='42501'; end if;
 if exists(select 1 from unnest(coalesce(adding,'{}')) p where p !~ '^(co|ag)-[0-9a-f]{32}$') then raise exception 'agentSettingInvalid' using errcode='22023'; end if;
 update public.agent_morning_leases l set profiles=coalesce((select array_agg(distinct p order by p) from unnest(l.profiles||coalesce(adding,'{}')) p
   where p<>all(coalesce(settled,'{}'))),'{}')
  where l.company_id=c and l.holder=morning_lease_profiles.holder and l.until>=now()
  returning l.profiles into kept;
 return kept;
end $_$;

ALTER FUNCTION public.morning_lease_profiles(c uuid, holder uuid, adding text[], settled text[]) OWNER TO postgres;

--
-- Name: move_agent_profile(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.move_agent_profile(agent uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare moving public.hermes_agents; first_owner uuid;
begin
 perform pg_advisory_xact_lock(hashtextextended('hermes_agents',0));
 select * into moving from public.hermes_agents where id=agent;
 if not found or not public.company_profile_ready(moving.company_id) or not public.agent_may_move(agent) or public.agent_move_blocked(agent)
  or not exists(select 1 from public.agent_profiles p where p.agent_id=agent and p.company_id=moving.company_id
   and p.tools_confirmed and not p.tools_pending and (p.skills_shared or not public.shared_skills_active(moving.company_id))) then return false; end if;
 select m.person_id into first_owner from public.members m where m.company_id=moving.company_id and m.role='owner' and m.removed_at is null order by m.person_id limit 1;
 update public.hermes_agents set profile=public.agent_engine_profile(agent),connection_id=gen_random_uuid() where id=agent;
 perform public.log_agent_event(moving.company_id,first_owner,null,agent,'MOVE_AGENT_PROFILE','{}');
 return true;
end $$;

ALTER FUNCTION public.move_agent_profile(agent uuid) OWNER TO postgres;

--
-- Name: move_company_profile(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.move_company_profile(c uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare first_owner uuid; movers uuid[]; agent uuid; moved integer:=0;
begin
 perform pg_advisory_xact_lock(hashtextextended('hermes_agents',0));
 if not public.company_profile_ready(c) then return 0; end if;
 select m.person_id into first_owner from public.members m where m.company_id=c and m.role='owner' and m.removed_at is null order by m.person_id limit 1;
 if first_owner is null then return 0; end if;
 movers:=array(select a.id from public.hermes_agents a where a.company_id=c and a.profile<>public.company_engine_profile(c) and a.profile !~ '^ag-[0-9a-f]{32}$');
 if exists(select 1 from public.conversation_run_reservations r where r.agent_id=any(movers) and r.abandoned_at is null)
  or exists(select 1 from public.channel_runs r where r.agent_id=any(movers) and r.outcome is null)
  or exists(select 1 from public.note_runs r where r.agent_id=any(movers) and r.outcome is null)
  or exists(select 1 from public.conversation_messages m join public.conversations cv on cv.id=m.conversation_id
   where cv.company_id=c and cv.agent_id=any(movers) and m.created_at>now()-interval '5 minutes')
  or exists(select 1 from public.conversation_messages m join public.conversations cv on cv.id=m.conversation_id
   where cv.company_id=c and cv.agent_id=any(movers) and m.author='person'
    and not exists(select 1 from public.conversation_messages r where r.conversation_id=m.conversation_id and r.author='agent' and r.run_id=m.run_id)
    and not exists(select 1 from public.conversation_run_ends u where u.conversation_id=m.conversation_id and u.run_id=m.run_id)
    and not exists(select 1 from public.agent_handovers h where h.conversation_id=m.conversation_id and h.run_id=m.run_id and h.answers_person))
  or exists(select 1 from public.agent_handovers h where h.state not in ('done','failed')
   and ((h.to_agent=any(movers) and (h.state in ('target','answering') or h.state='waiting' and h.target_attempts>0 or h.state='handing' and h.answer_attempts>0))
    or (h.from_agent=any(movers) and (h.state='follow_up' or h.state='returning' and h.return_attempts>0)))) then
  return 0;
 end if;
 for agent in update public.hermes_agents set profile=public.company_engine_profile(c),connection_id=gen_random_uuid() where id=any(movers) returning id loop
  perform public.log_agent_event(c,first_owner,null,agent,'MOVE_COMPANY_PROFILE','{}');
  moved:=moved+1;
 end loop;
 return moved;
end $_$;

ALTER FUNCTION public.move_company_profile(c uuid) OWNER TO postgres;

--
-- Name: move_work_card(uuid, bigint, bigint, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.move_work_card(c uuid, card bigint, stage bigint, evidence text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$ begin perform set_config('work.evidence',coalesce(evidence,''),true); update public.work_cards set stage_id=stage where company_id=c and id=card; if not found then raise exception 'card not found or not permitted'; end if; end $$;

ALTER FUNCTION public.move_work_card(c uuid, card bigint, stage bigint, evidence text) OWNER TO postgres;

--
-- Name: move_work_card_to_column(uuid, bigint, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.move_work_card_to_column(c uuid, card bigint, target text, evidence text DEFAULT NULL::text) RETURNS bigint
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare current_kind text; current_column text; stage bigint; begin
 if target is null or target not in ('waiting','ideas','planned','progress','live','done') then raise exception 'unknown column' using errcode='22023'; end if;
 select s.kind,s.board_column into current_kind,current_column from public.work_cards w join public.work_stages s on s.company_id=w.company_id and s.id=w.stage_id where w.company_id=c and w.id=card;
 if not found then raise exception 'card not found or not permitted'; end if;
 if current_column=target then return null; end if;
 select s.id into stage from public.work_stages s where s.company_id=c and s.board_column=target order by (s.kind=current_kind) desc,s.position,s.id limit 1;
 if stage is null then raise exception 'column has no stage'; end if;
 perform public.move_work_card(c,card,stage,evidence);
 return stage;
end $$;

ALTER FUNCTION public.move_work_card_to_column(c uuid, card bigint, target text, evidence text) OWNER TO postgres;

--
-- Name: note_member_invitation(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.note_member_invitation() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare general uuid;
begin
 select k.id into general from public.channels k where k.company_id=new.company_id and k.kind='general';
 if general is null then return null; end if;
 insert into public.channel_notes(company_id, channel_id, kind, invitation_id, invitee_name, actor_id, actor_name)
  values (new.company_id, general, 'invite', new.id, public.invitee_name(new.email), auth.uid(),
   coalesce((select btrim(p.name) from public.people p where p.id=auth.uid()),''))
  on conflict (invitation_id) do nothing;
 return null;
end $$;

ALTER FUNCTION public.note_member_invitation() OWNER TO postgres;

--
-- Name: note_mentions(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.note_mentions() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare writer text; card_title text; chosen public.hermes_agents;
begin
 if public.log_actor_kind(new.company_id, new.author_id) <> 'person' then return null; end if;
 if exists(select 1 from public.work_cards w where w.company_id=new.company_id and w.id=new.card_id and w.archived_at is not null) then return null; end if;
 select coalesce(btrim(name),'') into writer from public.people where id=new.author_id;
 select btrim(title) into card_title from public.work_cards where company_id=new.company_id and id=new.card_id;
 insert into public.waiting_items(company_id, person_id, kind, title, body, asked_by, card_id, note_id)
  select new.company_id, m.person_id, 'mention', left(coalesce(nullif(card_title,''), '#'||new.card_id), 300), left(new.body, 4000),
   left(coalesce(writer,''), 120), new.card_id, new.id
  from public.members m join public.people p on p.id=m.person_id
  where m.company_id=new.company_id and m.removed_at is null and m.person_id <> new.author_id and btrim(p.name) <> ''
   and (public.mention_at(new.body, p.name) > 0 or public.mention_at(new.body, split_part(btrim(p.name),' ',1)) > 0)
  on conflict (note_id, person_id) where note_id is not null do nothing;
 select * into chosen from public.hermes_agents where id=public.channel_mention(new.company_id, new.author_id, new.body);
 if chosen.id is not null then
  insert into public.note_runs(note_id, company_id, card_id, agent_id, agent_name, session, input, instructions, rules)
   values (new.id, new.company_id, new.card_id, chosen.id, chosen.name, md5('note:'||new.card_id||':'||chosen.id::text)::uuid,
           split_part(coalesce(writer,''),' ',1)||': '||new.body, nullif(btrim(chosen.instructions),''), public.agent_rules_in_force(chosen.id))
   on conflict (note_id) do nothing;
 end if;
 return null;
end $$;

ALTER FUNCTION public.note_mentions() OWNER TO postgres;

--
-- Name: note_permission_revoked(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.note_permission_revoked(c uuid, agent uuid, entry text) RETURNS timestamp with time zone
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare kept timestamptz:=clock_timestamp();
begin
 perform public.check_permission_revoke(c,agent);
 if entry is null or length(entry) not between 1 and 1000 then raise exception 'permissionInvalid' using errcode='22023'; end if;
 insert into public.agent_permission_revoked(agent_id,company_id,entry,revoked_at) values(agent,c,note_permission_revoked.entry,kept)
  on conflict on constraint agent_permission_revoked_pkey do update set company_id=excluded.company_id,revoked_at=excluded.revoked_at,previous_at=public.agent_permission_revoked.revoked_at;
 return kept;
end $$;

ALTER FUNCTION public.note_permission_revoked(c uuid, agent uuid, entry text) OWNER TO postgres;

--
-- Name: note_runs_due(bigint, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.note_runs_due(just_message bigint DEFAULT NULL::bigint, after bigint DEFAULT 0) RETURNS TABLE(message bigint, run text, profile text, company uuid)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
 select r.note_id, r.run_id, r.profile, r.company_id from public.note_runs r
 where r.outcome is null and r.note_id > coalesce(after, 0) and (just_message is null or r.note_id=just_message)
  and (r.run_id is not null or r.note_id=just_message
   or (r.attempts = 0 and r.created_at < now()-interval '1 minute') or (r.attempts > 0 and r.attempted_at < now()-interval '30 seconds'))
 order by r.note_id limit 500;
$$;

ALTER FUNCTION public.note_runs_due(just_message bigint, after bigint) OWNER TO postgres;

--
-- Name: open_conversation_runs(uuid, uuid, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.open_conversation_runs(just uuid DEFAULT NULL::uuid, owner uuid DEFAULT NULL::uuid, after bigint DEFAULT 0) RETURNS TABLE(message bigint, conversation uuid, run text, person uuid, profile text, company uuid)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
 select m.id,m.conversation_id,m.run_id,c.person_id,a.profile,c.company_id from public.conversation_messages m
 join public.conversations c on c.id=m.conversation_id left join public.hermes_agents a on a.id=c.agent_id and a.company_id=c.company_id
 where m.author='person' and m.id>after and (just is null or m.conversation_id=just) and (owner is null or c.person_id=owner)
  and not exists(select 1 from public.conversation_messages r where r.conversation_id=m.conversation_id and r.author='agent' and r.run_id=m.run_id)
  and not exists(select 1 from public.conversation_run_ends u where u.conversation_id=m.conversation_id and u.run_id=m.run_id)
  and not exists(select 1 from public.agent_handovers h where h.conversation_id=m.conversation_id and h.run_id=m.run_id and h.answers_person)
 order by m.id limit 500;
$$;

ALTER FUNCTION public.open_conversation_runs(just uuid, owner uuid, after bigint) OWNER TO postgres;

--
-- Name: open_engine_conversation(uuid, uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.open_engine_conversation(c uuid, conversation uuid, agent uuid, message text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare existing public.conversations; chosen public.hermes_agents; held text;
begin
 if not public.conversation_can_write(c) then raise exception 'conversationNotAllowed' using errcode='42501'; end if;
 if conversation is null or message is null then raise exception 'conversationNotFound' using errcode='22023'; end if;
 perform pg_advisory_xact_lock(hashtextextended('conversation_turn:'||conversation::text,0));
 select * into existing from public.conversations where id=conversation;
 if found then
  if existing.person_id<>auth.uid() or existing.company_id<>c or existing.agent_id is null then raise exception 'conversationNotFound' using errcode='P0002'; end if;
  agent := existing.agent_id;
 end if;
 select * into chosen from public.hermes_agents where id=agent and company_id=c;
 if not found or not public.agent_visible_to(c,auth.uid(),agent) then raise exception 'conversationNotFound' using errcode='P0002'; end if;
 if existing.id is null then
  -- A new Conversation starts on the Engine only in a Company switched over, and a message addressed to a Member is kept
  -- as a note on the old record, as today.
  if not coalesce((select o.engine_conversations from public.companies o where o.id=c),false)
   or (select a.person from public.conversation_addressee(c,message) a limit 1) is not null then
   return jsonb_build_object('state','old');
  end if;
  insert into public.conversations(id,company_id,person_id,agent_id,agent_name,hermes_session_id,last_message_at)
   values(conversation,c,auth.uid(),agent,chosen.name,'gtmworks-'||gen_random_uuid()::text,now())
   returning * into existing;
  held := existing.hermes_session_id;
 else
  -- Only a Conversation this path made is on the Engine: it has its session and nothing on the old record. Any other
  -- (one the old record holds, or a row made without a session, such as the Owner's empty first Conversation) stays there,
  -- but the one the main Agent opened in a Company switched over, which takes its session with its first send.
  if existing.hermes_session_id is null and existing.lead_opening
   and coalesce((select o.engine_conversations from public.companies o where o.id=c),false) then
   update public.conversations set hermes_session_id='gtmworks-'||gen_random_uuid()::text where id=conversation
    returning * into existing;
  end if;
  if existing.hermes_session_id is null
   or exists(select 1 from public.conversation_messages m where m.conversation_id=conversation)
   or exists(select 1 from public.conversation_queued_turns q where q.conversation_id=conversation)
   or exists(select 1 from public.conversation_notes n where n.conversation_id=conversation) then
   return jsonb_build_object('state','old');
  end if;
  -- A note to a Member has no place in an Engine session: it is refused, and the words stay in the box.
  if (select a.person from public.conversation_addressee(c,message) a limit 1) is not null then
   raise exception 'conversationAddressedOnEngine' using errcode='22023';
  end if;
  -- Writing in an archived Conversation brings it back, logged as the person's, as on the old record.
  update public.conversations set last_message_at=greatest(last_message_at,now()),archived_at=null,archived_by=null
   where id=conversation returning hermes_session_id into held;
  if existing.archived_at is not null then perform public.log_conversation_archive(conversation,false,auth.uid()); end if;
 end if;
 return jsonb_build_object('state','engine','agent',agent,'session',held,
  'note',(select n.note from public.member_notes n where n.company_id=c and n.person_id=auth.uid()),
  'model',existing.model)
  || case when existing.lead_opening then jsonb_build_object('opening',jsonb_build_object(
   'owner',(select split_part(p.name,' ',1) from public.people p where p.id=auth.uid()),
   'language',(select p.language from public.people p where p.id=auth.uid()),
   'lead',chosen.name,'company',(select o.name from public.companies o where o.id=c))) else '{}'::jsonb end;
end $$;

ALTER FUNCTION public.open_engine_conversation(c uuid, conversation uuid, agent uuid, message text) OWNER TO postgres;

--
-- Name: open_first_conversation(uuid, uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.open_first_conversation(c uuid, person uuid, conversation uuid, body text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare lead public.hermes_agents; target uuid; written boolean;
begin
 perform 1 from public.companies where id=c for update;
 if not found then return null; end if;
 if coalesce((select o.engine_conversations from public.companies o where o.id=c),false) then
  written := exists(select 1 from public.conversations v where v.company_id=c and v.hermes_session_id is not null)
   or exists(select 1 from public.conversation_messages m where m.company_id=c and public.written_message(m))
   or exists(select 1 from public.conversation_run_reservations r where r.company_id=c);
  select v.id into target from public.conversations v where v.company_id=c and v.lead_opening and v.person_id=person;
  if found then return case when not written then target end; end if;
  if written or exists(select 1 from public.conversations v where v.company_id=c and v.lead_opening) then return null; end if;
  if not exists(select 1 from public.members m where m.company_id=c and m.person_id=person and m.role='owner' and m.removed_at is null) then return null; end if;
  select * into lead from public.hermes_agents a where a.company_id=c and a.is_default;
  if not found then return null; end if;
  -- The Owner's empty Conversation with it (first run makes one), else a new one under the given id.
  select v.id into target from public.conversations v where v.company_id=c and v.person_id=person and v.agent_id=lead.id
   and v.hermes_session_id is null and not exists(select 1 from public.conversation_messages m where m.conversation_id=v.id)
   and not exists(select 1 from public.conversation_queued_turns q where q.conversation_id=v.id)
   and not exists(select 1 from public.conversation_notes n where n.conversation_id=v.id)
   order by v.id=conversation desc,v.created_at,v.id limit 1;
  if target is null then
   target:=conversation;
   insert into public.conversations(id,company_id,person_id,agent_id,agent_name) values(target,c,person,lead.id,lead.name);
  end if;
  update public.conversations set lead_opening=true where id=target;
  return target;
 end if;
 -- Opened already: until anyone writes in the Company, the Owner's visit goes back to it, whichever visit wrote it
 -- (a link's prefetch renders the page too, and its move to the Conversation goes nowhere).
 select m.conversation_id into target from public.conversation_messages m join public.conversations v on v.id=m.conversation_id
  where m.company_id=c and m.run_id='lead-opening' and v.person_id=person;
 if found then
  return case when not exists(select 1 from public.conversation_messages m where m.company_id=c and public.written_message(m))
   and not exists(select 1 from public.conversation_run_reservations r where r.company_id=c) then target end;
 end if;
 -- Opened for another Owner, or written in: never a second opening.
 if exists(select 1 from public.conversation_messages m where m.company_id=c and (m.run_id='lead-opening' or public.written_message(m)))
  or exists(select 1 from public.conversation_run_reservations r where r.company_id=c) then return null; end if;
 if not exists(select 1 from public.members m where m.company_id=c and m.person_id=person and m.role='owner' and m.removed_at is null) then return null; end if;
 select * into lead from public.hermes_agents a where a.company_id=c and a.is_default;
 if not found then return null; end if;
 select v.id into target from public.conversations v where v.company_id=c and v.person_id=person and v.agent_id=lead.id
  order by v.id=conversation desc,v.created_at,v.id limit 1;
 if target is null then
  target:=conversation;
  insert into public.conversations(id,company_id,person_id,agent_id,agent_name) values(target,c,person,lead.id,lead.name);
 end if;
 insert into public.conversation_messages(company_id,conversation_id,author,agent_id,author_name,body,run_id)
  values(c,target,'agent',lead.id,lead.name,body,'lead-opening');
 return target;
end $$;

ALTER FUNCTION public.open_first_conversation(c uuid, person uuid, conversation uuid, body text) OWNER TO postgres;

--
-- Name: open_hermes_agent(uuid); Type: FUNCTION; Schema: public; Owner: postgres
