CREATE FUNCTION public.open_hermes_agent(agent uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
 update public.hermes_agents set requester_opened_at=now() where id=agent and requested_by=auth.uid() and requester_opened_at is null and public.is_member(company_id);
 return found;
end $$;

ALTER FUNCTION public.open_hermes_agent(agent uuid) OWNER TO postgres;

--
-- Name: order_providers(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.order_providers(c uuid, entries jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
begin
 if not public.is_company_owner(c) then raise exception 'providerNotAllowed' using errcode='42501'; end if;
 -- One order at a time per Company: a second call waits and applies its whole list to the first one's rows, so two
 -- Providers never end in one place.
 perform pg_advisory_xact_lock(hashtextextended('provider_order:'||c::text,0));
 if jsonb_typeof(entries) is distinct from 'array' or jsonb_array_length(entries) not between 1 and 64
  or exists(select 1 from jsonb_array_elements(entries) e where jsonb_typeof(e) is distinct from 'object'
   or coalesce(e->>'provider','') !~ '^[a-z0-9][a-z0-9._-]{0,63}$' or coalesce(e->>'account','') !~ '^[A-Za-z0-9_-]{1,64}$')
  or (select count(distinct (e->>'provider',e->>'account')) from jsonb_array_elements(entries) e)<>jsonb_array_length(entries) then
  raise exception 'providerOrderInvalid' using errcode='22023';
 end if;
 update public.provider_order p set place=null,changed_by=auth.uid(),changed_at=now()
  where p.company_id=c and p.place is not null
   and not exists(select 1 from jsonb_array_elements(entries) e where e->>'provider'=p.provider and e->>'account'=p.account);
 insert into public.provider_order(company_id,provider,account,place,changed_by)
  select c,e->>'provider',e->>'account',(n-1)::int,auth.uid() from jsonb_array_elements(entries) with ordinality as x(e,n)
  on conflict on constraint provider_order_pkey do update set place=excluded.place,changed_by=excluded.changed_by,changed_at=now()
   where provider_order.place is distinct from excluded.place;
end $_$;

ALTER FUNCTION public.order_providers(c uuid, entries jsonb) OWNER TO postgres;

--
-- Name: conversations; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.conversations (
    id uuid NOT NULL,
    company_id uuid NOT NULL,
    person_id uuid NOT NULL,
    agent_id uuid,
    agent_name text NOT NULL,
    hermes_session_id text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    model jsonb,
    model_before jsonb,
    good_morning bigint,
    good_morning_day date,
    last_message_at timestamp with time zone DEFAULT '-infinity'::timestamp with time zone NOT NULL,
    archived_at timestamp with time zone,
    archived_by uuid,
    session_archived boolean,
    session_missing_since timestamp with time zone,
    session_mark_after timestamp with time zone,
    kept_agent_id uuid,
    open_runs text[] DEFAULT '{}'::text[] NOT NULL,
    lead_opening boolean DEFAULT false NOT NULL,
    CONSTRAINT conversations_archived_by_archived CHECK (((archived_by IS NULL) OR (archived_at IS NOT NULL))),
    CONSTRAINT conversations_good_morning_day CHECK (((good_morning IS NULL) OR (good_morning_day IS NOT NULL))),
    CONSTRAINT conversations_model_valid CHECK ((public.model_choice_valid(model) AND public.model_choice_valid(model_before))),
    CONSTRAINT conversations_open_runs CHECK (((cardinality(open_runs) <= 32) AND (array_to_string(open_runs, ','::text) ~ '^([A-Za-z0-9_.:-]{1,200}(,|$))*$'::text)))
);

ALTER TABLE public.conversations OWNER TO postgres;

--
-- Name: own_conversations(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.own_conversations(c uuid) RETURNS SETOF public.conversations
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
 select v.* from public.conversations v
 where v.company_id=c and v.person_id=(select auth.uid()) and public.is_member(c)
  and (v.agent_id is null or v.agent_id in (select h.id from public.hermes_agents h where h.company_id=c and public.agent_visible_to(c,(select auth.uid()),h.id)));
$$;

ALTER FUNCTION public.own_conversations(c uuid) OWNER TO postgres;

--
-- Name: password_link_allowed(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.password_link_allowed(maker uuid, person uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
 select exists(select 1 from public.members t where t.person_id=person and t.removed_at is null)
  and not exists(select 1 from public.members t where t.person_id=person and t.removed_at is null
   and not exists(select 1 from public.members m where m.company_id=t.company_id and m.person_id=maker and m.removed_at is null
    and (m.role='owner' or (m.role='manager' and t.role<>'owner'))));
$$;

ALTER FUNCTION public.password_link_allowed(maker uuid, person uuid) OWNER TO postgres;

--
-- Name: password_link_open(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.password_link_open(link_hash text) RETURNS TABLE(company text, person_name text, email text, two_step boolean)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
 select c.name,p.name,u.email::text,exists(select 1 from auth.mfa_factors f where f.user_id=l.person_id and f.status='verified') from public.company_links l
  join public.companies c on c.id=l.company_id
  join public.people p on p.id=l.person_id
  join auth.users u on u.id=l.person_id
  join public.members m on m.company_id=l.company_id and m.person_id=l.person_id and m.removed_at is null
 where l.secret_hash=link_hash and l.kind='password' and l.used_at is null and l.cancelled_at is null and l.ends_at>now();
$$;

ALTER FUNCTION public.password_link_open(link_hash text) OWNER TO postgres;

--
-- Name: pending_invite_links(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pending_invite_links(c uuid) RETURNS TABLE(id uuid, label text, role text, made_by_name text, ends_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
 if c is null or not public.is_company_owner(c) then raise exception 'inviteLinkNotAllowed' using errcode='42501'; end if;
 return query select l.id,l.label,l.role,p.name,l.ends_at
  from public.company_links l left join public.people p on p.id=l.made_by
  where l.company_id=c and l.kind='invite' and l.used_at is null and l.cancelled_at is null and l.ends_at>now()
  order by l.created_at;
end $$;

ALTER FUNCTION public.pending_invite_links(c uuid) OWNER TO postgres;

--
-- Name: permission_allows_of(jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.permission_allows_of(asking jsonb, kept jsonb) RETURNS text[]
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
 select case when kept->'choices' ? 'always' and jsonb_typeof(asking->'allows')='array' and jsonb_array_length(asking->'allows') between 1 and 32
  and not exists(select 1 from jsonb_array_elements(asking->'allows') a where jsonb_typeof(a)<>'string')
  then (select array_agg(a order by n) from jsonb_array_elements_text(asking->'allows') with ordinality x(a,n)) end;
$$;

ALTER FUNCTION public.permission_allows_of(asking jsonb, kept jsonb) OWNER TO postgres;

--
-- Name: permission_choices(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.permission_choices(c uuid) RETURNS text[]
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
 select coalesce((select case when m.role in ('owner','manager') then array['once','always','deny'] when m.role='contributor' then array['once','deny'] end
  from public.members m where m.company_id=c and m.person_id=auth.uid() and m.removed_at is null),'{}'::text[]);
$$;

ALTER FUNCTION public.permission_choices(c uuid) OWNER TO postgres;

--
-- Name: permission_revoke_held(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.permission_revoke_held(agent uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
 select exists(select 1 from public.agent_permission_revokes h where h.agent_id=agent and h.held_until>now());
$$;

ALTER FUNCTION public.permission_revoke_held(agent uuid) OWNER TO postgres;

--
-- Name: pin_channel_run(bigint, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pin_channel_run(message bigint, specs jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare r public.channel_runs; m public.channel_messages; offered text[];
begin
 select * into r from public.channel_runs where message_id=message and outcome is null order by ordinal limit 1 for update;
 if r.message_id is null or r.outcome is not null then return null; end if;
 if r.tools is null then
  select * into m from public.channel_messages where id=message;
  if m.id is null or m.author<>'person' then return null; end if;
  if public.channel_can_show_cards(r.channel_id,m.person_id,r.agent_id) then
   offered:=array(select t from unnest(array['show_draft','show_review','hand_over']) t where jsonb_typeof(specs->t)='string');
   if public.channel_can_hand_over(r.channel_id,m.person_id,r.agent_id) and jsonb_typeof(specs->'hand_to_agent')='string' then
    offered:=array_append(offered,'hand_to_agent'); end if;
   update public.channel_runs set tools=case when cardinality(offered)>0 then
     '['||(select string_agg(specs->>t,',' order by o) from unnest(offered) with ordinality u(t,o))||']' end
    where message_id=message and ordinal=r.ordinal returning * into r;
  end if;
 end if;
 return jsonb_build_object('tools',r.tools);
end $$;

ALTER FUNCTION public.pin_channel_run(message bigint, specs jsonb) OWNER TO postgres;

--
-- Name: pin_handover_tools(bigint, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pin_handover_tools(h bigint, spec text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare r public.agent_handovers;
begin
 select * into r from public.agent_handovers where id=h for update;
 if r.id is null then return null; end if;
 if r.tools is null then
  update public.agent_handovers set tools=case when r.answers_person then '' else coalesce(nullif(btrim(spec),''),'') end
   where id=h returning * into r;
 end if;
 return r.tools;
end $$;

ALTER FUNCTION public.pin_handover_tools(h bigint, spec text) OWNER TO postgres;

--
-- Name: pin_lead_brief(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pin_lead_brief(conversation uuid, message_key uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare held public.conversation_run_reservations; kept public.conversation_run_notes;
begin
 select * into held from public.conversation_run_reservations r where r.conversation_id=conversation and r.send_key=message_key for update;
 select * into kept from public.conversation_run_notes n where n.conversation_id=conversation and n.send_key=message_key for update;
 if kept.conversation_id is null then return null; end if;
 if kept.lead_brief is null and held.conversation_id is not null and held.start_attempts=0 and held.start_unknown_at is null
  and exists(select 1 from public.hermes_agents a where a.id=held.agent_id and a.company_id=held.company_id and a.is_default) then
  update public.conversation_run_notes n set lead_brief=jsonb_build_object(
   'role',(select m.role from public.members m where m.company_id=held.company_id and m.person_id=held.person_id and m.removed_at is null),
   'owner',(select split_part(p.name,' ',1) from public.members m join public.people p on p.id=m.person_id
     where m.company_id=held.company_id and m.role='owner' and m.removed_at is null order by p.name limit 1),
   'agents',coalesce((select jsonb_agg(jsonb_build_object('name',a.name,'job',a.speciality) order by a.name,a.id)
     from public.hermes_agents a
     where a.company_id=held.company_id and a.id<>held.agent_id and public.agent_visible_to(held.company_id,held.person_id,a.id)),'[]'::jsonb),
   'opening',(select m.body from public.conversation_messages m where m.conversation_id=conversation and m.author='agent' and m.run_id='lead-opening'
     and not exists(select 1 from public.conversation_messages p where p.conversation_id=conversation and p.author='person' and public.written_message(p))),
   'hidden',case when public.may_ask_to_open_agents(held.company_id,held.agent_id,held.person_id) then coalesce((
     select jsonb_agg(jsonb_build_object('job',h.job,'asks',split_part(p.name,' ',1),'role',m.role) order by h.job)
      from (select distinct on (lower(btrim(a.speciality))) btrim(a.speciality) job, public.agent_access_named(held.company_id,held.person_id,a.id) named
        from public.agents_hidden_from(held.company_id,held.person_id) a where length(btrim(a.speciality))>0
        order by lower(btrim(a.speciality)),a.id) h
      join public.people p on p.id=h.named
      join public.members m on m.company_id=held.company_id and m.person_id=h.named),'[]'::jsonb) else '[]'::jsonb end)
   where n.conversation_id=conversation and n.send_key=message_key returning * into kept;
 end if;
 return kept.lead_brief;
end $$;

ALTER FUNCTION public.pin_lead_brief(conversation uuid, message_key uuid) OWNER TO postgres;

--
-- Name: pin_run(uuid, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pin_run(conversation uuid, message_key uuid, specs jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare held public.conversation_run_reservations; kept public.conversation_run_notes; offered text[];
begin
 select * into held from public.conversation_run_reservations r where r.conversation_id=conversation and r.send_key=message_key for update;
 select * into kept from public.conversation_run_notes n where n.conversation_id=conversation and n.send_key=message_key for update;
 if kept.conversation_id is null then return null; end if;
 if kept.rules is null and held.conversation_id is not null and held.start_attempts=0 and held.start_unknown_at is null then
  offered:=array(select t from unnest(public.run_tools(held.company_id,held.agent_id,held.person_id)) t where jsonb_typeof(specs->t)='string');
  update public.conversation_run_notes n set
   tools=case when cardinality(offered)>0 then '['||(select string_agg(specs->>t,',' order by o) from unnest(offered) with ordinality u(t,o))||']' end,
   rules='{}'
   where n.conversation_id=conversation and n.send_key=message_key returning * into kept;
 end if;
 return jsonb_build_object('tools',kept.tools,'rules','[]'::jsonb);
end $$;

ALTER FUNCTION public.pin_run(conversation uuid, message_key uuid, specs jsonb) OWNER TO postgres;

--
-- Name: pin_run_brief(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pin_run_brief(conversation uuid, message_key uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare held public.conversation_run_reservations; kept public.conversation_run_notes; main boolean;
begin
 select * into held from public.conversation_run_reservations r where r.conversation_id=conversation and r.send_key=message_key for update;
 select * into kept from public.conversation_run_notes n where n.conversation_id=conversation and n.send_key=message_key for update;
 if kept.conversation_id is null then return null; end if;
 select a.is_default into main from public.hermes_agents a where a.id=held.agent_id and a.company_id=held.company_id;
 if kept.lead_brief is null and held.conversation_id is not null and held.start_attempts=0 and held.start_unknown_at is null and main is not null then
  update public.conversation_run_notes n set lead_brief=jsonb_build_object(
   'main',main,
   'self',held.profile,
   'role',(select m.role from public.members m where m.company_id=held.company_id and m.person_id=held.person_id and m.removed_at is null),
   'owner',(select split_part(p.name,' ',1) from public.members m join public.people p on p.id=m.person_id
     where m.company_id=held.company_id and m.role='owner' and m.removed_at is null order by p.name limit 1),
   'agents',coalesce((select jsonb_agg(jsonb_build_object('name',a.name,'job',a.speciality,'role',a.template,
      'board',case when a.profile is not null and (a.is_default or a.profile=public.agent_engine_profile(a.id)) then a.profile end) order by a.name,a.id)
     from public.hermes_agents a
     where a.company_id=held.company_id and a.id<>held.agent_id and public.agent_visible_to(held.company_id,held.person_id,a.id)),'[]'::jsonb),
   'opening',case when main then (select m.body from public.conversation_messages m where m.conversation_id=conversation and m.author='agent' and m.run_id='lead-opening'
     and not exists(select 1 from public.conversation_messages p where p.conversation_id=conversation and p.author='person' and public.written_message(p))) end,
   'hidden',case when main and public.may_ask_to_open_agents(held.company_id,held.agent_id,held.person_id) then coalesce((
     select jsonb_agg(jsonb_build_object('job',h.job,'asks',split_part(p.name,' ',1),'role',m.role) order by h.job)
      from (select distinct on (lower(btrim(a.speciality))) btrim(a.speciality) job, public.agent_access_named(held.company_id,held.person_id,a.id) named
        from public.agents_hidden_from(held.company_id,held.person_id) a where length(btrim(a.speciality))>0
        order by lower(btrim(a.speciality)),a.id) h
      join public.people p on p.id=h.named
      join public.members m on m.company_id=held.company_id and m.person_id=h.named),'[]'::jsonb) else '[]'::jsonb end)
   where n.conversation_id=conversation and n.send_key=message_key returning * into kept;
 end if;
 return kept.lead_brief;
end $$;

ALTER FUNCTION public.pin_run_brief(conversation uuid, message_key uuid) OWNER TO postgres;

--
-- Name: pin_run_history(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pin_run_history(conversation uuid, message_key uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare held public.conversation_run_reservations; kept public.conversation_run_notes; moved_at timestamptz; record jsonb; morning boolean;
begin
 select * into held from public.conversation_run_reservations r where r.conversation_id=conversation and r.send_key=message_key for update;
 select * into kept from public.conversation_run_notes n where n.conversation_id=conversation and n.send_key=message_key for update;
 if kept.conversation_id is null then return null; end if;
 if kept.history is null and held.conversation_id is not null and held.start_attempts=0 and held.start_unknown_at is null then
  select v.good_morning is not null and v.hermes_session_id is null into morning from public.conversations v where v.id=conversation;
  if held.profile=public.agent_engine_profile(held.agent_id) then
   select max(l.created_at) into moved_at from public.company_log l where l.agent_id=held.agent_id and l.company_id=held.company_id
    and l.source='hermes_agent_audit' and l.action=public.log_agent_action('MOVE_AGENT_PROFILE');
  end if;
  if coalesce(morning,false) or (moved_at is not null and exists(select 1 from public.conversation_messages m where m.conversation_id=conversation and m.created_at<moved_at)) then
   select jsonb_agg(x.entry order by x.id) into record from (
    select m.id,e.entry,sum(octet_length(e.entry::text)) over (order by m.id desc) as total
    from public.conversation_messages m,
     lateral (select jsonb_build_object('role',case m.author when 'agent' then 'assistant' else 'user' end,'content',m.body) as entry) e
    where m.conversation_id=conversation and m.send_key is distinct from message_key) x
   where x.total<=6000000;
   if record is not null then
    update public.conversation_run_notes n set history=record where n.conversation_id=conversation and n.send_key=message_key returning * into kept;
   end if;
  end if;
 end if;
 return kept.history;
end $$;

ALTER FUNCTION public.pin_run_history(conversation uuid, message_key uuid) OWNER TO postgres;

--
-- Name: pin_run_model(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pin_run_model(conversation uuid, message_key uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare held public.conversation_run_reservations; kept public.conversation_run_notes;
begin
 select * into held from public.conversation_run_reservations r where r.conversation_id=conversation and r.send_key=message_key for update;
 select * into kept from public.conversation_run_notes n where n.conversation_id=conversation and n.send_key=message_key for update;
 if kept.conversation_id is null then return 'null'::jsonb; end if;
 if kept.model is null then
  update public.conversation_run_notes n set model=case when held.conversation_id is not null and held.start_attempts=0 and held.start_unknown_at is null
    then coalesce((select cv.model from public.conversations cv where cv.id=conversation),'null'::jsonb) else 'null'::jsonb end
   where n.conversation_id=conversation and n.send_key=message_key returning * into kept;
 end if;
 return kept.model;
end $$;

ALTER FUNCTION public.pin_run_model(conversation uuid, message_key uuid) OWNER TO postgres;

--
-- Name: pin_run_tools(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pin_run_tools(conversation uuid, message_key uuid, tools text) RETURNS text
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO ''
    AS $$
 update public.conversation_run_notes r set tools=coalesce(r.tools,pin_run_tools.tools)
  where r.conversation_id=conversation and r.send_key=message_key and r.offers_tools returning r.tools;
$$;

ALTER FUNCTION public.pin_run_tools(conversation uuid, message_key uuid, tools text) OWNER TO postgres;

--
-- Name: pinned_run_note(uuid, uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pinned_run_note(conversation uuid, message_key uuid, c uuid, person uuid) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare kept text;
begin
 insert into public.conversation_run_notes(conversation_id,send_key,company_id,note,offers_tools)
  values(conversation,message_key,c,(select n.note from public.member_notes n where n.company_id=c and n.person_id=person),
   public.may_use_lead_tools(c,(select r.agent_id from public.conversation_run_reservations r where r.conversation_id=conversation and r.send_key=message_key),person))
  on conflict (conversation_id,send_key) do nothing;
 select r.note into kept from public.conversation_run_notes r where r.conversation_id=conversation and r.send_key=message_key;
 return kept;
end $$;

ALTER FUNCTION public.pinned_run_note(conversation uuid, message_key uuid, c uuid, person uuid) OWNER TO postgres;

--
-- Name: place_work_card(uuid, bigint, text, bigint, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.place_work_card(c uuid, card bigint, target text, before_card bigint DEFAULT NULL::bigint, evidence text DEFAULT NULL::text) RETURNS bigint
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare current_kind text; current_column text; stage bigint; arrived text; before_place numeric; previous_place numeric; place numeric; begin
 if target is null or target not in ('waiting','ideas','planned','progress','live','done') then raise exception 'unknown column' using errcode='22023'; end if;
 if not public.work_can_edit(c) then raise exception 'not permitted' using errcode='42501'; end if;
 select s.kind,s.board_column into current_kind,current_column from public.work_cards w join public.work_stages s on s.company_id=w.company_id and s.id=w.stage_id
  where w.company_id=c and w.id=card;
 if not found then raise exception 'card not found or not permitted'; end if;
 if current_column='waiting' or target='waiting' then raise exception 'waiting is not placed by hand' using errcode='42501'; end if;
 if (current_column in ('live','done') or target in ('live','done') or current_kind='after_review') and not public.can_manage_company(c) then
  raise exception 'not permitted' using errcode='42501'; end if;
 if target<>current_column then
  select s.id,s.kind into stage,arrived from public.work_stages s where s.company_id=c and s.board_column=target
   order by (s.kind=current_kind) desc,s.position,s.id limit 1;
  if stage is null then raise exception 'column has no stage'; end if;
  if arrived='after_review' and not public.can_manage_company(c) then raise exception 'not permitted' using errcode='42501'; end if;
 end if;
 if before_card is null then
  select coalesce(max(w.board_order),0)+1 into place from public.work_cards w join public.work_stages s on s.company_id=w.company_id and s.id=w.stage_id
   where w.company_id=c and s.board_column=target and w.id<>card;
 else
  -- The column's Cards are locked, so the place read here is still the place when the Card takes it. Two moves at once
  -- can leave two Cards on one place, and then there is no number between the neighbour above and the Card below: the
  -- column is numbered again, two apart, in the order the board draws it (place, then id; #174), so the slot is free.
  perform 1 from public.work_cards w join public.work_stages s on s.company_id=w.company_id and s.id=w.stage_id
   where w.company_id=c and s.board_column=target and w.id<>card for update of w;
  if exists(select 1 from public.work_cards w join public.work_stages s on s.company_id=w.company_id and s.id=w.stage_id
   where w.company_id=c and s.board_column=target and w.id<>card group by coalesce(w.board_order,0) having count(*)>1) then
   update public.work_cards w set board_order=o.again from (select w2.id,(row_number() over (order by coalesce(w2.board_order,0),w2.id))*2 as again
    from public.work_cards w2 join public.work_stages s2 on s2.company_id=w2.company_id and s2.id=w2.stage_id
    where w2.company_id=c and s2.board_column=target and w2.id<>card) o
    where w.company_id=c and w.id=o.id;
  end if;
  select w.board_order into before_place from public.work_cards w join public.work_stages s on s.company_id=w.company_id and s.id=w.stage_id
   where w.company_id=c and s.board_column=target and w.id=before_card and w.id<>card;
  if not found then raise exception 'the card it lands above is not in that column' using errcode='22023'; end if;
  select max(w.board_order) into previous_place from public.work_cards w join public.work_stages s on s.company_id=w.company_id and s.id=w.stage_id
   where w.company_id=c and s.board_column=target and w.id<>card and w.id<>before_card and w.board_order<before_place;
  place=case when previous_place is null then before_place-1 else (previous_place+before_place)/2 end;
 end if;
 perform set_config('work.evidence',coalesce(evidence,''),true);
 perform set_config('work.place_exact','yes',true);
 update public.work_cards w set stage_id=coalesce(stage,w.stage_id),board_order=place where w.company_id=c and w.id=card;
 if not found then perform set_config('work.place_exact','',true); raise exception 'card not found or not permitted'; end if;
 perform set_config('work.place_exact','',true);
 return stage;
end $$;

ALTER FUNCTION public.place_work_card(c uuid, card bigint, target text, before_card bigint, evidence text) OWNER TO postgres;

--
-- Name: post_channel_message(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.post_channel_message(ch uuid, message_key uuid, message text) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare k public.channels; saved bigint; writer text; chosen record;
begin
 select * into k from public.channels where id=ch;
 if k.id is null or not public.in_channel(ch) then raise exception 'channelNotFound' using errcode='P0002'; end if;
 if not public.conversation_can_write(k.company_id) then raise exception 'channelNotAllowed' using errcode='42501'; end if;
 if message_key is null or message is null or (btrim(message)='' and not exists(select 1 from public.channel_attachments a left join public.channel_messages m on m.id=a.message_id where a.channel_id=ch and a.send_key=message_key and a.person_id=auth.uid() and (a.message_id is null or (m.channel_id=ch and m.send_key=message_key and m.person_id=auth.uid() and m.author='person')))) or length(message) > 20000 then raise exception 'channelFailed' using errcode='22023'; end if;
 select coalesce(btrim(name),'') into writer from public.people where id=auth.uid();
 insert into public.channel_messages(company_id, channel_id, author, person_id, author_name, body, send_key)
  values (k.company_id, ch, 'person', auth.uid(), coalesce(writer,''), message, message_key)
  on conflict (channel_id, send_key) do nothing returning id into saved;
 if saved is null then
  select id into saved from public.channel_messages where channel_id=ch and send_key=message_key and person_id=auth.uid();
  if saved is null then raise exception 'channelFailed' using errcode='22023'; end if;
  return saved;
 end if;
 for chosen in select h.*, m.ordinal from public.channel_mentions_in(ch, auth.uid(), message) m
  join public.hermes_agents h on h.id=m.agent order by m.ordinal loop
  insert into public.channel_runs(message_id, ordinal, company_id, channel_id, agent_id, agent_name, session, input, instructions, rules)
   values (saved, chosen.ordinal, k.company_id, ch, chosen.id, chosen.name, md5(ch::text||':'||chosen.id::text)::uuid,
           split_part(coalesce(writer,''),' ',1)||': '||message, nullif(btrim(chosen.instructions),''), public.agent_rules_in_force(chosen.id));
 end loop;
 insert into public.waiting_items(company_id, person_id, kind, title, body, asked_by, channel_message_id)
  select k.company_id, m.person, 'channel_mention', left(coalesce(btrim(k.name),'general'),300), left(message,4000),
   left(coalesce(writer,''),120), saved
  from public.channel_message_mentions(ch, auth.uid(), message) m
  on conflict (channel_message_id, person_id) where channel_message_id is not null do nothing;
 return saved;
end $$;

ALTER FUNCTION public.post_channel_message(ch uuid, message_key uuid, message text) OWNER TO postgres;

--
-- Name: postpone_app_card(uuid, uuid, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.postpone_app_card(c uuid, conversation uuid, card bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare talk public.conversations; asked public.reply_cards;
begin
 if not public.is_company_owner(c) then raise exception 'conversationNotAllowed' using errcode='42501'; end if;
 select * into talk from public.conversations v where v.id=conversation and v.company_id=c;
 if not found or talk.person_id<>auth.uid() or not public.can_see_agent(c,talk.agent_id) then raise exception 'conversationNotFound' using errcode='P0002'; end if;
 select * into asked from public.reply_cards r where r.id=card and r.conversation_id=conversation and r.kind='connect' for update;
 if not found then raise exception 'conversationNotFound' using errcode='P0002'; end if;
 if asked.state='postponed' then return jsonb_build_object('state','postponed','first',false); end if;
 update public.reply_cards set state='postponed' where id=asked.id;
 return jsonb_build_object('state','postponed','first',true);
end $$;

ALTER FUNCTION public.postpone_app_card(c uuid, conversation uuid, card bigint) OWNER TO postgres;

--
-- Name: press_agent_access(uuid, uuid, bigint, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.press_agent_access(c uuid, conversation uuid, request bigint, ask boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare asked public.agent_access_requests;
begin
 if ask is null then raise exception 'agentAccessAnswerMissing' using errcode='22023'; end if;
 select * into asked from public.agent_access_requests r where r.id=request and r.company_id=c and r.conversation_id=conversation and r.asked_by=auth.uid() for update;
 if not found or not public.is_member(c) then raise exception 'agentAccessNotFound' using errcode='P0002'; end if;
 if not public.conversation_can_write(c) then raise exception 'agentAccessNotAllowed' using errcode='42501'; end if;
 if asked.state<>'offered' then return jsonb_build_object('state',asked.state,'at',asked.pressed_at,'first',false); end if;
 if public.agent_visible_to(c,asked.asked_by,asked.agent_id) then return jsonb_build_object('state','available','first',false); end if;
 -- The person the card named when it was pressed is kept: whoever may open the Agent now, should the one it named when it
 -- was made have lost that (conversation_agent_access names the same).
 update public.agent_access_requests set state=case when ask then 'asked' else 'dismissed' end,pressed_at=now(),
  named_to=case when public.may_open_agent_for(c,named_to,agent_id,asked_by) then named_to else coalesce(public.agent_access_named(c,asked_by,agent_id),named_to) end
  where id=asked.id returning * into asked;
 return jsonb_build_object('state',asked.state,'at',asked.pressed_at,'first',true);
end $$;

ALTER FUNCTION public.press_agent_access(c uuid, conversation uuid, request bigint, ask boolean) OWNER TO postgres;

--
-- Name: provider_accounts_work(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.provider_accounts_work() RETURNS TABLE(company_id uuid, accounts jsonb)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
 select c.id,coalesce((select jsonb_agg(jsonb_build_object('provider',k.provider,'account',k.account,'ordered',o.company_id is not null,'place',o.place,'enabled',coalesce(o.enabled,true),'name',n.name)
   order by k.provider,k.account)
  from (select p.provider,p.account from public.provider_order p where p.company_id=c.id
   union select n.provider,n.account from public.provider_names n where n.company_id=c.id) k
  left join public.provider_order o on o.company_id=c.id and o.provider=k.provider and o.account=k.account
  left join public.provider_names n on n.company_id=c.id and n.provider=k.provider and n.account=k.account),'[]'::jsonb)
 from public.companies c where c.engine_id is not null order by c.id;
$$;

ALTER FUNCTION public.provider_accounts_work() OWNER TO postgres;

--
-- Name: queue_conversation_turn(uuid, uuid, uuid, uuid, text, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.queue_conversation_turn(conversation uuid, c uuid, agent uuid, message_key uuid, message text, open_only boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare existing public.conversations; chosen public.hermes_agents; queued public.conversation_queued_turns; noted public.conversation_notes; addressee record; writer text;
begin
 if not public.conversation_can_write(c) then raise exception 'conversationNotAllowed' using errcode='42501'; end if;
 if message is null or length(message) not between 0 and 200000 or message_key is null then raise exception 'conversationNotFound' using errcode='22023'; end if;
 perform pg_advisory_xact_lock(hashtextextended('conversation_turn:'||conversation::text,0));
 select * into existing from public.conversations where id=conversation;
 if found and (existing.person_id<>auth.uid() or existing.company_id<>c or existing.agent_id is distinct from agent) then raise exception 'conversationNotFound' using errcode='P0002'; end if;
 select * into chosen from public.hermes_agents where id=agent and company_id=c;
 if not found then raise exception 'conversationNotFound' using errcode='P0002'; end if;
 if open_only then
  insert into public.conversations(id,company_id,person_id,agent_id,agent_name) values(conversation,c,auth.uid(),agent,chosen.name) on conflict (id) do nothing;
  return jsonb_build_object('state','opened');
 end if;
 -- A send key already answered keeps its answer, before anything is resolved again.
 if exists(select 1 from public.conversation_messages m where m.conversation_id=conversation and m.send_key=message_key and m.author='person') then
  return jsonb_build_object('state','sent');
 end if;
 select * into noted from public.conversation_notes n where n.conversation_id=conversation and n.send_key=message_key;
 if found then
  if noted.person_id<>auth.uid() then raise exception 'conversationNotFound' using errcode='P0002'; end if;
  return jsonb_build_object('state','note');
 end if;
 select * into queued from public.conversation_queued_turns q where q.conversation_id=conversation and q.send_key=message_key;
 if found then
  if queued.person_id<>auth.uid() then raise exception 'conversationNotFound' using errcode='P0002'; end if;
  return jsonb_build_object('state',case when queued.failed_at is not null then 'failed' else 'queued' end);
 end if;
 if exists(select 1 from public.reply_cards r where r.conversation_id=conversation and r.kind='question' and r.answer_key=message_key) then
  return jsonb_build_object('state','answered');
 end if;
 select name into writer from public.people where id=auth.uid();
 insert into public.conversations(id,company_id,person_id,agent_id,agent_name) values(conversation,c,auth.uid(),agent,chosen.name) on conflict (id) do nothing;
 -- A key already reserved for a run is a retry of that run, never a note.
 if not exists(select 1 from public.conversation_run_reservations r where r.conversation_id=conversation and r.send_key=message_key) then
  select * into addressee from public.conversation_addressee(c,message);
  if addressee.person is not null then
   insert into public.conversation_notes(company_id,conversation_id,person_id,author_name,addressed_to,addressed_name,body,send_key)
    values(c,conversation,auth.uid(),coalesce(writer,''),addressee.person,addressee.name,message,message_key) on conflict (conversation_id,send_key) do nothing;
   return jsonb_build_object('state','note');
  end if;
 end if;
 insert into public.conversation_queued_turns(conversation_id,send_key,company_id,person_id,agent_id,message)
  values(conversation,message_key,c,auth.uid(),agent,message) on conflict (conversation_id,send_key) do nothing;
 -- The message is the chat's newest from now (#764): the sidebar lists the chat by it before its Run stores it.
 update public.conversations set last_message_at=now() where id=conversation and last_message_at<now();
 return jsonb_build_object('state','queued');
end $$;

ALTER FUNCTION public.queue_conversation_turn(conversation uuid, c uuid, agent uuid, message_key uuid, message text, open_only boolean) OWNER TO postgres;

--
-- Name: conversation_run_reservations; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.conversation_run_reservations (
    conversation_id uuid NOT NULL,
    send_key uuid NOT NULL,
    company_id uuid NOT NULL,
    connection_id uuid NOT NULL,
    person_id uuid NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    agent_id uuid,
    message text,
    profile text,
    abandoned_at timestamp with time zone,
    start_unknown_at timestamp with time zone,
    start_attempts integer DEFAULT 0 NOT NULL,
    start_unreached_at timestamp with time zone,
    stop_at_start timestamp with time zone,
    start_begun_at timestamp with time zone
);

ALTER TABLE public.conversation_run_reservations OWNER TO postgres;

--
-- Name: queue_unknown_start(public.conversation_run_reservations); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.queue_unknown_start(held public.conversation_run_reservations) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare chosen public.hermes_agents;
begin
 update public.conversation_run_reservations r set start_unknown_at=coalesce(r.start_unknown_at,now()) where r.conversation_id=held.conversation_id and r.send_key=held.send_key;
 select * into chosen from public.hermes_agents a where a.id=held.agent_id and a.company_id=held.company_id;
 if chosen.id is not null and held.message is not null then
  insert into public.conversations(id,company_id,person_id,agent_id,agent_name) values(held.conversation_id,held.company_id,held.person_id,held.agent_id,chosen.name) on conflict (id) do nothing;
  insert into public.conversation_queued_turns(conversation_id,send_key,company_id,person_id,agent_id,message,queued_at)
   values(held.conversation_id,held.send_key,held.company_id,held.person_id,held.agent_id,held.message,held.created_at) on conflict (conversation_id,send_key) do nothing;
 end if;
end $$;

ALTER FUNCTION public.queue_unknown_start(held public.conversation_run_reservations) OWNER TO postgres;

--
-- Name: queued_conversations(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.queued_conversations(just uuid DEFAULT NULL::uuid) RETURNS TABLE(conversation uuid)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
 select distinct q.conversation_id from public.conversation_queued_turns q
 where q.started_at is null and q.failed_at is null and (just is null or q.conversation_id=just)
  and not exists(select 1 from public.conversation_open_run(q.conversation_id))
  and not exists(select 1 from public.conversation_run_reservations r where r.conversation_id=q.conversation_id and r.abandoned_at is null
   and not exists(select 1 from public.conversation_queued_turns o where o.conversation_id=r.conversation_id and o.send_key=r.send_key and o.started_at is null and o.failed_at is null))
 limit 500;
$$;

ALTER FUNCTION public.queued_conversations(just uuid) OWNER TO postgres;

--
-- Name: queued_conversations(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.queued_conversations(just uuid, after uuid) RETURNS TABLE(conversation uuid)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
 select distinct q.conversation_id from public.conversation_queued_turns q
 where q.started_at is null and q.failed_at is null and (just is null or q.conversation_id=just)
  and (after is null or q.conversation_id>after)
  and not exists(select 1 from public.conversation_open_run(q.conversation_id))
  and not exists(select 1 from public.conversation_run_reservations r where r.conversation_id=q.conversation_id and r.abandoned_at is null
   and not exists(select 1 from public.conversation_queued_turns o where o.conversation_id=r.conversation_id and o.send_key=r.send_key and o.started_at is null and o.failed_at is null))
 order by q.conversation_id
 limit 500;
$$;

ALTER FUNCTION public.queued_conversations(just uuid, after uuid) OWNER TO postgres;

--
-- Name: queued_turn_start(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.queued_turn_start(conversation uuid, message_key uuid) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
 select case
  when q.conversation_id is null then 'waiting'
  when q.started_at is not null then 'started'
  when q.failed_at is not null then case when q.model_refused then 'modelRefused' else 'failed' end
  when r.conversation_id is null or r.abandoned_at is not null or r.start_unknown_at is not null then 'waiting'
  else 'inFlight'
 end
 from (select 1) as one
 left join public.conversation_queued_turns q on q.conversation_id=conversation and q.send_key=message_key
 left join public.conversation_run_reservations r on r.conversation_id=conversation and r.send_key=message_key;
$$;

ALTER FUNCTION public.queued_turn_start(conversation uuid, message_key uuid) OWNER TO postgres;

--
-- Name: read_channel(uuid, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.read_channel(ch uuid, through bigint) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare k public.channels; newest bigint;
begin
 select * into k from public.channels where id=ch;
 if k.id is null or not public.in_channel(ch) then raise exception 'channelNotFound' using errcode='P0002'; end if;
 select coalesce(max(id),0) into newest from public.channel_messages where channel_id=ch;
 insert into public.channel_reads(channel_id, company_id, person_id, read_through)
  values (ch, k.company_id, auth.uid(), greatest(least(coalesce(through,0), newest), 0))
  on conflict (channel_id, person_id) do update set read_through=excluded.read_through, read_at=now()
   where public.channel_reads.read_through < excluded.read_through;
end $$;

ALTER FUNCTION public.read_channel(ch uuid, through bigint) OWNER TO postgres;

--
-- Name: read_channel_mention(uuid, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.read_channel_mention(ch uuid, message bigint) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare k public.channels; changed integer;
begin
 select * into k from public.channels where id=ch;
 if k.id is null or not public.in_channel(ch) then return false; end if;
 update public.waiting_items w set resolved_at=now()
  where w.company_id=k.company_id and w.person_id=auth.uid() and w.resolved_at is null and w.channel_message_id=message
   and exists(select 1 from public.channel_messages m where m.id=message and m.channel_id=ch);
 get diagnostics changed = row_count;
 return changed > 0;
end $$;

ALTER FUNCTION public.read_channel_mention(ch uuid, message bigint) OWNER TO postgres;

