-- Name: record_agent_profile(uuid, text, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.record_agent_profile(agent uuid, engine_profile text, subagents_written boolean DEFAULT NULL::boolean) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
 if engine_profile is distinct from public.agent_engine_profile(agent) then raise exception 'agentProfileInvalid' using errcode='22023'; end if;
 perform 1 from public.agent_profiles p where p.agent_id=record_agent_profile.agent for update;
 if subagents_written is not null and exists(select 1 from public.agent_profiles p where p.agent_id=record_agent_profile.agent and p.subagents is distinct from subagents_written) then
  raise exception 'agentProfileChanged' using errcode='40001'; end if;
 update public.agent_profiles set tools_confirmed=true,tools_pending=false where agent_id=agent;
end $$;

ALTER FUNCTION public.record_agent_profile(agent uuid, engine_profile text, subagents_written boolean) OWNER TO postgres;

--
-- Name: record_app_connected(uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.record_app_connected(c uuid, app_key text, agent uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
begin
 if not public.is_company_owner(c) then raise exception 'appsNotAllowed' using errcode='42501'; end if;
 if coalesce(app_key,'') !~ '^[a-z][a-z0-9_-]{0,63}$' then raise exception 'appsInvalid' using errcode='22023'; end if;
 if not exists(select 1 from public.company_app_agents(c) x where x.agent=record_app_connected.agent and x.own) then raise exception 'appsAgentNotOwn' using errcode='42501'; end if;
 insert into public.company_audit(company_id,actor_id,action,app,agent_id) values (c,auth.uid(),'app_connected',app_key,record_app_connected.agent);
end $_$;

ALTER FUNCTION public.record_app_connected(c uuid, app_key text, agent uuid) OWNER TO postgres;

