--
-- Name: record_company_profile(uuid, text, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.record_company_profile(c uuid, engine_profile text, subagents_written boolean DEFAULT NULL::boolean) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
 if engine_profile is distinct from public.company_engine_profile(c) then raise exception 'companyProfileInvalid' using errcode='22023'; end if;
 -- The row is locked first, so an Owner's switch cannot land between this check and the record below.
 perform 1 from public.company_profiles p where p.company_id=c for update;
 if subagents_written is not null and exists(select 1 from public.company_profiles p where p.company_id=c and p.subagents is distinct from subagents_written) then
  raise exception 'companyProfileChanged' using errcode='40001'; end if;
 insert into public.company_profiles(company_id,profile,tools_confirmed) values (c,engine_profile,true)
  -- A worker that names no switch writes no delegation: its read-back never clears a switch that is on.
  on conflict (company_id) do update set tools_confirmed=true,
   tools_pending=record_company_profile.subagents_written is null and public.company_profiles.subagents;
end $$;

ALTER FUNCTION public.record_company_profile(c uuid, engine_profile text, subagents_written boolean) OWNER TO postgres;

--
-- Name: record_conversation_turn(uuid, uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.record_conversation_turn(conversation uuid, message_key uuid, run text, started_on uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare turn public.conversation_queued_turns; held public.conversation_run_reservations; chosen public.hermes_agents; writer text; saved bigint;
begin
 perform pg_advisory_xact_lock(hashtextextended('hermes_agents',0));
 select * into turn from public.conversation_queued_turns q where q.conversation_id=conversation and q.send_key=message_key;
 if not found or run is null then raise exception 'conversationNotFound' using errcode='P0002'; end if;
 if turn.started_at is not null then return false; end if;
 -- Its message was already stored by the direct send's late record: the turn ran; it is started, never failed.
 if exists(select 1 from public.conversation_messages m where m.conversation_id=conversation and m.send_key=message_key and m.author='person') then
  update public.conversation_queued_turns q set started_at=now() where q.conversation_id=conversation and q.send_key=message_key;
  delete from public.conversation_run_reservations r where r.conversation_id=conversation and r.send_key=message_key and r.abandoned_at is null;
  return false;
 end if;
 select * into chosen from public.hermes_agents a where a.id=turn.agent_id and a.company_id=turn.company_id;
 select * into held from public.conversation_run_reservations r where r.conversation_id=conversation and r.send_key=message_key;
 if chosen.id is null or held.conversation_id is null or held.abandoned_at is not null or started_on is null or held.connection_id<>started_on or held.profile is distinct from chosen.profile then
  update public.conversation_queued_turns q set failed_at=now() where q.conversation_id=conversation and q.send_key=message_key;
  delete from public.conversation_run_reservations r where r.conversation_id=conversation and r.send_key=message_key and r.abandoned_at is null;
  return false;
 end if;
 perform pg_advisory_xact_lock(hashtextextended('conversation_run:'||run,0));
 if exists(select 1 from public.conversation_messages m where m.author='person' and m.run_id=run and m.conversation_id<>conversation) then raise exception 'conversationNotFound' using errcode='P0002'; end if;
 select name into writer from public.people where id=turn.person_id;
 insert into public.conversation_messages(company_id,conversation_id,author,person_id,author_name,body,send_key,run_id)
  values(turn.company_id,conversation,'person',turn.person_id,coalesce(writer,''),turn.message,message_key,run) on conflict do nothing returning id into saved;
 delete from public.conversation_run_reservations r where r.conversation_id=conversation and r.send_key=message_key;
 update public.conversation_queued_turns q set started_at=now() where q.conversation_id=conversation and q.send_key=message_key;
 return saved is not null;
end $$;

ALTER FUNCTION public.record_conversation_turn(conversation uuid, message_key uuid, run text, started_on uuid) OWNER TO postgres;

--
-- Name: record_fallback_move(uuid, text, text, text, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.record_fallback_move(c uuid, run text, from_provider text, from_model text, to_provider text, to_model text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare added integer;
begin
 if c is null or not exists(select 1 from public.company_fallback_models f where f.company_id=c and f.provider=to_provider) then
  raise exception 'fallbackMoveInvalid' using errcode='22023';
 end if;
 insert into public.company_audit(company_id,actor_id,action,run_id,from_provider,from_model,to_provider,to_model)
  values (c,null,'fallback_model_used',run,from_provider,from_model,to_provider,to_model)
  on conflict (company_id,run_id) where run_id is not null do nothing;
 get diagnostics added=row_count;
 return added>0;
exception when check_violation or not_null_violation then
 raise exception 'fallbackMoveInvalid' using errcode='22023';
end $$;

ALTER FUNCTION public.record_fallback_move(c uuid, run text, from_provider text, from_model text, to_provider text, to_model text) OWNER TO postgres;

--
-- Name: record_good_morning(uuid, uuid, text, date, timestamp with time zone, text, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.record_good_morning(c uuid, agent uuid, session text, greeting_day date, ran timestamp with time zone, greeting text, results jsonb) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare morning bigint; main public.hermes_agents; member record; opened integer:=0; talk uuid; reader text;
begin
 select * into main from public.hermes_agents a where a.id=agent and a.company_id=c;
 if not found then raise exception 'goodMorningInvalid' using errcode='22023'; end if;
 if results is null or jsonb_typeof(results)<>'array' or jsonb_array_length(results)>200 then raise exception 'goodMorningInvalid' using errcode='22023'; end if;
 insert into public.good_mornings(company_id,agent_id,session_id,day,ran_at,greeting) values(c,agent,session,greeting_day,ran,nullif(left(trim(greeting),4000),''))
  on conflict (company_id,session_id) do nothing returning id into morning;
 if morning is null then return null; end if;
 insert into public.good_morning_results(morning_id,company_id,agent_id,routine,line,ran_at)
  select morning,c,(r->>'agent')::uuid,left(r->>'routine',200),left(r->>'line',300),(r->>'at')::timestamptz
  from jsonb_array_elements(results) r
  where exists(select 1 from public.hermes_agents a where a.id=(r->>'agent')::uuid and a.company_id=c)
   and coalesce(r->>'routine','')<>'' and coalesce(r->>'line','')<>'';
 if nullif(trim(coalesce(greeting,'')),'') is null then return 0; end if;
 reader:=current_setting('request.jwt.claim.sub',true);
 for member in select m.person_id from public.members m where m.company_id=c and m.removed_at is null order by m.person_id loop
  -- Each Member's parts are read as that Member, with the very reads their own card makes.
  perform set_config('request.jwt.claim.sub',member.person_id::text,true);
  -- What the Member's own card would show: their "Waiting on you" under their own policies, or a result of the night
  -- from an Agent they see.
  if public.good_morning_waits(c)
   or exists(select 1 from public.good_morning_results r where r.morning_id=morning and public.can_see_agent(c,r.agent_id)) then
   talk:=gen_random_uuid();
   insert into public.conversations(id,company_id,person_id,agent_id,agent_name,good_morning,good_morning_day)
    values(talk,c,member.person_id,main.id,main.name,morning,greeting_day);
   insert into public.conversation_messages(company_id,conversation_id,author,agent_id,author_name,body,run_id,created_at)
    values(c,talk,'agent',main.id,main.name,left(trim(greeting),4000),'good-morning:'||morning,ran);
   opened:=opened+1;
  end if;
 end loop;
 perform set_config('request.jwt.claim.sub',coalesce(reader,''),true);
 return opened;
end $$;

ALTER FUNCTION public.record_good_morning(c uuid, agent uuid, session text, greeting_day date, ran timestamp with time zone, greeting text, results jsonb) OWNER TO postgres;

