--
-- Name: refuse_run_model(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.refuse_run_model(conversation uuid, message_key uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare refused jsonb; earlier jsonb;
begin
 select n.model into refused from public.conversation_run_notes n where n.conversation_id=conversation and n.send_key=message_key for update;
 if refused is null or jsonb_typeof(refused)='null' then return false; end if;
 update public.conversations cv set model=cv.model_before, model_before=null where cv.id=conversation and cv.model=refused returning cv.model into earlier;
 if not found then return false; end if;
 update public.conversation_run_notes n set model=coalesce(earlier,'null'::jsonb) where n.conversation_id=conversation and n.send_key=message_key;
 update public.conversation_queued_turns q set model_refused=true where q.conversation_id=conversation and q.send_key=message_key and q.started_at is null;
 return true;
end $$;

ALTER FUNCTION public.refuse_run_model(conversation uuid, message_key uuid) OWNER TO postgres;

--
-- Name: refuse_run_model(uuid, uuid, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.refuse_run_model(conversation uuid, message_key uuid, attempt integer) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare refused boolean;
begin
 perform pg_advisory_xact_lock(hashtextextended('hermes_agents',0));
 -- A reservation already settled (the turn recorded or failed) is as stale as one a newer attempt began.
 if not exists(select 1 from public.conversation_run_reservations r where r.conversation_id=conversation and r.send_key=message_key and r.abandoned_at is null
  and r.start_unknown_at is null and r.start_attempts=attempt) then return false; end if;
 refused:=public.refuse_run_model(conversation,message_key);
 perform public.fail_conversation_turn(conversation,message_key,attempt);
 return refused;
end $$;

ALTER FUNCTION public.refuse_run_model(conversation uuid, message_key uuid, attempt integer) OWNER TO postgres;

