--
-- Name: remove_agent_rule(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.remove_agent_rule(c uuid, rule uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare kept public.agent_rules;
begin
 select * into kept from public.agent_rules r where r.id=rule and r.company_id=c and r.agent_id is not null for update;
 if not found or not public.can_see_agent(c,kept.agent_id) then raise exception 'agentRuleNotFound' using errcode='P0002'; end if;
 if not public.may_tell_agent_rules(c,kept.agent_id,auth.uid()) then raise exception 'agentRuleNotAllowed' using errcode='42501'; end if;
 if kept.removed_at is not null then return false; end if;
 update public.agent_rules set removed_at=now(),removed_by=auth.uid() where id=rule;
 update public.waiting_items set resolved_at=now() where agent_rule_id=rule and resolved_at is null;
 perform public.log_agent_event(c,auth.uid(),(select name from public.people where id=auth.uid()),kept.agent_id,'AGENT_RULE_REMOVED',jsonb_build_object('rule',kept.body,'rule_id',rule)
   ||case when kept.suggestion in ('pending','rejected') then jsonb_build_object('private',true,'teller',kept.said_by) else '{}'::jsonb end);
 return true;
end $$;

ALTER FUNCTION public.remove_agent_rule(c uuid, rule uuid) OWNER TO postgres;

--
-- Name: remove_approval_step(uuid, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.remove_approval_step(c uuid, step bigint) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare s public.approval_steps%rowtype; nxt bigint; w record; target bigint; begin
 if not public.can_manage_company(c) then raise exception 'not permitted'; end if;
 select * into s from public.approval_steps where company_id=c and id=step and removed_at is null for update; if not found then raise exception 'step not found'; end if;
 if (select count(*) from public.approval_steps where company_id=c and removed_at is null)<2 then raise exception 'one step required'; end if;
 select id into nxt from public.approval_steps where company_id=c and removed_at is null and (position,id)>(s.position,s.id) order by position,id limit 1;
 perform set_config('approval.internal','yes',true);
 for w in select * from public.work_cards where company_id=c and approval_step_id=step for update loop
  insert into public.work_activity(company_id,card_id,actor_id,action,details) values(c,w.id,auth.uid(),'approval_skipped',jsonb_build_object('step',s.name,'step_id',s.id));
  if nxt is not null then update public.work_cards set approval_step_id=nxt,next_actor=public.approval_actor(c,nxt) where id=w.id;
  else target=public.required_work_stage(c,'approved'); update public.work_cards set approval_step_id=null,next_actor=null,stage_id=target where id=w.id; if w.go_live is not null then target=public.required_work_stage(c,'scheduled'); update public.work_cards set stage_id=target where id=w.id; end if; end if;
 end loop;
 update public.approval_steps set removed_at=now() where company_id=c and id=step;
 perform set_config('approval.internal','',true);
end $$;

ALTER FUNCTION public.remove_approval_step(c uuid, step bigint) OWNER TO postgres;

--
-- Name: remove_member(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.remove_member(target_company uuid, target_person uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
 if not public.can_manage_company(target_company) then raise exception 'not permitted to remove members'; end if;
 update public.members set removed_at=now() where company_id=target_company and person_id=target_person and removed_at is null;
end $$;

ALTER FUNCTION public.remove_member(target_company uuid, target_person uuid) OWNER TO postgres;

--
-- Name: rename_company(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rename_company(c uuid, company_name text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare cleaned text:=btrim(coalesce(company_name,'')); previous text;
begin
 if not public.is_company_owner(c) then raise exception 'companyRenameNotAllowed' using errcode='42501'; end if;
 if cleaned='' or char_length(cleaned)>80 then raise exception 'companyNameInvalid' using errcode='22023'; end if;
 select name into previous from public.companies where id=c for update;
 if previous is distinct from cleaned then
  update public.companies set name=cleaned where id=c;
  insert into public.company_audit(company_id,actor_id,action,old_name,new_name) values (c,auth.uid(),'company_renamed',previous,cleaned);
 end if;
 return cleaned;
end $$;

ALTER FUNCTION public.rename_company(c uuid, company_name text) OWNER TO postgres;

--
-- Name: rename_provider(uuid, text, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rename_provider(c uuid, provider text, account text, name text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare given text := btrim(coalesce(name,''));
begin
 if not public.is_company_owner(c) then raise exception 'providerNotAllowed' using errcode='42501'; end if;
 if coalesce(provider,'') !~ '^[a-z0-9][a-z0-9._-]{0,63}$' or coalesce(account,'') !~ '^[A-Za-z0-9_-]{1,64}$'
  or char_length(given)>60 or given ~ '[[:cntrl:]]' then
  raise exception 'providerNameInvalid' using errcode='22023';
 end if;
 if given='' then
  delete from public.provider_names p where p.company_id=c and p.provider=rename_provider.provider and p.account=rename_provider.account;
  return;
 end if;
 insert into public.provider_names(company_id,provider,account,name,named_by)
  values (c,rename_provider.provider,rename_provider.account,given,auth.uid())
  on conflict on constraint provider_names_pkey do update set name=excluded.name,named_by=excluded.named_by,named_at=now();
end $_$;

ALTER FUNCTION public.rename_provider(c uuid, provider text, account text, name text) OWNER TO postgres;

