--
-- Name: reply_card_in_channel(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.reply_card_in_channel(card bigint) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
 select auth.uid() is not null and exists(select 1 from public.reply_cards c
  join public.channel_messages m on m.id=c.channel_message_id
  where c.id=card and c.channel_message_id is not null and public.in_channel(m.channel_id));
$$;

ALTER FUNCTION public.reply_card_in_channel(card bigint) OWNER TO postgres;

--
-- Name: reply_card_in_other_channel(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.reply_card_in_other_channel(card bigint) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
 select exists(select 1 from public.reply_cards c
  join public.channel_messages m on m.id=c.channel_message_id
  join public.channels k on k.id=m.channel_id
  where c.id=card and c.channel_message_id is not null and c.company_id=k.company_id
   and public.is_member(k.company_id) and not public.in_channel(m.channel_id));
$$;

ALTER FUNCTION public.reply_card_in_other_channel(card bigint) OWNER TO postgres;

--
-- Name: reply_card_text(jsonb, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.reply_card_text(value jsonb, most integer) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
 select coalesce(jsonb_typeof(value)='string' and value#>>'{}'=btrim(value#>>'{}',E' \t\r\n') and length(value#>>'{}') between 1 and most,false);
$$;

ALTER FUNCTION public.reply_card_text(value jsonb, most integer) OWNER TO postgres;

--
-- Name: reply_cards; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.reply_cards (
    id bigint NOT NULL,
    company_id uuid NOT NULL,
    conversation_id uuid,
    run_id text NOT NULL,
    call_id text NOT NULL,
    kind text NOT NULL,
    title text NOT NULL,
    content jsonb NOT NULL,
    state text DEFAULT 'shown'::text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    answered_by uuid,
    answered_at timestamp with time zone,
    answer_key uuid,
    done_by uuid,
    done_at timestamp with time zone,
    decided_by uuid,
    decided_at timestamp with time zone,
    delivering_at timestamp with time zone,
    channel_message_id bigint,
    channel_ordinal smallint,
    addressed_to uuid,
    allows text[],
    said_before text,
    CONSTRAINT reply_cards_addressed CHECK (((addressed_to IS NULL) OR ((kind = 'question'::text) AND (channel_message_id IS NOT NULL)))),
    CONSTRAINT reply_cards_allows CHECK ((((allows IS NULL) OR ((kind = 'permission'::text) AND ((content -> 'choices'::text) ? 'always'::text))) AND public.permission_allows_valid(allows))),
    CONSTRAINT reply_cards_answer CHECK ((((answered_by IS NULL) = (answered_at IS NULL)) AND ((answered_at IS NULL) = (answer_key IS NULL)) AND ((answered_at IS NOT NULL) = ((kind = 'question'::text) AND (content ? 'answer'::text))))),
    CONSTRAINT reply_cards_channel_ordinal_check CHECK (((channel_ordinal >= 1) AND (channel_ordinal <= 3))),
    CONSTRAINT reply_cards_decided CHECK ((((decided_by IS NULL) = (decided_at IS NULL)) AND ((decided_at IS NOT NULL) = ((kind = 'permission'::text) AND (content ? 'choice'::text))))),
    CONSTRAINT reply_cards_done CHECK ((((done_by IS NULL) = (done_at IS NULL)) AND ((done_at IS NOT NULL) = ((kind = 'hand'::text) AND (state = 'done'::text))))),
    CONSTRAINT reply_cards_kind CHECK (public.reply_card_valid(kind, state, content)),
    CONSTRAINT reply_cards_one_place CHECK (((conversation_id IS NULL) <> (channel_message_id IS NULL))),
    CONSTRAINT reply_cards_said_before_check CHECK (((said_before IS NULL) OR ((length(said_before) >= 1) AND (length(said_before) <= 200000)))),
    CONSTRAINT reply_cards_title CHECK (public.reply_card_text(to_jsonb(title), 100))
);

ALTER TABLE public.reply_cards OWNER TO postgres;

--
-- Name: reply_card_waits(public.reply_cards); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.reply_card_waits(card public.reply_cards) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
 select exists(
  select 1 from public.reply_cards r
  join public.conversations v on v.id=r.conversation_id and v.company_id=r.company_id
  where r.id=card.id and r.state='open' and public.is_member(v.company_id)
   and (v.person_id=auth.uid() or exists(select 1 from public.work_cards w where w.company_id=v.company_id and w.conversation_id=v.id and public.can_see_card(w.company_id,w.id)))
   and case r.kind
    when 'question' then not exists(select 1 from public.conversation_run_ends u where u.conversation_id=r.conversation_id and u.run_id=r.run_id)
    when 'hand' then exists(select 1 from public.members m where m.company_id=v.company_id and m.person_id=v.person_id and m.removed_at is null and m.role<>'viewer')
     and public.agent_visible_to(v.company_id,v.person_id,v.agent_id)
    when 'permission' then not exists(select 1 from public.conversation_run_ends u where u.conversation_id=r.conversation_id and u.run_id=r.run_id)
     and exists(select 1 from public.members m where m.company_id=v.company_id and m.person_id=v.person_id and m.removed_at is null and m.role<>'viewer')
     and public.agent_visible_to(v.company_id,v.person_id,v.agent_id)
    else false end);
$$;

ALTER FUNCTION public.reply_card_waits(card public.reply_cards) OWNER TO postgres;

--
-- Name: reply_files_valid(jsonb, text[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.reply_files_valid(files jsonb, missed text[]) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $_$
 select (files is null or jsonb_typeof(files)='array' and jsonb_array_length(files)<=10 and not exists(
   select 1 from jsonb_array_elements(files) f where jsonb_typeof(f)<>'object' or coalesce(f->>'position','')!~'^[0-9]$'
    or length(coalesce(f->>'name',''))not between 1 and 255 or length(coalesce(f->>'content_type',''))not between 1 and 127
    or coalesce(f->>'size','')!~'^[0-9]{1,9}$'))
  and (missed is null or cardinality(missed)<=20 and not exists(select 1 from unnest(missed) m where length(coalesce(m,'')) not between 1 and 255));
$_$;

ALTER FUNCTION public.reply_files_valid(files jsonb, missed text[]) OWNER TO postgres;

--
-- Name: reply_hands_files(jsonb, text[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.reply_hands_files(files jsonb, missed text[]) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
 select coalesce(jsonb_array_length(case when jsonb_typeof(files)='array' then files end),0)>0 or coalesce(cardinality(missed),0)>0;
$$;

ALTER FUNCTION public.reply_hands_files(files jsonb, missed text[]) OWNER TO postgres;

--
-- Name: request_install_update(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.request_install_update() RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare now_state text;
begin
 if not exists(select 1 from public.members where person_id=auth.uid() and removed_at is null and role='owner') then
  raise exception 'updateNotAllowed' using errcode='42501';
 end if;
 insert into public.install_updates default values on conflict do nothing;
 if not (select button from public.install_updates) then raise exception 'updateButtonOff' using errcode='42501'; end if;
 if exists(select 1 from public.install_updates where state='failed' and changed_at > now() - interval '1 hour') then
  raise exception 'updateFailedRecently' using errcode='42501';
 end if;
 update public.install_updates set state='requested', requested_by=auth.uid(), changed_at=now()
  where state not in ('requested','updating');
 select state into now_state from public.install_updates;
 return now_state;
end $$;

ALTER FUNCTION public.request_install_update() OWNER TO postgres;

--
-- Name: required_work_stage(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.required_work_stage(c uuid, required_key text) RETURNS bigint
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$ declare result bigint; begin
 select id into result from public.work_stages where company_id=c and stage_key=required_key;
 if result is null then raise exception 'required work stage missing: %', required_key; end if;
 return result; end $$;

ALTER FUNCTION public.required_work_stage(c uuid, required_key text) OWNER TO postgres;

--
-- Name: reserve_channel_files(uuid, uuid, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.reserve_channel_files(ch uuid, c uuid, message_key uuid, files jsonb) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare k public.channels;
begin
 perform pg_advisory_xact_lock(hashtextextended('channel_files:'||ch::text||':'||message_key::text,0));
 if ch is null or c is null or message_key is null or files is null or jsonb_typeof(files)<>'array'
  or jsonb_array_length(files) not between 1 and 5 then
  raise exception 'channelFilesInvalid' using errcode='22023'; end if;
 if exists(select 1 from jsonb_array_elements(files) as chosen(file)
   where coalesce(file->>'content_type','') not in ('image/png','image/jpeg','image/gif','image/webp')) then
  raise exception 'channelFilesInvalid' using errcode='22023'; end if;
 select * into k from public.channels where id=ch and company_id=c;
 if not found or not public.in_channel(ch) then raise exception 'channelNotFound' using errcode='P0002'; end if;
 if not public.conversation_can_write(c) then raise exception 'channelNotAllowed' using errcode='42501'; end if;
 if exists(select 1 from public.channel_attachments a
   where a.channel_id=ch and a.company_id=c and a.send_key=message_key and a.person_id<>auth.uid()) then
  raise exception 'channelNotFound' using errcode='P0002'; end if;
 if exists(select 1 from public.channel_attachments a
   where a.channel_id=ch and a.company_id=c and a.send_key=message_key and a.message_id is not null) then
  return -1; end if;
 insert into public.channel_attachments(company_id,channel_id,send_key,message_id,person_id,position,name,content_type,size,path)
  select c,ch,message_key,null,auth.uid(),place,
   file->>'name',file->>'content_type',(file->>'size')::bigint,
   c::text||'/channels/'||ch::text||'/'||message_key::text||'-'||place::text
  from jsonb_array_elements(files) with ordinality as chosen(file,ord)
  cross join lateral (select coalesce(nullif(file->>'position','')::smallint,(ord-1)::smallint) as place) p
  on conflict do nothing;
 return (select count(*)::integer from public.channel_attachments a
  where a.channel_id=ch and a.company_id=c and a.send_key=message_key);
end;
$$;

ALTER FUNCTION public.reserve_channel_files(ch uuid, c uuid, message_key uuid, files jsonb) OWNER TO postgres;

--
-- Name: reserve_channel_files(uuid, uuid, uuid, jsonb, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.reserve_channel_files(ch uuid, c uuid, message_key uuid, files jsonb, attempt uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare k public.channels;
begin
 perform pg_advisory_xact_lock(hashtextextended('channel_files:'||ch::text||':'||message_key::text,0));
 if ch is null or c is null or message_key is null or attempt is null or files is null or jsonb_typeof(files)<>'array'
  or jsonb_array_length(files) not between 1 and 5 then
  raise exception 'channelFilesInvalid' using errcode='22023'; end if;
 if exists(select 1 from jsonb_array_elements(files) as chosen(file)
   where coalesce(file->>'content_type','') not in ('image/png','image/jpeg','image/gif','image/webp')) then
  raise exception 'channelFilesInvalid' using errcode='22023'; end if;
 select * into k from public.channels where id=ch and company_id=c;
 if not found or not public.in_channel(ch) then raise exception 'channelNotFound' using errcode='P0002'; end if;
 if not public.conversation_can_write(c) then raise exception 'channelNotAllowed' using errcode='42501'; end if;
 if exists(select 1 from public.channel_attachments a
   where a.channel_id=ch and a.company_id=c and a.send_key=message_key and a.person_id<>auth.uid()) then
  raise exception 'channelNotFound' using errcode='P0002'; end if;
 if exists(select 1 from public.channel_attachments a
   where a.channel_id=ch and a.company_id=c and a.send_key=message_key and a.message_id is not null) then
  return -1; end if;
 insert into public.channel_attachments(company_id,channel_id,send_key,message_id,person_id,position,name,content_type,size,path)
  select c,ch,message_key,null,auth.uid(),place,
   file->>'name',file->>'content_type',(file->>'size')::bigint,
   c::text||'/channels/'||ch::text||'/'||message_key::text||'-'||attempt::text||'-'||place::text
  from jsonb_array_elements(files) with ordinality as chosen(file,ord)
  cross join lateral (select coalesce(nullif(file->>'position','')::smallint,(ord-1)::smallint) as place) p
  on conflict do nothing;
 update public.channel_attachments a
  set holders=case when attempt=any(a.holders) then a.holders else array_append(a.holders,attempt) end,held_at=now()
  where a.channel_id=ch and a.company_id=c and a.send_key=message_key and a.message_id is null and a.person_id=auth.uid();
 return (select count(*)::integer from public.channel_attachments a
  where a.channel_id=ch and a.company_id=c and a.send_key=message_key);
end;
$$;

ALTER FUNCTION public.reserve_channel_files(ch uuid, c uuid, message_key uuid, files jsonb, attempt uuid) OWNER TO postgres;

--
-- Name: reserve_conversation_files(uuid, uuid, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.reserve_conversation_files(conversation uuid, c uuid, message_key uuid, files jsonb) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare existing public.conversations;
begin
 perform pg_advisory_xact_lock(hashtextextended('conversation_files:'||conversation::text||':'||message_key::text,0));
 if not public.conversation_can_write(c) then raise exception 'conversationNotAllowed' using errcode='42501'; end if;
 if conversation is null or message_key is null or files is null or jsonb_typeof(files)<>'array'
  or jsonb_array_length(files) not between 1 and 5 then
  raise exception 'conversationFilesInvalid' using errcode='22023'; end if;
 if exists(select 1 from jsonb_array_elements(files) as chosen(file)
   where coalesce(file->>'content_type','') not in ('image/png','image/jpeg','image/gif','image/webp')) then
  raise exception 'conversationFilesInvalid' using errcode='22023'; end if;
 select * into existing from public.conversations where id=conversation;
 if not found or existing.person_id<>auth.uid() or existing.company_id<>c then
  raise exception 'conversationNotFound' using errcode='P0002'; end if;
 if exists(select 1 from public.conversation_attachments a
   join public.conversation_messages m on m.id=a.message_id
   where a.conversation_id=conversation and a.company_id=c and a.send_key=message_key
    and m.author='person' and m.person_id=auth.uid()) then
  return -1; end if;
 if exists(select 1 from public.conversation_attachments a where a.conversation_id=conversation and a.company_id=c and a.send_key=message_key)
  and (exists(select 1 from public.conversation_queued_turns q where q.conversation_id=conversation and q.send_key=message_key
    and q.started_at is null and q.failed_at is null)
   or exists(select 1 from public.conversation_run_reservations r where r.conversation_id=conversation and r.send_key=message_key
    and r.abandoned_at is null)) then
  return -2; end if;
 if exists(select 1 from public.conversation_attachments a
   where a.conversation_id=conversation and a.company_id=c and a.send_key=message_key and a.message_id is not null) then
  raise exception 'conversationNotFound' using errcode='P0002'; end if;
 insert into public.conversation_attachments(company_id,conversation_id,send_key,position,message_id,name,content_type,size,path)
  select c,conversation,message_key,place,
   (select m.id from public.conversation_messages m where m.conversation_id=conversation and m.send_key=message_key and m.author='person' order by m.id limit 1),
   file->>'name',file->>'content_type',(file->>'size')::bigint,
   c::text||'/conversations/'||conversation::text||'/'||message_key::text||'-'||place::text
  from jsonb_array_elements(files) with ordinality as chosen(file,ord)
  cross join lateral (select coalesce(nullif(file->>'position','')::smallint,(ord-1)::smallint) as place) p
  where not exists(select 1 from public.conversation_attachments a
   where a.conversation_id=conversation and a.company_id=c and a.send_key=message_key and a.position=p.place)
  on conflict (company_id,path) do nothing;
 return (select count(*)::integer from public.conversation_attachments a
  where a.conversation_id=conversation and a.company_id=c and a.send_key=message_key);
end;
$$;

ALTER FUNCTION public.reserve_conversation_files(conversation uuid, c uuid, message_key uuid, files jsonb) OWNER TO postgres;

--
-- Name: reserve_conversation_files(uuid, uuid, uuid, jsonb, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.reserve_conversation_files(conversation uuid, c uuid, message_key uuid, files jsonb, attempt uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare existing public.conversations;
begin
 perform pg_advisory_xact_lock(hashtextextended('conversation_files:'||conversation::text||':'||message_key::text,0));
 if not public.conversation_can_write(c) then raise exception 'conversationNotAllowed' using errcode='42501'; end if;
 if conversation is null or message_key is null or attempt is null or files is null or jsonb_typeof(files)<>'array'
  or jsonb_array_length(files) not between 1 and 5 then
  raise exception 'conversationFilesInvalid' using errcode='22023'; end if;
 if exists(select 1 from jsonb_array_elements(files) as chosen(file)
   where coalesce(file->>'content_type','') not in ('image/png','image/jpeg','image/gif','image/webp')) then
  raise exception 'conversationFilesInvalid' using errcode='22023'; end if;
 select * into existing from public.conversations where id=conversation;
 if not found or existing.person_id<>auth.uid() or existing.company_id<>c then
  raise exception 'conversationNotFound' using errcode='P0002'; end if;
 if exists(select 1 from public.conversation_attachments a
   join public.conversation_messages m on m.id=a.message_id
   where a.conversation_id=conversation and a.company_id=c and a.send_key=message_key
    and m.author='person' and m.person_id=auth.uid()) then
  return -1; end if;
 if exists(select 1 from public.conversation_attachments a where a.conversation_id=conversation and a.company_id=c and a.send_key=message_key)
  and (exists(select 1 from public.conversation_queued_turns q where q.conversation_id=conversation and q.send_key=message_key
    and q.started_at is null and q.failed_at is null)
   or exists(select 1 from public.conversation_run_reservations r where r.conversation_id=conversation and r.send_key=message_key
    and r.abandoned_at is null)) then
  return -2; end if;
 if exists(select 1 from public.conversation_attachments a
   where a.conversation_id=conversation and a.company_id=c and a.send_key=message_key and a.message_id is not null) then
  raise exception 'conversationNotFound' using errcode='P0002'; end if;
 insert into public.conversation_attachments(company_id,conversation_id,send_key,position,message_id,name,content_type,size,path)
  select c,conversation,message_key,place,
   (select m.id from public.conversation_messages m where m.conversation_id=conversation and m.send_key=message_key and m.author='person' order by m.id limit 1),
   file->>'name',file->>'content_type',(file->>'size')::bigint,
   c::text||'/conversations/'||conversation::text||'/'||message_key::text||'-'||attempt::text||'-'||place::text
  from jsonb_array_elements(files) with ordinality as chosen(file,ord)
  cross join lateral (select coalesce(nullif(file->>'position','')::smallint,(ord-1)::smallint) as place) p
  where not exists(select 1 from public.conversation_attachments a
   where a.conversation_id=conversation and a.company_id=c and a.send_key=message_key and a.position=p.place)
  on conflict (company_id,path) do nothing;
 update public.conversation_attachments a
  set holders=case when attempt=any(a.holders) then a.holders else array_append(a.holders,attempt) end,held_at=now()
  where a.conversation_id=conversation and a.company_id=c and a.send_key=message_key and a.message_id is null;
 return (select count(*)::integer from public.conversation_attachments a
  where a.conversation_id=conversation and a.company_id=c and a.send_key=message_key);
end;
$$;

ALTER FUNCTION public.reserve_conversation_files(conversation uuid, c uuid, message_key uuid, files jsonb, attempt uuid) OWNER TO postgres;

--
-- Name: reserve_conversation_run(uuid, uuid, uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.reserve_conversation_run(conversation uuid, c uuid, agent uuid, message_key uuid, message text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare existing public.conversations; held public.conversation_run_reservations; target text; token uuid; refusal text;
begin
 if not public.conversation_can_write(c) then raise exception 'conversationNotAllowed' using errcode='42501'; end if;
 if message is null or length(message) not between 0 and 200000 then raise exception 'conversationNotFound' using errcode='22023'; end if;
 select * into existing from public.conversations where id=conversation;
 if found and (existing.person_id<>auth.uid() or existing.company_id<>c or existing.agent_id is distinct from agent) then raise exception 'conversationNotFound' using errcode='P0002'; end if;
 perform pg_advisory_xact_lock(hashtextextended('hermes_agents',0));
 if not exists(select 1 from public.hermes_agents a where a.id=agent and a.company_id=c) then raise exception 'conversationNotFound' using errcode='P0002'; end if;
 select * into held from public.conversation_run_reservations r where r.conversation_id=conversation and r.send_key=message_key;
 if found and (held.person_id<>auth.uid() or held.company_id<>c or held.agent_id is distinct from agent) then raise exception 'conversationNotFound' using errcode='P0002'; end if;
 -- A retry keeps the profile it first reserved, so it never starts a run on another profile; an abandoned one is
 -- reserved again on the Agent's profile of now. Either way the checks below run before it is returned.
 if found and held.abandoned_at is null then target:=held.profile; token:=held.connection_id;
 else select a.profile,a.connection_id into target,token from public.hermes_agents a where a.id=agent and a.company_id=c;
 end if;
 if target is null then raise exception 'conversationNotFound' using errcode='P0002'; end if;
 if target ~ '^co-[0-9a-f]{32}$' then
  if target<>public.company_engine_profile(c) then raise exception 'hermesProfileNotShared' using errcode='42501'; end if;
  if not public.company_profile_ready(c) then raise exception 'agentToolsPending' using errcode='55000'; end if;
 end if;
 refusal:=public.agent_profile_refusal(target,c,agent);
 if refusal='hermesProfileNotShared' then raise exception 'hermesProfileNotShared' using errcode='42501'; end if;
 if refusal='agentToolsPending' then raise exception 'agentToolsPending' using errcode='55000'; end if;
 insert into public.conversation_run_reservations(conversation_id,send_key,company_id,connection_id,person_id,agent_id,message,profile)
  values(conversation,message_key,c,token,auth.uid(),agent,message,target)
  on conflict (conversation_id,send_key) do update set connection_id=excluded.connection_id,profile=excluded.profile,message=excluded.message,created_at=now(),abandoned_at=null,
   start_attempts=0,start_unknown_at=null
   where public.conversation_run_reservations.abandoned_at is not null;
 return token;
end $_$;

ALTER FUNCTION public.reserve_conversation_run(conversation uuid, c uuid, agent uuid, message_key uuid, message text) OWNER TO postgres;

--
-- Name: reserve_conversation_turn(uuid, uuid, uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.reserve_conversation_turn(conversation uuid, c uuid, agent uuid, message_key uuid, message text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare existing public.conversations; chosen public.hermes_agents; queued public.conversation_queued_turns; noted public.conversation_notes; addressee record; writer text; pinned uuid;
begin
 if not public.conversation_can_write(c) then raise exception 'conversationNotAllowed' using errcode='42501'; end if;
 if message is null or length(message) not between 0 and 200000 or message_key is null then raise exception 'conversationNotFound' using errcode='22023'; end if;
 -- Lock order: this Conversation's turns first, then the agents lock reserve_conversation_run takes.
 perform pg_advisory_xact_lock(hashtextextended('conversation_turn:'||conversation::text,0));
 select * into existing from public.conversations where id=conversation;
 if found and (existing.person_id<>auth.uid() or existing.company_id<>c or existing.agent_id is distinct from agent) then raise exception 'conversationNotFound' using errcode='P0002'; end if;
 select * into chosen from public.hermes_agents where id=agent and company_id=c;
 if not found then raise exception 'conversationNotFound' using errcode='P0002'; end if;
 -- A send key already answered keeps its answer, before anything is resolved again.
 select * into noted from public.conversation_notes n where n.conversation_id=conversation and n.send_key=message_key;
 if found then
  if noted.person_id<>auth.uid() then raise exception 'conversationNotFound' using errcode='P0002'; end if;
  return jsonb_build_object('state','note');
 end if;
 select * into queued from public.conversation_queued_turns q where q.conversation_id=conversation and q.send_key=message_key;
 if found then
  if queued.person_id<>auth.uid() then raise exception 'conversationNotFound' using errcode='P0002'; end if;
  return jsonb_build_object('state',case when queued.failed_at is not null then 'failed' else 'queued' end);
 end if;
 -- A send key already claimed as a question's answer (#138: a send whose first try found no question, retried once one
 -- had opened) is that answer: it neither queues nor starts a Run, so the message reaches the Agent once.
 if exists(select 1 from public.reply_cards r where r.conversation_id=conversation and r.kind='question' and r.answer_key=message_key) then
  return jsonb_build_object('state','answered');
 end if;
 select name into writer from public.people where id=auth.uid();
 -- A key already reserved for a run is a retry of that run, never a note.
 if not exists(select 1 from public.conversation_run_reservations r where r.conversation_id=conversation and r.send_key=message_key) then
  select * into addressee from public.conversation_addressee(c,message);
  if addressee.person is not null then
   insert into public.conversations(id,company_id,person_id,agent_id,agent_name) values(conversation,c,auth.uid(),agent,chosen.name) on conflict (id) do nothing;
   insert into public.conversation_notes(company_id,conversation_id,person_id,author_name,addressed_to,addressed_name,body,send_key)
    values(c,conversation,auth.uid(),coalesce(writer,''),addressee.person,addressee.name,message,message_key) on conflict (conversation_id,send_key) do nothing;
   return jsonb_build_object('state','note');
  end if;
 end if;
 if public.conversation_busy(conversation,message_key) then
  insert into public.conversations(id,company_id,person_id,agent_id,agent_name) values(conversation,c,auth.uid(),agent,chosen.name) on conflict (id) do nothing;
  insert into public.conversation_queued_turns(conversation_id,send_key,company_id,person_id,agent_id,message) values(conversation,message_key,c,auth.uid(),agent,message);
  return jsonb_build_object('state','queued');
 end if;
 pinned:=public.reserve_conversation_run(conversation,c,agent,message_key,message);
 -- The profile the reservation pinned travels beside its token, as 20270213000000_one_hermes.sql left this answer.
 return jsonb_build_object('state','reserved','connection',pinned,'profile',(select r.profile from public.conversation_run_reservations r where r.conversation_id=conversation and r.send_key=message_key),'note',public.pinned_run_note(conversation,message_key,c,auth.uid()));
end $$;

ALTER FUNCTION public.reserve_conversation_turn(conversation uuid, c uuid, agent uuid, message_key uuid, message text) OWNER TO postgres;

--
-- Name: reset_agent_look(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.reset_agent_look(c uuid, agent uuid) RETURNS public.agent_looks
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare now_is public.agent_looks; part text;
begin
 foreach part in array array['shape','colour','temperament'] loop now_is:=public.change_agent_look(c,agent,part,null); end loop;
 return now_is;
end $$;

ALTER FUNCTION public.reset_agent_look(c uuid, agent uuid) OWNER TO postgres;

