--
-- Name: restore_agent_rule(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.restore_agent_rule(c uuid, rule uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare kept public.agent_rules;
begin
 select * into kept from public.agent_rules r where r.id=rule and r.company_id=c and r.agent_id is not null for update;
 if not found or not public.can_see_agent(c,kept.agent_id) then raise exception 'agentRuleNotFound' using errcode='P0002'; end if;
 if not public.may_tell_agent_rules(c,kept.agent_id,auth.uid()) then raise exception 'agentRuleNotAllowed' using errcode='42501'; end if;
 if kept.removed_at is null then return false; end if;
 if kept.suggestion is not null and kept.suggestion<>'approved' then return false; end if;
 update public.agent_rules set removed_at=null,removed_by=null where id=rule;
 perform public.log_agent_event(c,auth.uid(),(select name from public.people where id=auth.uid()),kept.agent_id,'AGENT_RULE_RESTORED',
  jsonb_build_object('rule',kept.body));
 return true;
end $$;

ALTER FUNCTION public.restore_agent_rule(c uuid, rule uuid) OWNER TO postgres;

--
-- Name: restore_cards(uuid, bigint[], timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.restore_cards(c uuid, cards bigint[], archived timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS SETOF bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare w public.work_cards; back_column text; back bigint;
begin
 if auth.uid() is null or not public.work_can_edit(c) then raise exception 'cardRestoreNotAllowed' using errcode='42501'; end if;
 for w in select * from public.work_cards where company_id=c and id=any(cards) and archived_at is not null order by id for update loop
  if not public.can_see_card(c,w.id) or archived is not null and w.archived_at<>archived then continue; end if;
  back:=null;
  if w.approval_step_id is null and exists(select 1 from public.work_stages s where s.company_id=c and s.id=w.stage_id and s.kind='review') then
   select m.from_stage_id into back from public.work_card_moves m
    join public.work_stages s on s.company_id=m.company_id and s.id=m.from_stage_id and s.kind in ('ideas','before_review')
    where m.company_id=c and m.card_id=w.id and m.to_stage_id=w.stage_id order by m.id desc limit 1;
   if back is null then
    select s.id into back from public.work_stages s where s.company_id=c and s.kind='before_review' order by s.position desc,s.id desc limit 1;
   end if;
  end if;
  perform set_config('approval.internal','yes',true);
  update public.work_cards set archived_at=null,archived_by=null,stage_id=coalesce(back,stage_id),
   review_submitter=case when back is null then review_submitter end,review_entered_at=case when back is null then review_entered_at end,
   next_actor=case when back is null then next_actor end
   where company_id=c and id=w.id;
  perform set_config('approval.internal','',true);
  select s.board_column into back_column from public.work_stages s join public.work_cards x on x.company_id=s.company_id and x.stage_id=s.id where x.company_id=c and x.id=w.id;
  insert into public.work_activity(company_id,card_id,actor_id,action,details)
   values(c,w.id,auth.uid(),'card_restored',jsonb_build_object('column',back_column));
  return next w.id;
 end loop;
end $$;

ALTER FUNCTION public.restore_cards(c uuid, cards bigint[], archived timestamp with time zone) OWNER TO postgres;

--
-- Name: restore_channel(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.restore_channel(c uuid, ch uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare k public.channels; logged bigint; writer text;
begin
 if auth.uid() is null then raise exception 'channelRestoreNotAllowed' using errcode='42501'; end if;
 select * into k from public.channels x where x.id=ch for update;
 if k.id is null or k.company_id is distinct from c or not public.in_channel(ch) then raise exception 'channelNotFound' using errcode='P0002'; end if;
 if k.kind<>'team' or not public.can_manage_company(k.company_id) then raise exception 'channelRestoreNotAllowed' using errcode='42501'; end if;
 if k.archived_at is null then return; end if;
 update public.channels x set archived_at=null, archived_by=null where x.id=ch;
 insert into public.channel_archives(company_id,channel_id,actor_id,action) values (k.company_id,ch,auth.uid(),'restored') returning id into logged;
 select p.name into writer from public.people p where p.id=auth.uid();
 insert into public.company_log(company_id,actor_id,actor_kind,actor_name,subject,action,details,source,source_id,created_at)
  values (k.company_id,auth.uid(),'person',writer,'company','channel_restored',jsonb_build_object('channel_id',ch,'channel',k.name),'channel_archives',logged,now());
end $$;

ALTER FUNCTION public.restore_channel(c uuid, ch uuid) OWNER TO postgres;

--
-- Name: restore_conversations(uuid, uuid[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.restore_conversations(c uuid, chats uuid[]) RETURNS SETOF uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v uuid;
begin
 if auth.uid() is null or not public.is_member(c) then raise exception 'conversationRestoreNotAllowed' using errcode='42501'; end if;
 for v in select o.id from public.own_conversations(c) o where o.id=any(chats) and o.archived_at is not null order by o.id loop
  update public.conversations x set archived_at=null, archived_by=null where x.id=v and x.archived_at is not null;
  if found then perform public.log_conversation_archive(v,false,auth.uid()); return next v; end if;
 end loop;
end $$;

ALTER FUNCTION public.restore_conversations(c uuid, chats uuid[]) OWNER TO postgres;

--
-- Name: restore_written_conversation(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.restore_written_conversation() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v public.conversations;
begin
 select * into v from public.conversations x where x.id=new.conversation_id;
 if tg_table_name='conversation_messages' then
  if new.author<>'person' then return null; end if;
  if exists(select 1 from public.conversation_run_reservations r where r.conversation_id=v.id and r.send_key=new.send_key
   and r.stop_at_start>=r.created_at) then
   if new.run_id is not null then
    insert into public.stopped_runs(company_id,conversation_id,run_id) values(v.company_id,v.id,new.run_id) on conflict do nothing;
   end if;
   return null;
  end if;
 end if;
 if v.archived_at is null then return null; end if;
 update public.conversations set archived_at=null, archived_by=null where id=v.id and archived_at is not null;
 if found then perform public.log_conversation_archive(v.id,false,new.person_id); end if;
 return null;
end $$;

ALTER FUNCTION public.restore_written_conversation() OWNER TO postgres;

--
-- Name: retry_channel_run(uuid, bigint, smallint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.retry_channel_run(ch uuid, message bigint, ordinal smallint) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare retried integer; k public.channels;
begin
 select * into k from public.channels where id=ch;
 if k.id is null or not public.in_channel(ch) then raise exception 'channelNotFound' using errcode='P0002'; end if;
 if not public.conversation_can_write(k.company_id) then raise exception 'channelNotAllowed' using errcode='42501'; end if;
 if not exists(select 1 from public.channel_messages m where m.id=message and m.channel_id=ch and m.author='person' and m.person_id=auth.uid()) then
  raise exception 'channelNotFound' using errcode='P0002';
 end if;
 update public.channel_runs r set outcome=null, closed_at=null, attempts=0, attempted_at=null
  where r.message_id=message and r.channel_id=ch and r.ordinal=retry_channel_run.ordinal and r.outcome='failed' and r.run_id is null;
 get diagnostics retried=row_count;
 return retried>0;
end $$;

ALTER FUNCTION public.retry_channel_run(ch uuid, message bigint, ordinal smallint) OWNER TO postgres;

--
-- Name: retry_conversation_turn(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.retry_conversation_turn(conversation uuid, c uuid, message_key uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare retried integer;
begin
 if not public.conversation_can_write(c) then raise exception 'conversationNotAllowed' using errcode='42501'; end if;
 perform pg_advisory_xact_lock(hashtextextended('conversation_turn:'||conversation::text,0));
 perform pg_advisory_xact_lock(hashtextextended('hermes_agents',0));
 if exists(select 1 from public.conversation_messages m where m.conversation_id=conversation and m.send_key=message_key and m.author='person') then return false; end if;
 update public.conversation_queued_turns q set failed_at=null,model_refused=false
  where q.conversation_id=conversation and q.send_key=message_key and q.company_id=c and q.person_id=auth.uid()
   and q.failed_at is not null and q.started_at is null;
 get diagnostics retried=row_count;
 if retried=0 then
  if not exists(select 1 from public.conversation_queued_turns q where q.conversation_id=conversation and q.send_key=message_key and q.person_id=auth.uid()) then
   raise exception 'conversationNotFound' using errcode='P0002';
  end if;
  return false;
 end if;
 return true;
end $$;

ALTER FUNCTION public.retry_conversation_turn(conversation uuid, c uuid, message_key uuid) OWNER TO postgres;

--
-- Name: routine_results_seen(uuid, text, text[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.routine_results_seen(c uuid, at_profile text, sessions text[]) RETURNS SETOF text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
 select r.session_id from public.routine_results r where r.company_id=c and r.profile=at_profile and r.session_id=any(sessions);
$$;

ALTER FUNCTION public.routine_results_seen(c uuid, at_profile text, sessions text[]) OWNER TO postgres;

--
-- Name: rule_suggestions_sent_to(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rule_suggestions_sent_to(conversation uuid) RETURNS TABLE(rule uuid, sent_to text[])
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
 select r.id,array_agg(p.name order by m.role='owner' desc,p.name,p.id)
  from public.conversations v join public.agent_rules r on r.conversation_id=v.id and r.suggestion is not null
  join public.waiting_items i on i.agent_rule_id=r.id join public.people p on p.id=i.person_id
  left join public.members m on m.company_id=i.company_id and m.person_id=i.person_id
  where v.id=conversation and v.person_id=auth.uid() and public.can_see_agent(v.company_id,v.agent_id)
  group by r.id;
$$;

ALTER FUNCTION public.rule_suggestions_sent_to(conversation uuid) OWNER TO postgres;

--
-- Name: rule_words(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rule_words(said text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $_$
 select regexp_replace(regexp_replace(lower(regexp_replace(btrim(said),'^@\S+\s+','')),'\s+',' ','g'),'[\s.!?؟]+$','');
$_$;

ALTER FUNCTION public.rule_words(said text) OWNER TO postgres;

--
-- Name: run_offers_tools(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.run_offers_tools(conversation uuid, message_key uuid) RETURNS boolean
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO ''
    AS $$
 with pinned as (update public.conversation_run_notes r set tools=coalesce(r.tools,public.lead_tools_spec_89())
  where r.conversation_id=conversation and r.send_key=message_key and r.offers_tools returning 1)
 select exists(select 1 from pinned);
$$;

ALTER FUNCTION public.run_offers_tools(conversation uuid, message_key uuid) OWNER TO postgres;

--
-- Name: run_tools(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.run_tools(c uuid, agent uuid, person uuid) RETURNS text[]
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
 select array_remove(array[
  case when public.may_use_lead_tools(c,agent,person) then 'create_agent' when public.may_ask_lead_for_agents(c,agent,person) then 'request_agent' end,
  case when public.may_hand_to_agent(c,agent,person) then 'hand_to_agent' end,
  case when public.may_tell_agent_rules(c,agent,person) then 'save_rule' when public.may_suggest_agent_rules(c,agent,person) then 'suggest_team_rule' end,
  case when public.may_show_reply_cards(c,agent,person) then 'show_draft' end,
  case when public.may_show_reply_cards(c,agent,person) then 'show_review' end,
  case when public.may_show_reply_cards(c,agent,person) then 'hand_over' end,
  case when public.may_show_reply_cards(c,agent,person) then 'ask_for_app' end,
  case when public.may_propose_agent_change(c,agent,person) then 'propose_change' end,
  case when public.may_ask_to_open_agents(c,agent,person) then 'ask_to_open_agent' end],null);
$$;

ALTER FUNCTION public.run_tools(c uuid, agent uuid, person uuid) OWNER TO postgres;

--
-- Name: save_approval_step(uuid, bigint, text, integer, uuid, public.member_role); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.save_approval_step(c uuid, step bigint, step_name text, step_position integer, member uuid, member_role public.member_role) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$ begin
 if not public.can_manage_company(c) then raise exception 'not permitted'; end if;
 if member is not null and not exists(select 1 from public.members where company_id=c and person_id=member and removed_at is null and role in ('owner','manager')) then raise exception 'invalid approver'; end if;
 if step is null then insert into public.approval_steps(company_id,name,position,person_id,role) values(c,step_name,step_position,member,member_role);
 else update public.approval_steps set name=step_name,position=step_position,person_id=member,role=member_role where company_id=c and id=step and removed_at is null; if not found then raise exception 'step not found'; end if; perform set_config('approval.internal','yes',true); update public.work_cards set next_actor=public.approval_actor(c,step) where company_id=c and approval_step_id=step; perform set_config('approval.internal','',true); end if;
end $$;

ALTER FUNCTION public.save_approval_step(c uuid, step bigint, step_name text, step_position integer, member uuid, member_role public.member_role) OWNER TO postgres;

--
-- Name: save_member_note(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.save_member_note(c uuid, note text) RETURNS text
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare kept text := btrim(coalesce(note,''));
begin
 if auth.uid() is null or not public.is_member(c) then raise exception 'memberNoteNotAllowed' using errcode='42501'; end if;
 if kept='' then delete from public.member_notes where company_id=c and person_id=auth.uid(); return ''; end if;
 if length(kept)>4000 then raise exception 'memberNoteTooLong' using errcode='22001'; end if;
 if public.secret_like(kept) then raise exception 'memberNoteSecret' using errcode='22023'; end if;
 insert into public.member_notes(company_id,person_id,note) values(c,auth.uid(),kept)
  on conflict (company_id,person_id) do update set note=excluded.note,updated_at=now();
 return kept;
end $$;

ALTER FUNCTION public.save_member_note(c uuid, note text) OWNER TO postgres;

--
-- Name: schedule_approved_card(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.schedule_approved_card() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$ begin
 if new.go_live is not null and old.go_live is null and exists(select 1 from public.work_stages where company_id=new.company_id and id=new.stage_id and stage_key='approved') then
  perform set_config('approval.internal','yes',true); update public.work_cards set stage_id=public.required_work_stage(new.company_id,'scheduled') where id=new.id; perform set_config('approval.internal','',true);
 end if; return new; end $$;

ALTER FUNCTION public.schedule_approved_card() OWNER TO postgres;

