--
-- Name: screen_hands(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.screen_hands(c uuid) RETURNS TABLE(card bigint, conversation uuid, agent uuid, agent_name text, title text, app text, step text, created_at timestamp with time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
 select r.id,v.id,v.agent_id,h.name,r.title,r.content->>'app',r.content->>'step',r.created_at
 from public.reply_cards r
 join public.conversations v on v.id=r.conversation_id
 join public.hermes_agents h on h.id=v.agent_id and h.company_id=c
 where r.company_id=c and v.company_id=c and r.kind='hand' and r.state='open' and r.content->'screen'='true'::jsonb
  and v.person_id=auth.uid() and v.archived_at is null
  and public.conversation_can_write(c) and public.can_see_agent(c,v.agent_id)
 order by r.id desc
 limit 20;
$$;

ALTER FUNCTION public.screen_hands(c uuid) OWNER TO postgres;

--
-- Name: search_fold(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.search_fold(text text) RETURNS text
    LANGUAGE sql IMMUTABLE STRICT PARALLEL SAFE
    SET search_path TO ''
    AS $$
 select btrim(regexp_replace(translate(regexp_replace(normalize(lower(text),NFKD),'[ً-ٰٟـ]','','g'),'ٱىة','ايه'),'\s+',' ','g'));
$$;

ALTER FUNCTION public.search_fold(text text) OWNER TO postgres;

--
-- Name: secret_like(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.secret_like(t text) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
 select coalesce(t ~ any(array[
   'sk-[A-Za-z0-9_-]{20,}',
   '(gtmw_agt_|gtmw_run_|agt_)[A-Za-z0-9_-]{16,}',
   'gh[pousr]_[A-Za-z0-9]{30,}',
   'github_pat_[A-Za-z0-9_]{20,}',
   'xox[abprs]-[A-Za-z0-9-]{10,}',
   'AKIA[0-9A-Z]{16}',
   'AIza[0-9A-Za-z_-]{35}',
   '-----BEGIN [A-Z ]*PRIVATE KEY-----',
   'eyJ[A-Za-z0-9_-]{10,}\.eyJ[A-Za-z0-9_-]{10,}\.[A-Za-z0-9_-]{10,}'
  ]) or t ~* any(array[
   '(password|passwd|pwd|passphrase|secret|api[ _-]?key|access[ _-]?key|access[ _-]?token|auth[ _-]?token|refresh[ _-]?token|client[ _-]?secret|private[ _-]?key|token)["'']?\s*[:=]\s*("[^"]+"|''[^'']+''|["'']?[^\s"''][^\s]{3,})',
   '[a-z][a-z0-9+.-]*://[^\s/:@]+:[^\s/@]+@',
   'bearer\s+[A-Za-z0-9._~+/-]{20,}',
   '(\u0643\u0644\u0645[\u0629\u0647] (\u0627\u0644\u0633\u0631|\u0627\u0644\u0645\u0631\u0648\u0631)|\u0628\u0627\u0633\u0648+\u0631\u062f)["'']?\s*[:=]\s*("[^"]+"|''[^'']+''|["'']?[^\s"''][^\s]{3,})'
  ]),false);
$$;

ALTER FUNCTION public.secret_like(t text) OWNER TO postgres;

--
-- Name: see_agent_failure(uuid, uuid, uuid, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.see_agent_failure(c uuid, conversation uuid DEFAULT NULL::uuid, channel uuid DEFAULT NULL::uuid, card bigint DEFAULT NULL::bigint) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare cleared integer;
begin
 if auth.uid() is null or num_nonnulls(conversation, channel, card) <> 1 then return 0; end if;
 insert into public.agent_reader_marks(company_id, person_id, agent_id, failure_seen_at)
  select c, auth.uid(), w.agent, now() from public.agent_work(c) w
  where w.failed_conversation is not distinct from conversation and w.failed_channel is not distinct from channel
   and w.failed_card is not distinct from card
  on conflict (person_id, agent_id) do update set failure_seen_at=excluded.failure_seen_at;
 get diagnostics cleared = row_count;
 return cleared;
end $$;

ALTER FUNCTION public.see_agent_failure(c uuid, conversation uuid, channel uuid, card bigint) OWNER TO postgres;

--
-- Name: send_conversation_message(uuid, uuid, uuid, text, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.send_conversation_message(conversation uuid, c uuid, agent uuid, message text, message_key uuid, run text) RETURNS boolean
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO ''
    AS $$
 select public.send_conversation_message(conversation,c,agent,message,message_key,run,null::uuid);
$$;

ALTER FUNCTION public.send_conversation_message(conversation uuid, c uuid, agent uuid, message text, message_key uuid, run text) OWNER TO postgres;

--
-- Name: send_conversation_message(uuid, uuid, uuid, text, uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.send_conversation_message(conversation uuid, c uuid, agent uuid, message text, message_key uuid, run text, started_on uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare existing public.conversations; chosen public.hermes_agents; held public.conversation_run_reservations; writer text; saved bigint;
begin
 if not public.conversation_can_write(c) then raise exception 'conversationNotAllowed' using errcode='42501'; end if;
 perform pg_advisory_xact_lock(hashtextextended('hermes_agents',0));
 select * into chosen from public.hermes_agents where id=agent and company_id=c;
 if not found then raise exception 'conversationNotFound' using errcode='P0002'; end if;
 select * into held from public.conversation_run_reservations r where r.conversation_id=conversation and r.send_key=message_key;
 if found and (held.abandoned_at is not null or started_on is null or held.connection_id<>started_on or held.profile is distinct from chosen.profile) then
  raise exception 'conversationSendAgain' using errcode='55000'; end if;
 insert into public.conversations(id,company_id,person_id,agent_id,agent_name) values(conversation,c,auth.uid(),agent,chosen.name) on conflict (id) do nothing;
 select * into existing from public.conversations where id=conversation;
 if existing.person_id<>auth.uid() or existing.company_id<>c or existing.agent_id is distinct from agent then raise exception 'conversationNotFound' using errcode='P0002'; end if;
 -- A Member cannot register a run that belongs to another conversation: each copy would be closed again and its
 -- engine usage counted twice. The lock keeps two calls at once from both passing. A retry in the same conversation
 -- stays idempotent.
 perform pg_advisory_xact_lock(hashtextextended('conversation_run:'||coalesce(run,''),0));
 if exists(select 1 from public.conversation_messages where author='person' and run_id=run and conversation_id<>conversation) then raise exception 'conversationNotFound' using errcode='P0002'; end if;
 select name into writer from public.people where id=auth.uid();
 insert into public.conversation_messages(company_id,conversation_id,author,person_id,author_name,body,send_key,run_id)
  values(c,conversation,'person',auth.uid(),coalesce(writer,''),message,message_key,run) on conflict do nothing returning id into saved;
 delete from public.conversation_run_reservations where conversation_id=conversation and send_key=message_key;
 return saved is not null;
end;
$$;

ALTER FUNCTION public.send_conversation_message(conversation uuid, c uuid, agent uuid, message text, message_key uuid, run text, started_on uuid) OWNER TO postgres;

--
-- Name: set_agent_learning_mode(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.set_agent_learning_mode(agent uuid, mode text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare c uuid;
begin
 if mode is not null and mode not in ('auto','ask') then raise exception 'learningModeInvalid' using errcode='22023'; end if;
 select a.company_id into c from public.hermes_agents a where a.id=set_agent_learning_mode.agent;
 if c is null then raise exception 'settingAgentUnknown' using errcode='P0002'; end if;
 if not public.is_company_owner(c) then raise exception 'settingNotAllowed' using errcode='42501'; end if;
 update public.agent_profiles p set learning_mode_choice=set_agent_learning_mode.mode where p.agent_id=set_agent_learning_mode.agent and p.company_id=c;
 if found then return; end if;
 update public.company_profiles p set learning_mode_choice=set_agent_learning_mode.mode where p.company_id=c and public.keeps_profile_alone(c,set_agent_learning_mode.agent);
 if not found then raise exception 'settingAgentShared' using errcode='42501'; end if;
end $$;

ALTER FUNCTION public.set_agent_learning_mode(agent uuid, mode text) OWNER TO postgres;

--
-- Name: set_agent_model(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.set_agent_model(agent uuid, model text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare c uuid;
begin
 if model is not null and model !~ '^[a-z0-9][a-z0-9._-]{0,63}/[^[:space:]/][^[:space:]]{0,199}$' then
  raise exception 'settingInvalid' using errcode='22023'; end if;
 select a.company_id into c from public.hermes_agents a where a.id=set_agent_model.agent;
 if c is null then raise exception 'settingAgentUnknown' using errcode='P0002'; end if;
 if not public.is_company_owner(c) then raise exception 'settingNotAllowed' using errcode='42501'; end if;
 update public.agent_profiles p set model_choice=set_agent_model.model where p.agent_id=set_agent_model.agent and p.company_id=c;
 if found then return; end if;
 update public.company_profiles p set model_choice=set_agent_model.model where p.company_id=c and public.keeps_profile_alone(c,set_agent_model.agent);
 if not found then raise exception 'settingAgentShared' using errcode='42501'; end if;
end $_$;

ALTER FUNCTION public.set_agent_model(agent uuid, model text) OWNER TO postgres;

--
-- Name: set_agent_subagents(uuid, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.set_agent_subagents(agent uuid, enabled boolean) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare c uuid;
begin
 if enabled is null then raise exception 'settingInvalid' using errcode='22023'; end if;
 select a.company_id into c from public.hermes_agents a where a.id=set_agent_subagents.agent;
 if c is null then raise exception 'settingAgentUnknown' using errcode='P0002'; end if;
 if not public.is_company_owner(c) then raise exception 'settingNotAllowed' using errcode='42501'; end if;
 update public.agent_profiles p set subagents=set_agent_subagents.enabled,tools_pending=true where p.agent_id=set_agent_subagents.agent and p.company_id=c;
 if found then return; end if;
 update public.company_profiles p set subagents=set_agent_subagents.enabled,tools_pending=true where p.company_id=c and public.keeps_profile_alone(c,set_agent_subagents.agent);
 if not found then raise exception 'settingAgentShared' using errcode='42501'; end if;
end $$;

ALTER FUNCTION public.set_agent_subagents(agent uuid, enabled boolean) OWNER TO postgres;

--
-- Name: set_agent_visible(uuid, uuid, uuid, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.set_agent_visible(c uuid, person uuid, agent uuid, visible boolean) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare chosen public.hermes_agents; target public.members;
begin
 if visible is null or not public.can_manage_company(c) then raise exception 'agentVisibilityNotAllowed' using errcode='42501'; end if;
 -- A Manager changes only the Agents they see themselves; one hidden from them is not found here either.
 select * into chosen from public.hermes_agents where id=agent and company_id=c and public.agent_visible_to(c,auth.uid(),agent);
 if not found then raise exception 'agentNotFound' using errcode='P0002'; end if;
 if chosen.is_default then raise exception 'mainAgentShownToAll' using errcode='42501'; end if;
 select * into target from public.members where company_id=c and person_id=person and removed_at is null;
 if not found then raise exception 'memberNotFound' using errcode='P0002'; end if;
 if target.role='owner' then raise exception 'ownerSeesEveryAgent' using errcode='42501'; end if;
 if visible then insert into public.member_agent_access(company_id,person_id,agent_id) values(c,person,agent) on conflict do nothing;
 else delete from public.member_agent_access where company_id=c and person_id=person and agent_id=agent;
 end if;
end;
$$;

ALTER FUNCTION public.set_agent_visible(c uuid, person uuid, agent uuid, visible boolean) OWNER TO postgres;

--
-- Name: set_channel_agent(uuid, uuid, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.set_channel_agent(ch uuid, agent uuid, present boolean) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare k public.channels;
begin
 select * into k from public.channels where id=ch;
 if k.id is null or not public.in_channel(ch) then raise exception 'channelNotFound' using errcode='P0002'; end if;
 if not public.can_manage_company(k.company_id) or k.kind<>'team' then raise exception 'channelNotAllowed' using errcode='42501'; end if;
 if present is null or agent is null then raise exception 'channelFailed' using errcode='22023'; end if;
 if not present then delete from public.channel_agents where channel_id=ch and agent_id=agent; return; end if;
 if not exists(select 1 from public.hermes_agents h where h.company_id=k.company_id and h.id=agent) or not public.agent_visible_to(k.company_id, auth.uid(), agent) then
  raise exception 'agentNotFound' using errcode='P0002'; end if;
 insert into public.channel_agents(channel_id, company_id, agent_id, added_by) values (ch, k.company_id, agent, auth.uid())
  on conflict (channel_id, agent_id) do nothing;
end $$;

ALTER FUNCTION public.set_channel_agent(ch uuid, agent uuid, present boolean) OWNER TO postgres;

--
-- Name: set_channel_invitee(uuid, uuid, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.set_channel_invitee(ch uuid, invitation uuid, present boolean) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare k public.channels; open_invite public.member_invitations;
begin
 select * into k from public.channels where id=ch;
 if k.id is null or not public.in_channel(ch) then raise exception 'channelNotFound' using errcode='P0002'; end if;
 if not public.can_manage_company(k.company_id) or k.kind<>'team' then raise exception 'channelNotAllowed' using errcode='42501'; end if;
 if present is null or invitation is null then raise exception 'channelFailed' using errcode='22023'; end if;
 if not present then delete from public.channel_invitees where channel_id=ch and invitation_id=invitation; return; end if;
 select * into open_invite from public.member_invitations v
  where v.id=invitation and v.company_id=k.company_id and v.claimed_at is null and v.ended_at is null for share;
 if open_invite.id is null then raise exception 'memberNotFound' using errcode='P0002'; end if;
 insert into public.channel_invitees(channel_id, company_id, invitation_id, added_by) values (ch, k.company_id, invitation, auth.uid())
  on conflict (channel_id, invitation_id) do nothing;
end $$;

ALTER FUNCTION public.set_channel_invitee(ch uuid, invitation uuid, present boolean) OWNER TO postgres;

--
-- Name: set_channel_person(uuid, uuid, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.set_channel_person(ch uuid, person uuid, present boolean) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare k public.channels;
begin
 select * into k from public.channels where id=ch;
 if k.id is null or not public.in_channel(ch) then raise exception 'channelNotFound' using errcode='P0002'; end if;
 if not public.can_manage_company(k.company_id) or k.kind<>'team' or person=auth.uid() then raise exception 'channelNotAllowed' using errcode='42501'; end if;
 if k.archived_at is not null then raise exception 'channelArchived' using errcode='42501'; end if;
 if present is null or person is null then raise exception 'channelFailed' using errcode='22023'; end if;
 if not present then delete from public.channel_people where channel_id=ch and person_id=person; return; end if;
 if not public.channel_person(k.company_id, person) then raise exception 'memberNotFound' using errcode='P0002'; end if;
 insert into public.channel_people(channel_id, company_id, person_id, joined_through, added_by)
  values (ch, k.company_id, person, coalesce((select max(id) from public.channel_messages where channel_id=ch),0), auth.uid())
  on conflict (channel_id, person_id) do nothing;
end $$;

ALTER FUNCTION public.set_channel_person(ch uuid, person uuid, present boolean) OWNER TO postgres;

--
-- Name: set_company_fallback_model(uuid, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.set_company_fallback_model(c uuid, fallback_provider text, fallback_model text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
begin
 if not public.is_company_owner(c) then raise exception 'fallbackNotAllowed' using errcode='42501'; end if;
 if fallback_provider is null and fallback_model is null then
  delete from public.company_fallback_models where company_id=c;
  return null;
 end if;
 if coalesce(fallback_provider,'') !~ '^[a-z0-9][a-z0-9._-]{0,63}$' or coalesce(fallback_model,'') !~ '^[^\s/][^\s]{0,199}$' then
  raise exception 'fallbackInvalid' using errcode='22023';
 end if;
 insert into public.company_fallback_models(company_id,provider,model,changed_by) values (c,fallback_provider,fallback_model,auth.uid())
  on conflict (company_id) do update set provider=excluded.provider,model=excluded.model,changed_by=excluded.changed_by,changed_at=now();
 return fallback_provider||'/'||fallback_model;
end $_$;

ALTER FUNCTION public.set_company_fallback_model(c uuid, fallback_provider text, fallback_model text) OWNER TO postgres;

--
-- Name: set_conversation_model(uuid, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.set_conversation_model(c uuid, conversation uuid, choice jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare talk public.conversations;
begin
 select * into talk from public.conversations cv where cv.id=conversation and cv.company_id=c and cv.person_id=auth.uid() and public.is_member(c) for update;
 if not found then raise exception 'conversationNotFound' using errcode='P0002'; end if;
 if not public.is_company_owner(c) then raise exception 'conversationNotAllowed' using errcode='42501'; end if;
 if jsonb_typeof(choice)='null' then choice:=null; end if;
 if not public.model_choice_valid(choice) then raise exception 'conversationModelInvalid' using errcode='22023'; end if;
 if talk.model is distinct from choice then
  update public.conversations set model_before=talk.model, model=choice where id=conversation;
 end if;
 return choice;
end $$;

ALTER FUNCTION public.set_conversation_model(c uuid, conversation uuid, choice jsonb) OWNER TO postgres;

--
-- Name: set_invitation_agent_visible(uuid, uuid, uuid, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.set_invitation_agent_visible(c uuid, invitation uuid, agent uuid, visible boolean) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare chosen public.hermes_agents; target public.member_invitations;
begin
 if visible is null or not public.can_manage_company(c) then raise exception 'agentVisibilityNotAllowed' using errcode='42501'; end if;
 select * into chosen from public.hermes_agents where id=agent and company_id=c and public.agent_visible_to(c,auth.uid(),agent);
 if not found then raise exception 'agentNotFound' using errcode='P0002'; end if;
 if chosen.is_default then raise exception 'mainAgentShownToAll' using errcode='42501'; end if;
 select * into target from public.member_invitations where id=invitation and company_id=c and claimed_at is null for update;
 if not found then raise exception 'invitationNotFound' using errcode='P0002'; end if;
 if target.role='owner' then raise exception 'ownerSeesEveryAgent' using errcode='42501'; end if;
 if visible then insert into public.invitation_agent_access(company_id,invitation_id,agent_id) values(c,invitation,agent) on conflict do nothing;
 else delete from public.invitation_agent_access where invitation_id=invitation and agent_id=agent;
 end if;
end;
$$;

ALTER FUNCTION public.set_invitation_agent_visible(c uuid, invitation uuid, agent uuid, visible boolean) OWNER TO postgres;

