--
-- Name: settle_channel_permission(bigint, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.settle_channel_permission(card bigint, verdict text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare asked public.channel_permissions;
begin
 if verdict is null or verdict not in ('decided','closed') then raise exception 'permissionVerdictInvalid' using errcode='22023'; end if;
 select * into asked from public.channel_permissions where id=card for update;
 if not found then return null; end if;
 if not (asked.state='sending' or verdict='decided' and asked.state='closed' and asked.content ? 'choice') then return asked.state; end if;
 update public.channel_permissions set state=verdict where id=asked.id;
 if verdict='decided' then
  insert into public.company_log(company_id,actor_id,actor_kind,actor_name,subject,agent_id,action,details,source,source_id,created_at)
   values(asked.company_id,asked.decided_by,'person',(select name from public.people where id=asked.decided_by),'agent',
    (select r.agent_id from public.channel_runs r where r.run_id=asked.run_id),'agent_permission_decided',
    jsonb_build_object('permission',jsonb_build_object('text',case when btrim(asked.content->>'description',E' \t\r\n')<>'' then asked.content->'description' else asked.content->'command' end,
     'choice',asked.content->'choice'),'private',true,'teller',asked.decided_by),
    'channel_permissions',asked.id,asked.decided_at)
   on conflict (source,source_id) do nothing;
 end if;
 return verdict;
end $$;

ALTER FUNCTION public.settle_channel_permission(card bigint, verdict text) OWNER TO postgres;

--
-- Name: settle_channel_question(bigint, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.settle_channel_question(card bigint, verdict text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare asked public.reply_cards; called public.channel_runs;
begin
 if verdict is null or verdict not in ('answered','closed') then raise exception 'questionVerdictInvalid' using errcode='22023'; end if;
 select * into asked from public.reply_cards where id=card and kind='question' and channel_message_id is not null for update;
 if not found then return null; end if;
 if not (asked.state='sending' or verdict='answered' and asked.state='closed' and asked.content ? 'answer') then return asked.state; end if;
 update public.reply_cards set state=verdict where id=asked.id;
 if verdict='answered' then
  select * into called from public.channel_runs
   where message_id=asked.channel_message_id and ordinal=coalesce(asked.channel_ordinal,1);
  insert into public.company_log(company_id,actor_id,actor_kind,actor_name,subject,agent_id,action,details,source,source_id,created_at)
   values(asked.company_id,asked.answered_by,'person',(select name from public.people where id=asked.answered_by),'agent',called.agent_id,
    'agent_question_answered',
    jsonb_build_object('question',jsonb_build_object('text',asked.content->'question','answer',asked.content->'answer'),
     'private',true,'teller',asked.answered_by),
    'reply_card_answers',asked.id,asked.answered_at)
   on conflict (source,source_id) do nothing;
 end if;
 return verdict;
end $$;

ALTER FUNCTION public.settle_channel_question(card bigint, verdict text) OWNER TO postgres;

