--
-- Name: settle_provider_key_holds(uuid, text[], bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.settle_provider_key_holds(c uuid, held text[], seen bigint DEFAULT NULL::bigint) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare since timestamptz:=now()-interval '10 minutes';
begin
 if held is null then raise exception 'keyInvalid' using errcode='22023'; end if;
 -- A read taken before a change began or ended in another process says nothing about that change. Checked and applied
 -- under the lock begin and finish take, so no change ends between the check and the update.
 if settle_provider_key_holds.seen is not null then perform pg_advisory_xact_lock(hashtextextended('hermes_agents',0)); end if;
 if settle_provider_key_holds.seen is not null and exists(select 1 from public.company_key_holds k where k.company_id=c and k.version>settle_provider_key_holds.seen) then return; end if;
 -- Each row's new values are computed once, from the row as read; a row another change wrote meanwhile is a newer row
 -- (ctid), left as that change wrote it for the next read. A row left as it was is not written, and no lock is taken, so
 -- a page read queues behind no other Company's Agents or key changes.
 update public.company_key_holds h set held=n.held,changing=false,uncertain=n.uncertain
  from (select k.ctid as row_at,coalesce(k.provider=any(settle_provider_key_holds.held),false) as held,
    k.uncertain and coalesce(k.changed_at>since,false) and not coalesce(k.provider=any(settle_provider_key_holds.held),false) as uncertain
   from public.company_key_holds k where k.company_id=c and not (k.changing and coalesce(k.changed_at>since,false))) n
  where h.ctid=n.row_at and (h.held,h.changing,h.uncertain) is distinct from (n.held,false,n.uncertain);
 insert into public.company_key_holds(company_id,provider,held,changing)
  select c,p,true,false from unnest(settle_provider_key_holds.held) p where p ~ '^[a-z0-9][a-z0-9._-]{0,63}$'
  on conflict (company_id,provider) do nothing;
 if not public.company_holds_provider_key(c) then
  -- lead_create_agent's lock, so no Agent is made waiting meanwhile; a change begun before it was taken is seen here.
  perform pg_advisory_xact_lock(hashtextextended('hermes_agents',0));
  delete from public.agent_key_waits w where w.company_id=c and not public.company_holds_provider_key(c);
 end if;
end $_$;

ALTER FUNCTION public.settle_provider_key_holds(c uuid, held text[], seen bigint) OWNER TO postgres;

--
-- Name: settle_question(bigint, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.settle_question(card bigint, verdict text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare asked public.reply_cards;
begin
 if verdict is null or verdict not in ('answered','closed') then raise exception 'questionVerdictInvalid' using errcode='22023'; end if;
 select * into asked from public.reply_cards where id=card and kind='question' for update;
 if not found then return null; end if;
 -- Not only the first verdict counts any more (20270112's rule): a delivery the Engine took wins over a "gone" another
 -- closer settled first, or over the Run's end closing the card before its closer settled it. The answer did reach the
 -- Engine, so the card reads answered and is logged once. A closed verdict never undoes an answered one.
 if not (asked.state='sending' or verdict='answered' and asked.state='closed' and asked.content ? 'answer') then return asked.state; end if;
 update public.reply_cards set state=verdict where id=asked.id;
 if verdict='answered' then
  perform public.log_chat_event(asked.conversation_id,asked.answered_by,'person',(select name from public.people where id=asked.answered_by),'agent_question_answered',
   jsonb_build_object('question',jsonb_build_object('text',asked.content->'question','answer',asked.content->'answer')),
   asked.answered_by,'reply_card_answers',asked.id,asked.answered_at);
 end if;
 return verdict;
end $$;

ALTER FUNCTION public.settle_question(card bigint, verdict text) OWNER TO postgres;

