--
-- Name: stop_card_work(uuid, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.stop_card_work(c uuid, card bigint) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare w public.work_cards;
begin
 select * into w from public.work_cards x where x.company_id=c and x.id=card;
 if w.conversation_id is not null then perform public.stop_conversation_work(w.conversation_id); end if;
 if w.channel_id is not null then perform public.stop_channel_work(c,w.channel_id); end if;
 update public.note_runs n set outcome='stopped', closed_at=now()
  where n.company_id=c and n.card_id=card and n.outcome is null and n.run_id is null and n.attempts=0;
 update public.note_runs n set stop_at_start=now()
  where n.company_id=c and n.card_id=card and n.outcome is null and n.run_id is null and n.attempts>0;
 insert into public.stopped_runs(company_id,note_id,run_id)
  select n.company_id,n.note_id,n.run_id from public.note_runs n where n.company_id=c and n.card_id=card and n.outcome is null and n.run_id is not null
  on conflict do nothing;
 update public.waiting_items i set resolved_at=now() where i.company_id=c and i.card_id=card and i.resolved_at is null;
end $$;

ALTER FUNCTION public.stop_card_work(c uuid, card bigint) OWNER TO postgres;

--
-- Name: stop_channel_message(uuid, uuid, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.stop_channel_message(c uuid, ch uuid, message bigint) RETURNS TABLE(run text, profile text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare m public.channel_messages;
begin
 if auth.uid() is null or not public.conversation_can_write(c) then raise exception 'channelNotAllowed' using errcode='42501'; end if;
 select * into m from public.channel_messages x where x.id=stop_channel_message.message;
 if m.id is null or m.company_id<>c or m.channel_id<>ch or m.author<>'person' or not public.in_channel(ch) then
  raise exception 'channelNotFound' using errcode='P0002'; end if;
 if m.person_id is distinct from auth.uid() and not public.can_manage_company(c) then raise exception 'channelNotAllowed' using errcode='42501'; end if;
 return query
  with unstarted as (
   update public.channel_runs r set outcome='stopped', closed_at=now()
    where r.message_id=m.id and r.outcome is null and r.run_id is null and r.attempts=0
    returning r.ordinal)
  select null::text, null::text from unstarted;
 return query select r.run_id, r.profile from public.channel_runs r where r.message_id=m.id and r.outcome is null and r.run_id is not null order by r.ordinal;
 return query select s.run, s.profile from public.stop_open_handovers(null,m.id) s;
end $$;

ALTER FUNCTION public.stop_channel_message(c uuid, ch uuid, message bigint) OWNER TO postgres;

--
-- Name: stop_channel_work(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.stop_channel_work(c uuid, channel uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare m bigint;
begin
 for m in select x.id from public.channel_messages x where x.channel_id=stop_channel_work.channel and x.company_id=c
  and (exists(select 1 from public.channel_runs r where r.message_id=x.id and r.outcome is null)
   or exists(select 1 from public.agent_handovers h where h.channel_message_id=x.id and h.state not in ('done','failed')))
  order by x.id loop
  update public.channel_runs r set outcome='stopped', closed_at=now() where r.message_id=m and r.outcome is null and r.run_id is null and r.attempts=0;
  update public.channel_runs r set stop_at_start=now() where r.message_id=m and r.outcome is null and r.run_id is null and r.attempts>0;
  perform public.stop_open_handovers(null,m);
 end loop;
 update public.reply_cards r set state='closed' from public.channel_messages x
  where x.id=r.channel_message_id and x.channel_id=stop_channel_work.channel and r.kind in ('question','hand') and r.state='open';
 update public.channel_permissions p set state='closed' where p.channel_id=stop_channel_work.channel and p.company_id=c and p.state in ('open','sending');
end $$;

ALTER FUNCTION public.stop_channel_work(c uuid, channel uuid) OWNER TO postgres;

--
-- Name: stop_conversation_handovers(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.stop_conversation_handovers(conversation uuid, c uuid) RETURNS TABLE(run text, profile text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare talk public.conversations;
begin
 select * into talk from public.conversations cv where cv.id=stop_conversation_handovers.conversation and cv.company_id=c;
 if auth.uid() is null or not public.is_member(c) or talk.id is null or not public.can_see_conversation_agent(c,talk.id) then
  raise exception 'conversationNotFound' using errcode='P0002'; end if;
 if not exists(select 1 from public.agent_handovers h where h.conversation_id=talk.id and h.state not in ('done','failed'))
  and not exists(select 1 from public.conversation_open_run(talk.id)) then return; end if;
 if talk.person_id is distinct from auth.uid() and not public.can_manage_company(c) then raise exception 'conversationStopNotAllowed' using errcode='42501'; end if;
 return query select s.run, s.profile from public.stop_open_handovers(talk.id,null) s;
end $$;

ALTER FUNCTION public.stop_conversation_handovers(conversation uuid, c uuid) OWNER TO postgres;

--
-- Name: stop_conversation_work(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.stop_conversation_work(conversation uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
 perform public.stop_open_handovers(conversation,null);
 with dropped as (
  update public.conversation_queued_turns q set failed_at=now()
   where q.conversation_id=stop_conversation_work.conversation and q.started_at is null and q.failed_at is null
    and not exists(select 1 from public.conversation_run_reservations r where r.conversation_id=q.conversation_id and r.send_key=q.send_key
     and r.abandoned_at is null and (r.start_unknown_at is not null or r.start_attempts>0))
   returning q.send_key)
 delete from public.conversation_run_reservations r using dropped d
  where r.conversation_id=stop_conversation_work.conversation and r.send_key=d.send_key and r.abandoned_at is null;
 update public.conversation_run_reservations r set stop_at_start=now()
  where r.conversation_id=stop_conversation_work.conversation and r.abandoned_at is null;
 update public.reply_cards r set state='closed'
  where r.conversation_id=stop_conversation_work.conversation and r.kind in ('question','permission','hand')
   and (r.state='open' or r.kind='permission' and r.state='sending');
end $$;

ALTER FUNCTION public.stop_conversation_work(conversation uuid) OWNER TO postgres;

--
-- Name: stop_late_handover_run(bigint, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.stop_late_handover_run(h bigint, run text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare kept bigint;
begin
 update public.agent_handovers x set stopping_run=coalesce(x.stopping_run,stop_late_handover_run.run),
  stopping_profile=coalesce(x.stopping_profile,(select a.profile from public.hermes_agents a
   where a.id=case when x.follow_up_outcome='stopped' then x.from_agent else x.to_agent end))
  where x.id=h and x.state='done' and (x.target_outcome='stopped' or x.follow_up_outcome='stopped') and coalesce(btrim(stop_late_handover_run.run),'')<>''
  returning x.id into kept;
 return kept is not null;
end $$;

ALTER FUNCTION public.stop_late_handover_run(h bigint, run text) OWNER TO postgres;

--
-- Name: channel_runs; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.channel_runs (
    message_id bigint NOT NULL,
    company_id uuid NOT NULL,
    channel_id uuid NOT NULL,
    agent_id uuid,
    agent_name text NOT NULL,
    session uuid NOT NULL,
    input text NOT NULL,
    instructions text,
    rules text[] DEFAULT '{}'::text[] NOT NULL,
    connection_id uuid,
    attempts integer DEFAULT 0 NOT NULL,
    attempted_at timestamp with time zone,
    run_id text,
    outcome text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    closed_at timestamp with time zone,
    profile text,
    tools text,
    ordinal smallint DEFAULT 1 NOT NULL,
    first_attempted_at timestamp with time zone,
    stop_at_start timestamp with time zone,
    kept_agent_id uuid,
    started boolean GENERATED ALWAYS AS ((run_id IS NOT NULL)) STORED,
    CONSTRAINT channel_runs_attempts_check CHECK ((attempts >= 0)),
    CONSTRAINT channel_runs_check CHECK (((run_id IS NULL) OR (attempts > 0))),
    CONSTRAINT channel_runs_check1 CHECK (((outcome IS NULL) = (closed_at IS NULL))),
    CONSTRAINT channel_runs_ordinal_check CHECK (((ordinal >= 1) AND (ordinal <= 3))),
    CONSTRAINT channel_runs_outcome_check CHECK ((outcome = ANY (ARRAY['completed'::text, 'failed'::text, 'no_model'::text, 'no_credit'::text, 'key_refused'::text, 'model_missing'::text, 'no_access'::text, 'stopped'::text, 'lost'::text])))
);

ALTER TABLE public.channel_runs OWNER TO postgres;

--
-- Name: stop_named_channel_run(public.channel_runs, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.stop_named_channel_run(r public.channel_runs, run text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
 if r.stop_at_start is not null or exists(select 1 from public.channels k where k.id=r.channel_id and k.archived_at is not null)
  or exists(select 1 from public.work_cards w where w.company_id=r.company_id and w.channel_id=r.channel_id and w.archived_at>=r.created_at) then
  insert into public.stopped_runs(company_id,channel_message_id,run_id) values(r.company_id,r.message_id,run) on conflict do nothing;
 end if;
end $$;

ALTER FUNCTION public.stop_named_channel_run(r public.channel_runs, run text) OWNER TO postgres;

--
-- Name: stop_open_handovers(uuid, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.stop_open_handovers(conversation uuid, message bigint) RETURNS TABLE(handover bigint, run text, profile text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare chain bigint[]; unsure bigint[];
begin
 -- The place's lock first: a Handover being kept there now is committed before the statements below read the chain.
 if stop_open_handovers.conversation is not null then
  perform 1 from public.conversations c where c.id=stop_open_handovers.conversation for no key update;
  insert into public.stopped_runs(company_id,conversation_id,run_id)
   select c.company_id,c.id,m.run_id from public.conversation_messages m join public.conversations c on c.id=m.conversation_id
   where m.conversation_id=stop_open_handovers.conversation and m.author='person'
    and not exists(select 1 from public.conversation_messages r where r.conversation_id=m.conversation_id and r.author='agent' and r.run_id=m.run_id)
    and not exists(select 1 from public.conversation_run_ends u where u.conversation_id=m.conversation_id and u.run_id=m.run_id)
   on conflict do nothing;
 else
  perform 1 from public.channel_messages x where x.id=stop_open_handovers.message for no key update;
  insert into public.stopped_runs(company_id,channel_message_id,run_id)
   select r.company_id,r.message_id,r.run_id from public.channel_runs r
   where r.message_id=stop_open_handovers.message and r.outcome is null and r.run_id is not null
   on conflict do nothing;
 end if;
 -- The chain's rows next, so a start's answer landing now is either in before they are read, or waits for Stop
 -- (answer_handover locks its row), and every leg is judged as it is.
 perform 1 from public.agent_handovers h
 where h.state not in ('done','failed')
  and ((stop_open_handovers.conversation is not null and h.conversation_id=stop_open_handovers.conversation)
   or (stop_open_handovers.message is not null and h.channel_message_id=stop_open_handovers.message))
 for update;
 select coalesce(array_agg(h.id) filter (where not public.handover_start_unsure(h)),'{}'),
  coalesce(array_agg(h.id) filter (where public.handover_start_unsure(h)),'{}')
  into chain, unsure
 from public.agent_handovers h
 where h.state not in ('done','failed')
  and ((stop_open_handovers.conversation is not null and h.conversation_id=stop_open_handovers.conversation)
   or (stop_open_handovers.message is not null and h.channel_message_id=stop_open_handovers.message));
 update public.agent_handovers h set stop_requested_at=coalesce(h.stop_requested_at,now()) where h.id=any(unsure);
 return query select e.handover, e.run, e.profile from public.end_handovers_stopped(chain) e;
 return query select u, null::text, null::text from unnest(unsure) u;
end $$;

ALTER FUNCTION public.stop_open_handovers(conversation uuid, message bigint) OWNER TO postgres;

--
-- Name: stopped_runs_open(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.stopped_runs_open() RETURNS TABLE(run text, profile text, company uuid)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
 select s.run_id, r.profile, s.company_id from public.stopped_runs s
  join public.channel_runs r on r.message_id=s.channel_message_id and r.run_id=s.run_id and r.outcome is null
 union all
 select s.run_id, a.profile, s.company_id from public.stopped_runs s
  join public.conversations c on c.id=s.conversation_id
  join public.hermes_agents a on a.id=c.agent_id and a.company_id=c.company_id
 where not exists(select 1 from public.conversation_run_ends u where u.conversation_id=s.conversation_id and u.run_id=s.run_id)
  and not exists(select 1 from public.conversation_messages m where m.conversation_id=s.conversation_id and m.author='agent' and m.run_id=s.run_id)
  and s.stopped_at > now()-interval '1 day'
 union all
 select s.run_id, r.profile, s.company_id from public.stopped_runs s
  join public.note_runs r on r.note_id=s.note_id and r.run_id=s.run_id and r.outcome is null;
$$;

ALTER FUNCTION public.stopped_runs_open() OWNER TO postgres;

--
-- Name: switch_provider(uuid, text, text, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.switch_provider(c uuid, provider text, account text, turned_on boolean) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
begin
 if not public.is_company_owner(c) then raise exception 'providerNotAllowed' using errcode='42501'; end if;
 if turned_on is null or coalesce(provider,'') !~ '^[a-z0-9][a-z0-9._-]{0,63}$' or coalesce(account,'') !~ '^[A-Za-z0-9_-]{1,64}$' then
  raise exception 'providerOrderInvalid' using errcode='22023';
 end if;
 insert into public.provider_order(company_id,provider,account,enabled,changed_by)
  values (c,switch_provider.provider,switch_provider.account,turned_on,auth.uid())
  on conflict on constraint provider_order_pkey do update set enabled=excluded.enabled,changed_by=excluded.changed_by,changed_at=now();
 return turned_on;
end $_$;

ALTER FUNCTION public.switch_provider(c uuid, provider text, account text, turned_on boolean) OWNER TO postgres;

--
-- Name: take_morning_lease(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.take_morning_lease(c uuid, holder uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
 if not public.can_manage_company(c) then raise exception 'agentSettingNotAllowed' using errcode='42501'; end if;
 insert into public.agent_morning_leases(company_id,holder,until) values(c,holder,now()+interval '60 seconds')
  on conflict (company_id) do update set holder=excluded.holder,until=excluded.until
  where public.agent_morning_leases.until<now() or public.agent_morning_leases.holder=excluded.holder;
 return exists(select 1 from public.agent_morning_leases l where l.company_id=c and l.holder=take_morning_lease.holder);
end $$;

ALTER FUNCTION public.take_morning_lease(c uuid, holder uuid) OWNER TO postgres;

--
-- Name: track_channel_permission(bigint, text, jsonb, boolean, timestamp with time zone, timestamp with time zone, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.track_channel_permission(message bigint, run text, asking jsonb, ended boolean, read_started_at timestamp with time zone, read_ended_at timestamp with time zone DEFAULT NULL::timestamp with time zone, run_profile text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare called public.channel_runs; asked text:=asking->>'id'; own boolean; kept jsonb; named text; handed jsonb; keeps text[]; words text:=public.words_of(asking);
begin
 perform pg_advisory_xact_lock(hashtextextended('channel_permission:'||message::text,0));
 select * into called from public.channel_runs where message_id=message and run_id=run;
 if not found then return '[]'::jsonb; end if;
 update public.channel_permissions p set state='closed' where p.message_id=message and p.run_id=run
  and ((ended or called.outcome is not null) and p.state in ('open','sending') or p.state='open' and p.request_id is distinct from asked and p.created_at<read_started_at);
 if asked is not null and not ended and called.outcome is null
  and not exists(select 1 from public.stopped_runs s where s.channel_message_id=message and s.run_id=run) then
  own:=coalesce(run_profile=public.agent_engine_profile(called.agent_id),false);
  kept:=jsonb_build_object('description',asking->'description','command',asking->'command','choices',
   case when jsonb_typeof(asking->'choices')='array' then coalesce((select jsonb_agg(o order by n) from jsonb_array_elements(asking->'choices') with ordinality x(o,n)
    where own or o<>'"always"'::jsonb),'[]'::jsonb) else asking->'choices' end);
  if length(asked) between 1 and 200 and public.reply_card_valid('permission','open',kept) then
   keeps:=public.permission_allows_of(asking,kept);
   if not public.permission_allows_valid(keeps) then keeps:=null; end if;
   named:=btrim(case when btrim(kept->>'description',E' \t\r\n')<>'' then kept->>'description' else kept->>'command' end,E' \t\r\n');
   insert into public.channel_permissions(company_id,channel_id,message_id,run_id,ordinal,request_id,title,content,state,created_at,allows,said_before)
    values(called.company_id,called.channel_id,message,run,called.ordinal,asked,
     case when length(named)<=100 then named else rtrim(left(named,99),E' \t\r\n')||'…' end,kept,'open',greatest(read_started_at,coalesce(read_ended_at,read_started_at)),keeps,
     case when not public.channel_run_said(message,run,words) then words end)
    on conflict do nothing;
   update public.channel_permissions p set said_before=words where p.message_id=message and p.run_id=run and p.request_id=asked and p.said_before is null
    and not public.channel_run_said(message,run,words);
  end if;
 end if;
 -- One closer at a time, as in a Conversation.
 with given as (
  update public.channel_permissions p set delivering_at=now()
   where p.message_id=message and p.run_id=run and p.state='sending'
    and not exists(select 1 from public.stopped_runs s where s.channel_message_id=message and s.run_id=run)
    and (p.delivering_at is null or p.delivering_at<now()-interval '15 seconds')
    and not (p.content->>'choice'='always' and public.permission_revoke_held(called.agent_id))
   returning p.id,p.request_id,p.content)
 select jsonb_agg(jsonb_build_object('card',g.id,'permission',g.request_id,'choice',g.content->'choice') order by g.id) into handed from given g;
 return coalesce(handed,'[]'::jsonb);
end $$;

ALTER FUNCTION public.track_channel_permission(message bigint, run text, asking jsonb, ended boolean, read_started_at timestamp with time zone, read_ended_at timestamp with time zone, run_profile text) OWNER TO postgres;

--
-- Name: track_channel_question(bigint, text, jsonb, boolean, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.track_channel_question(message bigint, run text, asking jsonb, ended boolean, read_started_at timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare called public.channel_runs; m public.channel_messages; asked text:=asking->>'id'; kept jsonb; main boolean; words text:=public.words_of(asking);
begin
 perform pg_advisory_xact_lock(hashtextextended('channel_question:'||message::text||':'||coalesce(run,''),0));
 select * into called from public.channel_runs where message_id=message and run_id=run;
 if not found then return '[]'::jsonb; end if;
 select * into m from public.channel_messages where id=message;
 if m.id is null or m.author<>'person' then return '[]'::jsonb; end if;
 update public.reply_cards r set state='closed' where r.channel_message_id=message and r.run_id=run and r.kind='question'
  and r.state='open' and (ended or (r.call_id is distinct from asked and r.created_at<read_started_at));
 if asked is not null and not ended and called.outcome is null
  and not exists(select 1 from public.stopped_runs s where s.channel_message_id=message and s.run_id=run) then
  kept:=jsonb_build_object('question',asking->'text','choices',asking->'choices','multiple',asking->'multiple');
  if length(asked) between 1 and 200 and public.reply_card_valid('question','open',kept) then
   main:=coalesce((select a.is_default from public.hermes_agents a where a.id=called.agent_id),false);
   insert into public.reply_cards(company_id,channel_message_id,channel_ordinal,run_id,call_id,kind,title,content,state,created_at,addressed_to,said_before)
    values(called.company_id,message,called.ordinal,run,asked,'question',
     case when length(kept->>'question')<=100 then kept->>'question' else rtrim(left(kept->>'question',99),E' \t\r\n')||'…' end,
     kept,'open',read_started_at,case when main then m.person_id end,
     case when not public.channel_run_said(message,run,words) then words end)
    on conflict do nothing;
   update public.reply_cards r set said_before=words where r.channel_message_id=message and r.run_id=run and r.kind='question' and r.call_id=asked and r.said_before is null
    and not public.channel_run_said(message,run,words);
  end if;
 end if;
 return coalesce((select jsonb_agg(jsonb_build_object('card',r.id,'question',r.call_id,'answer',r.content->'answer') order by r.id)
  from public.reply_cards r where r.channel_message_id=message and r.run_id=run and r.kind='question' and r.state='sending'),'[]'::jsonb);
end $$;

ALTER FUNCTION public.track_channel_question(message bigint, run text, asking jsonb, ended boolean, read_started_at timestamp with time zone) OWNER TO postgres;

--
-- Name: track_run_permission(uuid, text, jsonb, boolean, timestamp with time zone, timestamp with time zone, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.track_run_permission(conversation uuid, run text, asking jsonb, ended boolean, read_started_at timestamp with time zone, read_ended_at timestamp with time zone DEFAULT NULL::timestamp with time zone, run_profile text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare talk public.conversations; asked text:=asking->>'id'; own boolean; kept jsonb; named text; handed jsonb; keeps text[]; words text:=public.words_of(asking);
begin
 -- The lock a Run's end takes (close_ended_run_permissions), so a request is never kept after its Run has ended.
 perform pg_advisory_xact_lock(hashtextextended('permission_run:'||conversation::text||':'||run,0));
 select * into talk from public.conversations where id=conversation;
 if not found or not exists(select 1 from public.conversation_messages m where m.conversation_id=conversation and m.author='person' and m.run_id=run) then return '[]'::jsonb; end if;
 update public.reply_cards r set state='closed' where r.conversation_id=conversation and r.kind='permission'
  and (r.run_id=run and (ended and r.state in ('open','sending') or r.state='open' and r.call_id is distinct from asked and r.created_at<read_started_at)
   or r.state in ('open','sending') and r.run_id<>run and exists(select 1 from public.conversation_run_ends u where u.conversation_id=conversation and u.run_id=r.run_id));
 if asked is not null and not ended and not exists(select 1 from public.conversation_run_ends u where u.conversation_id=conversation and u.run_id=run)
  and not exists(select 1 from public.stopped_runs s where s.conversation_id=conversation and s.run_id=run) then
  own:=coalesce(run_profile=public.agent_engine_profile(talk.agent_id),false);
  kept:=jsonb_build_object('description',asking->'description','command',asking->'command','choices',
   case when jsonb_typeof(asking->'choices')='array' then coalesce((select jsonb_agg(o order by n) from jsonb_array_elements(asking->'choices') with ordinality x(o,n)
    where own or o<>'"always"'::jsonb),'[]'::jsonb) else asking->'choices' end);
  if length(asked) between 1 and 200 and public.reply_card_valid('permission','open',kept) then
   keeps:=public.permission_allows_of(asking,kept);
   if not public.permission_allows_valid(keeps) then keeps:=null; end if;
   named:=btrim(case when btrim(kept->>'description',E' \t\r\n')<>'' then kept->>'description' else kept->>'command' end,E' \t\r\n');
   insert into public.reply_cards(company_id,conversation_id,run_id,call_id,kind,title,content,state,created_at,allows,said_before)
    values(talk.company_id,conversation,run,asked,'permission',
     case when length(named)<=100 then named else rtrim(left(named,99),E' \t\r\n')||'…' end,kept,'open',greatest(read_started_at,coalesce(read_ended_at,read_started_at)),keeps,
     case when not public.conversation_run_said(conversation,run,words) then words end)
    on conflict do nothing;
   update public.reply_cards r set said_before=words where r.conversation_id=conversation and r.run_id=run and r.kind='permission' and r.call_id=asked and r.said_before is null
    and not public.conversation_run_said(conversation,run,words);
  end if;
 end if;
 -- Each claimed choice is handed to this closer alone, for 15 seconds (a choice's call to the Engine gives up after 10):
 -- another closer's read meanwhile gets nothing to deliver, so the Engine is asked once; a closer that died or could not
 -- reach the Engine leaves it to the first read after that.
 with given as (
  update public.reply_cards r set delivering_at=now()
   where r.conversation_id=conversation and r.run_id=run and r.kind='permission' and r.state='sending'
    and not exists(select 1 from public.stopped_runs s where s.conversation_id=conversation and s.run_id=run)
    and (r.delivering_at is null or r.delivering_at<now()-interval '15 seconds')
    and not (r.content->>'choice'='always' and public.permission_revoke_held(talk.agent_id))
   returning r.id,r.call_id,r.content)
 select jsonb_agg(jsonb_build_object('card',g.id,'permission',g.call_id,'choice',g.content->'choice') order by g.id) into handed from given g;
 return coalesce(handed,'[]'::jsonb);
end $$;

ALTER FUNCTION public.track_run_permission(conversation uuid, run text, asking jsonb, ended boolean, read_started_at timestamp with time zone, read_ended_at timestamp with time zone, run_profile text) OWNER TO postgres;

--
-- Name: track_run_question(uuid, text, jsonb, boolean, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.track_run_question(conversation uuid, run text, asking jsonb, ended boolean, read_started_at timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare talk public.conversations; asked text:=asking->>'id'; kept jsonb; handed jsonb; words text:=public.words_of(asking);
begin
 -- The lock a Run's end takes (close_ended_run_questions), so a question is never kept after its Run has ended.
 perform pg_advisory_xact_lock(hashtextextended('question_run:'||conversation::text||':'||run,0));
 select * into talk from public.conversations where id=conversation;
 if not found or not exists(select 1 from public.conversation_messages m where m.conversation_id=conversation and m.author='person' and m.run_id=run) then return '[]'::jsonb; end if;
 -- Closed first, so the next question is kept on the read that shows it (one open question per Conversation).
 -- Another Run's question that outlived its end, open or claimed (left from before a Run's end closed its questions),
 -- closes here too, its claimed answer kept, so it no longer holds the Conversation's one open question.
 update public.reply_cards r set state='closed' where r.conversation_id=conversation and r.kind='question'
  and (r.state='open' and r.run_id=run and (ended or (r.call_id is distinct from asked and r.created_at<read_started_at))
   or r.state in ('open','sending') and r.run_id<>run and exists(select 1 from public.conversation_run_ends u where u.conversation_id=conversation and u.run_id=r.run_id));
 -- A read that saw the question before another closer ended the Run keeps nothing for it.
 if asked is not null and not ended and not exists(select 1 from public.conversation_run_ends u where u.conversation_id=conversation and u.run_id=run)
  and not exists(select 1 from public.stopped_runs s where s.conversation_id=conversation and s.run_id=run) then
  kept:=jsonb_build_object('question',asking->'text','choices',asking->'choices','multiple',asking->'multiple');
  if length(asked) between 1 and 200 and public.reply_card_valid('question','open',kept) then
   insert into public.reply_cards(company_id,conversation_id,run_id,call_id,kind,title,content,state,created_at,said_before)
    values(talk.company_id,conversation,run,asked,'question',
     case when length(kept->>'question')<=100 then kept->>'question' else rtrim(left(kept->>'question',99),E' \t\r\n')||'…' end,kept,'open',read_started_at,
     case when not public.conversation_run_said(conversation,run,words) then words end)
    on conflict do nothing;
   -- A read that kept the card before it could read the words leaves them to the next read that can.
   update public.reply_cards r set said_before=words where r.conversation_id=conversation and r.run_id=run and r.kind='question' and r.call_id=asked and r.said_before is null
    and not public.conversation_run_said(conversation,run,words);
  end if;
 end if;
 -- Each claimed answer is handed to this closer alone, for 15 seconds (an answer's call to the Engine gives up after 10):
 -- another closer's read meanwhile gets nothing to deliver, so the Engine is asked once; a closer that died or could not
 -- reach the Engine leaves it to the first read after that.
 with given as (
  update public.reply_cards r set delivering_at=now()
   where r.conversation_id=conversation and r.run_id=run and r.kind='question' and r.state='sending'
    and (r.delivering_at is null or r.delivering_at<now()-interval '15 seconds')
   returning r.id,r.call_id,r.content)
 select jsonb_agg(jsonb_build_object('card',g.id,'question',g.call_id,'answer',g.content->'answer') order by g.id) into handed from given g;
 return coalesce(handed,'[]'::jsonb);
end $$;

ALTER FUNCTION public.track_run_question(conversation uuid, run text, asking jsonb, ended boolean, read_started_at timestamp with time zone) OWNER TO postgres;

--
-- Name: undo_work_card_move(uuid, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.undo_work_card_move(c uuid, card bigint) RETURNS text
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare moved public.work_card_moves; current_stage bigint; current_place numeric; current_column text; current_kind text;
 from_column text; from_kind text; begin
 if not public.work_can_edit(c) then raise exception 'not permitted' using errcode='42501'; end if;
 -- The Card is locked first, so no move commits between the checks and the way back.
 select w.stage_id,w.board_order,s.board_column,s.kind into current_stage,current_place,current_column,current_kind
  from public.work_cards w join public.work_stages s on s.company_id=w.company_id and s.id=w.stage_id
  where w.company_id=c and w.id=card for update of w;
 if not found then raise exception 'card not found or not permitted'; end if;
 select m.* into moved from public.work_card_moves m where m.company_id=c and m.card_id=card and m.person_id=auth.uid()
  order by m.id desc limit 1;
 if not found then raise exception 'nothing to undo' using errcode='42501'; end if;
 -- The caller's move must still be the Card's latest: a later move by anyone, even one that put it back on the same
 -- stage and place, is not the caller's to undo.
 if moved.id is distinct from public.work_card_latest_move(c,card)
  or current_stage is distinct from moved.to_stage_id or current_place is distinct from moved.to_place then
  raise exception 'the card moved on' using errcode='P0001';
 end if;
 select s.board_column,s.kind into from_column,from_kind from public.work_stages s where s.company_id=c and s.id=moved.from_stage_id;
 if from_column is null then raise exception 'card not found or not permitted'; end if;
 if current_column='waiting' or from_column='waiting' then raise exception 'waiting is not placed by hand' using errcode='42501'; end if;
 if (current_column in ('live','done') or from_column in ('live','done') or current_kind='after_review' or from_kind='after_review')
  and not public.can_manage_company(c) then raise exception 'not permitted' using errcode='42501'; end if;
 perform set_config('work.undo','yes',true);
 perform set_config('work.place_exact','yes',true);
 update public.work_cards w set stage_id=moved.from_stage_id,board_order=moved.from_place where w.company_id=c and w.id=card;
 if not found then perform set_config('work.place_exact','',true); perform set_config('work.undo','',true); raise exception 'card not found or not permitted'; end if;
 perform set_config('work.place_exact','',true);
 perform set_config('work.undo','',true);
 return from_column;
end $$;

ALTER FUNCTION public.undo_work_card_move(c uuid, card bigint) OWNER TO postgres;

--
-- Name: waiting_list(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.waiting_list(c uuid) RETURNS TABLE(kind text, id bigint, title text, body text, asked_by text, card_id bigint, conversation_id uuid, created_at timestamp with time zone)
    LANGUAGE plpgsql STABLE
    SET search_path TO ''
    SET plan_cache_mode TO 'force_generic_plan'
    AS $$
#variable_conflict use_column
begin
 return query select * from (
  select 'approval'::text, w.id, w.title, coalesce(a.name,''), ''::text, w.id, null::uuid, coalesce(w.review_entered_at,w.created_at)
   from public.work_cards w
   join public.work_stages s on s.company_id=w.company_id and s.id=w.stage_id and s.kind='review'
   left join public.approval_steps a on a.company_id=w.company_id and a.id=w.approval_step_id
   where w.company_id=c and w.approval_step_id is not null and public.approval_holds(c,w.approval_step_id)
  union all
  select i.kind, i.id, i.title, i.body, i.asked_by, i.card_id, i.conversation_id, i.created_at
   from public.waiting_items i where i.company_id=c and i.person_id=auth.uid() and i.resolved_at is null
  union all
  select 'agent_request'::text, r.id, r.agent_name, r.job, coalesce(p.name,''), null::bigint, null::uuid, r.created_at
   from public.lead_agent_requests r
   join public.members m on m.company_id=r.company_id and m.person_id=r.asked_by and m.removed_at is null
   left join public.people p on p.id=r.asked_by
   where r.company_id=c and r.state='waiting' and public.is_company_owner(c)
  union all
  select r.kind, r.id, case r.kind when 'question' then r.content->>'question' else r.title end, ''::text, v.agent_name,
    (select w.id from public.work_cards w where w.company_id=c and w.conversation_id=r.conversation_id), r.conversation_id, r.created_at
   from public.reply_cards r
   join public.conversations v on v.id=r.conversation_id and v.company_id=r.company_id
   where r.company_id=c and r.kind in ('question','hand','permission') and v.person_id=auth.uid() and public.reply_card_waits(r)
  union all
  select 'channel_permission'::text, p.id, p.title, ''::text, r.agent_name, null::bigint, null::uuid, p.created_at
   from public.channel_permissions p
   join public.channel_runs r on r.message_id=p.message_id and r.ordinal=p.ordinal
   where p.company_id=c and p.state='open' and public.channel_permission_waits(p)
  union all
  select 'channel_question'::text, r.id, r.content->>'question', ''::text, cr.agent_name, null::bigint, null::uuid, r.created_at
   from public.reply_cards r
   join public.channel_messages m on m.id=r.channel_message_id
   join public.channel_runs cr on cr.message_id=r.channel_message_id and cr.ordinal=coalesce(r.channel_ordinal,1)
   where r.company_id=c and r.kind='question' and r.state='open' and cr.outcome is null
    and public.conversation_can_write(c) and public.in_channel(m.channel_id)
    and (r.addressed_to is null or r.addressed_to=auth.uid())
  union all
  select 'channel_hand'::text, r.id, r.title, ''::text, cr.agent_name, null::bigint, null::uuid, r.created_at
   from public.reply_cards r
   join public.channel_messages m on m.id=r.channel_message_id
   join public.channel_runs cr on cr.message_id=r.channel_message_id and cr.ordinal=coalesce(r.channel_ordinal,1)
   where r.company_id=c and r.kind='hand' and r.state='open'
    and public.conversation_can_write(c) and public.in_channel(m.channel_id)
  union all
  select 'agent_key'::text, k.id, g.name, ''::text, ''::text, null::bigint, null::uuid, k.created_at
   from public.agent_key_waits k
   join public.hermes_agents g on g.company_id=k.company_id and g.id=k.agent_id
   where k.company_id=c and public.agent_key_waits_shown(c)
  union all
  select 'agent_change'::text, p.id, g.name, p.change, b.name, null::bigint, null::uuid, p.created_at
   from public.agent_change_proposals p
   join public.hermes_agents g on g.company_id=p.company_id and g.id=p.agent_id
   join public.hermes_agents b on b.company_id=p.company_id and b.id=p.proposed_by
   where p.company_id=c and p.state in ('waiting','applying') and public.is_company_owner(c)
  union all
  select 'agent_access'::text, r.id, g.name, g.speciality, coalesce(p.name,''), null::bigint, null::uuid, r.pressed_at
   from public.agent_access_requests r
   join public.hermes_agents g on g.company_id=r.company_id and g.id=r.agent_id
   join public.members m on m.company_id=r.company_id and m.person_id=r.asked_by and m.removed_at is null
   left join public.people p on p.id=r.asked_by
   where r.company_id=c and public.agent_access_waits(r)
 ) x(kind,id,title,body,asked_by,card_id,conversation_id,created_at)
 order by created_at desc, id desc;
end $$;

ALTER FUNCTION public.waiting_list(c uuid) OWNER TO postgres;

--
-- Name: wake_agent(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.wake_agent(c uuid, agent uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
 if auth.uid() is null or not public.can_see_agent(c, agent) then return false; end if;
 insert into public.agent_reader_marks(company_id, person_id, agent_id, woken_at) values (c, auth.uid(), agent, now())
  on conflict (person_id, agent_id) do update set woken_at=excluded.woken_at;
 return true;
end $$;

ALTER FUNCTION public.wake_agent(c uuid, agent uuid) OWNER TO postgres;

--
-- Name: words_of(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.words_of(asking jsonb) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
 select case when jsonb_typeof(asking->'said')='string' and btrim(asking->>'said',E' \t\r\n')<>'' and length(asking->>'said')<=200000 then asking->>'said' end;
$$;

ALTER FUNCTION public.words_of(asking jsonb) OWNER TO postgres;

--
-- Name: work_audit(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.work_audit() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare rowdata jsonb; previous jsonb; cid bigint; company uuid; field text; ev text; details jsonb; action_name text; begin
 rowdata=case when tg_op='DELETE' then to_jsonb(old) else to_jsonb(new) end;
 previous=case when tg_op='UPDATE' then to_jsonb(old) else '{}'::jsonb end;
 company=(rowdata->>'company_id')::uuid; cid=case when tg_table_name='work_cards' then (rowdata->>'id')::bigint else (rowdata->>'card_id')::bigint end;
 ev=nullif(current_setting('work.evidence',true),'');
 if tg_table_name='work_cards' and tg_op='UPDATE' then
  foreach field in array array['title','stage_id','offering','segment','hook','channel','format','go_live','goal','caption','next_actor','project_id'] loop
   if rowdata->field is distinct from previous->field then
    details=jsonb_build_object('field',field,'old',previous->field,'new',rowdata->field);
    if field='stage_id' then details=details || jsonb_build_object('old_name',(select name from public.work_stages where id=(previous->>'stage_id')::bigint),'new_name',(select name from public.work_stages where id=(rowdata->>'stage_id')::bigint));
     -- The way back (#168) is told by the board's columns, not the stages: it is the board's own "Undo".
     if coalesce(current_setting('work.undo',true),'')='yes' then details=details || jsonb_build_object('old_column',(select board_column from public.work_stages where id=(previous->>'stage_id')::bigint),'new_column',(select board_column from public.work_stages where id=(rowdata->>'stage_id')::bigint)); end if; end if;
    if field='project_id' then details=details || jsonb_build_object('old_name',(select name from public.work_projects where id=(previous->>'project_id')::bigint),'new_name',(select name from public.work_projects where id=(rowdata->>'project_id')::bigint)); end if;
    insert into public.work_activity(company_id,card_id,actor_id,action,details,evidence) values(company,cid,auth.uid(),
     case when field='stage_id' and coalesce(current_setting('work.undo',true),'')='yes' then 'card_moved_back' else 'card_changed' end,details,ev);
   end if;
  end loop;
 else
  action_name=case tg_table_name when 'work_cards' then case when current_setting('work.idea',true)='yes' then 'idea_added' else 'card_created' end when 'work_checklist' then 'checklist_changed' when 'work_card_labels' then 'label_changed' when 'work_assignees' then 'assignee_changed' when 'work_creatives' then 'creative_added' when 'work_versions' then 'version_added' when 'work_comments' then 'comment_added' end;
  if tg_table_name='work_versions' then ev=coalesce(ev,rowdata->>'path'); end if;
  insert into public.work_activity(company_id,card_id,actor_id,action,details,evidence) values(company,cid,auth.uid(),action_name,rowdata,ev);
 end if; return coalesce(new,old); end $$;

ALTER FUNCTION public.work_audit() OWNER TO postgres;

