--
-- Name: work_defaults(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.work_defaults() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$ begin
 insert into public.work_stages(company_id,name,position,kind,board_column) select new.id,n,ord,case when ord=1 then 'ideas' when ord=5 then 'review' when ord>5 then 'after_review' else 'before_review' end,
  (array['ideas','planned','progress','progress','waiting','planned','planned','live','live','done'])[ord]
  from unnest(array['أفكار','بريف جاهز','كتابة','تصميم ومونتاج','مراجعة','معتمد','مجدول للنشر','منشور','إعلانات شغالة','خلص']) with ordinality as x(n,ord);
 insert into public.work_labels(company_id,name,color) select new.id,n,c from (values ('static','#87bba2'),('reel','#bd8d81'),('carosel','#cdbb78'),('Paid','#a58bc1'),('content','#83a6be'),('Campaign','#d6a76f'),('Urgent','#d78484'),('Website','#8abbb7')) x(n,c); return new; end $$;

ALTER FUNCTION public.work_defaults() OWNER TO postgres;

--
-- Name: work_guard(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.work_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$ declare stage_kind text; previous_kind text; begin
 if tg_op='UPDATE' and new.company_id<>old.company_id then raise exception 'company cannot change'; end if;
 if current_setting('approval.internal',true) is distinct from 'yes' and (tg_op='INSERT' or new.stage_id<>old.stage_id) and auth.uid() is not null and not public.can_manage_company(new.company_id) then
 select kind into stage_kind from public.work_stages where id=new.stage_id and company_id=new.company_id;
 if tg_op='UPDATE' then select kind into previous_kind from public.work_stages where id=old.stage_id and company_id=old.company_id; end if;
 if stage_kind='after_review' or previous_kind='after_review' then raise exception 'contributors cannot move beyond review'; end if; end if; return new; end $$;

ALTER FUNCTION public.work_guard() OWNER TO postgres;

--
-- Name: work_stage_column(uuid, text, text, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.work_stage_column(stage_company uuid, stage_kind text, key text, stage_position integer) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
 select case
  when stage_kind='ideas' then 'ideas'
  when stage_kind='review' then 'waiting'
  when key in ('writing','design') then 'progress'
  when key in ('approved','scheduled') then 'planned'
  when stage_kind='before_review' and stage_position<coalesce((select w.position from public.work_stages w where w.company_id=stage_company and w.stage_key='writing'),0) then 'planned'
  when stage_kind='before_review' then 'progress'
  else 'live' end;
$$;

ALTER FUNCTION public.work_stage_column(stage_company uuid, stage_kind text, key text, stage_position integer) OWNER TO postgres;

--
-- Name: work_stage_key_guard(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.work_stage_key_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$ begin
 if tg_op='INSERT' then
  new.stage_key=case new.name when 'كتابة' then 'writing' when 'تصميم ومونتاج' then 'design' when 'معتمد' then 'approved' when 'مجدول للنشر' then 'scheduled' else null end;
 elsif new.stage_key is distinct from old.stage_key then raise exception 'stage identity cannot change'; end if;
 return new; end $$;

ALTER FUNCTION public.work_stage_key_guard() OWNER TO postgres;

--
-- Name: work_stage_place(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.work_stage_place() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
 if tg_op='UPDATE' then
  if new.board_column is distinct from old.board_column then raise exception 'stage identity cannot change'; end if;
  return new;
 end if;
 if new.board_column is null then new.board_column=public.work_stage_column(new.company_id,new.kind,new.stage_key,new.position); end if;
 if new.kind in ('ideas','before_review') and new.board_column in ('live','done') then raise exception 'a stage before review cannot be live or done'; end if;
 return new;
end $$;

ALTER FUNCTION public.work_stage_place() OWNER TO postgres;

