--
-- Name: written_message(public.conversation_messages); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.written_message(m public.conversation_messages) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
 select m.run_id<>'lead-opening' and not (m.author='person' and exists(select 1 from public.conversation_run_ends e
  where e.conversation_id=m.conversation_id and e.run_id=m.run_id and e.outcome='no_model'));
$$;

ALTER FUNCTION public.written_message(m public.conversation_messages) OWNER TO postgres;

