--

CREATE TABLE public.agent_change_proposals (
    id bigint NOT NULL,
    company_id uuid NOT NULL,
    conversation_id uuid NOT NULL,
    run_id text NOT NULL,
    call_id text NOT NULL,
    agent_id uuid NOT NULL,
    proposed_by uuid NOT NULL,
    asked_by uuid NOT NULL,
    change text NOT NULL,
    setting text,
    value jsonb NOT NULL,
    reason text NOT NULL,
    state text DEFAULT 'waiting'::text NOT NULL,
    answered_by uuid,
    answered_at timestamp with time zone,
    claimed_by uuid,
    claimed_at timestamp with time zone,
    maybe_applied boolean DEFAULT false NOT NULL,
    answer text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    claim_token uuid,
    approved_value jsonb,
    CONSTRAINT agent_change_proposals_answer_text CHECK (((answer IS NULL) OR ((length(btrim(answer)) >= 1) AND (length(btrim(answer)) <= 1000)))),
    CONSTRAINT agent_change_proposals_answered CHECK ((((state = ANY (ARRAY['approved'::text, 'declined'::text])) = (answered_by IS NOT NULL)) AND ((answered_by IS NULL) = (answered_at IS NULL)) AND ((answer IS NULL) OR (state = 'declined'::text)))),
    CONSTRAINT agent_change_proposals_approved_value CHECK (((approved_value IS NULL) OR ((approved_value <> value) AND public.agent_change_value_valid(change, approved_value) AND ((state = ANY (ARRAY['applying'::text, 'approved'::text])) OR ((state = 'declined'::text) AND maybe_applied))))),
    CONSTRAINT agent_change_proposals_change CHECK ((change = ANY (ARRAY['model'::text, 'instructions'::text, 'toolset'::text, 'setting'::text]))),
    CONSTRAINT agent_change_proposals_claimed CHECK ((((claimed_by IS NULL) = (claimed_at IS NULL)) AND ((state <> 'applying'::text) OR (claimed_at IS NOT NULL)))),
    CONSTRAINT agent_change_proposals_listed CHECK (((state = 'refused'::text) OR (public.agent_change_listed(change, setting) AND public.agent_change_value_valid(change, value)))),
    CONSTRAINT agent_change_proposals_reason CHECK (((length(btrim(reason)) >= 1) AND (length(btrim(reason)) <= 500))),
    CONSTRAINT agent_change_proposals_setting CHECK (((setting IS NULL) OR (setting ~ '^[a-zA-Z0-9][a-zA-Z0-9_.-]{0,119}$'::text))),
    CONSTRAINT agent_change_proposals_state CHECK ((state = ANY (ARRAY['waiting'::text, 'applying'::text, 'approved'::text, 'declined'::text, 'refused'::text]))),
    CONSTRAINT agent_change_proposals_token CHECK (((claim_token IS NULL) = (claimed_at IS NULL)))
);

ALTER TABLE public.agent_change_proposals OWNER TO postgres;

