    to_model text,
    CONSTRAINT company_audit_action_check CHECK ((action = ANY (ARRAY['company_renamed'::text, 'agent_level_changed'::text, 'company_knowledge_changed'::text, 'app_connected'::text, 'app_disconnected'::text, 'subscription_connected'::text, 'subscription_disconnected'::text, 'provider_key_set'::text, 'provider_key_removed'::text, 'provider_switched'::text, 'fallback_model_used'::text]))),
    CONSTRAINT company_audit_values CHECK ((((action = 'company_renamed'::text) AND (old_name IS NOT NULL) AND (new_name IS NOT NULL)) OR ((action = 'agent_level_changed'::text) AND ((old_level >= 1) AND (old_level <= 3)) AND ((new_level >= 1) AND (new_level <= 3))) OR ((action = 'company_knowledge_changed'::text) AND (knowledge_part IS NOT NULL) AND (knowledge_cleared IS NOT NULL)) OR ((action = ANY (ARRAY['app_connected'::text, 'app_disconnected'::text])) AND (app IS NOT NULL)) OR ((action = ANY (ARRAY['subscription_connected'::text, 'subscription_disconnected'::text])) AND (provider = ANY (ARRAY['openai-codex'::text, 'anthropic'::text]))) OR ((action = ANY (ARRAY['provider_key_set'::text, 'provider_key_removed'::text])) AND (provider ~ '^[a-z0-9][a-z0-9._-]{0,63}$'::text)) OR ((action = 'provider_switched'::text) AND (actor_id IS NULL) AND (switch_id IS NOT NULL) AND (from_account IS NOT NULL) AND (to_account IS NOT NULL) AND (from_name IS NOT NULL) AND (to_name IS NOT NULL) AND (provider = ANY (ARRAY['openai-codex'::text, 'anthropic'::text])) AND (switch_id ~ '^[0-9a-f]{32}$'::text) AND (from_account ~ '^[A-Za-z0-9_-]{1,64}$'::text) AND (to_account ~ '^[A-Za-z0-9_-]{1,64}$'::text) AND (from_account <> to_account) AND (from_name = btrim(from_name)) AND ((char_length(from_name) >= 1) AND (char_length(from_name) <= 80)) AND (from_name !~ '[[:cntrl:]]'::text) AND (to_name = btrim(to_name)) AND ((char_length(to_name) >= 1) AND (char_length(to_name) <= 80)) AND (to_name !~ '[[:cntrl:]]'::text)) OR ((action = 'fallback_model_used'::text) AND (actor_id IS NULL) AND (run_id IS NOT NULL) AND (from_provider IS NOT NULL) AND (from_model IS NOT NULL) AND (to_provider IS NOT NULL) AND (to_model IS NOT NULL) AND (run_id ~ '^[\w.:-]{1,200}$'::text) AND (from_provider ~ '^[a-z0-9][a-z0-9._-]{0,63}$'::text) AND (to_provider ~ '^[a-z0-9][a-z0-9._-]{0,63}$'::text) AND (from_model ~ '^[^\s[:cntrl:]]{1,200}$'::text) AND (to_model ~ '^[^\s[:cntrl:]]{1,200}$'::text) AND ((from_provider IS DISTINCT FROM to_provider) OR (from_model IS DISTINCT FROM to_model)))))
);

ALTER TABLE public.company_audit OWNER TO postgres;

