--
-- Name: agent_handovers agent_handovers_read; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY agent_handovers_read ON public.agent_handovers FOR SELECT TO authenticated USING ((EXISTS ( SELECT 1
   FROM public.conversations c
  WHERE ((c.id = agent_handovers.conversation_id) AND (c.company_id = agent_handovers.company_id) AND (c.person_id = auth.uid()) AND public.is_member(c.company_id) AND public.can_see_agent(c.company_id, c.agent_id)))));

