--
-- Name: company_log company_log_read; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY company_log_read ON public.company_log FOR SELECT TO authenticated USING (((public.is_member(company_id) AND public.can_see_agent(company_id, agent_id) AND public.can_see_agent(company_id, actor_id) AND (NOT ((source = 'reply_cards'::text) AND public.reply_card_in_other_channel(source_id))) AND (NOT ((source = 'reply_card_answers'::text) AND public.reply_card_in_other_channel(source_id))) AND (NOT ((source = 'agent_handovers'::text) AND public.handover_in_channel(source_id))) AND (((details ->> 'private'::text) IS NULL) OR (actor_id = auth.uid()) OR ((details ->> 'teller'::text) = (auth.uid())::text) OR
CASE
    WHEN ((details ->> 'private'::text) = 'owners'::text) THEN public.is_company_owner(company_id)
    ELSE public.can_manage_company(company_id)
END)) OR ((source = ANY (ARRAY['reply_cards'::text, 'reply_card_answers'::text])) AND public.reply_card_in_channel(source_id)) OR ((source = ANY (ARRAY['agent_handovers'::text, 'channel_handover_replies'::text])) AND public.handover_in_my_channel(source_id))));

