--
-- Name: waiting_items waiting_items_read; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY waiting_items_read ON public.waiting_items FOR SELECT TO authenticated USING (((person_id = auth.uid()) AND public.is_member(company_id) AND public.can_see_conversation_agent(company_id, conversation_id) AND public.can_decide_waiting_rule(company_id, agent_rule_id) AND ((channel_message_id IS NULL) OR (EXISTS ( SELECT 1
   FROM public.channel_messages m
  WHERE ((m.id = waiting_items.channel_message_id) AND public.in_channel(m.channel_id)))))));

