-- Storage policies
CREATE POLICY card_file_visible ON storage.objects AS RESTRICTIVE FOR SELECT TO authenticated USING (((bucket_id <> 'creatives'::text) OR can_see_card_file(name)));
CREATE POLICY card_file_visible_write ON storage.objects AS RESTRICTIVE FOR INSERT TO authenticated WITH CHECK (((bucket_id <> 'creatives'::text) OR can_see_card_file(name)));
CREATE POLICY channel_file_read ON storage.objects AS PERMISSIVE FOR SELECT TO authenticated USING (((bucket_id = 'creatives'::text) AND ((storage.foldername(name))[2] = 'channels'::text) AND (EXISTS ( SELECT 1
   FROM channels k
  WHERE (((k.id)::text = (storage.foldername(objects.name))[3]) AND ((k.company_id)::text = (storage.foldername(objects.name))[1]) AND in_channel(k.id))))));
CREATE POLICY conversation_file_read ON storage.objects AS PERMISSIVE FOR SELECT TO authenticated USING (((bucket_id = 'creatives'::text) AND ((storage.foldername(name))[2] = 'conversations'::text) AND (EXISTS ( SELECT 1
   FROM conversations c
  WHERE (((c.id)::text = (storage.foldername(objects.name))[3]) AND ((c.company_id)::text = (storage.foldername(objects.name))[1]) AND (c.person_id = uid()) AND is_member(c.company_id) AND can_see_agent(c.company_id, c.agent_id))))));
CREATE POLICY creative_read ON storage.objects AS PERMISSIVE FOR SELECT TO authenticated USING (((bucket_id = 'creatives'::text) AND ((storage.foldername(name))[2] IS DISTINCT FROM 'conversations'::text) AND ((storage.foldername(name))[2] IS DISTINCT FROM 'channels'::text) AND is_member(
CASE
    WHEN ((storage.foldername(name))[1] ~ '^[0-9a-f-]{36}$'::text) THEN ((storage.foldername(name))[1])::uuid
    ELSE NULL::uuid
END)));
CREATE POLICY creative_write ON storage.objects AS PERMISSIVE FOR INSERT TO authenticated WITH CHECK (((bucket_id = 'creatives'::text) AND ((storage.foldername(name))[2] IS DISTINCT FROM 'conversations'::text) AND ((storage.foldername(name))[2] IS DISTINCT FROM 'channels'::text) AND work_can_edit(
CASE
    WHEN ((storage.foldername(name))[1] ~ '^[0-9a-f-]{36}$'::text) THEN ((storage.foldername(name))[1])::uuid
    ELSE NULL::uuid
END)));
-- Storage buckets
-- bucket creatives: public f, file size limit none, types any
